Object.assign(window.DMA_DATEN.GERMAN_HISTORY_TODAY, {"08-01":{"year":1914,"levels":{"A1":"Am 1. August 1914 erklärt Deutschland Russland den Krieg. Ein großer Krieg beginnt.","A2":"Am 1. August 1914 erklärt das Deutsche Reich Russland den Krieg. Das ist der Beginn des Ersten Weltkriegs.","B1":"Am 1. August 1914 erklärt das Deutsche Reich Russland den Krieg. Damit beginnt der Erste Weltkrieg, der über vier Jahre dauern und Millionen Menschen das Leben kosten wird.","B2":"Am 1. August 1914 erklärt das Deutsche Reich Russland den Krieg — nur wenige Tage nach der Ermordung des österreichischen Thronfolgers in Sarajevo. Ein Bündnisgeflecht zieht binnen Tagen fast ganz Europa in den Ersten Weltkrieg.","C1":"Die deutsche Kriegserklärung an Russland am 1. August 1914 markiert den Einstieg des Deutschen Reichs in den Ersten Weltkrieg — ausgelöst durch das Bündnissystem, das nach dem Attentat von Sarajevo eine europaweite Kettenreaktion in Gang setzte.","C2":"Die Kriegserklärung des Deutschen Reichs an Russland am 1. August 1914, eingebettet in das komplexe Bündnisgeflecht der europäischen Großmächte, gilt als Schlüsselmoment jenes 'Sommers der Illusionen', in dem beinahe alle beteiligten Regierungen von einem kurzen, überschaubaren Krieg ausgingen."},"translationsA1":{"en":"On August 1, 1914, Germany declares war on Russia. A big war begins.","ar":"في 1 أغسطس 1914، أعلنت ألمانيا الحرب على روسيا. حرب كبيرة تبدأ.","tr":"1 Ağustos 1914'te Almanya Rusya'ya savaş ilan etti. Büyük bir savaş başlıyor.","ru":"1 августа 1914 года Германия объявила войну России. Начинается большая война.","es":"El 1 de agosto de 1914, Alemania declara la guerra a Rusia. Comienza una gran guerra.","fr":"Le 1er août 1914, l'Allemagne déclare la guerre à la Russie. Une grande guerre commence.","pl":"1 sierpnia 1914 roku Niemcy wypowiedziały wojnę Rosji. Zaczyna się wielka wojna.","uk":"1 серпня 1914 року Німеччина оголосила війну Росії. Починається велика війна.","fa":"در ۱ اوت ۱۹۱۴، آلمان به روسیه اعلان جنگ داد. جنگ بزرگی آغاز می‌شود.","it":"Il 1° agosto 1914 la Germania dichiara guerra alla Russia. Inizia una grande guerra."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On 1 August 1914, the German Empire declares war on Russia. This marks the beginning of the First World War.","ar":"في 1 أغسطس 1914 أعلنت الإمبراطورية الألمانية الحرب على روسيا. كان ذلك بداية الحرب العالمية الأولى.","tr":"1 Ağustos 1914'te Alman İmparatorluğu Rusya'ya savaş ilan etti. Bu, Birinci Dünya Savaşı'nın başlangıcıdır.","ru":"1 августа 1914 года Германская империя объявляет войну России. Это начало Первой мировой войны.","es":"El 1 de agosto de 1914 el Imperio alemán declara la guerra a Rusia. Es el comienzo de la Primera Guerra Mundial.","fr":"Le 1er août 1914, l'Empire allemand déclare la guerre à la Russie. C'est le début de la Première Guerre mondiale.","pl":"1 sierpnia 1914 roku Cesarstwo Niemieckie wypowiada wojnę Rosji. To początek pierwszej wojny światowej.","uk":"1 серпня 1914 року Німецька імперія оголошує війну Росії. Це початок Першої світової війни.","fa":"در ۱ اوت ۱۹۱۴ امپراتوری آلمان به روسیه اعلان جنگ داد. این آغاز جنگ جهانی اول است.","it":"Il 1° agosto 1914 l'Impero tedesco dichiara guerra alla Russia. È l'inizio della Prima guerra mondiale."},"B1":{"en":"On 1 August 1914, the German Empire declares war on Russia. This begins the First World War, which will last more than four years and cost millions of people their lives.","ar":"في 1 أغسطس 1914 أعلنت الإمبراطورية الألمانية الحرب على روسيا. بذلك بدأت الحرب العالمية الأولى التي ستستمر أكثر من أربع سنوات وتكلف ملايين البشر حياتهم.","tr":"1 Ağustos 1914'te Alman İmparatorluğu Rusya'ya savaş ilan etti. Böylece dört yıldan fazla sürecek ve milyonlarca insanın hayatına mal olacak Birinci Dünya Savaşı başlar.","ru":"1 августа 1914 года Германская империя объявляет войну России. Так начинается Первая мировая война, которая продлится более четырёх лет и унесёт жизни миллионов людей.","es":"El 1 de agosto de 1914 el Imperio alemán declara la guerra a Rusia. Así comienza la Primera Guerra Mundial, que durará más de cuatro años y costará la vida a millones de personas.","fr":"Le 1er août 1914, l'Empire allemand déclare la guerre à la Russie. C'est le début de la Première Guerre mondiale, qui durera plus de quatre ans et coûtera la vie à des millions de personnes.","pl":"1 sierpnia 1914 roku Cesarstwo Niemieckie wypowiada wojnę Rosji. Tak zaczyna się pierwsza wojna światowa, która potrwa ponad cztery lata i kosztować będzie życie milionów ludzi.","uk":"1 серпня 1914 року Німецька імперія оголошує війну Росії. Так починається Перша світова війна, яка триватиме понад чотири роки і забере життя мільйонів людей.","fa":"در ۱ اوت ۱۹۱۴ امپراتوری آلمان به روسیه اعلان جنگ داد. بدین‌ترتیب جنگ جهانی اول آغاز شد که بیش از چهار سال به طول انجامید و جان میلیون‌ها انسان را گرفت.","it":"Il 1° agosto 1914 l'Impero tedesco dichiara guerra alla Russia. Inizia così la Prima guerra mondiale, che durerà oltre quattro anni e costerà la vita a milioni di persone."},"B2":{"en":"On 1 August 1914, the German Empire declares war on Russia — only a few days after the assassination of the Austrian heir to the throne in Sarajevo. A web of alliances draws nearly all of Europe into the First World War within days.","ar":"في 1 أغسطس 1914 أعلنت الإمبراطورية الألمانية الحرب على روسيا — بعد أيام قليلة فقط من اغتيال ولي عهد النمسا في سراييفو. جرّت شبكة من التحالفات خلال أيام قليلة أوروبا بأكملها تقريباً إلى الحرب العالمية الأولى.","tr":"1 Ağustos 1914'te Alman İmparatorluğu Rusya'ya savaş ilan etti — Avusturya veliahtının Saraybosna'da öldürülmesinden yalnızca birkaç gün sonra. Bir ittifaklar ağı, günler içinde neredeyse tüm Avrupa'yı Birinci Dünya Savaşı'na sürükler.","ru":"1 августа 1914 года Германская империя объявляет войну России — всего через несколько дней после убийства австрийского наследника престола в Сараево. Сеть союзов за считанные дни втягивает почти всю Европу в Первую мировую войну.","es":"El 1 de agosto de 1914 el Imperio alemán declara la guerra a Rusia, solo unos días después del asesinato del heredero austríaco al trono en Sarajevo. Una red de alianzas arrastra en cuestión de días a casi toda Europa a la Primera Guerra Mundial.","fr":"Le 1er août 1914, l'Empire allemand déclare la guerre à la Russie — seulement quelques jours après l'assassinat de l'héritier du trône autrichien à Sarajevo. Un réseau d'alliances entraîne en quelques jours presque toute l'Europe dans la Première Guerre mondiale.","pl":"1 sierpnia 1914 roku Cesarstwo Niemieckie wypowiada wojnę Rosji — zaledwie kilka dni po zamachu na austriackiego następcę tronu w Sarajewie. Sieć sojuszy wciąga w ciągu kilku dni niemal całą Europę w pierwszą wojnę światową.","uk":"1 серпня 1914 року Німецька імперія оголошує війну Росії — лише за кілька днів після вбивства австрійського спадкоємця престолу в Сараєво. Мережа союзів протягом кількох днів втягує майже всю Європу в Першу світову війну.","fa":"در ۱ اوت ۱۹۱۴ امپراتوری آلمان به روسیه اعلان جنگ داد؛ تنها چند روز پس از ترور ولیعهد اتریش در سارایوو. شبکه‌ای از اتحادها در عرض چند روز تقریباً کل اروپا را وارد جنگ جهانی اول کرد.","it":"Il 1° agosto 1914 l'Impero tedesco dichiara guerra alla Russia, pochi giorni dopo l'assassinio dell'erede al trono austriaco a Sarajevo. Un intreccio di alleanze trascina nel giro di pochi giorni quasi tutta l'Europa nella Prima guerra mondiale."},"C1":{"en":"Germany's declaration of war on Russia on 1 August 1914 marks the German Empire's entry into the First World War — triggered by the system of alliances that, after the assassination in Sarajevo, set off a Europe-wide chain reaction.","ar":"يمثّل الإعلان الألماني للحرب على روسيا في 1 أغسطس 1914 دخول الإمبراطورية الألمانية الحرب العالمية الأولى — بفعل نظام التحالفات الذي أطلق، بعد اغتيال سراييفو، سلسلة ردود فعل شملت أوروبا بأسرها.","tr":"1 Ağustos 1914'teki Alman savaş ilanı, Alman İmparatorluğu'nun Birinci Dünya Savaşı'na girişini işaret eder — Saraybosna suikastından sonra Avrupa çapında bir zincirleme reaksiyon başlatan ittifaklar sistemi tarafından tetiklenmiştir.","ru":"Германское объявление войны России 1 августа 1914 года отмечает вступление Германской империи в Первую мировую войну — вызванное системой союзов, которая после сараевского покушения запустила общеевропейскую цепную реакцию.","es":"La declaración de guerra alemana a Rusia el 1 de agosto de 1914 marca la entrada del Imperio alemán en la Primera Guerra Mundial, desencadenada por el sistema de alianzas que, tras el atentado de Sarajevo, puso en marcha una reacción en cadena a escala europea.","fr":"La déclaration de guerre allemande à la Russie le 1er août 1914 marque l'entrée de l'Empire allemand dans la Première Guerre mondiale — déclenchée par le système d'alliances qui, après l'attentat de Sarajevo, mit en branle une réaction en chaîne à l'échelle européenne.","pl":"Niemieckie wypowiedzenie wojny Rosji 1 sierpnia 1914 roku oznacza wejście Cesarstwa Niemieckiego do pierwszej wojny światowej — wywołane przez system sojuszy, który po zamachu w Sarajewie uruchomił ogólnoeuropejską reakcję łańcuchową.","uk":"Німецьке оголошення війни Росії 1 серпня 1914 року позначає вступ Німецької імперії в Першу світову війну — спричинений системою союзів, яка після сараєвського замаху запустила загальноєвропейську ланцюгову реакцію.","fa":"اعلان جنگ آلمان علیه روسیه در ۱ اوت ۱۹۱۴ نشان‌دهنده ورود امپراتوری آلمان به جنگ جهانی اول است؛ ورودی که با نظام اتحادهایی برانگیخته شد که پس از ترور سارایوو، واکنشی زنجیره‌ای سراسر اروپا را به راه انداخت.","it":"La dichiarazione di guerra tedesca alla Russia del 1° agosto 1914 segna l'ingresso dell'Impero tedesco nella Prima guerra mondiale, innescato dal sistema di alleanze che, dopo l'attentato di Sarajevo, mise in moto una reazione a catena su scala europea."},"C2":{"en":"The German Empire's declaration of war on Russia on 1 August 1914, embedded in the complex web of alliances among the European great powers, is considered a key moment of that 'summer of illusions' in which almost all the governments involved assumed the war would be short and manageable.","ar":"يُعدّ إعلان الإمبراطورية الألمانية الحرب على روسيا في 1 أغسطس 1914، المندرج ضمن شبكة التحالفات المعقدة للقوى الأوروبية الكبرى، لحظة مفصلية من ذلك 'صيف الأوهام' الذي افترضت فيه جميع الحكومات المعنية تقريباً أن الحرب ستكون قصيرة ويمكن السيطرة عليها.","tr":"Alman İmparatorluğu'nun 1 Ağustos 1914'te Rusya'ya karşı savaş ilanı, Avrupalı büyük güçlerin karmaşık ittifak ağına gömülü olarak, neredeyse tüm ilgili hükümetlerin kısa ve kontrol edilebilir bir savaş beklediği o 'yanılsamalar yazının' kilit anı sayılır.","ru":"Объявление войны Германской империей России 1 августа 1914 года, вписанное в сложную сеть союзов европейских великих держав, считается ключевым моментом того 'лета иллюзий', когда почти все причастные правительства исходили из того, что война будет короткой и легко управляемой.","es":"La declaración de guerra del Imperio alemán a Rusia el 1 de agosto de 1914, inscrita en la compleja red de alianzas de las grandes potencias europeas, se considera un momento clave de aquel 'verano de las ilusiones' en el que casi todos los gobiernos implicados suponían una guerra corta y manejable.","fr":"La déclaration de guerre de l'Empire allemand à la Russie le 1er août 1914, inscrite dans l'enchevêtrement complexe des alliances des grandes puissances européennes, est considérée comme un moment clé de cet 'été des illusions' durant lequel presque tous les gouvernements impliqués tablaient sur une guerre courte et maîtrisable.","pl":"Wypowiedzenie wojny Rosji przez Cesarstwo Niemieckie 1 sierpnia 1914 roku, osadzone w złożonej sieci sojuszy europejskich mocarstw, uchodzi za kluczowy moment owego 'lata złudzeń', w którym niemal wszystkie zaangażowane rządy zakładały krótką i możliwą do opanowania wojnę.","uk":"Оголошення війни Німецькою імперією Росії 1 серпня 1914 року, вписане у складну мережу союзів європейських великих держав, вважається ключовим моментом того 'літа ілюзій', коли майже всі причетні уряди виходили з того, що війна буде короткою і контрольованою.","fa":"اعلان جنگ امپراتوری آلمان علیه روسیه در ۱ اوت ۱۹۱۴، که در شبکه پیچیده اتحادهای قدرت‌های بزرگ اروپایی جای دارد، لحظه‌ای کلیدی از آن 'تابستان توهمات' به شمار می‌رود که در آن تقریباً همه دولت‌های درگیر گمان می‌کردند جنگ کوتاه و قابل کنترل خواهد بود.","it":"La dichiarazione di guerra dell'Impero tedesco alla Russia del 1° agosto 1914, inserita nel complesso intreccio di alleanze delle grandi potenze europee, è considerata un momento chiave di quella \"estate delle illusioni\" in cui quasi tutti i governi coinvolti presumevano una guerra breve e circoscritta."}}},"08-02":{"year":1552,"levels":{"A1":"Am 2. August 1552 schließen Kaiser und Fürsten einen Vertrag. Der neue Glaube wird erlaubt. Der lange Streit hört für eine Weile auf.","A2":"Am 2. August 1552 wird in Passau ein Vertrag geschlossen. Die protestantischen Fürsten bekommen zum ersten Mal offiziell Rechte. Drei Jahre später folgte daraus der Augsburger Religionsfrieden.","B1":"Am 2. August 1552 unterzeichnen Kaiser Ferdinand I. und die protestantischen Fürsten den Passauer Vertrag. Zum ersten Mal wurde der Protestantismus im Reich rechtlich hingenommen. Es war kein Frieden aus Überzeugung, sondern aus Erschöpfung.","B2":"Am 2. August 1552 endet mit dem Passauer Vertrag der Versuch, die Glaubensspaltung militärisch zu beseitigen. Beide Seiten hatten erkannt, dass keine die andere besiegen konnte. Der Vertrag löste nichts — er stellte fest, dass man miteinander auskommen musste.","C1":"Der Vertrag vom 2. August 1552 markiert eine bemerkenswerte Wendung: Duldung entstand hier nicht aus Toleranz, sondern aus einem Patt. Diese Entstehungsgeschichte teilt sie mit den meisten Religionsfrieden der frühen Neuzeit — und erklärt, warum sie so lange brüchig blieben.","C2":"Am 2. August 1552 wurde etwas eingeräumt, das niemand für richtig hielt. Genau darin liegt der Wert des Vorgangs: Duldung, die keine Zustimmung voraussetzt, ist belastbarer als eine, die von wohlwollender Gesinnung abhängt. Religionsfreiheit begann in Europa nicht als Ideal, sondern als Ergebnis eines nicht zu gewinnenden Konflikts."},"translationsA1":{"en":"On August 2, 1552, the emperor and the princes conclude a treaty. The new faith is permitted. The long dispute stops for a while.","ar":"في 2 أغسطس 1552، أبرم الإمبراطور والأمراء معاهدة. سُمح بالمذهب الجديد. وتوقّف النزاع الطويل لبعض الوقت.","tr":"2 Ağustos 1552'de imparator ve prensler bir anlaşma yaptı. Yeni inanca izin verildi. Uzun anlaşmazlık bir süre durdu.","ru":"2 августа 1552 года император и князья заключили договор. Новая вера разрешена. Долгий спор на время прекратился.","es":"El 2 de agosto de 1552, el emperador y los príncipes firman un tratado. La nueva fe queda permitida. La larga disputa se detiene por un tiempo.","fr":"Le 2 août 1552, l'empereur et les princes concluent un traité. La nouvelle foi est autorisée. Le long conflit s'arrête un temps.","pl":"2 sierpnia 1552 roku cesarz i książęta zawarli układ. Nowa wiara została dozwolona. Długi spór na jakiś czas ustał.","uk":"2 серпня 1552 року імператор і князі уклали договір. Нову віру дозволено. Довга суперечка на час припинилася.","fa":"در ۲ اوت ۱۵۵۲، امپراتور و شاهزادگان پیمانی بستند. آیین تازه مجاز شد. کشمکش دراز مدتی متوقف شد.","it":"Il 2 agosto 1552 l'imperatore e i principi stipulano un accordo. La nuova fede viene consentita. La lunga disputa si interrompe per un po'."},"translationsByLevel":{"A2":{"en":"On August 2, 1552, a treaty is signed in Passau. The Protestant princes officially receive rights for the first time. Three years later, this led to the Peace of Augsburg.","ar":"في 2 أغسطس 1552 يُبرم عقد في باساو. يحصل الأمراء البروتستانت على حقوق رسمية للمرة الأولى. وبعد ثلاث سنوات نتج عن ذلك صلح أوغسبورغ الديني.","tr":"2 Ağustos 1552'de Passau'da bir antlaşma imzalanır. Protestan prensler ilk kez resmi olarak haklar elde eder. Üç yıl sonra bundan Augsburg Din Barışı doğdu.","ru":"2 августа 1552 года в Пассау заключается договор. Протестантские князья впервые официально получают права. Три года спустя из этого возник Аугсбургский религиозный мир.","es":"El 2 de agosto de 1552 se firma un tratado en Passau. Los príncipes protestantes reciben por primera vez derechos oficiales. Tres años después, de ello surgió la Paz de Augsburgo.","fr":"Le 2 août 1552, un traité est conclu à Passau. Les princes protestants obtiennent pour la première fois des droits officiels. Trois ans plus tard, cela a conduit à la paix religieuse d'Augsbourg.","pl":"2 sierpnia 1552 roku w Passau zawarto traktat. Protestanccy książęta po raz pierwszy oficjalnie otrzymują prawa. Trzy lata później doprowadziło to do pokoju religijnego w Augsburgu.","uk":"2 серпня 1552 року в Пассау укладено договір. Протестантські князі вперше офіційно отримують права. Три роки по тому це призвело до Аугсбурзького релігійного миру.","fa":"در ۲ اوت ۱۵۵۲ در پاسائو پیمانی منعقد می‌شود. شاهزادگان پروتستان برای نخستین‌بار رسماً صاحب حقوقی می‌شوند. سه سال بعد از آن، صلح دینی آوگسبورگ پدید آمد.","it":"Il 2 agosto 1552 viene stipulato a Passavia un trattato. I principi protestanti ottengono per la prima volta diritti ufficiali. Tre anni dopo ne seguì la Pace di religione di Augusta."},"B1":{"en":"On August 2, 1552, Emperor Ferdinand I and the Protestant princes signed the Peace of Passau. For the first time, Protestantism was legally accepted within the Empire. It was not a peace born of conviction, but of exhaustion.","ar":"في 2 أغسطس 1552 وقّع الإمبراطور فرديناند الأول والأمراء البروتستانت معاهدة باساو. ولأول مرة، تم قبول البروتستانتية قانونياً داخل الإمبراطورية. لم يكن سلاماً نابعاً عن قناعة، بل عن إنهاك.","tr":"2 Ağustos 1552'de İmparator I. Ferdinand ve Protestan prensler Passau Antlaşması'nı imzaladı. İlk kez Protestanlık İmparatorluk içinde hukuken kabul edildi. Bu, inançtan değil, bitkinlikten doğan bir barıştı.","ru":"2 августа 1552 года император Фердинанд I и протестантские князья подписали Пассауский договор. Впервые протестантизм был юридически признан в пределах империи. Это был мир не по убеждению, а от изнеможения.","es":"El 2 de agosto de 1552, el emperador Fernando I y los príncipes protestantes firmaron el Tratado de Passau. Por primera vez, el protestantismo fue aceptado legalmente dentro del Imperio. No fue una paz nacida de la convicción, sino del agotamiento.","fr":"Le 2 août 1552, l'empereur Ferdinand Ier et les princes protestants signent le traité de Passau. Pour la première fois, le protestantisme est juridiquement toléré au sein de l'Empire. Ce n'était pas une paix née de la conviction, mais de l'épuisement.","pl":"2 sierpnia 1552 roku cesarz Ferdynand I i protestanccy książęta podpisali traktat pasawski. Po raz pierwszy protestantyzm został prawnie zaakceptowany w Rzeszy. Nie był to pokój z przekonania, lecz z wyczerpania.","uk":"2 серпня 1552 року імператор Фердинанд I та протестантські князі підписали Пассауський договір. Уперше протестантизм було юридично визнано в межах імперії. Це був мир не з переконання, а від виснаження.","fa":"در ۲ اوت ۱۵۵۲ امپراتور فردیناند اول و شاهزادگان پروتستان پیمان پاسائو را امضا کردند. برای نخستین‌بار پروتستانیسم در درون امپراتوری از نظر قانونی پذیرفته شد. این صلحی برخاسته از باور نبود، بلکه ناشی از فرسودگی بود.","it":"Il 2 agosto 1552 l'imperatore Ferdinando I e i principi protestanti firmano il Trattato di Passavia. Per la prima volta il protestantesimo veniva accettato giuridicamente nell'Impero. Non fu una pace nata dalla convinzione, ma dalla stanchezza."},"B2":{"en":"On August 2, 1552, the Peace of Passau ended the attempt to resolve the religious schism by military means. Both sides had realized that neither could defeat the other. The treaty solved nothing — it merely established that they had to coexist.","ar":"في 2 أغسطس 1552 وضعت معاهدة باساو حداً لمحاولة إنهاء الانقسام الديني بالوسائل العسكرية. أدرك الطرفان أن أياً منهما لا يستطيع هزيمة الآخر. لم تحل المعاهدة شيئاً — بل أثبتت أنه لا بد من التعايش.","tr":"2 Ağustos 1552'de Passau Antlaşması, inanç bölünmesini askeri yollarla ortadan kaldırma girişimine son verdi. Her iki taraf da diğerini yenemeyeceğini anlamıştı. Antlaşma hiçbir şeyi çözmedi — sadece birbirleriyle geçinmek zorunda olduklarını tespit etti.","ru":"2 августа 1552 года Пассауский договор положил конец попытке устранить религиозный раскол военным путём. Обе стороны осознали, что ни одна не может победить другую. Договор ничего не решил — он лишь констатировал, что придётся уживаться друг с другом.","es":"El 2 de agosto de 1552, el Tratado de Passau puso fin al intento de resolver la escisión religiosa por la fuerza militar. Ambos bandos habían comprendido que ninguno podía vencer al otro. El tratado no resolvió nada: solo constató que debían convivir.","fr":"Le 2 août 1552, le traité de Passau met fin à la tentative de résoudre le schisme religieux par les armes. Les deux camps avaient compris qu'aucun ne pouvait vaincre l'autre. Le traité ne résolvait rien — il constatait seulement qu'il fallait cohabiter.","pl":"2 sierpnia 1552 roku traktat pasawski zakończył próbę militarnego rozwiązania rozłamu religijnego. Obie strony zrozumiały, że żadna nie może pokonać drugiej. Traktat niczego nie rozwiązał — jedynie stwierdzał, że trzeba się ze sobą dogadać.","uk":"2 серпня 1552 року Пассауський договір поклав край спробі усунути релігійний розкол воєнним шляхом. Обидві сторони зрозуміли, що жодна не може перемогти іншу. Договір нічого не вирішив — він лише констатував, що доведеться уживатися одне з одним.","fa":"در ۲ اوت ۱۵۵۲ پیمان پاسائو به تلاش برای پایان‌دادن به شکاف دینی از راه نظامی خاتمه داد. هر دو طرف دریافته بودند که هیچ‌کدام نمی‌تواند دیگری را شکست دهد. این پیمان چیزی را حل نکرد — تنها این واقعیت را ثبت کرد که باید با یکدیگر کنار می‌آمدند.","it":"Il 2 agosto 1552, con il Trattato di Passavia, si conclude il tentativo di eliminare militarmente la scissione religiosa. Entrambe le parti avevano capito che nessuna poteva sconfiggere l'altra. Il trattato non risolse nulla: constatò semplicemente che bisognava convivere."},"C1":{"en":"The treaty of August 2, 1552, marks a remarkable turn: toleration here arose not from tolerance but from a stalemate. This origin is shared by most religious peace settlements of the early modern period — and explains why they remained so fragile for so long.","ar":"تُمثّل معاهدة 2 أغسطس 1552 منعطفاً لافتاً: فالتسامح هنا لم ينشأ عن قناعة بالتسامح، بل عن جمود لا يُحسم. وهذه النشأة تشترك فيها معظم اتفاقيات السلام الديني في مطلع العصر الحديث — وهو ما يفسر بقاءها هشة لأمد طويل.","tr":"2 Ağustos 1552 tarihli antlaşma dikkat çekici bir dönüşü işaret eder: Buradaki hoşgörü, hoşgörüden değil, bir açmazdan doğdu. Bu köken, erken modern dönemin çoğu din barışı antlaşmasıyla ortaktır — ve bunların neden bu kadar uzun süre kırılgan kaldığını açıklar.","ru":"Договор от 2 августа 1552 года знаменует примечательный поворот: терпимость здесь возникла не из толерантности, а из патовой ситуации. Эта история происхождения роднит его с большинством религиозных мирных соглашений раннего Нового времени — и объясняет, почему они так долго оставались хрупкими.","es":"El tratado del 2 de agosto de 1552 marca un giro notable: la tolerancia surgió aquí no de la convicción tolerante, sino de un empate insalvable. Este origen lo comparte con la mayoría de las paces religiosas de la Edad Moderna temprana, y explica por qué siguieron siendo tan frágiles durante tanto tiempo.","fr":"Le traité du 2 août 1552 marque un tournant remarquable : la tolérance y est née non pas de la tolérance en tant que valeur, mais d'une impasse. Cette genèse, elle la partage avec la plupart des paix religieuses du début de l'époque moderne — ce qui explique pourquoi elles sont restées si longtemps fragiles.","pl":"Traktat z 2 sierpnia 1552 roku wyznacza znaczący zwrot: tolerancja powstała tu nie z przekonania o tolerancji, lecz z patowej sytuacji. Ta geneza łączy go z większością pokojów religijnych wczesnej epoki nowożytnej — i wyjaśnia, dlaczego pozostawały one tak długo kruche.","uk":"Договір від 2 серпня 1552 року знаменує помітний поворот: терпимість тут виникла не з толерантності, а з патової ситуації. Це походження споріднює його з більшістю релігійних мирних угод раннього Нового часу — і пояснює, чому вони так довго залишалися крихкими.","fa":"پیمان ۲ اوت ۱۵۵۲ نقطه‌عطفی قابل‌توجه را رقم می‌زند: تساهل در اینجا نه از سر بردباری، بلکه از یک بن‌بست پدید آمد. این خاستگاه را با بیشتر صلح‌های دینی اوایل دوران مدرن مشترک است — و توضیح می‌دهد چرا آن‌ها این‌قدر طولانی شکننده باقی ماندند.","it":"Il trattato del 2 agosto 1552 segna una svolta notevole: qui la tolleranza non nacque dalla convinzione, ma da una situazione di stallo. Questa origine è comune alla maggior parte delle paci di religione dell'età moderna, e spiega perché rimasero così a lungo fragili."},"C2":{"en":"On August 2, 1552, something was conceded that no one considered right. Precisely herein lies the value of the event: toleration that presupposes no approval is more resilient than one dependent on benevolent sentiment. Religious freedom in Europe did not begin as an ideal, but as the outcome of an unwinnable conflict.","ar":"في 2 أغسطس 1552 جرى التسليم بأمر لم يره أحد صواباً. وهنا بالضبط تكمن قيمة هذا الحدث: فالتسامح الذي لا يفترض موافقة أكثر صموداً من ذلك الذي يتوقف على نوايا حسنة. لم تبدأ حرية الدين في أوروبا كمثال أعلى، بل كنتيجة لصراع تعذّر حسمه.","tr":"2 Ağustos 1552'de kimsenin doğru bulmadığı bir şey kabul edildi. İşte bu olayın değeri tam da burada yatar: Onay gerektirmeyen bir hoşgörü, iyi niyete bağlı olandan daha dayanıklıdır. Avrupa'da din özgürlüğü bir ideal olarak değil, kazanılamayan bir çatışmanın sonucu olarak başladı.","ru":"2 августа 1552 года было признано то, что никто не считал правильным. Именно в этом ценность произошедшего: терпимость, не предполагающая одобрения, устойчивее той, что зависит от доброжелательного настроя. Свобода вероисповедания в Европе начиналась не как идеал, а как итог конфликта, который невозможно было выиграть.","es":"El 2 de agosto de 1552 se concedió algo que nadie consideraba correcto. Precisamente ahí radica el valor del hecho: una tolerancia que no presupone aprobación resulta más resistente que aquella que depende de una actitud benevolente. La libertad religiosa en Europa no comenzó como un ideal, sino como el resultado de un conflicto imposible de ganar.","fr":"Le 2 août 1552, on concéda quelque chose que personne ne jugeait juste. C'est précisément là que réside la valeur de l'événement : une tolérance qui ne présuppose aucune adhésion est plus solide que celle qui dépend d'une disposition bienveillante. La liberté religieuse n'a pas commencé en Europe comme un idéal, mais comme le résultat d'un conflit impossible à remporter.","pl":"2 sierpnia 1552 roku uznano coś, czego nikt nie uważał za słuszne. Właśnie na tym polega wartość tego wydarzenia: tolerancja, która nie zakłada aprobaty, jest trwalsza niż ta zależna od życzliwego nastawienia. Wolność religijna w Europie nie zaczęła się jako ideał, lecz jako wynik konfliktu, którego nie dało się rozstrzygnąć zwycięsko.","uk":"2 серпня 1552 року було визнано те, що ніхто не вважав правильним. Саме в цьому й полягає цінність цієї події: терпимість, яка не передбачає схвалення, стійкіша за ту, що залежить від доброзичливого настрою. Свобода віросповідання в Європі почалася не як ідеал, а як наслідок конфлікту, який неможливо було виграти.","fa":"در ۲ اوت ۱۵۵۲ چیزی پذیرفته شد که هیچ‌کس آن را درست نمی‌دانست. ارزش این رویداد دقیقاً در همین نکته نهفته است: تحملی که مستلزم رضایت نیست، پایدارتر از تحملی است که به نیت خیرخواهانه وابسته باشد. آزادی دینی در اروپا نه به‌عنوان یک آرمان، بلکه به‌عنوان نتیجه‌ی نزاعی غیرقابل‌برد آغاز شد.","it":"Il 2 agosto 1552 fu concesso qualcosa che nessuno riteneva giusto. Proprio in questo sta il valore dell'evento: una tolleranza che non presuppone consenso è più solida di una che dipende dalla buona volontà. In Europa la libertà religiosa non nacque come ideale, ma come esito di un conflitto impossibile da vincere."}},"sideFacts":[]},"08-03":{"year":1984,"levels":{"A1":"Am 3. August 1984 kommt die erste E-Mail in Deutschland an. Sie kommt aus den USA, in Karlsruhe.","A2":"Am 3. August 1984 kommt an der Universität Karlsruhe die erste E-Mail in Deutschland an. Professor Werner Zorn und sein Mitarbeiter Michael Rotert erhalten sie.","B1":"Am 3. August 1984 um 10:14 Uhr erhalten Professor Werner Zorn und Michael Rotert an der Universität Karlsruhe die erste E-Mail in Deutschland. Sie kommt von Laura Breeden aus den USA und heißt sie beim Computer-Netzwerk CSNET willkommen.","B2":"Am 3. August 1984 empfangen Werner Zorn und Michael Rotert an der Universität Karlsruhe die erste E-Mail Deutschlands — einen Willkommensgruß von Laura Breeden aus Boston zum CSNET-Netzwerk, einem Vorläufer des heutigen Internets. Deutschland wird damit neben Israel eines der ersten Länder außerhalb der USA im Netzwerk.","C1":"Der Empfang der ersten deutschen E-Mail am 3. August 1984 in Karlsruhe, ein knapper Willkommensgruß zum CSNET-Netzwerk, markiert einen unscheinbaren, aber folgenreichen Anfang: Aus diesem experimentellen Forschungsprojekt von Werner Zorn entwickelte sich binnen weniger Jahrzehnte eine der prägendsten Kommunikationstechnologien der Gegenwart.","C2":"Die erste deutsche E-Mail von 1984, technisch kaum mehr als ein bürokratischer Willkommensgruß, illustriert im Rückblick eindrücklich, wie unscheinbar epochale technologische Umbrüche oft beginnen — vom Nischenprojekt einiger Karlsruher Informatiker zu einer Kommunikationsform, ohne die sich das gesellschaftliche und wirtschaftliche Leben des 21. Jahrhunderts kaum noch denken lässt."},"translationsA1":{"en":"On August 3, 1984, the first email arrives in Germany. It comes from the USA, to Karlsruhe.","ar":"في 3 أغسطس 1984، وصلت أول رسالة بريد إلكتروني إلى ألمانيا. جاءت من الولايات المتحدة، إلى كارلسروه.","tr":"3 Ağustos 1984'te Almanya'ya ilk e-posta ulaştı. ABD'den, Karlsruhe'ye geldi.","ru":"3 августа 1984 года в Германию пришло первое электронное письмо. Оно пришло из США в Карлсруэ.","es":"El 3 de agosto de 1984, llega el primer correo electrónico a Alemania. Viene de EE. UU., a Karlsruhe.","fr":"Le 3 août 1984, le premier e-mail arrive en Allemagne. Il vient des États-Unis, à Karlsruhe.","pl":"3 sierpnia 1984 roku do Niemiec dotarł pierwszy e-mail. Przyszedł z USA, do Karlsruhe.","uk":"3 серпня 1984 року до Німеччини прийшов перший електронний лист. Він прийшов зі США до Карлсруе.","fa":"در ۳ اوت ۱۹۸۴، اولین ایمیل به آلمان رسید. این ایمیل از آمریکا به کارلسروهه آمد.","it":"Il 3 agosto 1984 arriva la prima e-mail in Germania. Arriva dagli Stati Uniti, a Karlsruhe."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 3, 1984, the first email in Germany arrives at the University of Karlsruhe. Professor Werner Zorn and his colleague Michael Rotert receive it.","ar":"في 3 أغسطس 1984 تصل أول رسالة بريد إلكتروني في ألمانيا إلى جامعة كارلسروه. يستلمها البروفيسور فيرنر تسورن ومساعده ميشائيل روتيرت.","tr":"3 Ağustos 1984'te Almanya'nın ilk e-postası Karlsruhe Üniversitesi'ne ulaşır. Profesör Werner Zorn ve çalışma arkadaşı Michael Rotert onu alır.","ru":"3 августа 1984 года в университет Карлсруэ приходит первое электронное письмо в Германии. Его получают профессор Вернер Цорн и его сотрудник Михаэль Ротерт.","es":"El 3 de agosto de 1984 llega a la Universidad de Karlsruhe el primer correo electrónico de Alemania. Lo reciben el profesor Werner Zorn y su colaborador Michael Rotert.","fr":"Le 3 août 1984, le premier e-mail d'Allemagne arrive à l'université de Karlsruhe. Le professeur Werner Zorn et son collaborateur Michael Rotert le reçoivent.","pl":"3 sierpnia 1984 roku na Uniwersytet w Karlsruhe dociera pierwszy e-mail w Niemczech. Odbierają go profesor Werner Zorn i jego współpracownik Michael Rotert.","uk":"3 серпня 1984 року до Університету Карлсруе надходить перший електронний лист у Німеччині. Його отримують професор Вернер Цорн та його співробітник Міхаель Ротерт.","fa":"در ۳ اوت ۱۹۸۴ نخستین ایمیل آلمان به دانشگاه کارلسروهه می‌رسد. پروفسور ورنر تسورن و همکارش میشائیل روترت آن را دریافت می‌کنند.","it":"Il 3 agosto 1984 arriva all'Università di Karlsruhe la prima e-mail in Germania. La ricevono il professor Werner Zorn e il suo collaboratore Michael Rotert."},"B1":{"en":"On August 3, 1984, at 10:14 a.m., Professor Werner Zorn and Michael Rotert receive the first email in Germany at the University of Karlsruhe. It comes from Laura Breeden in the USA and welcomes them to the CSNET computer network.","ar":"في 3 أغسطس 1984 الساعة 10:14 صباحاً، يستلم البروفيسور فيرنر تسورن وميشائيل روتيرت في جامعة كارلسروه أول رسالة بريد إلكتروني في ألمانيا. وصلت من لورا بريدن من الولايات المتحدة، وترحب بهما في شبكة الحاسوب CSNET.","tr":"3 Ağustos 1984 saat 10:14'te, Profesör Werner Zorn ve Michael Rotert Karlsruhe Üniversitesi'nde Almanya'nın ilk e-postasını alır. E-posta, ABD'den Laura Breeden'dan gelir ve onları CSNET bilgisayar ağına hoş geldin der.","ru":"3 августа 1984 года в 10:14 профессор Вернер Цорн и Михаэль Ротерт получают в университете Карлсруэ первое электронное письмо в Германии. Оно приходит от Лауры Бридн из США и приветствует их в компьютерной сети CSNET.","es":"El 3 de agosto de 1984, a las 10:14, el profesor Werner Zorn y Michael Rotert reciben en la Universidad de Karlsruhe el primer correo electrónico de Alemania. Proviene de Laura Breeden, de Estados Unidos, y les da la bienvenida a la red informática CSNET.","fr":"Le 3 août 1984 à 10h14, le professeur Werner Zorn et Michael Rotert reçoivent à l'université de Karlsruhe le premier e-mail d'Allemagne. Il vient de Laura Breeden, aux États-Unis, et leur souhaite la bienvenue sur le réseau informatique CSNET.","pl":"3 sierpnia 1984 roku o godzinie 10:14 profesor Werner Zorn i Michael Rotert odbierają na Uniwersytecie w Karlsruhe pierwszy e-mail w Niemczech. Pochodzi od Laury Breeden ze Stanów Zjednoczonych i wita ich w sieci komputerowej CSNET.","uk":"3 серпня 1984 року о 10:14 професор Вернер Цорн і Міхаель Ротерт отримують в Університеті Карлсруе перший електронний лист у Німеччині. Він надійшов від Лори Бріден зі США і вітає їх у комп'ютерній мережі CSNET.","fa":"در ۳ اوت ۱۹۸۴ ساعت ۱۰:۱۴، پروفسور ورنر تسورن و میشائیل روترت در دانشگاه کارلسروهه نخستین ایمیل آلمان را دریافت می‌کنند. این پیام از سوی لورا بریدن از ایالات متحده آمده و آن‌ها را به شبکه رایانه‌ای سی‌اس‌نت خوش‌آمد می‌گوید.","it":"Il 3 agosto 1984, alle ore 10:14, il professor Werner Zorn e Michael Rotert ricevono all'Università di Karlsruhe la prima e-mail in Germania. Arriva da Laura Breeden, dagli Stati Uniti, e li accoglie nella rete informatica CSNET."},"B2":{"en":"On August 3, 1984, Werner Zorn and Michael Rotert receive Germany's first email at the University of Karlsruhe — a welcome message from Laura Breeden in Boston to the CSNET network, a precursor of today's internet. Germany thus becomes, alongside Israel, one of the first countries outside the USA to join the network.","ar":"في 3 أغسطس 1984 يستلم فيرنر تسورن وميشائيل روتيرت في جامعة كارلسروه أول رسالة بريد إلكتروني في ألمانيا — رسالة ترحيب من لورا بريدن من بوسطن بشبكة CSNET، إحدى مقدمات الإنترنت الحالي. وبذلك تصبح ألمانيا، إلى جانب إسرائيل، من أوائل الدول خارج الولايات المتحدة المنضمة إلى الشبكة.","tr":"3 Ağustos 1984'te Werner Zorn ve Michael Rotert, Karlsruhe Üniversitesi'nde Almanya'nın ilk e-postasını alır — bugünkü internetin öncüsü olan CSNET ağına Boston'dan Laura Breeden'ın gönderdiği bir hoş geldin mesajı. Böylece Almanya, İsrail'in yanı sıra ağa katılan ABD dışındaki ilk ülkelerden biri olur.","ru":"3 августа 1984 года Вернер Цорн и Михаэль Ротерт получают в университете Карлсруэ первое электронное письмо Германии — приветственное сообщение от Лауры Бридн из Бостона в сеть CSNET, предшественницу сегодняшнего интернета. Тем самым Германия, наряду с Израилем, становится одной из первых стран за пределами США в этой сети.","es":"El 3 de agosto de 1984, Werner Zorn y Michael Rotert reciben en la Universidad de Karlsruhe el primer correo electrónico de Alemania: un saludo de bienvenida de Laura Breeden desde Boston a la red CSNET, precursora de internet. Alemania se convierte así, junto con Israel, en uno de los primeros países fuera de EE. UU. en integrarse a la red.","fr":"Le 3 août 1984, Werner Zorn et Michael Rotert reçoivent à l'université de Karlsruhe le premier e-mail d'Allemagne — un message de bienvenue de Laura Breeden, depuis Boston, pour le réseau CSNET, précurseur de l'internet actuel. L'Allemagne devient ainsi, aux côtés d'Israël, l'un des premiers pays hors des États-Unis à rejoindre ce réseau.","pl":"3 sierpnia 1984 roku Werner Zorn i Michael Rotert odbierają na Uniwersytecie w Karlsruhe pierwszy e-mail w Niemczech — powitalną wiadomość od Laury Breeden z Bostonu do sieci CSNET, poprzedniczki dzisiejszego internetu. Niemcy stają się tym samym, obok Izraela, jednym z pierwszych krajów poza USA w tej sieci.","uk":"3 серпня 1984 року Вернер Цорн і Міхаель Ротерт отримують в Університеті Карлсруе перший електронний лист Німеччини — вітальне повідомлення від Лори Бріден з Бостона до мережі CSNET, попередниці сучасного інтернету. Таким чином Німеччина, поряд з Ізраїлем, стає однією з перших країн поза межами США в цій мережі.","fa":"در ۳ اوت ۱۹۸۴ ورنر تسورن و میشائیل روترت در دانشگاه کارلسروهه نخستین ایمیل آلمان را دریافت می‌کنند — پیام خوش‌آمدگویی از سوی لورا بریدن از بوستون به شبکه سی‌اس‌نت، پیشگام اینترنت امروزی. بدین‌ترتیب آلمان در کنار اسرائیل یکی از نخستین کشورهای خارج از ایالات متحده در این شبکه می‌شود.","it":"Il 3 agosto 1984 Werner Zorn e Michael Rotert ricevono all'Università di Karlsruhe la prima e-mail della Germania: un saluto di benvenuto di Laura Breeden da Boston per la rete CSNET, precursore dell'odierno Internet. La Germania diventa così, insieme a Israele, uno dei primi paesi al di fuori degli USA a entrare nella rete."},"C1":{"en":"The receipt of Germany's first email on August 3, 1984, in Karlsruhe — a brief welcome message to the CSNET network — marks an inconspicuous yet consequential beginning: within a few decades, this experimental research project of Werner Zorn's grew into one of the most defining communication technologies of our time.","ar":"يمثل استلام أول رسالة بريد إلكتروني ألمانية في 3 أغسطس 1984 بمدينة كارلسروه، وهي رسالة ترحيب مقتضبة بشبكة CSNET، بداية غير لافتة لكنها بعيدة الأثر: فمن هذا المشروع البحثي التجريبي لفيرنر تسورن تطورت خلال عقود قليلة إحدى أهم تقنيات الاتصال المعاصرة.","tr":"3 Ağustos 1984'te Karlsruhe'de alınan ilk Alman e-postası — CSNET ağına kısa bir hoş geldin mesajı — göze çarpmayan ama sonuçları büyük bir başlangıcı işaret eder: Werner Zorn'un bu deneysel araştırma projesinden birkaç on yıl içinde günümüzün en belirleyici iletişim teknolojilerinden biri doğdu.","ru":"Получение первого немецкого электронного письма 3 августа 1984 года в Карлсруэ — краткого приветствия в сети CSNET — знаменует собой неприметное, но чреватое последствиями начало: из этого экспериментального исследовательского проекта Вернера Цорна за несколько десятилетий выросла одна из самых определяющих коммуникационных технологий современности.","es":"La recepción del primer correo electrónico alemán el 3 de agosto de 1984 en Karlsruhe —un breve saludo de bienvenida a la red CSNET— marca un comienzo discreto pero trascendental: de este proyecto de investigación experimental de Werner Zorn surgió, en pocas décadas, una de las tecnologías de comunicación más determinantes de nuestro tiempo.","fr":"La réception du premier e-mail allemand le 3 août 1984 à Karlsruhe — un bref message de bienvenue sur le réseau CSNET — marque un début discret mais lourd de conséquences : de ce projet de recherche expérimental de Werner Zorn est née, en quelques décennies, l'une des technologies de communication les plus marquantes de notre époque.","pl":"Odebranie pierwszego niemieckiego e-maila 3 sierpnia 1984 roku w Karlsruhe — krótkiego powitania w sieci CSNET — wyznacza niepozorny, lecz brzemienny w skutki początek: z tego eksperymentalnego projektu badawczego Wernera Zorna w ciągu kilku dekad wykształciła się jedna z najbardziej przełomowych technologii komunikacyjnych współczesności.","uk":"Отримання першого німецького електронного листа 3 серпня 1984 року в Карлсруе — короткого вітання в мережі CSNET — знаменує непомітний, але доленосний початок: із цього експериментального дослідницького проєкту Вернера Цорна за кілька десятиліть виросла одна з найвизначальніших комунікаційних технологій сучасності.","fa":"دریافت نخستین ایمیل آلمانی در ۳ اوت ۱۹۸۴ در کارلسروهه — پیامی کوتاه از خوش‌آمدگویی به شبکه سی‌اس‌نت — آغازی کم‌جلوه اما پرپیامد را رقم می‌زند: از این پروژه پژوهشی آزمایشی ورنر تسورن، طی چند دهه یکی از تعیین‌کننده‌ترین فناوری‌های ارتباطی روزگار ما پدید آمد.","it":"La ricezione della prima e-mail tedesca il 3 agosto 1984 a Karlsruhe, un breve saluto di benvenuto per la rete CSNET, segna un inizio modesto ma denso di conseguenze: da questo progetto di ricerca sperimentale di Werner Zorn si sviluppò, nel giro di pochi decenni, una delle tecnologie di comunicazione più significative del presente."},"C2":{"en":"Germany's first email from 1984, technically little more than a bureaucratic welcome note, illustrates in retrospect how inconspicuously epochal technological upheavals often begin — from a niche project of a few Karlsruhe computer scientists to a form of communication without which the social and economic life of the 21st century can scarcely be imagined.","ar":"أول رسالة بريد إلكتروني ألمانية من عام 1984، التي لم تكن تقنياً أكثر من ترحيب بيروقراطي، توضح بأثر رجعي بجلاء كم تبدأ التحولات التكنولوجية الكبرى غالباً بشكل متواضع — من مشروع محدود لبضعة علماء حاسوب في كارلسروه إلى شكل اتصال يصعب تصور الحياة الاجتماعية والاقتصادية للقرن الحادي والعشرين من دونه.","tr":"1984'ten kalma ilk Alman e-postası, teknik olarak bürokratik bir hoş geldin notundan pek fazlası değildi; geriye dönüp bakıldığında, çağ açan teknolojik dönüşümlerin çoğu zaman ne kadar sıradan başladığını çarpıcı biçimde göstermektedir — birkaç Karlsruhelu bilgisayar bilimcisinin niş projesinden, 21. yüzyılın toplumsal ve ekonomik yaşamının artık neredeyse düşünülemeyeceği bir iletişim biçimine.","ru":"Первое немецкое электронное письмо 1984 года, технически представлявшее собой немногим больше бюрократического приветствия, наглядно демонстрирует задним числом, насколько неприметно нередко начинаются эпохальные технологические перевороты — от нишевого проекта нескольких карлсруйских информатиков до формы коммуникации, без которой едва ли можно представить общественную и экономическую жизнь XXI века.","es":"El primer correo electrónico alemán de 1984, técnicamente poco más que un saludo burocrático de bienvenida, ilustra retrospectivamente de manera elocuente lo discretos que suelen ser los inicios de las transformaciones tecnológicas de época: de un proyecto marginal de unos pocos informáticos de Karlsruhe a una forma de comunicación sin la cual apenas puede concebirse la vida social y económica del siglo XXI.","fr":"Le premier e-mail allemand de 1984, techniquement guère plus qu'un mot de bienvenue bureaucratique, illustre rétrospectivement de façon frappante combien les bouleversements technologiques d'une époque commencent souvent discrètement — d'un projet de niche mené par quelques informaticiens de Karlsruhe à une forme de communication sans laquelle la vie sociale et économique du XXIe siècle serait aujourd'hui difficilement concevable.","pl":"Pierwszy niemiecki e-mail z 1984 roku, technicznie niewiele więcej niż biurokratyczne powitanie, retrospektywnie dobitnie pokazuje, jak niepozornie zaczynają się często epokowe przełomy technologiczne — od niszowego projektu kilku informatyków z Karlsruhe do formy komunikacji, bez której trudno dziś wyobrazić sobie życie społeczne i gospodarcze XXI wieku.","uk":"Перший німецький електронний лист 1984 року, технічно не набагато більший за бюрократичне вітання, ретроспективно яскраво показує, наскільки непомітно часто починаються епохальні технологічні зрушення — від нішевого проєкту кількох карлсруенських інформатиків до форми комунікації, без якої важко уявити суспільне та економічне життя XXI століття.","fa":"نخستین ایمیل آلمانی از سال ۱۹۸۴، که از نظر فنی چیزی بیش از یک یادداشت خوش‌آمدگویی اداری نبود، به‌طرز گویایی نشان می‌دهد که چگونه تحولات فناورانه‌ی دوران‌ساز غالباً بی‌سروصدا آغاز می‌شوند — از یک پروژه‌ی حاشیه‌ای چند دانشمند رایانه در کارلسروهه تا شکلی از ارتباط که بدون آن زندگی اجتماعی و اقتصادی قرن بیست‌ویکم به‌سختی قابل تصور است.","it":"La prima e-mail tedesca del 1984, tecnicamente poco più di un saluto burocratico di benvenuto, mostra in retrospettiva in modo impressionante quanto modestamente iniziano spesso le svolte tecnologiche epocali: da progetto di nicchia di alcuni informatici di Karlsruhe a forma di comunicazione senza la quale la vita sociale ed economica del ventunesimo secolo sarebbe difficilmente immaginabile."}}},"08-04":{"year":1929,"levels":{"A1":"Am 4. August 1929 stirbt Carl Auer von Welsbach. Er macht das Gaslicht viel heller. Später erfindet er auch den Stein im Feuerzeug.","A2":"Am 4. August 1929 stirbt der Chemiker Carl Auer von Welsbach. Sein Glühstrumpf machte Gaslampen zehnmal heller. Von ihm stammt auch der kleine Zündstein im Feuerzeug.","B1":"Am 4. August 1929 stirbt Carl Auer von Welsbach. Sein Glühstrumpf rettete das Gaslicht für zwei weitere Jahrzehnte, als die Elektrizität schon anrückte. Der Zündstein in jedem Feuerzeug geht ebenfalls auf ihn zurück.","B2":"Am 4. August 1929 stirbt Auer von Welsbach. Sein Fall zeigt ein häufiges Muster: Eine ablösungsreife Technik wird durch eine Verbesserung noch einmal wettbewerbsfähig. Das Gaslicht verschwand nicht, weil es schlecht war, sondern weil die elektrische Infrastruktur schließlich billiger wurde.","C1":"Der am 4. August 1929 Gestorbene arbeitete mit den Seltenen Erden, als deren Nutzen noch niemand absah. Sein Glühstrumpf machte aus einem Laborstoff ein Massenprodukt — dieselben Elemente stecken heute in Bildschirmen, Magneten und Batterien.","C2":"An Auer von Welsbach, gestorben am 4. August 1929, lässt sich die Dynamik konkurrierender Techniken studieren. Eine bedrohte Technik reagiert oft mit ihrer stärksten Innovation — und verlängert damit ihre Lebensdauer, ohne den Ausgang zu ändern. Verdrängungsprozesse verlaufen deshalb selten linear, sondern in Wellen von Verbesserung und plötzlichem Abbruch."},"translationsA1":{"en":"On August 4, 1929, Carl Auer von Welsbach dies. He makes gaslight far brighter. Later he also invents the flint in the lighter.","ar":"في 4 أغسطس 1929، توفي كارل أور فون فيلسباخ. جعل ضوء الغاز أشد سطوعًا. ولاحقًا ابتكر أيضًا حجر القداحة.","tr":"4 Ağustos 1929'da Carl Auer von Welsbach öldü. Gaz ışığını çok daha parlak yaptı. Sonra çakmak taşını da buldu.","ru":"4 августа 1929 года умер Карл Ауэр фон Вельсбах. Он сделал газовый свет намного ярче. Позже он изобрёл и кремень для зажигалки.","es":"El 4 de agosto de 1929 muere Carl Auer von Welsbach. Hace que la luz de gas sea mucho más brillante. Después inventa también la piedra del mechero.","fr":"Le 4 août 1929, Carl Auer von Welsbach meurt. Il rend la lumière au gaz bien plus vive. Plus tard, il invente aussi la pierre à briquet.","pl":"4 sierpnia 1929 roku zmarł Carl Auer von Welsbach. Sprawił, że światło gazowe stało się dużo jaśniejsze. Później wynalazł też kamień do zapalniczki.","uk":"4 серпня 1929 року помер Карл Ауер фон Вельсбах. Він зробив газове світло набагато яскравішим. Пізніше він винайшов і кремінь для запальнички.","fa":"در ۴ اوت ۱۹۲۹، کارل آوئر فون ولسباخ درگذشت. او نور گاز را بسیار روشن‌تر کرد. بعدها سنگ فندک را نیز ابداع کرد.","it":"Il 4 agosto 1929 muore Carl Auer von Welsbach. Rende la luce a gas molto più intensa. In seguito inventa anche la pietrina dell'accendino."},"translationsByLevel":{"A2":{"en":"On August 4, 1929, the chemist Carl Auer von Welsbach dies. His gas mantle made gas lamps ten times brighter. The small flint in cigarette lighters also comes from him.","ar":"في 4 أغسطس 1929 يتوفى الكيميائي كارل أوير فون فيلسباخ. جعلت شبكيته المتوهجة مصابيح الغاز أكثر سطوعاً بعشر مرات. ويعود إليه أيضاً حجر الصوان الصغير في الولاعة.","tr":"4 Ağustos 1929'da kimyager Carl Auer von Welsbach hayatını kaybeder. Onun geliştirdiği gaz lambası fitili, gaz lambalarını on kat daha aydınlık yaptı. Çakmaktaki küçük çakmaktaşı da ondan gelir.","ru":"4 августа 1929 года умирает химик Карл Ауэр фон Вельсбах. Его газокалильная сетка сделала газовые лампы в десять раз ярче. От него же происходит и маленький кремень в зажигалке.","es":"El 4 de agosto de 1929 muere el químico Carl Auer von Welsbach. Su camisa incandescente hizo que las lámparas de gas fueran diez veces más brillantes. También se le debe la pequeña piedra de encendedor.","fr":"Le 4 août 1929, le chimiste Carl Auer von Welsbach meurt. Son manchon à incandescence rendait les lampes à gaz dix fois plus lumineuses. La petite pierre à briquet lui doit également son existence.","pl":"4 sierpnia 1929 roku umiera chemik Carl Auer von Welsbach. Jego koszulka żarowa sprawiła, że lampy gazowe świeciły dziesięć razy jaśniej. Od niego pochodzi też mały kamień krzemienny w zapalniczce.","uk":"4 серпня 1929 року помирає хімік Карл Ауер фон Вельсбах. Його газокалільна сітка зробила газові лампи в десять разів яскравішими. Від нього ж походить і маленький кремінь у запальничці.","fa":"در ۴ اوت ۱۹۲۹ شیمی‌دان کارل آوئر فون ولسباخ درگذشت. توری گرمازای او چراغ‌های گازی را ده برابر روشن‌تر کرد. سنگ کوچک چخماق فندک نیز از اوست.","it":"Il 4 agosto 1929 muore il chimico Carl Auer von Welsbach. La sua reticella incandescente rese le lampade a gas dieci volte più luminose. A lui si deve anche la piccola pietrina dell'accendino."},"B1":{"en":"On August 4, 1929, Carl Auer von Welsbach dies. His gas mantle saved gaslight for two more decades, even as electricity was already advancing. The flint in every cigarette lighter also traces back to him.","ar":"في 4 أغسطس 1929 يتوفى كارل أوير فون فيلسباخ. أنقذت شبكيته المتوهجة إنارة الغاز لعقدين إضافيين، في وقت كانت الكهرباء تتقدم فيه بالفعل. ويعود حجر الصوان في كل ولاعة إليه أيضاً.","tr":"4 Ağustos 1929'da Carl Auer von Welsbach hayatını kaybeder. Onun gaz lambası fitili, elektrik zaten ilerlerken gaz ışığını iki on yıl daha kurtardı. Her çakmaktaki çakmaktaşı da ona dayanır.","ru":"4 августа 1929 года умирает Карл Ауэр фон Вельсбах. Его газокалильная сетка спасла газовое освещение ещё на два десятилетия, когда электричество уже наступало. Кремень в каждой зажигалке также восходит к нему.","es":"El 4 de agosto de 1929 muere Carl Auer von Welsbach. Su camisa incandescente salvó la iluminación de gas por dos décadas más, cuando la electricidad ya avanzaba. La piedra de cada encendedor también se remonta a él.","fr":"Le 4 août 1929, Carl Auer von Welsbach meurt. Son manchon à incandescence a sauvé l'éclairage au gaz pendant deux décennies supplémentaires, alors que l'électricité progressait déjà. La pierre de chaque briquet lui doit aussi son origine.","pl":"4 sierpnia 1929 roku umiera Carl Auer von Welsbach. Jego koszulka żarowa uratowała oświetlenie gazowe na kolejne dwie dekady, gdy elektryczność już nadciągała. Kamień krzemienny w każdej zapalniczce również pochodzi od niego.","uk":"4 серпня 1929 року помирає Карл Ауер фон Вельсбах. Його газокалільна сітка врятувала газове освітлення ще на два десятиліття, коли електрика вже наступала. Кремінь у кожній запальничці також походить від нього.","fa":"در ۴ اوت ۱۹۲۹ کارل آوئر فون ولسباخ درگذشت. توری گرمازای او روشنایی گازی را برای دو دهه دیگر نجات داد، در حالی که برق پیش‌تر در حال پیشروی بود. سنگ چخماق در هر فندکی نیز به او برمی‌گردد.","it":"Il 4 agosto 1929 muore Carl Auer von Welsbach. La sua reticella incandescente salvò l'illuminazione a gas per altri due decenni, mentre l'elettricità già avanzava. Anche la pietrina di ogni accendino risale a lui."},"B2":{"en":"On August 4, 1929, Auer von Welsbach dies. His case illustrates a common pattern: a technology ripe for replacement becomes competitive once again through an improvement. Gaslight did not disappear because it was bad, but because the electrical infrastructure eventually became cheaper.","ar":"في 4 أغسطس 1929 يتوفى أوير فون فيلسباخ. تُظهر حالته نمطاً شائعاً: التقنية التي نضج استبدالها تعود قادرة على المنافسة بفضل تحسين جديد. لم يختفِ ضوء الغاز لأنه كان سيئاً، بل لأن البنية التحتية الكهربائية أصبحت في النهاية أرخص.","tr":"4 Ağustos 1929'da Auer von Welsbach hayatını kaybeder. Onun durumu yaygın bir örüntüyü gösterir: Değiştirilmeye hazır bir teknoloji, bir iyileştirmeyle yeniden rekabetçi hale gelir. Gaz ışığı kötü olduğu için değil, elektrik altyapısı sonunda daha ucuz hale geldiği için ortadan kalktı.","ru":"4 августа 1929 года умирает Ауэр фон Вельсбах. Его случай показывает распространённую закономерность: технология, готовая к замене, благодаря усовершенствованию снова становится конкурентоспособной. Газовое освещение исчезло не потому, что было плохим, а потому, что электрическая инфраструктура со временем стала дешевле.","es":"El 4 de agosto de 1929 muere Auer von Welsbach. Su caso ilustra un patrón frecuente: una tecnología madura para ser sustituida vuelve a ser competitiva gracias a una mejora. La luz de gas no desapareció porque fuera mala, sino porque la infraestructura eléctrica finalmente se volvió más barata.","fr":"Le 4 août 1929, Auer von Welsbach meurt. Son cas illustre un schéma fréquent : une technologie mûre pour être remplacée redevient compétitive grâce à une amélioration. L'éclairage au gaz n'a pas disparu parce qu'il était mauvais, mais parce que l'infrastructure électrique est finalement devenue moins chère.","pl":"4 sierpnia 1929 roku umiera Auer von Welsbach. Jego przypadek pokazuje częsty wzorzec: technologia dojrzała do zastąpienia staje się dzięki udoskonaleniu ponownie konkurencyjna. Światło gazowe nie zniknęło, bo było złe, lecz dlatego, że infrastruktura elektryczna z czasem stała się tańsza.","uk":"4 серпня 1929 року помирає Ауер фон Вельсбах. Його випадок демонструє поширену закономірність: технологія, готова до заміни, завдяки вдосконаленню знову стає конкурентоспроможною. Газове освітлення зникло не тому, що було поганим, а тому, що електрична інфраструктура зрештою стала дешевшою.","fa":"در ۴ اوت ۱۹۲۹ آوئر فون ولسباخ درگذشت. سرگذشت او الگویی رایج را نشان می‌دهد: فناوری‌ای که آماده‌ی جایگزینی است، با یک بهبود بار دیگر رقابت‌پذیر می‌شود. روشنایی گازی از میان نرفت چون بد بود، بلکه از آن‌رو که زیرساخت برق سرانجام ارزان‌تر شد.","it":"Il 4 agosto 1929 muore Auer von Welsbach. Il suo caso mostra uno schema ricorrente: una tecnologia ormai matura per essere sostituita torna competitiva grazie a un miglioramento. La luce a gas non scomparve perché era scadente, ma perché l'infrastruttura elettrica alla fine divenne più economica."},"C1":{"en":"The man who died on August 4, 1929, worked with rare earth elements at a time when no one yet foresaw their usefulness. His gas mantle turned a laboratory substance into a mass product — the very same elements are found today in screens, magnets, and batteries.","ar":"عمل المتوفى في 4 أغسطس 1929 بالعناصر الأرضية النادرة في وقت لم يكن أحد يتوقع فائدتها. حوّلت شبكيته المتوهجة مادة مخبرية إلى منتج جماهيري — وتوجد نفس هذه العناصر اليوم في الشاشات والمغناطيسات والبطاريات.","tr":"4 Ağustos 1929'da hayatını kaybeden kişi, faydası henüz kimse tarafından öngörülemeyen nadir toprak elementleriyle çalışıyordu. Onun gaz lambası fitili bir laboratuvar maddesini kitlesel bir ürüne dönüştürdü — aynı elementler bugün ekranlarda, mıknatıslarda ve pillerde bulunuyor.","ru":"Умерший 4 августа 1929 года работал с редкоземельными элементами тогда, когда их пользы ещё никто не предвидел. Его газокалильная сетка превратила лабораторное вещество в массовый продукт — те же элементы сегодня используются в экранах, магнитах и батареях.","es":"El fallecido el 4 de agosto de 1929 trabajaba con las tierras raras cuando nadie aún preveía su utilidad. Su camisa incandescente convirtió una sustancia de laboratorio en un producto de masas: los mismos elementos se encuentran hoy en pantallas, imanes y baterías.","fr":"Celui qui est mort le 4 août 1929 travaillait sur les terres rares alors que personne n'en soupçonnait encore l'utilité. Son manchon à incandescence a transformé une substance de laboratoire en produit de masse — les mêmes éléments se retrouvent aujourd'hui dans les écrans, les aimants et les batteries.","pl":"Zmarły 4 sierpnia 1929 roku pracował z metalami ziem rzadkich, gdy nikt jeszcze nie przewidywał ich przydatności. Jego koszulka żarowa zmieniła substancję laboratoryjną w produkt masowy — te same elementy znajdują się dziś w ekranach, magnesach i bateriach.","uk":"Померлий 4 серпня 1929 року працював із рідкісноземельними елементами тоді, коли їхньої користі ще ніхто не передбачав. Його газокалільна сітка перетворила лабораторну речовину на масовий продукт — ті самі елементи сьогодні використовуються в екранах, магнітах і батареях.","fa":"کسی که در ۴ اوت ۱۹۲۹ درگذشت با عناصر خاکی کمیاب کار می‌کرد، در زمانی که هیچ‌کس هنوز کاربرد آن‌ها را پیش‌بینی نمی‌کرد. توری گرمازای او یک ماده‌ی آزمایشگاهی را به محصولی انبوه تبدیل کرد — همان عناصر امروز در صفحه‌نمایش‌ها، آهنرباها و باتری‌ها یافت می‌شوند.","it":"Morto il 4 agosto 1929, lavorò con le terre rare quando ancora nessuno ne prevedeva l'utilità. La sua reticella incandescente trasformò una sostanza da laboratorio in un prodotto di massa: gli stessi elementi si trovano oggi negli schermi, nei magneti e nelle batterie."},"C2":{"en":"Auer von Welsbach, who died on August 4, 1929, offers a case study in the dynamics of competing technologies. A threatened technology often responds with its strongest innovation yet — thereby extending its lifespan without changing the eventual outcome. Displacement processes therefore rarely proceed in a straight line, but rather in waves of improvement followed by sudden breakdown.","ar":"يتيح أوير فون فيلسباخ، المتوفى في 4 أغسطس 1929، دراسة ديناميكية التقنيات المتنافسة. غالباً ما تستجيب تقنية مهددة بأقوى ابتكار لديها — فتمدد بذلك عمرها دون تغيير النتيجة النهائية. لهذا تسير عمليات الإزاحة نادراً بشكل خطي، بل في موجات من التحسين والانهيار المفاجئ.","tr":"4 Ağustos 1929'da ölen Auer von Welsbach üzerinden, rekabet eden teknolojilerin dinamiği incelenebilir. Tehdit altındaki bir teknoloji genellikle en güçlü yeniliğiyle karşılık verir — böylece sonucu değiştirmeden ömrünü uzatır. Bu nedenle yerinden edilme süreçleri nadiren doğrusal ilerler, daha çok iyileştirme ve ani kopuş dalgaları hâlinde gerçekleşir.","ru":"На примере Ауэра фон Вельсбаха, умершего 4 августа 1929 года, можно изучать динамику конкурирующих технологий. Технология под угрозой часто отвечает своей самой сильной инновацией — тем самым продлевая свой срок жизни, но не меняя итоговый исход. Поэтому процессы вытеснения редко идут линейно, а происходят волнами улучшений и внезапных обвалов.","es":"En Auer von Welsbach, fallecido el 4 de agosto de 1929, puede estudiarse la dinámica de las tecnologías en competencia. Una tecnología amenazada suele responder con su innovación más potente, prolongando así su vida útil sin cambiar el resultado final. Por eso los procesos de desplazamiento rara vez son lineales, sino que avanzan en oleadas de mejora seguidas de un colapso repentino.","fr":"Chez Auer von Welsbach, mort le 4 août 1929, on peut étudier la dynamique des technologies concurrentes. Une technologie menacée réagit souvent par sa plus forte innovation — prolongeant ainsi sa durée de vie sans en changer l'issue. Les processus de substitution ne se déroulent donc rarement de façon linéaire, mais par vagues d'amélioration suivies d'un effondrement soudain.","pl":"Na przykładzie Auera von Welsbacha, zmarłego 4 sierpnia 1929 roku, można studiować dynamikę konkurujących technologii. Zagrożona technologia często odpowiada swoją najsilniejszą innowacją — wydłużając tym samym swój żywot, bez zmiany ostatecznego wyniku. Procesy wypierania rzadko przebiegają więc linearnie, lecz w falach udoskonaleń i nagłego załamania.","uk":"На прикладі Ауера фон Вельсбаха, який помер 4 серпня 1929 року, можна вивчати динаміку конкуруючих технологій. Технологія під загрозою часто відповідає своєю найпотужнішою інновацією — тим самим продовжуючи свій вік без зміни кінцевого результату. Тому процеси витіснення рідко відбуваються лінійно, а хвилями вдосконалень і раптового обвалу.","fa":"در سرگذشت آوئر فون ولسباخ، که در ۴ اوت ۱۹۲۹ درگذشت، می‌توان دینامیک فناوری‌های رقیب را بررسی کرد. یک فناوری در معرض تهدید غالباً با قوی‌ترین نوآوری خود پاسخ می‌دهد — و بدین‌سان عمر خود را طولانی‌تر می‌کند، بدون آنکه نتیجه‌ی نهایی را تغییر دهد. از این‌رو فرایندهای جابه‌جایی به‌ندرت خطی پیش می‌روند، بلکه در امواجی از بهبود و فروپاشی ناگهانی رخ می‌دهند.","it":"Nel caso di Auer von Welsbach, morto il 4 agosto 1929, si può studiare la dinamica delle tecnologie in concorrenza tra loro. Una tecnologia minacciata reagisce spesso con la sua innovazione più forte, prolungando così la propria durata senza cambiarne l'esito finale. I processi di sostituzione procedono perciò raramente in modo lineare, ma a ondate di miglioramento e brusca interruzione."}},"sideFacts":[]},"08-05":{"year":1895,"levels":{"A1":"Am 5. August 1895 stirbt Friedrich Engels. Er kommt aus Wuppertal. Er schreibt zusammen mit Karl Marx wichtige Bücher.","A2":"Am 5. August 1895 stirbt Friedrich Engels. Er stammte aus einer Fabrikantenfamilie in Wuppertal und leitete selbst eine Fabrik. Zugleich schrieb er über die Not der Arbeiter.","B1":"Am 5. August 1895 stirbt Friedrich Engels. Er beschrieb 1845 die Lage der arbeitenden Klasse in England so genau, dass sein Buch bis heute als Quelle dient. Sein Geld aus der Textilfabrik finanzierte jahrzehntelang die Arbeit von Karl Marx.","B2":"Am 5. August 1895 stirbt Friedrich Engels. Sein Leben enthält einen offenen Widerspruch: Er kritisierte den Fabrikkapitalismus und lebte von den Erträgen einer Fabrik. Er hat das nie verschwiegen — es machte seine Beschreibungen genauer als jede Beobachtung von außen.","C1":"Der am 5. August 1895 Gestorbene ordnete nach Marx' Tod dessen unfertige Manuskripte und gab sie heraus. Damit prägte er entscheidend, welche Fassung als das Werk gilt. Herausgeberschaft ist bei nachgelassenen Schriften nie eine bloß technische Tätigkeit.","C2":"An Engels, gestorben am 5. August 1895, lässt sich fragen, wie viel Deutungsmacht in der Edition steckt. Er entschied über Auswahl, Reihenfolge und Titel dessen, was als Hauptwerk des Marxismus gilt. Spätere Debatten darüber, was Marx wirklich meinte, verhandeln deshalb immer auch Engels' redaktionelle Entscheidungen mit."},"translationsA1":{"en":"On August 5, 1895, Friedrich Engels dies. He comes from Wuppertal. Together with Karl Marx he writes important books.","ar":"في 5 أغسطس 1895، توفي فريدريش إنغلز. كان من فوبرتال. كتب مع كارل ماركس كتبًا مهمة.","tr":"5 Ağustos 1895'te Friedrich Engels öldü. Wuppertal'dendi. Karl Marx ile birlikte önemli kitaplar yazdı.","ru":"5 августа 1895 года умер Фридрих Энгельс. Он был родом из Вупперталя. Вместе с Карлом Марксом он написал важные книги.","es":"El 5 de agosto de 1895 muere Friedrich Engels. Es de Wuppertal. Junto con Karl Marx escribe libros importantes.","fr":"Le 5 août 1895, Friedrich Engels meurt. Il vient de Wuppertal. Avec Karl Marx, il écrit des livres importants.","pl":"5 sierpnia 1895 roku zmarł Friedrich Engels. Pochodził z Wuppertalu. Razem z Karolem Marksem pisał ważne książki.","uk":"5 серпня 1895 року помер Фрідріх Енгельс. Він був родом із Вупперталя. Разом із Карлом Марксом він писав важливі книжки.","fa":"در ۵ اوت ۱۸۹۵، فریدریش انگلس درگذشت. او اهل ووپرتال بود. او با کارل مارکس کتاب‌های مهمی نوشت.","it":"Il 5 agosto 1895 muore Friedrich Engels. Viene da Wuppertal. Scrive libri importanti insieme a Karl Marx."},"translationsByLevel":{"A2":{"en":"On August 5, 1895, Friedrich Engels dies. He came from a family of factory owners in Wuppertal and ran a factory himself. At the same time, he wrote about the hardship of the workers.","ar":"في 5 أغسطس 1895 يتوفى فريدريش إنجلز. كان ينحدر من عائلة أصحاب مصانع في فوبرتال، وأدار هو نفسه مصنعاً. وفي الوقت ذاته كتب عن معاناة العمال.","tr":"5 Ağustos 1895'te Friedrich Engels hayatını kaybeder. Wuppertal'da bir fabrikatör ailesinden geliyordu ve kendisi de bir fabrika yönetiyordu. Aynı zamanda işçilerin sıkıntıları hakkında yazıyordu.","ru":"5 августа 1895 года умирает Фридрих Энгельс. Он происходил из семьи фабрикантов в Вуппертале и сам руководил фабрикой. Одновременно он писал о бедственном положении рабочих.","es":"El 5 de agosto de 1895 muere Friedrich Engels. Provenía de una familia de fabricantes de Wuppertal y él mismo dirigía una fábrica. Al mismo tiempo, escribía sobre la miseria de los trabajadores.","fr":"Le 5 août 1895, Friedrich Engels meurt. Il était issu d'une famille d'industriels de Wuppertal et dirigeait lui-même une usine. Il écrivait pourtant sur la misère des ouvriers.","pl":"5 sierpnia 1895 roku umiera Fryderyk Engels. Pochodził z rodziny fabrykantów z Wuppertalu i sam prowadził fabrykę. Jednocześnie pisał o niedoli robotników.","uk":"5 серпня 1895 року помирає Фрідріх Енгельс. Він походив із родини фабрикантів у Вуппертале і сам керував фабрикою. Водночас він писав про злидні робітників.","fa":"در ۵ اوت ۱۸۹۵ فریدریش انگلس درگذشت. او از خانواده‌ای کارخانه‌دار در ووپرتال بود و خود نیز کارخانه‌ای را اداره می‌کرد. در همان حال، درباره‌ی رنج کارگران می‌نوشت.","it":"Il 5 agosto 1895 muore Friedrich Engels. Proveniva da una famiglia di industriali di Wuppertal e dirigeva egli stesso una fabbrica. Allo stesso tempo scriveva della miseria degli operai."},"B1":{"en":"On August 5, 1895, Friedrich Engels dies. In 1845, he described the condition of the working class in England so precisely that his book still serves as a source today. His money from the textile factory financed Karl Marx's work for decades.","ar":"في 5 أغسطس 1895 يتوفى فريدريش إنجلز. وصف عام 1845 أوضاع الطبقة العاملة في إنجلترا بدقة جعلت كتابه مصدراً يُعتمد عليه حتى اليوم. ومولت أمواله من مصنع النسيج عمل كارل ماركس لعقود.","tr":"5 Ağustos 1895'te Friedrich Engels hayatını kaybeder. 1845'te İngiltere'deki çalışan sınıfın durumunu öyle titizlikle betimledi ki kitabı bugün hâlâ bir kaynak olarak kullanılıyor. Tekstil fabrikasından gelen parası on yıllarca Karl Marx'ın çalışmasını finanse etti.","ru":"5 августа 1895 года умирает Фридрих Энгельс. В 1845 году он так точно описал положение рабочего класса в Англии, что его книга до сих пор служит источником. Его деньги от текстильной фабрики десятилетиями финансировали работу Карла Маркса.","es":"El 5 de agosto de 1895 muere Friedrich Engels. En 1845 describió la situación de la clase obrera en Inglaterra con tal precisión que su libro sigue siendo hoy una fuente de referencia. Su dinero de la fábrica textil financió durante décadas el trabajo de Karl Marx.","fr":"Le 5 août 1895, Friedrich Engels meurt. En 1845, il décrivit la condition de la classe ouvrière en Angleterre avec une telle précision que son livre sert encore aujourd'hui de source. Son argent, tiré de l'usine textile, finança pendant des décennies le travail de Karl Marx.","pl":"5 sierpnia 1895 roku umiera Fryderyk Engels. W 1845 roku opisał położenie klasy robotniczej w Anglii tak dokładnie, że jego książka do dziś służy jako źródło. Pieniądze z fabryki tekstylnej przez dziesięciolecia finansowały pracę Karola Marksa.","uk":"5 серпня 1895 року помирає Фрідріх Енгельс. У 1845 році він так точно описав становище робітничого класу в Англії, що його книга й досі є джерелом. Його гроші з текстильної фабрики десятиліттями фінансували роботу Карла Маркса.","fa":"در ۵ اوت ۱۸۹۵ فریدریش انگلس درگذشت. او در سال ۱۸۴۵ وضعیت طبقه‌ی کارگر در انگلستان را چنان دقیق توصیف کرد که کتابش تا امروز به‌عنوان یک منبع به‌کار می‌رود. پول او از کارخانه‌ی نساجی برای دهه‌ها کار کارل مارکس را تأمین مالی می‌کرد.","it":"Il 5 agosto 1895 muore Friedrich Engels. Nel 1845 descrisse la condizione della classe operaia in Inghilterra con tale precisione che il suo libro serve ancora oggi come fonte. Il denaro proveniente dalla sua fabbrica tessile finanziò per decenni il lavoro di Karl Marx."},"B2":{"en":"On August 5, 1895, Friedrich Engels dies. His life contains an open contradiction: he criticized factory capitalism while living off the profits of a factory. He never concealed this — it made his descriptions more precise than any outside observation.","ar":"في 5 أغسطس 1895 يتوفى فريدريش إنجلز. تنطوي حياته على تناقض صريح: انتقد رأسمالية المصانع بينما كان يعيش على عائدات مصنع. لم يُخفِ ذلك يوماً — بل جعل ذلك أوصافه أدق من أي ملاحظة من الخارج.","tr":"5 Ağustos 1895'te Friedrich Engels hayatını kaybeder. Yaşamı açık bir çelişki barındırır: Fabrika kapitalizmini eleştirdi ve bir fabrikanın gelirinden geçindi. Bunu asla gizlemedi — bu da tasvirlerini dışarıdan yapılan her gözlemden daha kesin kıldı.","ru":"5 августа 1895 года умирает Фридрих Энгельс. В его жизни есть открытое противоречие: он критиковал фабричный капитализм и при этом жил на доходы от фабрики. Он никогда этого не скрывал — это делало его описания точнее любого стороннего наблюдения.","es":"El 5 de agosto de 1895 muere Friedrich Engels. Su vida encierra una contradicción abierta: criticaba el capitalismo fabril y vivía de los beneficios de una fábrica. Nunca lo ocultó, y eso hizo sus descripciones más precisas que cualquier observación externa.","fr":"Le 5 août 1895, Friedrich Engels meurt. Sa vie renferme une contradiction manifeste : il critiquait le capitalisme industriel tout en vivant des revenus d'une usine. Il ne l'a jamais caché — cela rendait ses descriptions plus précises que n'importe quelle observation extérieure.","pl":"5 sierpnia 1895 roku umiera Fryderyk Engels. Jego życie zawiera jawną sprzeczność: krytykował kapitalizm fabryczny, żyjąc z dochodów fabryki. Nigdy tego nie ukrywał — dzięki temu jego opisy były dokładniejsze niż jakakolwiek obserwacja z zewnątrz.","uk":"5 серпня 1895 року помирає Фрідріх Енгельс. У його житті є відверта суперечність: він критикував фабричний капіталізм, живучи з доходів фабрики. Він ніколи цього не приховував — це робило його описи точнішими за будь-яке стороннє спостереження.","fa":"در ۵ اوت ۱۸۹۵ فریدریش انگلس درگذشت. زندگی او تناقضی آشکار دربر دارد: او سرمایه‌داری کارخانه‌ای را نقد می‌کرد و در همان حال از درآمد یک کارخانه زندگی می‌کرد. او هرگز این را پنهان نکرد — و همین امر توصیفاتش را دقیق‌تر از هر مشاهده‌ی بیرونی می‌ساخت.","it":"Il 5 agosto 1895 muore Friedrich Engels. La sua vita contiene una contraddizione dichiarata: criticava il capitalismo industriale e viveva dei proventi di una fabbrica. Non lo nascose mai: proprio questo rese le sue descrizioni più precise di qualsiasi osservazione dall'esterno."},"C1":{"en":"The man who died on August 5, 1895, organized Marx's unfinished manuscripts after his death and published them. In doing so, he decisively shaped which version came to be regarded as the definitive work. Editorship of posthumous writings is never a merely technical activity.","ar":"رتّب المتوفى في 5 أغسطس 1895 مخطوطات ماركس غير المكتملة بعد وفاته ونشرها. وبذلك حدد بشكل حاسم أي نسخة تُعتبر العمل الأصلي. فتحرير الأعمال المخلّفة بعد الوفاة ليس أبداً نشاطاً تقنياً محضاً.","tr":"5 Ağustos 1895'te ölen kişi, Marx'ın ölümünden sonra tamamlanmamış el yazmalarını düzenleyip yayımladı. Böylece hangi versiyonun 'eser' sayılacağını belirleyici biçimde şekillendirdi. Ölümden sonra bırakılan yazılarda editörlük hiçbir zaman salt teknik bir faaliyet değildir.","ru":"Умерший 5 августа 1895 года после смерти Маркса упорядочил его незавершённые рукописи и издал их. Тем самым он решающим образом определил, какая версия считается основным трудом. Редактирование посмертных сочинений никогда не бывает чисто технической работой.","es":"El fallecido el 5 de agosto de 1895 ordenó, tras la muerte de Marx, sus manuscritos inacabados y los publicó. Con ello determinó de forma decisiva qué versión se considera la obra. La labor editorial de escritos póstumos nunca es una actividad meramente técnica.","fr":"Celui qui est mort le 5 août 1895 a mis en ordre, après la mort de Marx, ses manuscrits inachevés et les a publiés. Il a ainsi déterminé de façon décisive quelle version serait considérée comme l'œuvre. L'édition d'écrits posthumes n'est jamais une activité purement technique.","pl":"Zmarły 5 sierpnia 1895 roku uporządkował po śmierci Marksa jego niedokończone rękopisy i wydał je. W ten sposób w decydujący sposób ukształtował, którą wersję uznaje się za dzieło. Redagowanie pism pozostawionych po zmarłym nigdy nie jest czynnością czysto techniczną.","uk":"Померлий 5 серпня 1895 року після смерті Маркса впорядкував його незавершені рукописи та видав їх. Тим самим він вирішально визначив, яка версія вважається основним твором. Редагування посмертних творів ніколи не є суто технічною діяльністю.","fa":"کسی که در ۵ اوت ۱۸۹۵ درگذشت، پس از مرگ مارکس دست‌نوشته‌های ناتمام او را سامان داد و منتشر کرد. بدین‌سان به‌طور تعیین‌کننده‌ای مشخص کرد که کدام نسخه به‌عنوان اثر اصلی شناخته شود. ویراستاری آثار به‌جامانده هرگز صرفاً یک کار فنی نیست.","it":"Morto il 5 agosto 1895, dopo la morte di Marx ordinò i suoi manoscritti incompiuti e li pubblicò. In questo modo determinò in maniera decisiva quale versione fosse considerata l'opera. Curare l'edizione di scritti postumi non è mai un'attività meramente tecnica."},"C2":{"en":"In the case of Engels, who died on August 5, 1895, one may ask how much interpretive power lies in editing. He decided the selection, order, and title of what is regarded as the principal work of Marxism. Later debates about what Marx really meant therefore always also negotiate Engels's editorial decisions.","ar":"يمكن أن نتساءل، من خلال إنجلز المتوفى في 5 أغسطس 1895، عن مقدار السلطة التفسيرية الكامنة في التحرير. فقد قرر الاختيار والترتيب والعنوان لما يُعتبر العمل الرئيسي للماركسية. لهذا فإن النقاشات اللاحقة حول ما كان ماركس يقصده فعلاً تتناول دائماً أيضاً قرارات إنجلز التحريرية.","tr":"5 Ağustos 1895'te ölen Engels üzerinden, editörlükte ne kadar yorumlama gücü barındığı sorulabilir. O, Marksizmin ana eseri sayılan şeyin seçimine, sırasına ve başlığına karar verdi. Marx'ın gerçekte ne demek istediğine dair sonraki tartışmalar bu yüzden her zaman Engels'in editoryal kararlarını da tartışır.","ru":"На примере Энгельса, умершего 5 августа 1895 года, можно поставить вопрос о том, сколько интерпретационной власти скрыто в редактировании. Он определял отбор, порядок и название того, что считается главным трудом марксизма. Поэтому последующие споры о том, что Маркс на самом деле имел в виду, всегда затрагивают и редакторские решения Энгельса.","es":"A partir de Engels, fallecido el 5 de agosto de 1895, cabe preguntarse cuánto poder interpretativo encierra la edición. Él decidió la selección, el orden y el título de lo que se considera la obra principal del marxismo. Por eso los debates posteriores sobre lo que realmente quiso decir Marx siempre discuten también las decisiones editoriales de Engels.","fr":"À propos d'Engels, mort le 5 août 1895, on peut se demander quelle part de pouvoir d'interprétation réside dans l'édition. Il a décidé de la sélection, de l'ordre et du titre de ce qui est considéré comme l'œuvre maîtresse du marxisme. Les débats ultérieurs sur ce que Marx voulait vraiment dire portent donc toujours aussi, implicitement, sur les décisions éditoriales d'Engels.","pl":"Na przykładzie Engelsa, zmarłego 5 sierpnia 1895 roku, można zapytać, ile władzy interpretacyjnej tkwi w redagowaniu. To on zdecydował o doborze, kolejności i tytule tego, co uznaje się za główne dzieło marksizmu. Późniejsze debaty o tym, co Marks naprawdę miał na myśli, dotyczą więc zawsze także redakcyjnych decyzji Engelsa.","uk":"На прикладі Енгельса, який помер 5 серпня 1895 року, можна поставити питання, скільки інтерпретаційної влади міститься в редагуванні. Саме він вирішував відбір, порядок і назву того, що вважається головним твором марксизму. Тому пізніші дебати про те, що насправді мав на увазі Маркс, завжди зачіпають і редакційні рішення Енгельса.","fa":"درباره‌ی انگلس، که در ۵ اوت ۱۸۹۵ درگذشت، می‌توان پرسید که چقدر قدرت تفسیر در ویراستاری نهفته است. او درباره‌ی گزینش، ترتیب و عنوان آنچه به‌عنوان اثر اصلی مارکسیسم شناخته می‌شود تصمیم گرفت. از این‌رو مناظره‌های بعدی درباره‌ی آنچه مارکس واقعاً در نظر داشت، همواره تصمیمات ویراستارانه‌ی انگلس را نیز به بحث می‌گذارند.","it":"Nel caso di Engels, morto il 5 agosto 1895, ci si può chiedere quanto potere interpretativo risieda nell'edizione dei testi. Decise la selezione, l'ordine e il titolo di ciò che è considerato l'opera principale del marxismo. I dibattiti successivi su cosa Marx intendesse realmente discutono perciò sempre anche delle sue scelte redazionali."}},"sideFacts":[]},"08-06":{"year":1806,"levels":{"A1":"Am 6. August 1806 endet das Heilige Römische Reich. Kaiser Franz II. gibt seine Krone ab.","A2":"Am 6. August 1806 legt Kaiser Franz II. seine Krone nieder. Damit endet das Heilige Römische Reich nach fast 1000 Jahren.","B1":"Am 6. August 1806 dankt Kaiser Franz II. ab, weil Napoleon großen Druck auf ihn ausübt. Damit endet das Heilige Römische Reich Deutscher Nation nach fast 1000 Jahren Geschichte.","B2":"Am 6. August 1806 legt Kaiser Franz II. unter dem Druck Napoleons die Kaiserkrone nieder, nachdem sich 16 süd- und westdeutsche Fürstentümer im Rheinbund mit Napoleon verbündet und aus dem Reich ausgetreten waren — das Heilige Römische Reich endet damit nach fast 1000 Jahren.","C1":"Die Abdankung Kaiser Franz II. am 6. August 1806, ausgelöst durch die Gründung des napoleontreuen Rheinbunds, markiert das Ende des fast tausendjährigen Heiligen Römischen Reiches — ein Reich, dessen lockere, föderale Struktur den zentralistischen Machtansprüchen Napoleons letztlich nicht mehr standhalten konnte.","C2":"Mit der Niederlegung der Kaiserkrone am 6. August 1806 zog Franz II. die Konsequenz aus einer Entwicklung, die sich bereits durch die Koalitionskriege und den Reichsdeputationshauptschluss von 1803 abgezeichnet hatte: Das Heilige Römische Reich, dessen komplexe föderale Struktur schon länger brüchig geworden war, endete nicht mit einem dramatischen Umsturz, sondern faktisch mit einem einzigen Federstrich."},"translationsA1":{"en":"On August 6, 1806, the Holy Roman Empire ends. Emperor Franz II gives up his crown.","ar":"في 6 أغسطس 1806، انتهت الإمبراطورية الرومانية المقدسة. تخلى الإمبراطور فرانتس الثاني عن تاجه.","tr":"6 Ağustos 1806'da Kutsal Roma İmparatorluğu sona erdi. İmparator II. Franz tacından vazgeçti.","ru":"6 августа 1806 года Священная Римская империя прекратила существование. Император Франц II отказался от короны.","es":"El 6 de agosto de 1806, termina el Sacro Imperio Romano Germánico. El emperador Francisco II renuncia a su corona.","fr":"Le 6 août 1806, le Saint-Empire romain germanique prend fin. L'empereur François II renonce à sa couronne.","pl":"6 sierpnia 1806 roku Święte Cesarstwo Rzymskie przestało istnieć. Cesarz Franciszek II zrzekł się korony.","uk":"6 серпня 1806 року Священна Римська імперія припинила існування. Імператор Франц II відмовився від корони.","fa":"در ۶ اوت ۱۸۰۶، امپراتوری مقدس روم به پایان رسید. امپراتور فرانتس دوم از تاج خود کناره‌گیری کرد.","it":"Il 6 agosto 1806 finisce il Sacro Romano Impero. L'imperatore Francesco II depone la corona."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 6, 1806, Emperor Francis II lays down his crown. This ends the Holy Roman Empire after almost 1,000 years.","ar":"في 6 أغسطس 1806 يتنازل الإمبراطور فرانتس الثاني عن تاجه. وبذلك تنتهي الإمبراطورية الرومانية المقدسة بعد قرابة 1000 عام.","tr":"6 Ağustos 1806'da İmparator II. Franz tacını bırakır. Böylece Kutsal Roma İmparatorluğu yaklaşık 1000 yıl sonra sona erer.","ru":"6 августа 1806 года император Франц II слагает с себя корону. Тем самым после почти 1000 лет заканчивается Священная Римская империя.","es":"El 6 de agosto de 1806, el emperador Francisco II depone su corona. Con ello termina el Sacro Imperio Romano Germánico tras casi 1000 años.","fr":"Le 6 août 1806, l'empereur François II dépose sa couronne. Cela met fin au Saint-Empire romain germanique après près de 1000 ans.","pl":"6 sierpnia 1806 roku cesarz Franciszek II składa koronę. Tym samym po niemal 1000 latach kończy się Święte Cesarstwo Rzymskie.","uk":"6 серпня 1806 року імператор Франц II складає з себе корону. Тим самим після майже 1000 років закінчується Священна Римська імперія.","fa":"در ۶ اوت ۱۸۰۶ امپراتور فرانتس دوم تاج خود را کنار می‌گذارد. بدین‌ترتیب امپراتوری مقدس روم پس از نزدیک به ۱۰۰۰ سال به پایان می‌رسد.","it":"Il 6 agosto 1806 l'imperatore Francesco II depone la corona. Con ciò termina il Sacro Romano Impero dopo quasi 1000 anni."},"B1":{"en":"On August 6, 1806, Emperor Francis II abdicates because Napoleon puts great pressure on him. This ends the Holy Roman Empire of the German Nation after almost 1,000 years of history.","ar":"في 6 أغسطس 1806 يتنازل الإمبراطور فرانتس الثاني عن العرش بسبب ضغط نابليون الكبير عليه. وبذلك تنتهي الإمبراطورية الرومانية المقدسة للأمة الألمانية بعد قرابة 1000 عام من التاريخ.","tr":"6 Ağustos 1806'da İmparator II. Franz, Napolyon'un üzerindeki büyük baskısı nedeniyle tahttan çekilir. Böylece Alman Milletinin Kutsal Roma İmparatorluğu yaklaşık 1000 yıllık tarihinin ardından sona erer.","ru":"6 августа 1806 года император Франц II отрекается от престола из-за сильного давления Наполеона. Тем самым Священная Римская империя германской нации заканчивается после почти 1000-летней истории.","es":"El 6 de agosto de 1806, el emperador Francisco II abdica debido a la gran presión que ejerce Napoleón sobre él. Con ello termina el Sacro Imperio Romano Germánico tras casi 1000 años de historia.","fr":"Le 6 août 1806, l'empereur François II abdique en raison de la forte pression exercée par Napoléon. Cela met fin au Saint-Empire romain germanique après près de 1000 ans d'histoire.","pl":"6 sierpnia 1806 roku cesarz Franciszek II abdykuje pod silną presją Napoleona. Tym samym kończy się Święte Cesarstwo Rzymskie Narodu Niemieckiego po niemal 1000 latach historii.","uk":"6 серпня 1806 року імператор Франц II зрікається престолу через сильний тиск Наполеона. Тим самим Священна Римська імперія німецької нації закінчується після майже 1000-річної історії.","fa":"در ۶ اوت ۱۸۰۶ امپراتور فرانتس دوم به دلیل فشار شدید ناپلئون از سلطنت کناره‌گیری می‌کند. بدین‌ترتیب امپراتوری مقدس روم ملت آلمان پس از نزدیک به ۱۰۰۰ سال تاریخ به پایان می‌رسد.","it":"Il 6 agosto 1806 l'imperatore Francesco II abdica perché Napoleone esercita su di lui una forte pressione. Con ciò termina il Sacro Romano Impero della Nazione Germanica dopo quasi 1000 anni di storia."},"B2":{"en":"On August 6, 1806, Emperor Francis II lays down the imperial crown under pressure from Napoleon, after 16 southern and western German principalities had allied with Napoleon in the Confederation of the Rhine and withdrawn from the Empire — the Holy Roman Empire thus ends after almost 1,000 years.","ar":"في 6 أغسطس 1806 يتنازل الإمبراطور فرانتس الثاني عن التاج الإمبراطوري تحت ضغط نابليون، بعد أن تحالفت 16 إمارة ألمانية جنوبية وغربية مع نابليون في اتحاد الراين وانسحبت من الإمبراطورية — وبذلك تنتهي الإمبراطورية الرومانية المقدسة بعد قرابة 1000 عام.","tr":"6 Ağustos 1806'da, 16 güney ve batı Alman prensliği Ren Konfederasyonu içinde Napolyon'la ittifak kurup İmparatorluktan ayrıldıktan sonra, İmparator II. Franz Napolyon'un baskısıyla imparatorluk tacını bırakır — Kutsal Roma İmparatorluğu böylece yaklaşık 1000 yıl sonra sona erer.","ru":"6 августа 1806 года император Франц II под давлением Наполеона слагает императорскую корону после того, как 16 южно- и западногерманских княжеств объединились с Наполеоном в Рейнском союзе и вышли из империи — тем самым Священная Римская империя заканчивается после почти 1000 лет.","es":"El 6 de agosto de 1806, el emperador Francisco II depone la corona imperial bajo la presión de Napoleón, después de que 16 principados del sur y el oeste de Alemania se aliaran con Napoleón en la Confederación del Rin y se retiraran del Imperio; el Sacro Imperio Romano Germánico termina así tras casi 1000 años.","fr":"Le 6 août 1806, l'empereur François II dépose la couronne impériale sous la pression de Napoléon, après que 16 principautés d'Allemagne du Sud et de l'Ouest se sont alliées à Napoléon au sein de la Confédération du Rhin et ont quitté l'Empire — le Saint-Empire romain germanique s'achève ainsi après près de 1000 ans.","pl":"6 sierpnia 1806 roku cesarz Franciszek II pod naciskiem Napoleona składa koronę cesarską, po tym jak 16 południowo- i zachodnioniemieckich księstw sprzymierzyło się z Napoleonem w Związku Reńskim i wystąpiło z Rzeszy — Święte Cesarstwo Rzymskie kończy się tym samym po niemal 1000 latach.","uk":"6 серпня 1806 року імператор Франц II під тиском Наполеона складає імператорську корону після того, як 16 південно- та західнонімецьких князівств об'єдналися з Наполеоном у Рейнському союзі й вийшли з імперії — Священна Римська імперія завершується таким чином після майже 1000 років.","fa":"در ۶ اوت ۱۸۰۶ امپراتور فرانتس دوم زیر فشار ناپلئون تاج امپراتوری را کنار می‌گذارد، پس از آنکه ۱۶ فرمانروایی آلمانی جنوبی و غربی در کنفدراسیون راین با ناپلئون متحد شده و از امپراتوری خارج شده بودند — امپراتوری مقدس روم بدین‌سان پس از نزدیک به ۱۰۰۰ سال به پایان می‌رسد.","it":"Il 6 agosto 1806 l'imperatore Francesco II, sotto la pressione di Napoleone, depone la corona imperiale, dopo che 16 principati della Germania meridionale e occidentale si erano alleati con Napoleone nella Confederazione del Reno ed erano usciti dall'Impero: il Sacro Romano Impero finisce così dopo quasi 1000 anni."},"C1":{"en":"The abdication of Emperor Francis II on August 6, 1806, triggered by the formation of the pro-Napoleon Confederation of the Rhine, marks the end of the almost thousand-year-old Holy Roman Empire — an empire whose loose, federal structure could ultimately no longer withstand Napoleon's centralist claims to power.","ar":"يمثّل تنازل الإمبراطور فرانتس الثاني في 6 أغسطس 1806، الذي أطلقه تأسيس اتحاد الراين الموالي لنابليون، نهاية الإمبراطورية الرومانية المقدسة التي دام عمرها قرابة ألف عام — إمبراطورية لم يعد بمقدور بنيتها الفدرالية المرنة الصمود أمام مطالب نابليون المركزية بالسلطة.","tr":"Napolyon'a bağlı Ren Konfederasyonu'nun kuruluşuyla tetiklenen İmparator II. Franz'ın 6 Ağustos 1806'daki tahttan çekilişi, neredeyse bin yıllık Kutsal Roma İmparatorluğu'nun sonunu işaret eder — gevşek, federal yapısı Napolyon'un merkeziyetçi iktidar taleplerine artık dayanamayan bir imparatorluk.","ru":"Отречение императора Франца II 6 августа 1806 года, вызванное образованием пронаполеоновского Рейнского союза, знаменует конец почти тысячелетней Священной Римской империи — империи, чья рыхлая федеративная структура в конечном счёте уже не могла противостоять централистским притязаниям Наполеона на власть.","es":"La abdicación del emperador Francisco II el 6 de agosto de 1806, provocada por la creación de la Confederación del Rin, aliada de Napoleón, marca el fin del Sacro Imperio Romano Germánico, casi milenario, un imperio cuya estructura federal laxa ya no pudo resistir las pretensiones centralistas de poder de Napoleón.","fr":"L'abdication de l'empereur François II le 6 août 1806, provoquée par la création de la Confédération du Rhin fidèle à Napoléon, marque la fin du Saint-Empire romain germanique presque millénaire — un empire dont la structure fédérale lâche ne pouvait finalement plus résister aux prétentions centralisatrices de Napoléon.","pl":"Abdykacja cesarza Franciszka II 6 sierpnia 1806 roku, wywołana utworzeniem wiernego Napoleonowi Związku Reńskiego, wyznacza koniec niemal tysiącletniego Świętego Cesarstwa Rzymskiego — cesarstwa, którego luźna, federalna struktura nie mogła już ostatecznie oprzeć się centralistycznym roszczeniom władzy Napoleona.","uk":"Зречення імператора Франца II 6 серпня 1806 року, спричинене утворенням проналеонівського Рейнського союзу, знаменує кінець майже тисячолітньої Священної Римської імперії — імперії, чия пухка федеративна структура зрештою вже не могла протистояти централістським претензіям Наполеона на владу.","fa":"کناره‌گیری امپراتور فرانتس دوم در ۶ اوت ۱۸۰۶، که با تشکیل کنفدراسیون راین وفادار به ناپلئون آغاز شد، پایان امپراتوری مقدس روم را که نزدیک به هزار سال دوام آورده بود رقم می‌زند — امپراتوری‌ای که ساختار سست و فدرال آن سرانجام دیگر نمی‌توانست در برابر ادعاهای متمرکز قدرت ناپلئون مقاومت کند.","it":"L'abdicazione dell'imperatore Francesco II il 6 agosto 1806, provocata dalla fondazione della Confederazione del Reno fedele a Napoleone, segna la fine del Sacro Romano Impero, quasi millenario: un impero la cui struttura federale e poco coesa non poté più reggere alle pretese di potere centralistiche di Napoleone."},"C2":{"en":"By laying down the imperial crown on August 6, 1806, Francis II drew the consequence of a development that had already been foreshadowed by the Coalition Wars and the Imperial Recess of 1803: the Holy Roman Empire, whose complex federal structure had long been growing brittle, ended not with a dramatic upheaval but, in effect, with a single stroke of the pen.","ar":"بتنازله عن التاج الإمبراطوري في 6 أغسطس 1806، استخلص فرانتس الثاني نتيجة تطور كانت بوادره قد ظهرت بالفعل عبر حروب التحالف وقرار مجلس النواب الإمبراطوري لعام 1803: فالإمبراطورية الرومانية المقدسة، التي كانت بنيتها الفدرالية المعقدة قد أخذت تتصدع منذ زمن، لم تنتهِ بانقلاب درامي، بل عملياً بجرة قلم واحدة.","tr":"6 Ağustos 1806'da imparatorluk tacını bırakarak II. Franz, Koalisyon Savaşları ve 1803 tarihli İmparatorluk Kararı ile zaten belirginleşmiş bir gelişmenin sonucunu ortaya koydu: Karmaşık federal yapısı çoktan çatlamaya başlamış olan Kutsal Roma İmparatorluğu, dramatik bir çöküşle değil, fiilen tek bir kalem darbesiyle sona erdi.","ru":"Сложив с себя императорскую корону 6 августа 1806 года, Франц II сделал вывод из развития событий, которое уже наметилось через Коалиционные войны и Имперскую депутацию 1803 года: Священная Римская империя, чья сложная федеративная структура давно стала хрупкой, закончилась не драматическим переворотом, а фактически одним росчерком пера.","es":"Al deponer la corona imperial el 6 de agosto de 1806, Francisco II extrajo la consecuencia de una evolución que ya se había perfilado a través de las guerras de coalición y el Receso Imperial de 1803: el Sacro Imperio Romano Germánico, cuya compleja estructura federal llevaba tiempo resquebrajándose, no terminó con un vuelco dramático, sino, de hecho, con un simple plumazo.","fr":"En déposant la couronne impériale le 6 août 1806, François II tirait la conséquence d'une évolution qui s'était déjà dessinée à travers les guerres de coalition et le recès d'Empire de 1803 : le Saint-Empire romain germanique, dont la structure fédérale complexe s'était depuis longtemps fragilisée, ne s'est pas achevé par un bouleversement spectaculaire, mais, en fait, par un simple trait de plume.","pl":"Składając koronę cesarską 6 sierpnia 1806 roku, Franciszek II wyciągnął konsekwencję z rozwoju wydarzeń, który zarysował się już w wojnach koalicyjnych i uchwale deputacji Rzeszy z 1803 roku: Święte Cesarstwo Rzymskie, którego złożona federalna struktura od dawna stawała się krucha, zakończyło się nie dramatycznym przewrotem, lecz w istocie jednym pociągnięciem pióra.","uk":"Склавши імператорську корону 6 серпня 1806 року, Франц II зробив висновок із розвитку подій, який уже окреслився через Коаліційні війни та Імперську депутацію 1803 року: Священна Римська імперія, чия складна федеративна структура давно стала крихкою, закінчилася не драматичним переворотом, а фактично одним розчерком пера.","fa":"با کنار گذاشتن تاج امپراتوری در ۶ اوت ۱۸۰۶، فرانتس دوم نتیجه‌ی روندی را پذیرفت که پیش‌تر با جنگ‌های ائتلاف و مصوبه‌ی مجمع امپراتوری در سال ۱۸۰۳ رقم خورده بود: امپراتوری مقدس روم، که ساختار پیچیده و فدرال آن مدت‌ها بود شکننده شده بود، نه با یک واژگونی نمایشی، بلکه در عمل با یک ضربه‌قلم به پایان رسید.","it":"Con la deposizione della corona imperiale il 6 agosto 1806, Francesco II trasse le conseguenze di uno sviluppo che si era già delineato attraverso le guerre di coalizione e il Reichsdeputationshauptschluss del 1803: il Sacro Romano Impero, la cui complessa struttura federale era da tempo divenuta fragile, non finì con un rovesciamento drammatico, ma di fatto con un semplice tratto di penna."}}},"08-07":{"year":1883,"levels":{"A1":"Am 7. August 1883 wird Joachim Ringelnatz geboren. Er schreibt lustige Gedichte. Sein bekanntester Held ist ein Seemann.","A2":"Am 7. August 1883 kommt Joachim Ringelnatz zur Welt. Er war Seemann, Kabarettist und Dichter. Seine Gedichte klingen einfach und sind oft überraschend traurig.","B1":"Am 7. August 1883 wird Joachim Ringelnatz geboren. Er erfand die Figur des Seemanns Kuttel Daddeldu und trug seine Gedichte selbst im Kabarett vor. Hinter dem Blödsinn steckt fast immer eine ernste Zeile.","B2":"Am 7. August 1883 wird Ringelnatz geboren. Seine Gedichte wirken hingeworfen und sind sorgfältig gebaut: Der Reim führt den Leser in eine Erwartung, die die letzte Zeile umkippt. Diese Technik hat das deutsche Kabarett bis heute geprägt.","C1":"Der am 7. August 1883 Geborene arbeitete an der Grenze zwischen Komik und Verzweiflung. Seine Figuren sind Außenseiter, die ihre Lage in Reimen erträglich machen. Dass seine Bücher 1933 verboten wurden, zeigt, wie ernst Regime harmlos wirkende Komik nehmen.","C2":"An Ringelnatz, geboren am 7. August 1883, lässt sich das politische Gewicht des Unernsts studieren. Seine Verse enthalten keine Programme und waren dennoch unerwünscht, weil sie eine Haltung transportieren: Wer über alles lachen kann, lässt sich schlecht in Ergriffenheit versetzen. Diktaturen misstrauen dem Humor nicht wegen seiner Inhalte, sondern wegen seiner Tonlage."},"translationsA1":{"en":"On August 7, 1883, Joachim Ringelnatz is born. He writes funny poems. His best-known character is a sailor.","ar":"في 7 أغسطس 1883، وُلد يواخيم رينغلناتس. كتب قصائد مضحكة. أشهر شخصياته بحّار.","tr":"7 Ağustos 1883'te Joachim Ringelnatz doğdu. Komik şiirler yazdı. En bilinen kahramanı bir denizcidir.","ru":"7 августа 1883 года родился Иоахим Рингельнатц. Он писал смешные стихи. Его самый известный герой — моряк.","es":"El 7 de agosto de 1883 nace Joachim Ringelnatz. Escribe poemas divertidos. Su personaje más conocido es un marinero.","fr":"Le 7 août 1883, Joachim Ringelnatz naît. Il écrit des poèmes drôles. Son personnage le plus connu est un marin.","pl":"7 sierpnia 1883 roku urodził się Joachim Ringelnatz. Pisał zabawne wiersze. Jego najbardziej znanym bohaterem jest marynarz.","uk":"7 серпня 1883 року народився Йоахім Рінгельнац. Він писав смішні вірші. Його найвідоміший герой — моряк.","fa":"در ۷ اوت ۱۸۸۳، یوآخیم رینگل‌ناتس به دنیا آمد. او شعرهای خنده‌دار می‌نوشت. مشهورترین قهرمانش یک ملوان است.","it":"Il 7 agosto 1883 nasce Joachim Ringelnatz. Scrive poesie divertenti. Il suo eroe più famoso è un marinaio."},"translationsByLevel":{"A2":{"en":"On August 7, 1883, Joachim Ringelnatz is born. He was a sailor, cabaret performer, and poet. His poems sound simple and are often surprisingly sad.","ar":"في 7 أغسطس 1883 يولد يواخيم رينغلناتس. كان بحاراً وفناناً في الكاباريه وشاعراً. تبدو قصائده بسيطة وغالباً ما تكون حزينة بشكل مفاجئ.","tr":"7 Ağustos 1883'te Joachim Ringelnatz dünyaya gelir. Denizci, kabare sanatçısı ve şairdi. Şiirleri sade görünür ve sık sık şaşırtıcı derecede hüzünlüdür.","ru":"7 августа 1883 года рождается Иоахим Рингельнатц. Он был моряком, кабаретистом и поэтом. Его стихи звучат просто и часто на удивление грустны.","es":"El 7 de agosto de 1883 nace Joachim Ringelnatz. Fue marinero, artista de cabaré y poeta. Sus poemas suenan sencillos y a menudo son sorprendentemente tristes.","fr":"Le 7 août 1883, Joachim Ringelnatz voit le jour. Il était marin, artiste de cabaret et poète. Ses poèmes semblent simples et sont souvent étonnamment tristes.","pl":"7 sierpnia 1883 roku przychodzi na świat Joachim Ringelnatz. Był marynarzem, kabareciarzem i poetą. Jego wiersze brzmią prosto i często są zaskakująco smutne.","uk":"7 серпня 1883 року народжується Йоахім Рінгельнац. Він був моряком, кабаретистом і поетом. Його вірші звучать просто і часто напрочуд сумно.","fa":"در ۷ اوت ۱۸۸۳ یواخیم رینگل‌ناتس به دنیا آمد. او دریانورد، هنرمند کاباره و شاعر بود. اشعار او ساده به‌نظر می‌رسند و غالباً به‌طرز شگفت‌انگیزی غم‌انگیزند.","it":"Il 7 agosto 1883 viene al mondo Joachim Ringelnatz. Fu marinaio, cabarettista e poeta. Le sue poesie suonano semplici e sono spesso sorprendentemente tristi."},"B1":{"en":"On August 7, 1883, Joachim Ringelnatz is born. He created the character of the sailor Kuttel Daddeldu and performed his poems himself in cabarets. Behind the nonsense there is almost always a serious line.","ar":"في 7 أغسطس 1883 يولد يواخيم رينغلناتس. ابتكر شخصية البحار كوتيل دادلدو وألقى قصائده بنفسه في الكاباريه. خلف الهزل يكمن دائماً تقريباً سطر جاد.","tr":"7 Ağustos 1883'te Joachim Ringelnatz doğar. Denizci Kuttel Daddeldu karakterini yarattı ve şiirlerini kabarede bizzat sundu. Saçmalığın ardında neredeyse her zaman ciddi bir dize gizlidir.","ru":"7 августа 1883 года рождается Иоахим Рингельнатц. Он придумал персонажа моряка Куттеля Даддельду и сам исполнял свои стихи в кабаре. За вздором почти всегда скрывается серьёзная строка.","es":"El 7 de agosto de 1883 nace Joachim Ringelnatz. Creó al personaje del marinero Kuttel Daddeldu y él mismo recitaba sus poemas en el cabaré. Detrás de la tontería casi siempre se esconde una línea seria.","fr":"Le 7 août 1883, Joachim Ringelnatz naît. Il inventa le personnage du marin Kuttel Daddeldu et récitait lui-même ses poèmes au cabaret. Derrière la bêtise se cache presque toujours un vers sérieux.","pl":"7 sierpnia 1883 roku rodzi się Joachim Ringelnatz. Stworzył postać marynarza Kuttela Daddeldu i sam recytował swoje wiersze w kabarecie. Za bzdurą kryje się niemal zawsze poważny wers.","uk":"7 серпня 1883 року народжується Йоахім Рінгельнац. Він створив образ моряка Куттеля Даддельду і сам виконував свої вірші в кабаре. За безглуздям майже завжди ховається серйозний рядок.","fa":"در ۷ اوت ۱۸۸۳ یواخیم رینگل‌ناتس زاده شد. او شخصیت دریانورد کوتل دادل‌دو را خلق کرد و خود اشعارش را در کاباره اجرا می‌کرد. پشت مسخرگی تقریباً همیشه یک سطر جدی نهفته است.","it":"Il 7 agosto 1883 nasce Joachim Ringelnatz. Inventò il personaggio del marinaio Kuttel Daddeldu e recitava lui stesso le sue poesie nel cabaret. Dietro le sciocchezze si nasconde quasi sempre un verso serio."},"B2":{"en":"On August 7, 1883, Ringelnatz is born. His poems seem casually tossed off yet are carefully constructed: the rhyme leads the reader into an expectation that the final line overturns. This technique has shaped German cabaret to this day.","ar":"في 7 أغسطس 1883 يولد رينغلناتس. تبدو قصائده وكأنها ارتُجلت لكنها مبنية بعناية: يقود القافية القارئ إلى توقع تنقلبه الجملة الأخيرة. شكّلت هذه التقنية الكاباريه الألماني حتى اليوم.","tr":"7 Ağustos 1883'te Ringelnatz doğar. Şiirleri gelişigüzel yazılmış gibi görünür ama titizlikle kurgulanmıştır: Kafiye okuyucuyu bir beklentiye sürükler, son dize ise bu beklentiyi tersine çevirir. Bu teknik Alman kabaresini bugüne kadar şekillendirmiştir.","ru":"7 августа 1883 года рождается Рингельнатц. Его стихи кажутся небрежно набросанными, но тщательно выстроены: рифма ведёт читателя к ожиданию, которое переворачивает последняя строка. Эта техника до сих пор определяет облик немецкого кабаре.","es":"El 7 de agosto de 1883 nace Ringelnatz. Sus poemas parecen improvisados, pero están cuidadosamente construidos: la rima conduce al lector hacia una expectativa que el último verso invierte. Esta técnica ha marcado el cabaré alemán hasta hoy.","fr":"Le 7 août 1883, Ringelnatz naît. Ses poèmes paraissent jetés à la hâte mais sont soigneusement construits : la rime conduit le lecteur vers une attente que le dernier vers renverse. Cette technique a marqué le cabaret allemand jusqu'à aujourd'hui.","pl":"7 sierpnia 1883 roku rodzi się Ringelnatz. Jego wiersze sprawiają wrażenie rzuconych od niechcenia, a są starannie skonstruowane: rym prowadzi czytelnika ku oczekiwaniu, które ostatni wers odwraca. Ta technika ukształtowała niemiecki kabaret aż do dziś.","uk":"7 серпня 1883 року народжується Рінгельнац. Його вірші здаються недбало кинутими, але старанно вибудувані: рима веде читача до очікування, яке останній рядок перевертає. Ця техніка формує німецьке кабаре й донині.","fa":"در ۷ اوت ۱۸۸۳ رینگل‌ناتس زاده شد. اشعار او بی‌دقت به‌نظر می‌رسند اما با ظرافت ساخته شده‌اند: قافیه خواننده را به سوی انتظاری می‌برد که سطر پایانی آن را وارونه می‌کند. این فن تا امروز کاباره‌ی آلمان را شکل داده است.","it":"Il 7 agosto 1883 nasce Ringelnatz. Le sue poesie sembrano buttate giù di getto ma sono costruite con cura: la rima conduce il lettore verso un'aspettativa che l'ultimo verso ribalta. Questa tecnica ha segnato il cabaret tedesco fino a oggi."},"C1":{"en":"The man born on August 7, 1883, worked at the boundary between comedy and despair. His characters are outsiders who make their situation bearable through rhyme. That his books were banned in 1933 shows how seriously regimes take comedy that appears harmless.","ar":"عمل المولود في 7 أغسطس 1883 عند الحد الفاصل بين الكوميديا واليأس. شخصياته منبوذون يجعلون وضعهم محتملاً عبر القوافي. حظر كتبه عام 1933 يُظهر مدى جدية الأنظمة تجاه الكوميديا التي تبدو غير مؤذية.","tr":"7 Ağustos 1883'te doğan kişi, komedi ile umutsuzluk arasındaki sınırda çalıştı. Karakterleri, durumlarını kafiyeyle katlanılabilir kılan kenar figürlerdir. Kitaplarının 1933'te yasaklanması, rejimlerin zararsız görünen komediyi ne kadar ciddiye aldığını gösterir.","ru":"Родившийся 7 августа 1883 года работал на грани комизма и отчаяния. Его персонажи — аутсайдеры, которые делают своё положение сносным с помощью рифм. То, что его книги были запрещены в 1933 году, показывает, насколько серьёзно режимы относятся к комизму, кажущемуся безобидным.","es":"El nacido el 7 de agosto de 1883 trabajaba en la frontera entre lo cómico y la desesperación. Sus personajes son marginados que hacen soportable su situación en versos rimados. Que sus libros fueran prohibidos en 1933 muestra cuán en serio se toman los regímenes la comicidad de apariencia inofensiva.","fr":"Celui qui est né le 7 août 1883 travaillait à la frontière entre le comique et le désespoir. Ses personnages sont des marginaux qui rendent leur condition supportable en vers rimés. Le fait que ses livres aient été interdits en 1933 montre combien les régimes prennent au sérieux un comique d'apparence anodine.","pl":"Urodzony 7 sierpnia 1883 roku pracował na granicy między komizmem a rozpaczą. Jego postacie to outsiderzy, którzy czynią swoje położenie znośnym za pomocą rymów. To, że jego książki zakazano w 1933 roku, pokazuje, jak poważnie reżimy traktują pozornie nieszkodliwy komizm.","uk":"Народжений 7 серпня 1883 року працював на межі між комізмом і відчаєм. Його персонажі — аутсайдери, які роблять своє становище стерпним за допомогою рим. Те, що його книги заборонили в 1933 році, показує, наскільки серйозно режими ставляться до, здавалося б, безневинного гумору.","fa":"کسی که در ۷ اوت ۱۸۸۳ زاده شد، در مرز میان طنز و ناامیدی کار می‌کرد. شخصیت‌های او افرادی حاشیه‌نشین‌اند که وضعیت خود را با قافیه‌ها قابل‌تحمل می‌سازند. اینکه کتاب‌های او در سال ۱۹۳۳ ممنوع شدند، نشان می‌دهد که رژیم‌ها طنزی را که بی‌خطر به‌نظر می‌رسد چقدر جدی می‌گیرند.","it":"Nato il 7 agosto 1883, lavorò al confine tra comicità e disperazione. I suoi personaggi sono outsider che rendono sopportabile la propria condizione attraverso le rime. Il fatto che i suoi libri furono vietati nel 1933 mostra quanto seriamente i regimi prendano una comicità apparentemente innocua."},"C2":{"en":"In Ringelnatz, born on August 7, 1883, one can study the political weight of unseriousness. His verses contain no programs and were nonetheless unwelcome, because they convey an attitude: whoever can laugh at everything is hard to move to solemn conviction. Dictatorships distrust humor not for its content, but for its tone.","ar":"يمكن أن نستكشف من خلال رينغلناتس، المولود في 7 أغسطس 1883، الوزن السياسي لعدم الجدية. لم تحمل أبياته أي برامج ومع ذلك كانت غير مرغوب فيها، لأنها تنقل موقفاً: من يستطيع الضحك على كل شيء يصعب دفعه إلى الانفعال الجماعي. لا تشك الديكتاتوريات في الفكاهة بسبب مضمونها، بل بسبب نبرتها.","tr":"7 Ağustos 1883'te doğan Ringelnatz üzerinden ciddiyetsizliğin siyasi ağırlığı incelenebilir. Dizeleri hiçbir program içermiyordu, yine de istenmiyordu, çünkü bir tutum aktarıyorlardı: Her şeye gülebilen biri, kolayca coşkuya sürüklenemez. Diktatörlükler mizahtan içeriği yüzünden değil, tonu yüzünden kuşku duyar.","ru":"На примере Рингельнатца, родившегося 7 августа 1883 года, можно изучить политический вес несерьёзности. Его стихи не содержали никаких программ и всё же были нежелательны, поскольку передавали позицию: тот, кто способен смеяться над всем, плохо поддаётся воодушевлению. Диктатуры не доверяют юмору не из-за его содержания, а из-за его тональности.","es":"En Ringelnatz, nacido el 7 de agosto de 1883, puede estudiarse el peso político de la falta de seriedad. Sus versos no contenían programa alguno y, sin embargo, resultaban indeseables porque transmitían una actitud: quien puede reírse de todo se deja arrastrar mal a la exaltación. Las dictaduras desconfían del humor no por su contenido, sino por su tono.","fr":"Chez Ringelnatz, né le 7 août 1883, on peut étudier le poids politique du non-sérieux. Ses vers ne contenaient aucun programme et étaient pourtant indésirables, car ils véhiculaient une attitude : celui qui peut rire de tout se laisse difficilement gagner par l'exaltation. Les dictatures se méfient de l'humour non pour son contenu, mais pour son ton.","pl":"Na przykładzie Ringelnatza, urodzonego 7 sierpnia 1883 roku, można badać polityczną wagę niepowagi. Jego wiersze nie zawierały żadnych programów, a mimo to były niepożądane, ponieważ niosły postawę: kto potrafi śmiać się ze wszystkiego, trudno poddaje się uniesieniu. Dyktatury nie ufają humorowi nie z powodu jego treści, lecz z powodu jego tonu.","uk":"На прикладі Рінгельнаца, народженого 7 серпня 1883 року, можна вивчати політичну вагу несерйозності. Його вірші не містили жодних програм і все ж були небажаними, бо передавали позицію: хто здатен сміятися з усього, того важко захопити піднесенням. Диктатури не довіряють гумору не через його зміст, а через його тон.","fa":"درباره‌ی رینگل‌ناتس، که در ۷ اوت ۱۸۸۳ زاده شد، می‌توان وزن سیاسی بی‌جدی‌بودن را بررسی کرد. اشعار او هیچ برنامه‌ای در بر نداشتند و با این حال نامطلوب بودند، زیرا نگرشی را منتقل می‌کردند: کسی که می‌تواند به همه‌چیز بخندد، به‌سختی دچار شور و هیجان می‌شود. دیکتاتوری‌ها به طنز نه به‌خاطر محتوایش، بلکه به‌خاطر لحن آن بی‌اعتماد هستند.","it":"Nel caso di Ringelnatz, nato il 7 agosto 1883, si può studiare il peso politico della non serietà. I suoi versi non contengono programmi eppure erano sgraditi, perché trasmettono un atteggiamento: chi sa ridere di tutto si lascia difficilmente trascinare nell'esaltazione. Le dittature diffidano dell'umorismo non per i suoi contenuti, ma per il suo tono."}},"sideFacts":[]},"08-08":{"year":1869,"levels":{"A1":"Am 8. August 1869 gründen Arbeiter in Eisenach eine neue Partei. Sie wollen bessere Löhne und mehr Rechte. Später wird daraus die SPD.","A2":"Am 8. August 1869 gründen August Bebel und Wilhelm Liebknecht in Eisenach eine Arbeiterpartei. Es gab damals schon eine zweite Arbeiterpartei. Erst 1875 schlossen sich beide zusammen.","B1":"Am 8. August 1869 entsteht in Eisenach die Sozialdemokratische Arbeiterpartei. Sie stand in scharfer Konkurrenz zu Lassalles älterem Arbeiterverein — die beiden Lager stritten härter miteinander als mit dem Staat. 1875 vereinigten sie sich schließlich in Gotha.","B2":"Am 8. August 1869 wird in Eisenach eine zweite deutsche Arbeiterpartei gegründet. Der Streit zwischen beiden Richtungen ging um eine Grundfrage: ob man mit dem bestehenden Staat verhandeln oder ihn überwinden soll. Diese Frage hat die europäische Linke seither nie ganz verlassen.","C1":"Die Gründung vom 8. August 1869 zeigt, dass Bewegungen sich zuerst intern sortieren. Die Auseinandersetzung zwischen Eisenachern und Lassalleanern verbrauchte über Jahre mehr Kraft als der Kampf um politische Rechte — ein Muster, das sich bei jungen politischen Kräften regelmäßig wiederholt.","C2":"Am 8. August 1869 begann eine Konkurrenz, die sich sechs Jahre später in einem Kompromiss auflöste, den beide Seiten für halb falsch hielten. Genau solche Programme halten am längsten: Sie zwingen niemanden zur Aufgabe seiner Position und lassen die Frage offen, die eine Bewegung sonst sofort spalten würde."},"translationsA1":{"en":"On August 8, 1869, workers found a new party in Eisenach. They want better wages and more rights. Later it becomes the SPD.","ar":"في 8 أغسطس 1869، أسّس العمال حزبًا جديدًا في آيزناخ. أرادوا أجورًا أفضل وحقوقًا أكثر. لاحقًا صار الحزب الاشتراكي الديمقراطي.","tr":"8 Ağustos 1869'da işçiler Eisenach'ta yeni bir parti kurdu. Daha iyi ücret ve daha çok hak istiyorlardı. Sonradan bu SPD oldu.","ru":"8 августа 1869 года рабочие основали в Айзенахе новую партию. Они хотели лучших зарплат и больше прав. Позже из неё возникла СДПГ.","es":"El 8 de agosto de 1869, los obreros fundan un nuevo partido en Eisenach. Quieren mejores salarios y más derechos. Más tarde se convierte en el SPD.","fr":"Le 8 août 1869, des ouvriers fondent un nouveau parti à Eisenach. Ils veulent de meilleurs salaires et plus de droits. Il deviendra plus tard le SPD.","pl":"8 sierpnia 1869 roku robotnicy założyli w Eisenach nową partię. Chcieli lepszych płac i więcej praw. Później powstała z niej SPD.","uk":"8 серпня 1869 року робітники заснували в Айзенасі нову партію. Вони хотіли кращих зарплат і більше прав. Пізніше з неї постала СДПН.","fa":"در ۸ اوت ۱۸۶۹، کارگران در آیزناخ حزبی تازه بنیان نهادند. آنان دستمزد بهتر و حقوق بیشتر می‌خواستند. بعدها این حزب SPD شد.","it":"L'8 agosto 1869 alcuni operai fondano a Eisenach un nuovo partito. Vogliono salari migliori e più diritti. In seguito ne nascerà la SPD."},"translationsByLevel":{"A2":{"en":"On August 8, 1869, August Bebel and Wilhelm Liebknecht found a workers' party in Eisenach. At the time there was already a second workers' party. The two only merged in 1875.","ar":"في 8 أغسطس 1869 يؤسس أوغست بيبل وفيلهلم ليبكنخت حزباً عمالياً في آيزناخ. كان هناك بالفعل حزب عمالي ثانٍ في ذلك الوقت. ولم يندمج الحزبان إلا في عام 1875.","tr":"8 Ağustos 1869'da August Bebel ve Wilhelm Liebknecht, Eisenach'ta bir işçi partisi kurar. O sırada zaten ikinci bir işçi partisi vardı. İki parti ancak 1875'te birleşti.","ru":"8 августа 1869 года Август Бебель и Вильгельм Либкнехт основывают в Айзенахе рабочую партию. Тогда уже существовала вторая рабочая партия. Обе объединились лишь в 1875 году.","es":"El 8 de agosto de 1869, August Bebel y Wilhelm Liebknecht fundan un partido obrero en Eisenach. En aquel entonces ya existía un segundo partido obrero. Ambos no se unieron hasta 1875.","fr":"Le 8 août 1869, August Bebel et Wilhelm Liebknecht fondent un parti ouvrier à Eisenach. Il existait déjà à l'époque un second parti ouvrier. Les deux ne fusionnèrent qu'en 1875.","pl":"8 sierpnia 1869 roku August Bebel i Wilhelm Liebknecht zakładają w Eisenach partię robotniczą. Istniała już wtedy druga partia robotnicza. Obie połączyły się dopiero w 1875 roku.","uk":"8 серпня 1869 року Август Бебель і Вільгельм Лібкнехт засновують в Айзенасі робітничу партію. Тоді вже існувала друга робітнича партія. Обидві об'єдналися лише в 1875 році.","fa":"در ۸ اوت ۱۸۶۹ آوگوست بِبل و ویلهلم لیبکنشت در آیزناخ حزبی کارگری تأسیس کردند. در آن زمان از پیش حزب کارگری دیگری نیز وجود داشت. این دو حزب تنها در سال ۱۸۷۵ با هم یکی شدند.","it":"L'8 agosto 1869 August Bebel e Wilhelm Liebknecht fondano a Eisenach un partito operaio. All'epoca esisteva già un secondo partito operaio. Solo nel 1875 i due si unirono."},"B1":{"en":"On August 8, 1869, the Social Democratic Workers' Party is founded in Eisenach. It stood in fierce competition with Lassalle's older workers' association — the two camps fought harder with each other than with the state. In 1875, they finally united in Gotha.","ar":"في 8 أغسطس 1869 يتأسس في آيزناخ حزب العمال الاشتراكي الديمقراطي. كان في منافسة حادة مع جمعية العمال الأقدم التي أسسها لاسال — تنازع المعسكران فيما بينهما بقسوة أكبر من نزاعهما مع الدولة. اتحدا أخيراً عام 1875 في غوتا.","tr":"8 Ağustos 1869'da Eisenach'ta Sosyal Demokrat İşçi Partisi kurulur. Lassalle'ın daha eski işçi derneğiyle sert bir rekabet içindeydi — iki kamp birbiriyle devletle olduğundan daha sert çatışıyordu. 1875'te sonunda Gotha'da birleştiler.","ru":"8 августа 1869 года в Айзенахе возникает Социал-демократическая рабочая партия. Она находилась в острой конкуренции со старым рабочим союзом Лассаля — оба лагеря спорили друг с другом ожесточённее, чем с государством. В 1875 году они наконец объединились в Готе.","es":"El 8 de agosto de 1869 surge en Eisenach el Partido Obrero Socialdemócrata. Competía fuertemente con la asociación obrera más antigua de Lassalle: ambos bandos se enfrentaban entre sí con más dureza que con el Estado. En 1875 finalmente se unieron en Gotha.","fr":"Le 8 août 1869, le Parti ouvrier social-démocrate voit le jour à Eisenach. Il était en vive concurrence avec l'association ouvrière plus ancienne de Lassalle — les deux camps se querellaient plus durement entre eux qu'avec l'État. En 1875, ils finirent par s'unir à Gotha.","pl":"8 sierpnia 1869 roku powstaje w Eisenach Socjaldemokratyczna Partia Robotnicza. Rywalizowała ostro ze starszym związkiem robotniczym Lassalle'a — oba obozy spierały się ze sobą ostrzej niż z państwem. W 1875 roku ostatecznie zjednoczyły się w Gocie.","uk":"8 серпня 1869 року в Айзенасі виникає Соціал-демократична робітнича партія. Вона перебувала в гострій конкуренції зі старішим робітничим союзом Лассаля — обидва табори сварилися між собою жорсткіше, ніж з державою. У 1875 році вони врешті об'єдналися в Готі.","fa":"در ۸ اوت ۱۸۶۹ حزب کارگری سوسیال‌دموکرات در آیزناخ پدید آمد. این حزب در رقابتی سخت با انجمن کارگری قدیمی‌تر لاسال قرار داشت — این دو جناح با یکدیگر سخت‌تر از دولت نزاع می‌کردند. سرانجام در سال ۱۸۷۵ در گوتا با هم متحد شدند.","it":"L'8 agosto 1869 nasce a Eisenach il Partito Operaio Socialdemocratico. Era in forte concorrenza con l'associazione operaia più antica di Lassalle: i due schieramenti litigavano più duramente tra loro che con lo Stato. Nel 1875 si unirono infine a Gotha."},"B2":{"en":"On August 8, 1869, a second German workers' party is founded in Eisenach. The dispute between the two factions revolved around a fundamental question: whether one should negotiate with the existing state or overcome it. This question has never entirely left the European left since.","ar":"في 8 أغسطس 1869 يتأسس في آيزناخ حزب عمالي ألماني ثانٍ. دار الخلاف بين التيارين حول سؤال جوهري: هل يجب التفاوض مع الدولة القائمة أم تجاوزها؟ لم يفارق هذا السؤال اليسار الأوروبي كلياً منذ ذلك الحين.","tr":"8 Ağustos 1869'da Eisenach'ta ikinci bir Alman işçi partisi kurulur. İki akım arasındaki anlaşmazlık temel bir soru üzerineydi: mevcut devletle müzakere mi edilmeli, yoksa o aşılmalı mı? Bu soru o zamandan beri Avrupa solunu hiç tam olarak terk etmedi.","ru":"8 августа 1869 года в Айзенахе основывается вторая немецкая рабочая партия. Спор между двумя направлениями шёл о принципиальном вопросе: следует ли договариваться с существующим государством или его преодолеть. Этот вопрос с тех пор так и не покидал европейские левые движения окончательно.","es":"El 8 de agosto de 1869 se funda en Eisenach un segundo partido obrero alemán. La disputa entre ambas corrientes giraba en torno a una cuestión fundamental: si negociar con el Estado existente o superarlo. Esta pregunta nunca ha abandonado del todo a la izquierda europea desde entonces.","fr":"Le 8 août 1869, un second parti ouvrier allemand est fondé à Eisenach. Le différend entre les deux courants portait sur une question fondamentale : fallait-il négocier avec l'État existant ou le dépasser ? Cette question n'a jamais vraiment quitté la gauche européenne depuis lors.","pl":"8 sierpnia 1869 roku w Eisenach powstaje druga niemiecka partia robotnicza. Spór między obydwoma kierunkami dotyczył zasadniczej kwestii: czy negocjować z istniejącym państwem, czy je przezwyciężyć. To pytanie nigdy odtąd całkowicie nie opuściło europejskiej lewicy.","uk":"8 серпня 1869 року в Айзенасі виникає друга німецька робітнича партія. Суперечка між обома напрямами точилася навколо принципового питання: чи слід домовлятися з наявною державою, чи долати її. Це питання відтоді ніколи повністю не покидало європейські ліві рухи.","fa":"در ۸ اوت ۱۸۶۹ دومین حزب کارگری آلمانی در آیزناخ تأسیس شد. اختلاف میان این دو جریان بر سر یک پرسش بنیادین بود: آیا باید با دولت موجود مذاکره کرد یا آن را از میان برداشت؟ این پرسش از آن پس هرگز به‌طور کامل چپ اروپا را رها نکرده است.","it":"L'8 agosto 1869 viene fondato a Eisenach un secondo partito operaio tedesco. Il contrasto tra i due orientamenti verteva su una questione di fondo: se trattare con lo Stato esistente o superarlo. Questa domanda da allora non ha mai abbandonato del tutto la sinistra europea."},"C1":{"en":"The founding of August 8, 1869, shows that movements first sort themselves out internally. The conflict between the Eisenachers and the Lassalleans consumed more energy over the years than the struggle for political rights — a pattern that regularly repeats itself among young political forces.","ar":"يُظهر تأسيس 8 أغسطس 1869 أن الحركات تُرتّب أوضاعها الداخلية أولاً. استهلك الصراع بين الآيزناخيين واللاسالليين طاقة أكبر على مدى سنوات من النضال من أجل الحقوق السياسية — نمط يتكرر بانتظام لدى القوى السياسية الناشئة.","tr":"8 Ağustos 1869 kuruluşu, hareketlerin önce içsel olarak düzene girdiğini gösterir. Eisenachlılar ile Lassalleciler arasındaki çekişme, yıllarca siyasi haklar için mücadeleden daha fazla güç tüketti — genç siyasi güçlerde düzenli olarak tekrarlanan bir örüntü.","ru":"Основание 8 августа 1869 года показывает, что движения сначала выясняют отношения внутри себя. Противостояние между айзенахцами и лассальянцами годами отнимало больше сил, чем борьба за политические права, — закономерность, регулярно повторяющаяся у молодых политических сил.","es":"La fundación del 8 de agosto de 1869 muestra que los movimientos primero se ordenan internamente. El enfrentamiento entre los eisenachianos y los lassalleanos consumió durante años más energía que la lucha por los derechos políticos, un patrón que se repite regularmente en las fuerzas políticas jóvenes.","fr":"La fondation du 8 août 1869 montre que les mouvements se règlent d'abord en interne. L'affrontement entre les partisans d'Eisenach et les lassalliens a consumé pendant des années plus d'énergie que la lutte pour les droits politiques — un schéma qui se répète régulièrement chez les jeunes forces politiques.","pl":"Założenie z 8 sierpnia 1869 roku pokazuje, że ruchy najpierw porządkują się wewnętrznie. Spór między eisenachczykami a lassalczykami pochłaniał przez lata więcej sił niż walka o prawa polityczne — wzorzec, który regularnie powtarza się wśród młodych sił politycznych.","uk":"Заснування 8 серпня 1869 року показує, що рухи спершу впорядковуються всередині себе. Протистояння між айзенахцями та лассальянцями роками поглинало більше сил, ніж боротьба за політичні права — закономірність, яка регулярно повторюється серед молодих політичних сил.","fa":"تأسیس در ۸ اوت ۱۸۶۹ نشان می‌دهد که جنبش‌ها ابتدا در درون خود سامان می‌یابند. نزاع میان آیزناخی‌ها و لاسالی‌ها سال‌ها نیرویی بیشتر از مبارزه برای حقوق سیاسی مصرف کرد — الگویی که در نیروهای سیاسی جوان مرتباً تکرار می‌شود.","it":"La fondazione dell'8 agosto 1869 mostra che i movimenti si ordinano prima al proprio interno. Lo scontro tra gli eisenachiani e i lassalliani assorbì per anni più energie della lotta per i diritti politici, uno schema che si ripete regolarmente nelle giovani forze politiche."},"C2":{"en":"On August 8, 1869, a rivalry began that dissolved six years later into a compromise both sides considered half wrong. It is precisely such programs that last longest: they force no one to give up their position and leave open the question that would otherwise split a movement immediately.","ar":"في 8 أغسطس 1869 بدأت منافسة انحلّت بعد ست سنوات في حل وسط اعتبره الطرفان خاطئاً جزئياً. مثل هذه البرامج بالذات هي التي تدوم أطول: فهي لا تُجبر أحداً على التخلي عن موقفه وتترك السؤال معلقاً الذي كان سيشق أي حركة أخرى فوراً.","tr":"8 Ağustos 1869'da, altı yıl sonra her iki tarafın da yarı yanlış bulduğu bir uzlaşmada eriyen bir rekabet başladı. İşte tam da böyle programlar en uzun süre ayakta kalır: Kimseyi konumundan vazgeçmeye zorlamaz ve aksi takdirde bir hareketi hemen bölecek soruyu açık bırakır.","ru":"8 августа 1869 года началось соперничество, которое шесть лет спустя разрешилось компромиссом, который обе стороны считали наполовину неверным. Именно такие программы держатся дольше всего: они никого не заставляют отказываться от своей позиции и оставляют открытым вопрос, который иначе сразу же расколол бы движение.","es":"El 8 de agosto de 1869 comenzó una rivalidad que seis años después se disolvió en un compromiso que ambos bandos consideraban medio equivocado. Precisamente ese tipo de programas son los que más perduran: no obligan a nadie a renunciar a su posición y dejan abierta la cuestión que, de otro modo, dividiría de inmediato a un movimiento.","fr":"Le 8 août 1869 débuta une rivalité qui, six ans plus tard, se résolut par un compromis que les deux camps jugeaient à moitié erroné. Ce sont précisément de tels programmes qui durent le plus longtemps : ils ne forcent personne à abandonner sa position et laissent ouverte la question qui, sinon, diviserait immédiatement un mouvement.","pl":"8 sierpnia 1869 roku rozpoczęła się rywalizacja, która sześć lat później rozwiązała się w kompromisie, który obie strony uważały za w połowie błędny. To właśnie takie programy trwają najdłużej: nikogo nie zmuszają do porzucenia swojego stanowiska i pozostawiają otwartą kwestię, która inaczej natychmiast rozłamałaby ruch.","uk":"8 серпня 1869 року почалося суперництво, яке шість років по тому розчинилося в компромісі, що обидві сторони вважали наполовину хибним. Саме такі програми тримаються найдовше: вони нікого не змушують відмовлятися від своєї позиції і залишають відкритим питання, яке інакше одразу розкололо б рух.","fa":"در ۸ اوت ۱۸۶۹ رقابتی آغاز شد که شش سال بعد به مصالحه‌ای انجامید که هر دو طرف آن را تا حدی نادرست می‌دانستند. دقیقاً چنین برنامه‌هایی طولانی‌ترین عمر را دارند: هیچ‌کس را ناچار به کنارگذاشتن موضع خود نمی‌کنند و آن پرسشی را که در غیر این صورت بی‌درنگ جنبشی را دو شقه می‌کرد، باز می‌گذارند.","it":"L'8 agosto 1869 iniziò una rivalità che sei anni dopo si risolse in un compromesso che entrambe le parti consideravano per metà sbagliato. Sono proprio programmi di questo tipo a durare più a lungo: non costringono nessuno ad abbandonare la propria posizione e lasciano aperta la questione che altrimenti dividerebbe subito un movimento."}},"sideFacts":[]},"08-09":{"year":1896,"levels":{"A1":"Am 9. August 1896 stirbt Otto Lilienthal. Er baut Flugapparate und fliegt selbst damit. Bei einem Flug stürzt er ab.","A2":"Am 9. August 1896 stirbt Otto Lilienthal an den Folgen eines Absturzes. Er war der erste Mensch, der regelmäßig mit einem Gleiter flog. Über zweitausend Flüge hatte er gemacht.","B1":"Am 9. August 1896 stirbt Otto Lilienthal, einen Tag nach einem Absturz mit seinem Gleiter. Er hatte den Vogelflug jahrelang beobachtet und daraus die Form seiner Tragflächen abgeleitet. Die Brüder Wright bauten später ausdrücklich auf seinen Messwerten auf.","B2":"Am 9. August 1896 stirbt Otto Lilienthal. Sein entscheidender Beitrag waren nicht die Flüge, sondern die Tabellen: Er maß systematisch, wie viel Auftrieb eine Tragfläche bei welchem Winkel erzeugt. Ohne diese Daten hätte der Motorflug Jahre länger gebraucht.","C1":"Der am 9. August 1896 Gestorbene betrieb Fliegen als Messwissenschaft, nicht als Wagnis. Seine letzten Worte, es müssten Opfer gebracht werden, sind zum geflügelten Wort geworden — und verdecken, wie sehr er auf Systematik statt auf Mut setzte.","C2":"An Lilienthal, gestorben am 9. August 1896, zeigt sich, wie Technikgeschichte ihre Helden zurechtschneidet. Erinnert wird der Absturz, entscheidend waren die Tabellen. Die Erzählung vom kühnen Pionier ist attraktiver als die vom geduldigen Vermesser — und verfälscht regelmäßig, woran technischer Fortschritt tatsächlich hängt."},"translationsA1":{"en":"On August 9, 1896, Otto Lilienthal dies. He builds flying machines and flies them himself. On one flight he crashes.","ar":"في 9 أغسطس 1896، توفي أوتو ليلينتال. كان يبني آلات طائرة ويطير بها بنفسه. في إحدى الرحلات سقط.","tr":"9 Ağustos 1896'da Otto Lilienthal öldü. Uçan aygıtlar yapar ve kendisi uçardı. Bir uçuşta düştü.","ru":"9 августа 1896 года умер Отто Лилиенталь. Он строил летательные аппараты и сам на них летал. В одном полёте он разбился.","es":"El 9 de agosto de 1896 muere Otto Lilienthal. Construye aparatos voladores y vuela él mismo. En un vuelo se estrella.","fr":"Le 9 août 1896, Otto Lilienthal meurt. Il construit des appareils volants et vole lui-même. Lors d'un vol, il s'écrase.","pl":"9 sierpnia 1896 roku zmarł Otto Lilienthal. Budował aparaty latające i sam nimi latał. Podczas jednego lotu runął.","uk":"9 серпня 1896 року помер Отто Лілієнталь. Він будував літальні апарати й сам на них літав. В одному польоті він розбився.","fa":"در ۹ اوت ۱۸۹۶، اتو لیلینتال درگذشت. او دستگاه‌های پرنده می‌ساخت و خود با آن‌ها پرواز می‌کرد. در یکی از پروازها سقوط کرد.","it":"Il 9 agosto 1896 muore Otto Lilienthal. Costruisce apparecchi volanti e vola lui stesso con essi. Durante un volo precipita."},"translationsByLevel":{"A2":{"en":"On August 9, 1896, Otto Lilienthal dies from the effects of a crash. He was the first person to fly regularly with a glider. He had made over two thousand flights.","ar":"في 9 أغسطس 1896 يتوفى أوتو ليلينتال متأثراً بجروح سقوط. كان أول إنسان يطير بانتظام بواسطة طائرة شراعية. وكان قد أجرى أكثر من ألفي رحلة.","tr":"9 Ağustos 1896'da Otto Lilienthal bir düşüşün ardından ölür. Bir planörle düzenli olarak uçan ilk insandı. İki binden fazla uçuş yapmıştı.","ru":"9 августа 1896 года Отто Лилиенталь умирает от последствий падения. Он был первым человеком, регулярно летавшим на планёре. Он совершил более двух тысяч полётов.","es":"El 9 de agosto de 1896 muere Otto Lilienthal a causa de un accidente. Fue la primera persona en volar regularmente con un planeador. Había realizado más de dos mil vuelos.","fr":"Le 9 août 1896, Otto Lilienthal meurt des suites d'une chute. Il fut le premier homme à voler régulièrement avec un planeur. Il avait effectué plus de deux mille vols.","pl":"9 sierpnia 1896 roku umiera Otto Lilienthal wskutek upadku. Był pierwszym człowiekiem, który regularnie latał szybowcem. Wykonał ponad dwa tysiące lotów.","uk":"9 серпня 1896 року помирає Отто Ліліенталь унаслідок падіння. Він був першою людиною, яка регулярно літала на планері. Він здійснив понад дві тисячі польотів.","fa":"در ۹ اوت ۱۸۹۶ اتو لیلینتال بر اثر سقوطی درگذشت. او نخستین انسانی بود که به‌طور منظم با یک بالگرد بدون موتور پرواز کرد. او بیش از دو هزار پرواز انجام داده بود.","it":"Il 9 agosto 1896 muore Otto Lilienthal per le conseguenze di un incidente. Fu il primo uomo a volare regolarmente con un aliante. Aveva effettuato oltre duemila voli."},"B1":{"en":"On August 9, 1896, Otto Lilienthal dies, one day after crashing with his glider. He had observed bird flight for years and derived the shape of his wings from it. The Wright brothers later explicitly built on his measurements.","ar":"في 9 أغسطس 1896 يتوفى أوتو ليلينتال بعد يوم واحد من سقوط طائرته الشراعية. كان قد راقب طيران الطيور لسنوات واستنتج منه شكل أجنحته. اعتمد الأخوان رايت لاحقاً بوضوح على قياساته.","tr":"9 Ağustos 1896'da Otto Lilienthal, planörüyle yaşadığı düşüşten bir gün sonra hayatını kaybeder. Yıllarca kuş uçuşunu gözlemlemiş ve kanatlarının şeklini bundan türetmişti. Wright kardeşler sonradan açıkça onun ölçüm verilerine dayandılar.","ru":"9 августа 1896 года умирает Отто Лилиенталь, через день после падения на своём планёре. Он годами наблюдал за полётом птиц и вывел из этого форму своих крыльев. Братья Райт позднее прямо опирались на его измерения.","es":"El 9 de agosto de 1896 muere Otto Lilienthal, un día después de un accidente con su planeador. Había observado durante años el vuelo de las aves y de ahí dedujo la forma de sus alas. Los hermanos Wright se basaron después expresamente en sus mediciones.","fr":"Le 9 août 1896, Otto Lilienthal meurt, un jour après une chute avec son planeur. Il avait observé pendant des années le vol des oiseaux et en avait déduit la forme de ses ailes. Les frères Wright s'appuyèrent plus tard explicitement sur ses mesures.","pl":"9 sierpnia 1896 roku umiera Otto Lilienthal, dzień po upadku ze swoim szybowcem. Latami obserwował lot ptaków i wywiódł z tego kształt swoich skrzydeł. Bracia Wright później wyraźnie opierali się na jego pomiarach.","uk":"9 серпня 1896 року помирає Отто Ліліенталь, через день після падіння зі своїм планером. Він роками спостерігав за польотом птахів і виводив із цього форму своїх крил. Брати Райт пізніше прямо спиралися на його вимірювання.","fa":"در ۹ اوت ۱۸۹۶ اتو لیلینتال، یک روز پس از سقوط با بالگردش، درگذشت. او سال‌ها پرواز پرندگان را زیر نظر داشت و شکل بال‌های خود را از آن استخراج کرده بود. برادران رایت بعدها آشکارا بر پایه‌ی داده‌های اندازه‌گیری او کار کردند.","it":"Il 9 agosto 1896 muore Otto Lilienthal, un giorno dopo essere precipitato con il suo aliante. Aveva osservato per anni il volo degli uccelli e ne aveva ricavato la forma delle sue ali. I fratelli Wright si basarono in seguito esplicitamente sui suoi dati."},"B2":{"en":"On August 9, 1896, Otto Lilienthal dies. His decisive contribution was not the flights but the tables: he systematically measured how much lift a wing generates at what angle. Without this data, powered flight would have taken years longer.","ar":"في 9 أغسطس 1896 يتوفى أوتو ليلينتال. لم تكن مساهمته الحاسمة هي الرحلات بل الجداول: قاس بشكل منهجي مقدار الرفع الذي ينتجه الجناح عند أي زاوية. ولولا هذه البيانات لاستغرقت الطيران بالمحرك سنوات أطول.","tr":"9 Ağustos 1896'da Otto Lilienthal hayatını kaybeder. Onun asıl katkısı uçuşlar değil, tablolardı: Bir kanadın hangi açıda ne kadar kaldırma kuvveti ürettiğini sistematik olarak ölçtü. Bu veriler olmasaydı motorlu uçuş yıllarca daha uzun sürerdi.","ru":"9 августа 1896 года умирает Отто Лилиенталь. Его решающий вклад состоял не в полётах, а в таблицах: он систематически измерял, сколько подъёмной силы создаёт крыло при том или ином угле. Без этих данных моторный полёт занял бы годами больше времени.","es":"El 9 de agosto de 1896 muere Otto Lilienthal. Su aporte decisivo no fueron los vuelos, sino las tablas: midió sistemáticamente cuánta sustentación genera un ala según el ángulo. Sin esos datos, el vuelo a motor habría tardado años más en desarrollarse.","fr":"Le 9 août 1896, Otto Lilienthal meurt. Sa contribution décisive ne fut pas les vols mais les tableaux : il mesura systématiquement combien de portance une aile génère à tel ou tel angle. Sans ces données, le vol motorisé aurait mis des années de plus à voir le jour.","pl":"9 sierpnia 1896 roku umiera Otto Lilienthal. Jego decydujący wkład stanowiły nie loty, lecz tabele: systematycznie mierzył, ile siły nośnej wytwarza skrzydło przy danym kącie. Bez tych danych lot silnikowy potrzebowałby o lata dłużej.","uk":"9 серпня 1896 року помирає Отто Ліліенталь. Його вирішальним внеском були не польоти, а таблиці: він систематично вимірював, скільки підйомної сили створює крило під тим чи іншим кутом. Без цих даних моторний політ зайняв би на роки більше часу.","fa":"در ۹ اوت ۱۸۹۶ اتو لیلینتال درگذشت. سهم تعیین‌کننده‌ی او پروازها نبودند، بلکه جدول‌ها بودند: او به‌طور نظام‌مند اندازه می‌گرفت که یک بال در چه زاویه‌ای چقدر نیروی برآ تولید می‌کند. بدون این داده‌ها، پرواز موتوری سال‌ها بیشتر طول می‌کشید.","it":"Il 9 agosto 1896 muore Otto Lilienthal. Il suo contributo decisivo non furono i voli, ma le tabelle: misurò sistematicamente quanta portanza genera un'ala a seconda dell'angolo. Senza questi dati il volo a motore avrebbe richiesto anni in più."},"C1":{"en":"The man who died on August 9, 1896, pursued flying as a science of measurement, not as a daring feat. His last words — that sacrifices must be made — have become a famous saying, obscuring how much he relied on systematic method rather than courage.","ar":"مارس المتوفى في 9 أغسطس 1896 الطيران كعلم قياس، لا كمغامرة. أصبحت كلماته الأخيرة، أنه لا بد من تقديم تضحيات، مثلاً سائراً — وهي تحجب مدى اعتماده على المنهجية بدلاً من الشجاعة.","tr":"9 Ağustos 1896'da ölen kişi, uçmayı bir cesaret gösterisi değil, bir ölçüm bilimi olarak yürüttü. 'Kurbanlar verilmelidir' şeklindeki son sözleri meşhur bir söz haline geldi — ve onun cesaretten çok sistematiğe dayandığını gizler.","ru":"Умерший 9 августа 1896 года занимался полётами как измерительной наукой, а не как отчаянным предприятием. Его последние слова о том, что нужны жертвы, стали крылатой фразой — и скрывают, насколько он полагался на систематичность, а не на отвагу.","es":"El fallecido el 9 de agosto de 1896 practicaba el vuelo como una ciencia de medición, no como una temeridad. Sus últimas palabras, según las cuales había que hacer sacrificios, se han convertido en una frase célebre, que oculta cuánto se basaba en la sistemática y no en el valor.","fr":"Celui qui est mort le 9 août 1896 pratiquait le vol comme une science de la mesure, non comme un pari audacieux. Ses derniers mots, selon lesquels des sacrifices étaient nécessaires, sont devenus une formule célèbre — qui masque à quel point il misait sur la méthode plutôt que sur le courage.","pl":"Zmarły 9 sierpnia 1896 roku uprawiał latanie jako naukę pomiarową, nie jako ryzykowną przygodę. Jego ostatnie słowa, że trzeba ponosić ofiary, stały się skrzydlatym powiedzeniem — i przesłaniają to, jak bardzo stawiał na systematyczność, a nie na odwagę.","uk":"Померлий 9 серпня 1896 року займався польотами як точною наукою, а не як ризикованою авантюрою. Його останні слова про те, що потрібні жертви, стали крилатим виразом — і приховують, наскільки він покладався на систематичність, а не на відвагу.","fa":"کسی که در ۹ اوت ۱۸۹۶ درگذشت، پرواز را به‌مثابه دانشی مبتنی بر اندازه‌گیری دنبال می‌کرد، نه به‌عنوان یک اقدام مخاطره‌آمیز. آخرین سخنان او، که باید فداکاری‌هایی صورت گیرد، به سخنی مشهور بدل شده است — و پنهان می‌کند که او تا چه اندازه به نظم‌مندی تکیه داشت تا شجاعت.","it":"Morto il 9 agosto 1896, praticava il volo come scienza della misura, non come azzardo. Le sue ultime parole, secondo cui bisogna fare dei sacrifici, sono diventate un modo di dire, e nascondono quanto puntasse sul metodo piuttosto che sul coraggio."},"C2":{"en":"In Lilienthal, who died on August 9, 1896, one can see how the history of technology tailors its heroes. What is remembered is the crash; what was decisive were the tables. The narrative of the bold pioneer is more appealing than that of the patient measurer — and it regularly distorts what technical progress actually depends on.","ar":"يتضح في ليلينتال، المتوفى في 9 أغسطس 1896، كيف يُعيد تاريخ التقنية تشكيل أبطاله. يُتذكر السقوط، بينما كانت الجداول هي الحاسمة. حكاية الرائد الجريء أكثر جاذبية من حكاية القائم بالقياسات الصبور — وهي تشوّه بانتظام ما يعتمد عليه التقدم التقني فعلاً.","tr":"9 Ağustos 1896'da ölen Lilienthal üzerinden, teknoloji tarihinin kahramanlarını nasıl yeniden biçimlendirdiği görülür. Hatırlanan düşüştür, oysa belirleyici olan tablolardı. Cesur öncü anlatısı, sabırlı ölçümcü anlatısından daha çekicidir — ve teknik ilerlemenin gerçekte neye dayandığını düzenli olarak çarpıtır.","ru":"На примере Лилиенталя, умершего 9 августа 1896 года, видно, как история техники подгоняет своих героев. Помнят падение, а решающими были таблицы. Рассказ о смелом первопроходце привлекательнее рассказа о терпеливом измерителе — и регулярно искажает то, от чего на самом деле зависит технический прогресс.","es":"En Lilienthal, fallecido el 9 de agosto de 1896, se aprecia cómo la historia de la técnica moldea a sus héroes. Se recuerda el accidente; lo decisivo fueron las tablas. El relato del pionero audaz resulta más atractivo que el del medidor paciente, y falsea regularmente aquello de lo que realmente depende el progreso técnico.","fr":"Chez Lilienthal, mort le 9 août 1896, on voit comment l'histoire des techniques façonne ses héros. On se souvient de la chute ; ce qui fut décisif, ce furent les tableaux. Le récit du pionnier téméraire est plus séduisant que celui du mesureur patient — et il déforme régulièrement ce dont dépend réellement le progrès technique.","pl":"Na przykładzie Lilienthala, zmarłego 9 sierpnia 1896 roku, widać, jak historia techniki kroi swoich bohaterów na miarę. Pamięta się upadek, decydujące były jednak tabele. Opowieść o śmiałym pionierze jest bardziej atrakcyjna niż ta o cierpliwym pomiarowcu — i regularnie zniekształca to, od czego naprawdę zależy postęp techniczny.","uk":"На прикладі Ліліенталя, який помер 9 серпня 1896 року, видно, як історія техніки перекроює своїх героїв. Пам'ятають про падіння, а вирішальними були таблиці. Розповідь про відважного першопрохідця привабливіша за розповідь про терплячого вимірювача — і регулярно спотворює те, від чого насправді залежить технічний прогрес.","fa":"درباره‌ی لیلینتال، که در ۹ اوت ۱۸۹۶ درگذشت، می‌توان دید که چگونه تاریخ فناوری قهرمانانش را می‌آراید. آنچه به‌یاد می‌ماند سقوط اوست، اما آنچه تعیین‌کننده بود جدول‌ها بودند. روایت پیشگام دلیر جذاب‌تر از روایت اندازه‌گیرِ صبور است — و پیوسته آنچه را که پیشرفت فنی واقعاً به آن وابسته است تحریف می‌کند.","it":"Nel caso di Lilienthal, morto il 9 agosto 1896, si vede come la storia della tecnica ritagli i propri eroi. Si ricorda l'incidente, ma decisive furono le tabelle. Il racconto del pioniere audace è più attraente di quello del paziente rilevatore di misure, e falsa regolarmente da cosa dipenda davvero il progresso tecnico."}},"sideFacts":[]},"08-10":{"year":1995,"levels":{"A1":"Am 10. August 1995 sagt ein Gericht: Kreuze in bayrischen Schulen sind ein Problem. Das ist der Kruzifix-Beschluss.","A2":"Am 10. August 1995 veröffentlicht das Bundesverfassungsgericht den Kruzifix-Beschluss. Kreuze in bayrischen Klassenzimmern verstoßen gegen die Religionsfreiheit im Grundgesetz.","B1":"Am 10. August 1995 wird der sogenannte Kruzifix-Beschluss des Bundesverfassungsgerichts veröffentlicht. Die verpflichtende Anbringung von Kreuzen in bayrischen Klassenzimmern verstößt demnach gegen die im Grundgesetz garantierte Religionsfreiheit.","B2":"Am 10. August 1995 wird der Kruzifix-Beschluss des Bundesverfassungsgerichts veröffentlicht (gefällt bereits am 16. Mai): Die in der bayrischen Volksschulordnung vorgeschriebenen Kreuze in Klassenzimmern verletzen die negative Religionsfreiheit nicht-christlicher oder konfessionsloser Schüler. Das Urteil löst eine heftige gesellschaftliche Debatte aus.","C1":"Der am 10. August 1995 veröffentlichte Kruzifix-Beschluss des Bundesverfassungsgerichts erklärte die verpflichtende Kreuz-Anbringung in bayrischen Klassenzimmern für verfassungswidrig, da sie die negative Religionsfreiheit andersgläubiger Schüler verletze. Das Urteil zählt zu den gesellschaftlich umstrittensten Entscheidungen des Gerichts.","C2":"Der Kruzifix-Beschluss vom 10. August 1995 löste eine der emotionalsten Verfassungsdebatten der bundesdeutschen Geschichte aus: Während Kritiker eine Verdrängung christlicher Kultur aus dem öffentlichen Raum beklagten, sahen Befürworter darin eine konsequente Anwendung der im Grundgesetz verankerten staatlichen Neutralität in Glaubensfragen."},"translationsA1":{"en":"On August 10, 1995, a court says: crosses in Bavarian schools are a problem. This is the Crucifix Decision.","ar":"في 10 أغسطس 1995، قالت محكمة: الصلبان في مدارس بافاريا مشكلة. هذا قرار الصليب.","tr":"10 Ağustos 1995'te bir mahkeme şunu söyledi: Bavyera okullarındaki haçlar bir sorundur. Bu, Haç Kararı'dır.","ru":"10 августа 1995 года суд заявил: кресты в баварских школах — это проблема. Это «решение о распятии».","es":"El 10 de agosto de 1995, un tribunal dice: los crucifijos en las escuelas bávaras son un problema. Esta es la Decisión del Crucifijo.","fr":"Le 10 août 1995, un tribunal déclare : les croix dans les écoles bavaroises posent problème. C'est la décision sur le crucifix.","pl":"10 sierpnia 1995 roku sąd orzekł: krzyże w bawarskich szkołach są problemem. To tzw. orzeczenie w sprawie krucyfiksu.","uk":"10 серпня 1995 року суд заявив: хрести в баварських школах — це проблема. Це «рішення про розп'яття».","fa":"در ۱۰ اوت ۱۹۹۵، دادگاهی گفت: صلیب‌ها در مدارس باواریا مشکل‌ساز هستند. این تصمیم صلیب نام دارد.","it":"Il 10 agosto 1995 un tribunale dichiara: i crocifissi nelle scuole bavaresi sono un problema. È la sentenza sul crocifisso."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 10, 1995, the Federal Constitutional Court publishes the Crucifix Decision. Crosses in Bavarian classrooms violate the freedom of religion in the Basic Law.","ar":"في 10 أغسطس 1995 تنشر المحكمة الدستورية الاتحادية قرار الصليب. تنتهك الصلبان في الفصول الدراسية البافارية حرية الدين المنصوص عليها في القانون الأساسي.","tr":"10 Ağustos 1995'te Federal Anayasa Mahkemesi Haç Kararı'nı yayımlar. Bavyera sınıflarındaki haçlar, Anayasa'daki din özgürlüğünü ihlal etmektedir.","ru":"10 августа 1995 года Федеральный конституционный суд публикует «Решение о распятии». Кресты в баварских классных комнатах нарушают свободу вероисповедания, закреплённую в Основном законе.","es":"El 10 de agosto de 1995, el Tribunal Constitucional Federal publica la sentencia del Crucifijo. Los crucifijos en las aulas bávaras vulneran la libertad religiosa consagrada en la Ley Fundamental.","fr":"Le 10 août 1995, la Cour constitutionnelle fédérale publie l'arrêt sur le crucifix. Les crucifix dans les salles de classe bavaroises violent la liberté religieuse garantie par la Loi fondamentale.","pl":"10 sierpnia 1995 roku Federalny Trybunał Konstytucyjny publikuje orzeczenie w sprawie krucyfiksów. Krzyże w bawarskich klasach naruszają wolność wyznania zapisaną w Ustawie Zasadniczej.","uk":"10 серпня 1995 року Федеральний конституційний суд оприлюднює рішення про розп'яття. Хрести в баварських класних кімнатах порушують свободу віросповідання, закріплену в Основному законі.","fa":"در ۱۰ اوت ۱۹۹۵ دادگاه قانون اساسی فدرال آلمان رأی صلیب را منتشر کرد. نصب صلیب در کلاس‌های درس باواریا آزادی دین را که در قانون اساسی تضمین شده نقض می‌کند.","it":"Il 10 agosto 1995 la Corte costituzionale federale pubblica la sentenza sul crocifisso. I crocifissi nelle aule bavaresi violano la libertà religiosa sancita dalla Legge fondamentale."},"B1":{"en":"On August 10, 1995, the so-called Crucifix Decision of the Federal Constitutional Court is published. According to it, the mandatory placement of crosses in Bavarian classrooms violates the freedom of religion guaranteed by the Basic Law.","ar":"في 10 أغسطس 1995 يُنشر ما يُعرف بقرار الصليب الصادر عن المحكمة الدستورية الاتحادية. ووفقاً له، فإن الإلزام بتعليق الصلبان في الفصول الدراسية البافارية ينتهك حرية الدين المكفولة في القانون الأساسي.","tr":"10 Ağustos 1995'te Federal Anayasa Mahkemesi'nin sözde Haç Kararı yayımlanır. Buna göre, Bavyera sınıflarında haçların zorunlu olarak asılması, Anayasa'da güvence altına alınan din özgürlüğünü ihlal etmektedir.","ru":"10 августа 1995 года публикуется так называемое «Решение о распятии» Федерального конституционного суда. Согласно ему, обязательное размещение крестов в баварских классных комнатах нарушает свободу вероисповедания, гарантированную Основным законом.","es":"El 10 de agosto de 1995 se publica la llamada sentencia del Crucifijo del Tribunal Constitucional Federal. Según esta, la colocación obligatoria de crucifijos en las aulas bávaras vulnera la libertad religiosa garantizada por la Ley Fundamental.","fr":"Le 10 août 1995, le fameux arrêt sur le crucifix de la Cour constitutionnelle fédérale est publié. Selon celui-ci, l'apposition obligatoire de crucifix dans les salles de classe bavaroises viole la liberté religieuse garantie par la Loi fondamentale.","pl":"10 sierpnia 1995 roku publikowane jest tak zwane orzeczenie w sprawie krucyfiksów Federalnego Trybunału Konstytucyjnego. Zgodnie z nim obowiązkowe umieszczanie krzyży w bawarskich klasach narusza wolność wyznania gwarantowaną przez Ustawę Zasadniczą.","uk":"10 серпня 1995 року публікується так зване рішення про розп'яття Федерального конституційного суду. Згідно з ним, обов'язкове розміщення хрестів у баварських класних кімнатах порушує свободу віросповідання, гарантовану Основним законом.","fa":"در ۱۰ اوت ۱۹۹۵ آنچه به رأی صلیب دادگاه قانون اساسی فدرال معروف است منتشر می‌شود. بر پایه‌ی این رأی، نصب اجباری صلیب در کلاس‌های درس باواریا آزادی دین تضمین‌شده در قانون اساسی را نقض می‌کند.","it":"Il 10 agosto 1995 viene pubblicata la cosiddetta sentenza sul crocifisso della Corte costituzionale federale. L'obbligo di esporre crocifissi nelle aule bavaresi viola quindi la libertà religiosa garantita dalla Legge fondamentale."},"B2":{"en":"On August 10, 1995, the Federal Constitutional Court's Crucifix Decision is published (already handed down on May 16): the crosses in classrooms mandated by Bavarian elementary school regulations violate the negative freedom of religion of non-Christian or non-denominational pupils. The ruling triggers a fierce public debate.","ar":"في 10 أغسطس 1995 يُنشر قرار الصليب الصادر عن المحكمة الدستورية الاتحادية (والذي صدر بالفعل في 16 مايو): الصلبان المفروضة في لوائح المدارس الابتدائية البافارية داخل الفصول تنتهك حرية عدم اعتناق الدين لدى التلاميذ غير المسيحيين أو غير المنتمين لطائفة. أثار الحكم جدلاً اجتماعياً حاداً.","tr":"10 Ağustos 1995'te Federal Anayasa Mahkemesi'nin Haç Kararı (16 Mayıs'ta zaten verilmişti) yayımlanır: Bavyera ilkokul yönetmeliğinde öngörülen sınıf içi haçlar, Hristiyan olmayan veya mezhepsiz öğrencilerin negatif din özgürlüğünü ihlal etmektedir. Karar şiddetli bir toplumsal tartışmayı ateşler.","ru":"10 августа 1995 года публикуется «Решение о распятии» Федерального конституционного суда (вынесенное ещё 16 мая): предписанные баварскими школьными правилами кресты в классах нарушают негативную свободу вероисповедания нехристианских или неконфессиональных учеников. Решение вызывает бурную общественную дискуссию.","es":"El 10 de agosto de 1995 se publica la sentencia del Crucifijo del Tribunal Constitucional Federal (dictada ya el 16 de mayo): los crucifijos exigidos en las aulas por el reglamento escolar bávaro vulneran la libertad religiosa negativa de los alumnos no cristianos o sin confesión. El fallo desata un intenso debate social.","fr":"Le 10 août 1995, l'arrêt sur le crucifix de la Cour constitutionnelle fédérale (déjà rendu le 16 mai) est publié : les crucifix imposés par le règlement scolaire bavarois dans les salles de classe violent la liberté religieuse négative des élèves non chrétiens ou sans confession. Le jugement déclenche un vif débat sociétal.","pl":"10 sierpnia 1995 roku publikowane jest orzeczenie w sprawie krucyfiksów Federalnego Trybunału Konstytucyjnego (wydane już 16 maja): krzyże nakazane przez bawarski regulamin szkół podstawowych w klasach naruszają negatywną wolność wyznania uczniów niechrześcijańskich lub bezwyznaniowych. Wyrok wywołuje gwałtowną debatę społeczną.","uk":"10 серпня 1995 року публікується рішення про розп'яття Федерального конституційного суду (винесене ще 16 травня): приписані баварським шкільним регламентом хрести в класах порушують негативну свободу віросповідання нехристиянських або неконфесійних учнів. Рішення викликає бурхливу суспільну дискусію.","fa":"در ۱۰ اوت ۱۹۹۵ رأی صلیب دادگاه قانون اساسی فدرال (که پیش‌تر در ۱۶ مه صادر شده بود) منتشر می‌شود: نصب اجباری صلیب در کلاس‌ها که آیین‌نامه‌ی مدارس ابتدایی باواریا مقرر کرده بود، آزادی منفی دینی دانش‌آموزان غیرمسیحی یا بی‌دین را نقض می‌کند. این رأی جدلی اجتماعی شدید برمی‌انگیزد.","it":"Il 10 agosto 1995 viene pubblicata la sentenza sul crocifisso della Corte costituzionale federale (emessa già il 16 maggio): i crocifissi nelle aule, prescritti dal regolamento scolastico bavarese, violano la libertà religiosa negativa degli alunni non cristiani o senza confessione. La sentenza scatena un acceso dibattito sociale."},"C1":{"en":"The Federal Constitutional Court's Crucifix Decision, published on August 10, 1995, declared the mandatory placement of crosses in Bavarian classrooms unconstitutional, on the grounds that it violated the negative freedom of religion of pupils of other faiths. The ruling ranks among the court's most socially contested decisions.","ar":"أعلن قرار الصليب الصادر عن المحكمة الدستورية الاتحادية والمنشور في 10 أغسطس 1995 أن الإلزام بتعليق الصلبان في الفصول الدراسية البافارية غير دستوري، لانتهاكه حرية عدم اعتناق الدين لدى التلاميذ من ديانات أخرى. ويُعد الحكم من أكثر قرارات المحكمة إثارة للجدل المجتمعي.","tr":"10 Ağustos 1995'te yayımlanan Federal Anayasa Mahkemesi'nin Haç Kararı, Bavyera sınıflarında haç asılmasının zorunlu tutulmasını, farklı inançtaki öğrencilerin negatif din özgürlüğünü ihlal ettiği gerekçesiyle anayasaya aykırı ilan etti. Karar, mahkemenin toplumsal açıdan en tartışmalı kararlarından biri sayılır.","ru":"«Решение о распятии» Федерального конституционного суда, опубликованное 10 августа 1995 года, объявило обязательное размещение крестов в баварских классных комнатах неконституционным, поскольку оно нарушает негативную свободу вероисповедания учеников иной веры. Это решение относится к числу самых спорных в общественном отношении решений суда.","es":"La sentencia del Crucifijo del Tribunal Constitucional Federal, publicada el 10 de agosto de 1995, declaró inconstitucional la colocación obligatoria de crucifijos en las aulas bávaras, por vulnerar la libertad religiosa negativa de los alumnos de otras creencias. El fallo se cuenta entre las decisiones socialmente más controvertidas del tribunal.","fr":"L'arrêt sur le crucifix de la Cour constitutionnelle fédérale, publié le 10 août 1995, a déclaré inconstitutionnelle l'apposition obligatoire de crucifix dans les salles de classe bavaroises, au motif qu'elle violait la liberté religieuse négative des élèves d'autres confessions. Ce jugement compte parmi les décisions les plus controversées de la Cour sur le plan sociétal.","pl":"Orzeczenie w sprawie krucyfiksów Federalnego Trybunału Konstytucyjnego, opublikowane 10 sierpnia 1995 roku, uznało obowiązkowe umieszczanie krzyży w bawarskich klasach za niezgodne z konstytucją, gdyż narusza negatywną wolność wyznania uczniów innej wiary. Wyrok należy do najbardziej kontrowersyjnych społecznie decyzji trybunału.","uk":"Рішення про розп'яття Федерального конституційного суду, оприлюднене 10 серпня 1995 року, визнало обов'язкове розміщення хрестів у баварських класних кімнатах неконституційним, оскільки воно порушує негативну свободу віросповідання учнів іншої віри. Це рішення належить до найбільш суспільно суперечливих рішень суду.","fa":"رأی صلیب دادگاه قانون اساسی فدرال، که در ۱۰ اوت ۱۹۹۵ منتشر شد، نصب اجباری صلیب در کلاس‌های درس باواریا را خلاف قانون اساسی اعلام کرد، زیرا آزادی منفی دینی دانش‌آموزان دیگر ادیان را نقض می‌کرد. این رأی از جمله جنجالی‌ترین تصمیمات این دادگاه از نظر اجتماعی به‌شمار می‌رود.","it":"La sentenza sul crocifisso della Corte costituzionale federale, pubblicata il 10 agosto 1995, dichiarò incostituzionale l'obbligo di esporre crocifissi nelle aule bavaresi, in quanto lesivo della libertà religiosa negativa degli alunni di fede diversa. La sentenza è tra le decisioni socialmente più controverse della Corte."},"C2":{"en":"The Crucifix Decision of August 10, 1995, sparked one of the most emotional constitutional debates in the history of the Federal Republic: while critics lamented a displacement of Christian culture from public space, supporters saw it as a consistent application of the state neutrality in matters of faith enshrined in the Basic Law.","ar":"أثار قرار الصليب الصادر في 10 أغسطس 1995 واحداً من أكثر النقاشات الدستورية عاطفية في تاريخ ألمانيا الاتحادية: بينما شكا المنتقدون من إزاحة الثقافة المسيحية من الفضاء العام، رأى فيه المؤيدون تطبيقاً متسقاً لحياد الدولة في المسائل الدينية المكرّس في القانون الأساسي.","tr":"10 Ağustos 1995 tarihli Haç Kararı, Federal Almanya tarihinin en duygusal anayasal tartışmalarından birini tetikledi: Eleştirmenler Hristiyan kültürünün kamusal alandan dışlandığından yakınırken, savunucuları bunu Anayasa'da yer alan devletin dini konularda tarafsızlığının tutarlı bir uygulaması olarak gördü.","ru":"«Решение о распятии» от 10 августа 1995 года вызвало одну из самых эмоциональных конституционных дискуссий в истории ФРГ: если критики сетовали на вытеснение христианской культуры из общественного пространства, то сторонники видели в этом последовательное применение закреплённого в Основном законе государственного нейтралитета в вопросах веры.","es":"La sentencia del Crucifijo del 10 de agosto de 1995 desató uno de los debates constitucionales más emotivos de la historia de la República Federal: mientras los críticos lamentaban un desplazamiento de la cultura cristiana del espacio público, sus defensores lo veían como una aplicación coherente de la neutralidad estatal en cuestiones de fe consagrada en la Ley Fundamental.","fr":"L'arrêt sur le crucifix du 10 août 1995 a déclenché l'un des débats constitutionnels les plus passionnés de l'histoire de la République fédérale : tandis que les critiques déploraient une éviction de la culture chrétienne de l'espace public, ses défenseurs y voyaient une application cohérente de la neutralité de l'État en matière de foi, inscrite dans la Loi fondamentale.","pl":"Orzeczenie w sprawie krucyfiksów z 10 sierpnia 1995 roku wywołało jedną z najbardziej emocjonalnych debat konstytucyjnych w historii RFN: podczas gdy krytycy ubolewali nad wypieraniem kultury chrześcijańskiej z przestrzeni publicznej, zwolennicy widzieli w tym konsekwentne zastosowanie zakotwiczonej w Ustawie Zasadniczej neutralności państwa w sprawach wiary.","uk":"Рішення про розп'яття від 10 серпня 1995 року викликало одну з найемоційніших конституційних дискусій в історії ФРН: критики нарікали на витіснення християнської культури з публічного простору, тоді як прихильники вбачали в цьому послідовне застосування закріпленого в Основному законі державного нейтралітету у справах віри.","fa":"رأی صلیب مورخ ۱۰ اوت ۱۹۹۵ یکی از احساسی‌ترین مناظره‌های قانون اساسی در تاریخ آلمان فدرال را برانگیخت: در حالی که منتقدان از رانده‌شدن فرهنگ مسیحی از فضای عمومی گلایه داشتند، طرفداران آن را کاربردی منسجم از بی‌طرفی دولت در مسائل دینی می‌دانستند که در قانون اساسی مقرر شده است.","it":"La sentenza sul crocifisso del 10 agosto 1995 scatenò uno dei dibattiti costituzionali più accesi della storia della Repubblica federale: mentre i critici denunciavano un'espulsione della cultura cristiana dallo spazio pubblico, i sostenitori vi vedevano un'applicazione coerente della neutralità statale in materia di fede sancita dalla Legge fondamentale."}}},"08-11":{"year":1922,"levels":{"A1":"Am 11. August 1922 bekommt Deutschland eine Nationalhymne. Die Melodie ist von Joseph Haydn. Heute singt man nur die dritte Strophe.","A2":"Am 11. August 1922 erklärt Reichspräsident Friedrich Ebert das Lied der Deutschen zur Nationalhymne. Der Text stammt von Hoffmann von Fallersleben, die Melodie von Joseph Haydn. Heute wird nur die dritte Strophe gesungen.","B1":"Am 11. August 1922 wird das Lied der Deutschen zur Nationalhymne erklärt. Ebert wählte es bewusst: 1841 war es ein Lied der Demokratiebewegung gewesen, die ein einiges und freies Deutschland forderte. Heute gilt allein die dritte Strophe.","B2":"Am 11. August 1922 macht Friedrich Ebert das Lied der Deutschen zur Hymne der Republik. Der Text war ursprünglich ein Freiheitslied gegen die Kleinstaaterei; erst später wurde die erste Strophe machtpolitisch gelesen. Die Beschränkung auf die dritte Strophe stellt den ursprünglichen Sinn wieder her.","C1":"Die Entscheidung vom 11. August 1922 zeigt, dass Symbole ihre Bedeutung nicht selbst festlegen. Dasselbe Lied stand für demokratischen Aufbruch, für imperialen Anspruch und schließlich für eine Republik, die sich auf seine Anfänge berief. Ob eine Hymne trägt, hängt weniger am Text als an dem, was eine Gesellschaft in ihm hören will.","C2":"Am 11. August 1922 wurde ein Lied vereinnahmt, das seither dreimal umgedeutet wurde. Die heutige Beschränkung auf Einigkeit und Recht und Freiheit ist ein bemerkenswerter Vorgang: Ein Staat behält ein belastetes Symbol und beschneidet es so, dass genau der Teil übrig bleibt, zu dem er sich bekennen kann. Ob das Kontinuität stiftet oder Verdrängung erleichtert, wird bis heute unterschiedlich beurteilt."},"translationsA1":{"en":"On August 11, 1922, Germany gets a national anthem. The melody is by Joseph Haydn. Today only the third verse is sung.","ar":"في 11 أغسطس 1922، حصلت ألمانيا على نشيد وطني. اللحن من تأليف يوزف هايدن. اليوم يُغنّى المقطع الثالث فقط.","tr":"11 Ağustos 1922'de Almanya bir millî marş aldı. Ezgi Joseph Haydn'a aittir. Bugün yalnızca üçüncü kıta söylenir.","ru":"11 августа 1922 года Германия получила государственный гимн. Мелодия принадлежит Йозефу Гайдну. Сегодня поют только третий куплет.","es":"El 11 de agosto de 1922, Alemania recibe un himno nacional. La melodía es de Joseph Haydn. Hoy solo se canta la tercera estrofa.","fr":"Le 11 août 1922, l'Allemagne se dote d'un hymne national. La mélodie est de Joseph Haydn. Aujourd'hui, on ne chante que le troisième couplet.","pl":"11 sierpnia 1922 roku Niemcy otrzymały hymn narodowy. Melodię napisał Joseph Haydn. Dziś śpiewa się tylko trzecią zwrotkę.","uk":"11 серпня 1922 року Німеччина отримала державний гімн. Мелодію написав Йозеф Гайдн. Сьогодні співають лише третю строфу.","fa":"در ۱۱ اوت ۱۹۲۲، آلمان سرود ملی یافت. آهنگ آن از یوزف هایدن است. امروز تنها بند سوم خوانده می‌شود.","it":"L'11 agosto 1922 la Germania riceve un inno nazionale. La melodia è di Joseph Haydn. Oggi si canta solo la terza strofa."},"translationsByLevel":{"A2":{"en":"On August 11, 1922, President Friedrich Ebert declares the Song of the Germans the national anthem. The text is by Hoffmann von Fallersleben, the melody by Joseph Haydn. Today only the third stanza is sung.","ar":"في 11 أغسطس 1922 يُعلن الرئيس فريدريش إيبرت أغنية الألمان نشيداً وطنياً. النص من تأليف هوفمان فون فالرسليبن، واللحن من تلحين جوزيف هايدن. اليوم لا تُغنّى سوى المقطع الثالث.","tr":"11 Ağustos 1922'de Cumhurbaşkanı Friedrich Ebert, Almanların Şarkısı'nı milli marş ilan eder. Sözleri Hoffmann von Fallersleben'e, melodisi Joseph Haydn'a aittir. Bugün sadece üçüncü kıta söylenmektedir.","ru":"11 августа 1922 года президент Фридрих Эберт провозглашает «Песнь немцев» национальным гимном. Текст написан Гофманом фон Фаллерслебеном, мелодия — Йозефом Гайдном. Сегодня поют только третий куплет.","es":"El 11 de agosto de 1922, el presidente Friedrich Ebert declara la Canción de los alemanes himno nacional. La letra es de Hoffmann von Fallersleben, la melodía de Joseph Haydn. Hoy solo se canta la tercera estrofa.","fr":"Le 11 août 1922, le président Friedrich Ebert proclame le Chant des Allemands hymne national. Le texte est de Hoffmann von Fallersleben, la mélodie de Joseph Haydn. Aujourd'hui, seule la troisième strophe est chantée.","pl":"11 sierpnia 1922 roku prezydent Friedrich Ebert ogłasza Pieśń Niemców hymnem narodowym. Tekst pochodzi od Hoffmanna von Fallerslebena, melodia od Josepha Haydna. Dziś śpiewana jest tylko trzecia zwrotka.","uk":"11 серпня 1922 року президент Фрідріх Еберт проголошує «Пісню німців» національним гімном. Текст написав Гофман фон Фаллерслебен, мелодію — Йозеф Гайдн. Сьогодні співають лише третій куплет.","fa":"در ۱۱ اوت ۱۹۲۲ رئیس‌جمهور فریدریش ابرت، سرود آلمانی‌ها را سرود ملی اعلام کرد. متن آن از هوفمان فون فالرسلبن و آهنگ آن از یوزف هایدن است. امروزه تنها بند سوم آن خوانده می‌شود.","it":"L'11 agosto 1922 il presidente del Reich Friedrich Ebert proclama il Canto dei tedeschi inno nazionale. Il testo è di Hoffmann von Fallersleben, la melodia di Joseph Haydn. Oggi si canta solo la terza strofa."},"B1":{"en":"On August 11, 1922, the Song of the Germans is declared the national anthem. Ebert chose it deliberately: in 1841 it had been a song of the democratic movement demanding a united and free Germany. Today only the third stanza is official.","ar":"في 11 أغسطس 1922 تُعلن أغنية الألمان نشيداً وطنياً. اختارها إيبرت عن قصد: فقد كانت عام 1841 أغنية لحركة الديمقراطية التي طالبت بألمانيا موحدة وحرة. اليوم لا تُعتمد سوى المقطع الثالث.","tr":"11 Ağustos 1922'de Almanların Şarkısı milli marş ilan edilir. Ebert onu bilinçli olarak seçti: 1841'de birleşik ve özgür bir Almanya talep eden demokrasi hareketinin bir şarkısıydı. Bugün yalnızca üçüncü kıta geçerlidir.","ru":"11 августа 1922 года «Песнь немцев» провозглашается национальным гимном. Эберт выбрал её осознанно: в 1841 году это была песня демократического движения, требовавшего единой и свободной Германии. Сегодня официален только третий куплет.","es":"El 11 de agosto de 1922, la Canción de los alemanes es declarada himno nacional. Ebert la eligió deliberadamente: en 1841 había sido una canción del movimiento democrático que exigía una Alemania unida y libre. Hoy solo es oficial la tercera estrofa.","fr":"Le 11 août 1922, le Chant des Allemands est proclamé hymne national. Ebert l'a choisi délibérément : en 1841, c'était un chant du mouvement démocratique réclamant une Allemagne unie et libre. Aujourd'hui, seule la troisième strophe est officielle.","pl":"11 sierpnia 1922 roku Pieśń Niemców zostaje ogłoszona hymnem narodowym. Ebert wybrał ją świadomie: w 1841 roku była pieśnią ruchu demokratycznego, który domagał się zjednoczonych i wolnych Niemiec. Dziś obowiązuje tylko trzecia zwrotka.","uk":"11 серпня 1922 року «Пісню німців» проголошують національним гімном. Еберт обрав її свідомо: у 1841 році це була пісня демократичного руху, який вимагав єдиної і вільної Німеччини. Сьогодні офіційним є лише третій куплет.","fa":"در ۱۱ اوت ۱۹۲۲ سرود آلمانی‌ها به‌عنوان سرود ملی اعلام می‌شود. ابرت آگاهانه آن را برگزید: در سال ۱۸۴۱ این سرود، سرود جنبش دموکراسی‌خواهی بود که خواستار آلمانی متحد و آزاد بود. امروز تنها بند سوم رسمیت دارد.","it":"L'11 agosto 1922 il Canto dei tedeschi viene proclamato inno nazionale. Ebert lo scelse deliberatamente: nel 1841 era stato un canto del movimento democratico, che chiedeva una Germania unita e libera. Oggi vale soltanto la terza strofa."},"B2":{"en":"On August 11, 1922, Friedrich Ebert makes the Song of the Germans the anthem of the Republic. The text was originally a freedom song against the fragmentation into petty states; only later was the first stanza read in terms of power politics. Limiting it to the third stanza restores the original meaning.","ar":"في 11 أغسطس 1922 يجعل فريدريش إيبرت أغنية الألمان نشيداً للجمهورية. كان النص في الأصل أغنية حرية ضد تجزؤ الدويلات الصغيرة؛ ولم يُقرأ المقطع الأول سياسياً كمطلب هيمنة إلا لاحقاً. يعيد الاقتصار على المقطع الثالث المعنى الأصلي.","tr":"11 Ağustos 1922'de Friedrich Ebert, Almanların Şarkısı'nı Cumhuriyetin marşı yapar. Metin başlangıçta küçük devletçiliğe karşı bir özgürlük şarkısıydı; ilk kıta ancak daha sonra iktidar politikası açısından yorumlandı. Üçüncü kıtaya sınırlama, orijinal anlamı yeniden tesis eder.","ru":"11 августа 1922 года Фридрих Эберт делает «Песнь немцев» гимном Республики. Изначально текст был песней свободы против раздробленности на мелкие государства; лишь позднее первый куплет стали трактовать в духе властной политики. Ограничение третьим куплетом восстанавливает первоначальный смысл.","es":"El 11 de agosto de 1922, Friedrich Ebert convierte la Canción de los alemanes en el himno de la República. El texto era originalmente una canción de libertad contra el fraccionamiento en pequeños estados; solo más tarde se leyó la primera estrofa en clave de política de poder. La limitación a la tercera estrofa restablece el sentido original.","fr":"Le 11 août 1922, Friedrich Ebert fait du Chant des Allemands l'hymne de la République. Le texte était à l'origine un chant de liberté contre le morcellement en petits États ; ce n'est que plus tard que la première strophe fut lue en termes de politique de puissance. Le fait de se limiter à la troisième strophe restaure le sens originel.","pl":"11 sierpnia 1922 roku Friedrich Ebert czyni Pieśń Niemców hymnem Republiki. Tekst był pierwotnie pieśnią wolnościową przeciwko rozdrobnieniu na małe państewka; dopiero później pierwszą zwrotkę odczytywano w kategoriach polityki mocarstwowej. Ograniczenie do trzeciej zwrotki przywraca pierwotny sens.","uk":"11 серпня 1922 року Фрідріх Еберт робить «Пісню німців» гімном Республіки. Текст спочатку був піснею свободи проти роздробленості на дрібні держави; лише пізніше перший куплет почали тлумачити в дусі владної політики. Обмеження третім куплетом відновлює первісний сенс.","fa":"در ۱۱ اوت ۱۹۲۲ فریدریش ابرت سرود آلمانی‌ها را به سرود جمهوری بدل می‌کند. این متن در آغاز سرودی آزادی‌خواهانه علیه پراکندگی دولت‌های کوچک بود؛ تنها بعدها بود که بند نخست از منظر سیاست قدرت خوانده شد. محدودکردن آن به بند سوم، معنای اصلی را بازمی‌گرداند.","it":"L'11 agosto 1922 Friedrich Ebert fa del Canto dei tedeschi l'inno della Repubblica. Il testo era in origine un canto di libertà contro il particolarismo territoriale; solo più tardi la prima strofa fu letta in chiave di potere politico. La limitazione alla terza strofa ripristina il senso originario."},"C1":{"en":"The decision of August 11, 1922, shows that symbols do not fix their own meaning. The same song stood for democratic awakening, for imperial ambition, and finally for a republic that appealed to its origins. Whether an anthem holds depends less on the text than on what a society wants to hear in it.","ar":"يُظهر قرار 11 أغسطس 1922 أن الرموز لا تحدد معناها بنفسها. رمزت الأغنية نفسها للانطلاقة الديمقراطية، ولطموح إمبراطوري، وأخيراً لجمهورية استندت إلى بداياتها. وقدرة نشيد ما على الصمود تعتمد أقل على النص وأكثر على ما يريد مجتمع أن يسمعه فيه.","tr":"11 Ağustos 1922 kararı, sembollerin anlamlarını kendilerinin belirlemediğini gösterir. Aynı şarkı demokratik atılımı, emperyal iddiayı ve nihayet kendi köklerine dayanan bir cumhuriyeti temsil etti. Bir marşın tutup tutmaması metinden çok, bir toplumun onda ne duymak istediğine bağlıdır.","ru":"Решение от 11 августа 1922 года показывает, что символы не устанавливают своё значение сами по себе. Одна и та же песня олицетворяла демократический подъём, имперские притязания и, наконец, республику, апеллировавшую к её истокам. То, приживётся ли гимн, зависит не столько от текста, сколько от того, что общество хочет в нём услышать.","es":"La decisión del 11 de agosto de 1922 muestra que los símbolos no fijan por sí mismos su significado. La misma canción representó el despertar democrático, la ambición imperial y, finalmente, una república que apelaba a sus orígenes. Que un himno arraigue depende menos del texto que de lo que una sociedad quiere oír en él.","fr":"La décision du 11 août 1922 montre que les symboles ne fixent pas eux-mêmes leur signification. Le même chant a représenté un élan démocratique, une prétention impériale et enfin une république qui invoquait ses origines. Qu'un hymne prenne ou non dépend moins du texte que de ce qu'une société veut y entendre.","pl":"Decyzja z 11 sierpnia 1922 roku pokazuje, że symbole nie ustalają swojego znaczenia same. Ta sama pieśń oznaczała demokratyczny przełom, imperialne roszczenia i wreszcie republikę odwołującą się do jej początków. To, czy hymn się przyjmuje, zależy mniej od tekstu, a bardziej od tego, co społeczeństwo chce w nim usłyszeć.","uk":"Рішення від 11 серпня 1922 року показує, що символи не встановлюють своє значення самі. Та сама пісня означала демократичне пробудження, імперські амбіції і нарешті республіку, яка апелювала до її витоків. Чи приживається гімн, залежить менше від тексту, а більше від того, що суспільство хоче в ньому почути.","fa":"تصمیم ۱۱ اوت ۱۹۲۲ نشان می‌دهد که نمادها معنای خود را خودشان تعیین نمی‌کنند. همان سرود، نماد بیداری دموکراتیک، ادعای امپراتوری‌گری و سرانجام جمهوری‌ای بود که به آغاز آن استناد می‌کرد. اینکه یک سرود ماندگار می‌شود یا نه، کمتر به متن آن و بیشتر به این بستگی دارد که جامعه می‌خواهد در آن چه بشنود.","it":"La decisione dell'11 agosto 1922 mostra che i simboli non stabiliscono da soli il proprio significato. Lo stesso canto rappresentò lo slancio democratico, la pretesa imperiale e infine una repubblica che si richiamava alle sue origini. Che un inno regga o meno dipende meno dal testo che da ciò che una società vuole sentirvi."},"C2":{"en":"On August 11, 1922, a song was appropriated that has since been reinterpreted three times over. Today's restriction to 'unity and justice and freedom' is a remarkable process: a state retains a burdened symbol and trims it so that exactly the part it can endorse remains. Whether this creates continuity or merely eases repression is judged differently to this day.","ar":"في 11 أغسطس 1922 استُولي على أغنية أُعيد تأويلها ثلاث مرات منذ ذلك الحين. إن الاقتصار الحالي على «الوحدة والحق والحرية» عملية لافتة: تحتفظ الدولة برمز مثقل وتقتطع منه ما يبقى بالضبط الجزء الذي يمكنها تبنّيه. أما ما إذا كان ذلك يرسّخ الاستمرارية أو يسهّل الإزاحة، فتباينت الآراء حوله حتى اليوم.","tr":"11 Ağustos 1922'de, o zamandan beri üç kez yeniden yorumlanmış bir şarkı sahiplenildi. Bugünkü 'birlik ve hukuk ve özgürlük' kısıtlaması dikkat çekici bir süreçtir: Bir devlet, yüklü bir sembolü elinde tutar ve onu, tam da sahiplenebileceği kısım kalacak şekilde budar. Bunun süreklilik mi yarattığı yoksa bastırmayı mı kolaylaştırdığı, bugün hâlâ farklı biçimlerde değerlendiriliyor.","ru":"11 августа 1922 года была присвоена песня, которую с тех пор трижды переосмысливали. Сегодняшнее ограничение словами «единство, право и свобода» — примечательный процесс: государство сохраняет обременённый символ и обрезает его так, что остаётся именно та часть, к которой оно может себя причислить. Создаёт ли это преемственность или лишь облегчает вытеснение прошлого — по сей день оценивается по-разному.","es":"El 11 de agosto de 1922 se apropió de una canción que desde entonces ha sido reinterpretada tres veces. La actual limitación a 'unidad y justicia y libertad' es un proceso notable: un Estado conserva un símbolo cargado y lo recorta de modo que quede exactamente la parte con la que puede identificarse. Si eso crea continuidad o solo facilita la represión es algo que hasta hoy se juzga de manera distinta.","fr":"Le 11 août 1922, un chant fut annexé, qui a depuis été réinterprété trois fois. La limitation actuelle à « unité, droit et liberté » constitue un processus remarquable : un État conserve un symbole chargé et le rogne de manière à ne laisser subsister que la part qu'il peut assumer. Que cela crée de la continuité ou facilite un refoulement demeure aujourd'hui encore diversement apprécié.","pl":"11 sierpnia 1922 roku zawłaszczono pieśń, którą od tego czasu trzykrotnie reinterpretowano. Dzisiejsze ograniczenie do słów jedność i prawo, i wolność to godny uwagi proces: państwo zachowuje obciążony symbol i przycina go tak, by pozostała dokładnie ta część, do której może się przyznać. Czy tworzy to ciągłość, czy jedynie ułatwia wyparcie, do dziś ocenia się różnie.","uk":"11 серпня 1922 року було привласнено пісню, яку відтоді тричі переосмислювали. Сьогоднішнє обмеження словами «єдність, право і свобода» — примітний процес: держава зберігає обтяжений символ і обрізає його так, що залишається саме та частина, до якої вона може себе зарахувати. Чи створює це наступність, чи лише полегшує витіснення минулого, донині оцінюється по-різному.","fa":"در ۱۱ اوت ۱۹۲۲ سرودی مصادره شد که از آن پس سه بار بازتفسیر شده است. محدودکردن کنونی آن به عبارت «وحدت و حق و آزادی» فرایندی قابل‌توجه است: یک دولت نمادی سنگین را نگاه می‌دارد و آن را چنان می‌تراشد که دقیقاً همان بخشی باقی بماند که می‌تواند به آن اقرار کند. اینکه آیا این کار پیوستگی می‌آفریند یا سرکوب گذشته را آسان‌تر می‌کند، تا امروز به شکل‌های متفاوت داوری می‌شود.","it":"L'11 agosto 1922 fu adottato un canto che da allora è stato reinterpretato tre volte. L'attuale limitazione a \"unità e diritto e libertà\" è un fatto notevole: uno Stato conserva un simbolo compromesso e lo riduce in modo che ne resti proprio la parte a cui può professarsi fedele. Se questo crei continuità o faciliti la rimozione è tuttora giudicato in modo diverso."}},"sideFacts":[]},"08-12":{"year":1923,"levels":{"A1":"Am 12. August 1923 soll Gustav Stresemann eine Regierung bilden. Das Geld in Deutschland ist fast nichts mehr wert. Er muss die Lage retten.","A2":"Am 12. August 1923 wird Gustav Stresemann mit der Regierungsbildung beauftragt. Deutschland steckte in der schlimmsten Geldkrise seiner Geschichte. Ein Brot kostete Milliarden Mark.","B1":"Am 12. August 1923 erhält Gustav Stresemann den Auftrag, eine Regierung zu bilden. Die Inflation hatte jede Ersparnis vernichtet: Löhne wurden zweimal täglich gezahlt, weil das Geld über Nacht wertlos wurde. In gut hundert Tagen beendete seine Regierung die Geldentwertung.","B2":"Am 12. August 1923 übernimmt Stresemann in der schwersten Krise der Republik. Seine Amtszeit als Kanzler dauerte nur hundert Tage und beendete die Hyperinflation. Er tat es mit unpopulären Mitteln — Abbruch des Ruhrkampfs, neue Währung — und verlor darüber seine Mehrheit.","C1":"Der Regierungsauftrag vom 12. August 1923 markiert einen der wenigen Momente, in denen kurzfristige Unbeliebtheit und langfristiger Erfolg klar auseinanderfielen. Stresemann beendete eine Katastrophe und wurde dafür gestürzt. Politische Belohnung folgt der Wahrnehmung, nicht der Wirkung.","C2":"Am 12. August 1923 begann eine Regierungszeit, die zeigt, wie Vertrauen in Geld funktioniert. Die neue Währung war durch nichts Reales besser gedeckt als die alte; entscheidend war, dass alle Beteiligten ihr Verhalten gleichzeitig änderten. Währungsstabilität ist deshalb weniger ein technisches als ein kollektives Problem — und genau darum so schwer wiederherzustellen."},"translationsA1":{"en":"On August 12, 1923, Gustav Stresemann is asked to form a government. Money in Germany is almost worthless. He has to save the situation.","ar":"في 12 أغسطس 1923، كُلّف غوستاف شتريزمان بتشكيل حكومة. كانت النقود في ألمانيا بلا قيمة تقريبًا. كان عليه إنقاذ الوضع.","tr":"12 Ağustos 1923'te Gustav Stresemann hükümet kurmakla görevlendirildi. Almanya'da para neredeyse değersizdi. Durumu kurtarması gerekiyordu.","ru":"12 августа 1923 года Густаву Штреземану поручили сформировать правительство. Деньги в Германии почти ничего не стоили. Он должен был спасти положение.","es":"El 12 de agosto de 1923 se encarga a Gustav Stresemann formar gobierno. El dinero en Alemania casi no vale nada. Debe salvar la situación.","fr":"Le 12 août 1923, Gustav Stresemann est chargé de former un gouvernement. L'argent en Allemagne ne vaut presque plus rien. Il doit sauver la situation.","pl":"12 sierpnia 1923 roku Gustav Stresemann otrzymał zadanie utworzenia rządu. Pieniądz w Niemczech był prawie bezwartościowy. Musiał ratować sytuację.","uk":"12 серпня 1923 року Ґуставу Штреземану доручили сформувати уряд. Гроші в Німеччині майже нічого не вартували. Він мав урятувати становище.","fa":"در ۱۲ اوت ۱۹۲۳، به گوستاو اشترزمان مأموریت تشکیل دولت داده شد. پول در آلمان تقریباً بی‌ارزش بود. او باید وضع را نجات می‌داد.","it":"Il 12 agosto 1923 Gustav Stresemann deve formare un governo. Il denaro in Germania ormai non vale quasi più nulla. Deve salvare la situazione."},"translationsByLevel":{"A2":{"en":"On August 12, 1923, Gustav Stresemann is tasked with forming a government. Germany was in the midst of the worst monetary crisis in its history. A loaf of bread cost billions of marks.","ar":"في 12 أغسطس 1923، كُلِّف غوستاف شتريزمان بتشكيل حكومة. كانت ألمانيا تمر بأسوأ أزمة نقدية في تاريخها. كان ثمن رغيف الخبز مليارات المارك.","tr":"12 Ağustos 1923'te Gustav Stresemann hükümeti kurmakla görevlendirilir. Almanya, tarihinin en kötü para krizinin içindeydi. Bir ekmeğin fiyatı milyarlarca marktı.","ru":"12 августа 1923 года Густаву Штреземану поручено сформировать правительство. Германия переживала худший денежный кризис в своей истории. Буханка хлеба стоила миллиарды марок.","es":"El 12 de agosto de 1923, Gustav Stresemann recibe el encargo de formar gobierno. Alemania atravesaba la peor crisis monetaria de su historia. Una barra de pan costaba miles de millones de marcos.","fr":"Le 12 août 1923, Gustav Stresemann est chargé de former un gouvernement. L'Allemagne traversait la pire crise monétaire de son histoire. Un pain coûtait des milliards de marks.","pl":"12 sierpnia 1923 roku Gustav Stresemann otrzymuje misję utworzenia rządu. Niemcy tkwiły w najgorszym kryzysie pieniężnym swojej historii. Bochenek chleba kosztował miliardy marek.","uk":"12 серпня 1923 року Густаву Штреземану доручено сформувати уряд. Німеччина переживала найгіршу грошову кризу у своїй історії. Буханець хліба коштував мільярди марок.","fa":"در ۱۲ اوت ۱۹۲۳، گوستاو اشترزمان مأمور تشکیل دولت می‌شود. آلمان در بدترین بحران پولی تاریخ خود به سر می‌برد. یک قرص نان میلیاردها مارک قیمت داشت.","it":"Il 12 agosto 1923 Gustav Stresemann riceve l'incarico di formare il governo. La Germania si trovava nella peggiore crisi monetaria della sua storia. Un pane costava miliardi di marchi."},"B1":{"en":"On August 12, 1923, Gustav Stresemann receives the task of forming a government. Inflation had destroyed every savings: wages were paid twice a day, because the money became worthless overnight. In just over a hundred days, his government ended the currency devaluation.","ar":"في 12 أغسطس 1923، يتلقى غوستاف شتريزمان مهمة تشكيل حكومة. كان التضخم قد دمّر كل مدخرات: كانت الأجور تُدفع مرتين يومياً، لأن النقود كانت تفقد قيمتها بين ليلة وضحاها. في مئة يوم تقريباً، أنهت حكومته انهيار قيمة العملة.","tr":"12 Ağustos 1923'te Gustav Stresemann bir hükümet kurma görevini alır. Enflasyon her türlü birikimi yok etmişti: paralar bir gecede değersizleştiği için ücretler günde iki kez ödeniyordu. Hükümeti, yüz günü aşkın bir sürede para değer kaybını sona erdirdi.","ru":"12 августа 1923 года Густав Штреземан получает задачу сформировать правительство. Инфляция уничтожила все сбережения: зарплату выплачивали дважды в день, потому что деньги обесценивались за одну ночь. Всего за сто с небольшим дней его правительство остановило обесценивание денег.","es":"El 12 de agosto de 1923, Gustav Stresemann recibe el encargo de formar gobierno. La inflación había destruido todos los ahorros: los salarios se pagaban dos veces al día, porque el dinero perdía su valor de un día para otro. En poco más de cien días, su gobierno puso fin a la devaluación monetaria.","fr":"Le 12 août 1923, Gustav Stresemann reçoit la mission de former un gouvernement. L'inflation avait détruit toute épargne : les salaires étaient versés deux fois par jour, car l'argent devenait sans valeur du jour au lendemain. En un peu plus de cent jours, son gouvernement mit fin à la dépréciation monétaire.","pl":"12 sierpnia 1923 roku Gustav Stresemann otrzymuje zadanie utworzenia rządu. Inflacja zniszczyła wszystkie oszczędności: pensje wypłacano dwa razy dziennie, ponieważ pieniądz z dnia na dzień tracił wartość. W nieco ponad sto dni jego rząd zakończył dewaluację pieniądza.","uk":"12 серпня 1923 року Густав Штреземан отримує завдання сформувати уряд. Інфляція знищила всі заощадження: зарплату виплачували двічі на день, бо гроші знецінювалися за одну ніч. Трохи більш ніж за сто днів його уряд поклав край знеціненню грошей.","fa":"در ۱۲ اوت ۱۹۲۳، گوستاو اشترزمان مأموریت تشکیل دولت را دریافت می‌کند. تورم تمام پس‌اندازها را نابود کرده بود: دستمزدها دو بار در روز پرداخت می‌شد، زیرا پول طی یک شب بی‌ارزش می‌شد. دولت او در کمی بیش از صد روز به کاهش ارزش پول پایان داد.","it":"Il 12 agosto 1923 Gustav Stresemann riceve l'incarico di formare un governo. L'inflazione aveva distrutto ogni risparmio: i salari venivano pagati due volte al giorno, perché il denaro perdeva valore da un giorno all'altro. In poco più di cento giorni il suo governo pose fine alla svalutazione monetaria."},"B2":{"en":"On August 12, 1923, Stresemann takes over amid the Republic's gravest crisis. His term as chancellor lasted only a hundred days and ended the hyperinflation. He did it with unpopular measures — abandoning the Ruhr struggle, introducing a new currency — and lost his majority over it.","ar":"في 12 أغسطس 1923، يتولى شتريزمان الحكم في أخطر أزمة تمر بها الجمهورية. لم تدم فترة توليه منصب المستشار سوى مئة يوم، وخلالها أنهى التضخم المفرط. فعل ذلك بوسائل غير شعبية — وقف مقاومة الرور، وعملة جديدة — وخسر بسبب ذلك أغلبيته.","tr":"12 Ağustos 1923'te Stresemann, Cumhuriyet'in en ağır krizinde iktidarı devralır. Şansölye olarak görev süresi yalnızca yüz gün sürdü ve hiperenflasyonu sona erdirdi. Bunu popüler olmayan araçlarla yaptı — Ruhr direnişinin sona erdirilmesi, yeni bir para birimi — ve bu yüzden çoğunluğunu kaybetti.","ru":"12 августа 1923 года Штреземан приходит к власти в самый тяжёлый кризис Республики. Его пребывание на посту канцлера длилось всего сто дней и положило конец гиперинфляции. Он добился этого непопулярными мерами — прекращением рурской борьбы, введением новой валюты — и из-за этого потерял большинство.","es":"El 12 de agosto de 1923, Stresemann asume el poder en la crisis más grave de la República. Su mandato como canciller duró solo cien días y puso fin a la hiperinflación. Lo logró con medidas impopulares —el fin de la resistencia del Ruhr, una nueva moneda— y por ello perdió su mayoría.","fr":"Le 12 août 1923, Stresemann prend les rênes au plus fort de la crise de la République. Son mandat de chancelier ne dura que cent jours et mit fin à l'hyperinflation. Il y parvint par des moyens impopulaires — l'arrêt de la résistance de la Ruhr, une nouvelle monnaie — et perdit sa majorité pour cela.","pl":"12 sierpnia 1923 roku Stresemann obejmuje władzę w najcięższym kryzysie Republiki. Jego kadencja jako kanclerza trwała zaledwie sto dni i zakończyła hiperinflację. Dokonał tego niepopularnymi środkami — zakończeniem walki o Zagłębie Ruhry, nową walutą — i za to stracił większość.","uk":"12 серпня 1923 року Штреземан очолює уряд у найважчій кризі Республіки. Його канцлерство тривало лише сто днів і поклало край гіперінфляції. Він досяг цього непопулярними заходами — припиненням боротьби за Рур, новою валютою — і через це втратив більшість.","fa":"در ۱۲ اوت ۱۹۲۳، اشترزمان در سخت‌ترین بحران جمهوری زمام امور را به دست می‌گیرد. دوران صدارت او تنها صد روز به طول انجامید و به ابرتورم پایان داد. او این کار را با اقدامات نامحبوب انجام داد — توقف مبارزه رور، پول جدید — و به همین دلیل اکثریت خود را از دست داد.","it":"Il 12 agosto 1923 Stresemann assume la guida nella crisi più grave della Repubblica. Il suo mandato di cancelliere durò solo cento giorni e pose fine all'iperinflazione. Lo fece con misure impopolari — l'interruzione della lotta della Ruhr, una nuova moneta — perdendo così la propria maggioranza."},"C1":{"en":"The mandate to form a government of August 12, 1923, marks one of the few moments in which short-term unpopularity and long-term success clearly diverged. Stresemann ended a catastrophe and was toppled for it. Political reward follows perception, not effect.","ar":"تُشكّل مهمة تشكيل الحكومة الصادرة في 12 أغسطس 1923 واحدة من اللحظات النادرة التي انفصل فيها بوضوح عدم الشعبية قصيرة المدى عن النجاح طويل المدى. أنهى شتريزمان كارثة وسقط بسبب ذلك. المكافأة السياسية تتبع التصور، لا الأثر الفعلي.","tr":"12 Ağustos 1923 tarihli hükümet kurma görevi, kısa vadeli sevilmemenin ve uzun vadeli başarının açıkça birbirinden ayrıldığı nadir anlardan birini işaret eder. Stresemann bir felaketi sona erdirdi ve bunun için devrildi. Siyasi ödül, etkiyi değil algıyı izler.","ru":"Поручение сформировать правительство от 12 августа 1923 года отмечает один из немногих моментов, когда кратковременная непопулярность и долгосрочный успех явно разошлись. Штреземан положил конец катастрофе и за это был свергнут. Политическая награда следует за восприятием, а не за реальным эффектом.","es":"El encargo de formar gobierno del 12 de agosto de 1923 marca uno de los pocos momentos en que la impopularidad a corto plazo y el éxito a largo plazo se separaron claramente. Stresemann puso fin a una catástrofe y por ello fue derrocado. La recompensa política sigue a la percepción, no al efecto.","fr":"La mission de former un gouvernement confiée le 12 août 1923 marque l'un des rares moments où l'impopularité à court terme et le succès à long terme se sont clairement dissociés. Stresemann mit fin à une catastrophe et fut renversé pour cela. La récompense politique suit la perception, non l'effet réel.","pl":"Misja utworzenia rządu z 12 sierpnia 1923 roku wyznacza jeden z nielicznych momentów, w których krótkoterminowa niepopularność i długoterminowy sukces wyraźnie się rozeszły. Stresemann położył kres katastrofie i za to został obalony. Nagroda polityczna podąża za percepcją, nie za faktycznym skutkiem.","uk":"Доручення сформувати уряд від 12 серпня 1923 року позначає один із небагатьох моментів, коли короткочасна непопулярність і довгостроковий успіх чітко розійшлися. Штреземан поклав край катастрофі й за це був повалений. Політична винагорода йде за сприйняттям, а не за реальним ефектом.","fa":"مأموریت تشکیل دولت در ۱۲ اوت ۱۹۲۳ یکی از معدود لحظاتی را نشان می‌دهد که در آن محبوبیت کوتاه‌مدت و موفقیت بلندمدت به‌وضوح از هم جدا شدند. اشترزمان به یک فاجعه پایان داد و به همین دلیل برکنار شد. پاداش سیاسی از ادراک پیروی می‌کند، نه از تأثیر واقعی.","it":"L'incarico di governo del 12 agosto 1923 segna uno dei rari momenti in cui l'impopolarità immediata e il successo a lungo termine si separarono nettamente. Stresemann pose fine a una catastrofe e per questo fu rovesciato. La ricompensa politica segue la percezione, non l'effetto reale."},"C2":{"en":"On August 12, 1923, a period of government began that shows how trust in money actually works. The new currency was backed by nothing real any better than the old one; what mattered was that everyone involved changed their behavior simultaneously. Currency stability is therefore less a technical than a collective problem — and precisely for that reason so hard to restore.","ar":"في 12 أغسطس 1923 بدأت فترة حكم تُظهر كيف تعمل الثقة بالنقود. لم تكن العملة الجديدة مدعومة بأي شيء حقيقي أفضل من القديمة؛ الحاسم كان أن جميع الأطراف المعنية غيّرت سلوكها في الوقت نفسه. لذلك فإن استقرار العملة ليس مشكلة تقنية بقدر ما هو مشكلة جماعية — ولهذا السبب بالذات يصعب استعادته.","tr":"12 Ağustos 1923'te, paraya duyulan güvenin nasıl işlediğini gösteren bir hükümet dönemi başladı. Yeni para biriminin gerçek karşılığı, eskisinden hiç de daha iyi değildi; belirleyici olan, tüm tarafların davranışlarını aynı anda değiştirmesiydi. Bu yüzden para istikrarı teknik olmaktan çok kolektif bir sorundur — ve tam da bu yüzden yeniden sağlanması bu kadar zordur.","ru":"12 августа 1923 года началось правление, показывающее, как на самом деле работает доверие к деньгам. Новая валюта не имела реального обеспечения, лучшего, чем старая; решающим было то, что все участники одновременно изменили своё поведение. Поэтому стабильность валюты — проблема не столько техническая, сколько коллективная, и именно поэтому её так трудно восстановить.","es":"El 12 de agosto de 1923 comenzó un periodo de gobierno que muestra cómo funciona realmente la confianza en el dinero. La nueva moneda no estaba respaldada por nada real mejor que la antigua; lo decisivo fue que todos los implicados cambiaron su comportamiento al mismo tiempo. La estabilidad monetaria es, por tanto, un problema menos técnico que colectivo, y precisamente por eso tan difícil de restablecer.","fr":"Le 12 août 1923 débuta une période gouvernementale qui montre comment fonctionne réellement la confiance dans la monnaie. La nouvelle monnaie n'était adossée à rien de réellement plus solide que l'ancienne ; ce qui comptait, c'est que tous les acteurs changèrent leur comportement simultanément. La stabilité monétaire est donc moins un problème technique qu'un problème collectif — et c'est précisément pour cela qu'elle est si difficile à rétablir.","pl":"12 sierpnia 1923 roku rozpoczął się okres rządów, który pokazuje, jak naprawdę działa zaufanie do pieniądza. Nowa waluta nie miała żadnego realnego pokrycia lepszego niż stara; decydujące było to, że wszyscy uczestnicy jednocześnie zmienili swoje zachowanie. Stabilność waluty jest zatem problemem mniej technicznym, a bardziej zbiorowym — i właśnie dlatego tak trudno ją przywrócić.","uk":"12 серпня 1923 року розпочався період правління, який показує, як насправді працює довіра до грошей. Нова валюта не мала жодного реального забезпечення, кращого за стару; вирішальним було те, що всі учасники одночасно змінили свою поведінку. Тому стабільність валюти є радше колективною, ніж технічною проблемою — і саме тому її так важко відновити.","fa":"در ۱۲ اوت ۱۹۲۳ دوره‌ای از حکومت آغاز شد که نشان می‌دهد اعتماد به پول واقعاً چگونه عمل می‌کند. پول جدید هیچ پشتوانه واقعی بهتری از پول قدیم نداشت؛ نکته تعیین‌کننده این بود که همه طرف‌های درگیر همزمان رفتار خود را تغییر دادند. بنابراین ثبات پولی کمتر یک مسئله فنی و بیشتر یک مسئله جمعی است — و دقیقاً به همین دلیل بازگرداندن آن بسیار دشوار است.","it":"Il 12 agosto 1923 iniziò un periodo di governo che mostra come funzioni la fiducia nel denaro. La nuova moneta non era garantita da nulla di più reale rispetto alla vecchia; decisivo fu che tutti i soggetti coinvolti cambiassero comportamento nello stesso momento. La stabilità monetaria è quindi meno un problema tecnico che collettivo, e proprio per questo così difficile da ripristinare."}},"sideFacts":[]},"08-13":{"year":1961,"levels":{"A1":"Am 13. August 1961 baut die DDR eine Mauer in Berlin. Die Stadt ist jetzt geteilt.","A2":"Am 13. August 1961 beginnt der Bau der Berliner Mauer über Nacht. Berlin und Deutschland werden geteilt.","B1":"Am 13. August 1961 beginnt die DDR über Nacht mit dem Bau der Berliner Mauer. Familien und Freunde werden plötzlich getrennt — für 28 Jahre.","B2":"In der Nacht zum 13. August 1961 beginnt die DDR-Führung überraschend mit dem Bau der Berliner Mauer, um die Flucht in den Westen zu stoppen. Über Nacht werden Familien getrennt, Straßen und U-Bahn-Linien unterbrochen.","C1":"In der Nacht zum 13. August 1961 begann die DDR-Führung mit dem Bau der Berliner Mauer — eine Reaktion auf die massenhafte Flucht von DDR-Bürgern in den Westen. Für 28 Jahre teilte die Mauer nicht nur eine Stadt, sondern symbolisierte die Teilung ganz Europas.","C2":"Der überraschende Mauerbau in der Nacht zum 13. August 1961 war das Ergebnis eines eskalierenden Exodus von DDR-Bürgern in den Westen und wurde von der SED-Führung euphemistisch als 'antifaschistischer Schutzwall' bezeichnet — eine Formulierung, die bis heute als Sinnbild propagandistischer Sprachverdrehung gilt."},"translationsA1":{"en":"On August 13, 1961, East Germany built a wall in Berlin. The city is now divided.","ar":"في 13 أغسطس 1961، بنت ألمانيا الشرقية جداراً في برلين. المدينة مقسمة الآن.","tr":"13 Ağustos 1961'de Doğu Almanya Berlin'de bir duvar inşa etti. Şehir artık bölünmüş durumda.","ru":"13 августа 1961 года Восточная Германия построила стену в Берлине. Город теперь разделён.","es":"El 13 de agosto de 1961, Alemania Oriental construyó un muro en Berlín. La ciudad está ahora dividida.","fr":"Le 13 août 1961, l'Allemagne de l'Est construit un mur à Berlin. La ville est maintenant divisée.","pl":"13 sierpnia 1961 roku NRD zbudowała mur w Berlinie. Miasto jest teraz podzielone.","uk":"13 серпня 1961 року Східна Німеччина побудувала стіну в Берліні. Місто тепер розділене.","fa":"در ۱۳ اوت ۱۹۶۱، آلمان شرقی دیواری در برلین ساخت. این شهر اکنون تقسیم شده است.","it":"Il 13 agosto 1961 la DDR costruisce un muro a Berlino. La città ora è divisa."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 13, 1961, construction of the Berlin Wall begins overnight. Berlin and Germany are divided.","ar":"في 13 أغسطس 1961، يبدأ بناء سور برلين بين عشية وضحاها. تنقسم برلين وألمانيا.","tr":"13 Ağustos 1961'de Berlin Duvarı'nın inşası bir gecede başlar. Berlin ve Almanya bölünür.","ru":"13 августа 1961 года за одну ночь начинается строительство Берлинской стены. Берлин и Германия оказываются разделены.","es":"El 13 de agosto de 1961 comienza la construcción del Muro de Berlín de la noche a la mañana. Berlín y Alemania quedan divididas.","fr":"Le 13 août 1961, la construction du mur de Berlin commence du jour au lendemain. Berlin et l'Allemagne sont divisées.","pl":"13 sierpnia 1961 roku z dnia na dzień rozpoczyna się budowa muru berlińskiego. Berlin i Niemcy zostają podzielone.","uk":"13 серпня 1961 року за одну ніч розпочинається будівництво Берлінського муру. Берлін і Німеччина стають розділеними.","fa":"در ۱۳ اوت ۱۹۶۱، ساخت دیوار برلین یک‌شبه آغاز می‌شود. برلین و آلمان تقسیم می‌شوند.","it":"Il 13 agosto 1961 inizia, nel giro di una notte, la costruzione del Muro di Berlino. Berlino e la Germania vengono divise."},"B1":{"en":"On August 13, 1961, East Germany begins building the Berlin Wall overnight. Families and friends are suddenly separated — for 28 years.","ar":"في 13 أغسطس 1961، تبدأ ألمانيا الشرقية بين عشية وضحاها ببناء سور برلين. تنفصل العائلات والأصدقاء فجأة — لمدة 28 عاماً.","tr":"13 Ağustos 1961'de Doğu Almanya bir gecede Berlin Duvarı'nın inşasına başlar. Aileler ve arkadaşlar aniden ayrılır — 28 yıl boyunca.","ru":"13 августа 1961 года ГДР за одну ночь начинает строительство Берлинской стены. Семьи и друзья внезапно оказываются разлучены — на 28 лет.","es":"El 13 de agosto de 1961, la RDA comienza de la noche a la mañana la construcción del Muro de Berlín. Familias y amigos quedan separados de repente, durante 28 años.","fr":"Le 13 août 1961, la RDA entreprend du jour au lendemain la construction du mur de Berlin. Familles et amis se retrouvent brusquement séparés — pour 28 ans.","pl":"13 sierpnia 1961 roku NRD z dnia na dzień rozpoczyna budowę muru berlińskiego. Rodziny i przyjaciele zostają nagle rozdzieleni — na 28 lat.","uk":"13 серпня 1961 року НДР за одну ніч починає будівництво Берлінського муру. Родини та друзі раптово розлучаються — на 28 років.","fa":"در ۱۳ اوت ۱۹۶۱، آلمان شرقی یک‌شبه ساخت دیوار برلین را آغاز می‌کند. خانواده‌ها و دوستان به‌ناگاه از هم جدا می‌شوند — برای ۲۸ سال.","it":"Il 13 agosto 1961 la DDR inizia, da un giorno all'altro, la costruzione del Muro di Berlino. Famiglie e amici vengono improvvisamente separati — per 28 anni."},"B2":{"en":"On the night of August 13, 1961, the East German leadership unexpectedly begins building the Berlin Wall to stop the flight to the West. Overnight, families are separated and streets and subway lines are cut off.","ar":"في ليلة 13 أغسطس 1961، تبدأ قيادة ألمانيا الشرقية بشكل مفاجئ ببناء سور برلين لوقف الهروب إلى الغرب. بين ليلة وضحاها تنفصل العائلات وتُقطع الشوارع وخطوط مترو الأنفاق.","tr":"13 Ağustos 1961'i bağlayan gece, Doğu Almanya liderliği Batı'ya kaçışı durdurmak için beklenmedik şekilde Berlin Duvarı'nın inşasına başlar. Bir gecede aileler ayrılır, caddeler ve metro hatları kesilir.","ru":"В ночь на 13 августа 1961 года руководство ГДР неожиданно начинает строительство Берлинской стены, чтобы остановить бегство на Запад. За одну ночь разлучаются семьи, перекрываются улицы и линии метро.","es":"En la noche del 13 de agosto de 1961, la dirección de la RDA comienza sorpresivamente la construcción del Muro de Berlín para detener la huida hacia el Oeste. De la noche a la mañana se separan familias y se cortan calles y líneas de metro.","fr":"Dans la nuit du 13 août 1961, la direction est-allemande entreprend de manière inattendue la construction du mur de Berlin pour stopper la fuite vers l'Ouest. Du jour au lendemain, des familles sont séparées, des rues et des lignes de métro coupées.","pl":"W nocy z 12 na 13 sierpnia 1961 roku kierownictwo NRD niespodziewanie rozpoczyna budowę muru berlińskiego, by zatrzymać ucieczki na Zachód. Z dnia na dzień rozdzielone zostają rodziny, przecięte ulice i linie metra.","uk":"У ніч на 13 серпня 1961 року керівництво НДР несподівано розпочинає будівництво Берлінського муру, щоб зупинити втечі на Захід. За одну ніч розлучаються родини, перериваються вулиці та лінії метро.","fa":"در شب ۱۳ اوت ۱۹۶۱، رهبری آلمان شرقی به‌طور غافلگیرکننده‌ای ساخت دیوار برلین را برای توقف فرار به غرب آغاز می‌کند. یک‌شبه خانواده‌ها از هم جدا می‌شوند و خیابان‌ها و خطوط مترو قطع می‌شوند.","it":"Nella notte tra il 12 e il 13 agosto 1961 la dirigenza della DDR avvia a sorpresa la costruzione del Muro di Berlino, per fermare la fuga verso l'Ovest. Nel giro di una notte le famiglie vengono separate e strade e linee della metropolitana interrotte."},"C1":{"en":"On the night of August 13, 1961, the East German leadership began building the Berlin Wall — a response to the mass flight of East German citizens to the West. For 28 years, the wall divided not just a city but symbolized the division of all of Europe.","ar":"في ليلة 13 أغسطس 1961، بدأت قيادة ألمانيا الشرقية ببناء سور برلين — رداً على الهروب الجماعي لمواطني ألمانيا الشرقية إلى الغرب. لمدة 28 عاماً لم يقسّم السور مدينة واحدة فحسب، بل رمز إلى انقسام أوروبا بأكملها.","tr":"13 Ağustos 1961'i bağlayan gece, Doğu Almanya liderliği Berlin Duvarı'nın inşasına başladı — bu, Doğu Almanya vatandaşlarının Batı'ya toplu kaçışına bir tepkiydi. Duvar 28 yıl boyunca sadece bir şehri bölmekle kalmadı, tüm Avrupa'nın bölünmüşlüğünün simgesi oldu.","ru":"В ночь на 13 августа 1961 года руководство ГДР начало строительство Берлинской стены — в ответ на массовое бегство граждан ГДР на Запад. В течение 28 лет стена не только разделяла город, но и символизировала раскол всей Европы.","es":"En la noche del 13 de agosto de 1961, la dirección de la RDA comenzó la construcción del Muro de Berlín, en respuesta a la huida masiva de ciudadanos de la RDA hacia el Oeste. Durante 28 años, el muro no solo dividió una ciudad, sino que simbolizó la división de toda Europa.","fr":"Dans la nuit du 13 août 1961, la direction est-allemande entreprit la construction du mur de Berlin — une réaction à la fuite massive de citoyens est-allemands vers l'Ouest. Pendant 28 ans, le mur n'a pas seulement divisé une ville, il a symbolisé la division de toute l'Europe.","pl":"W nocy z 12 na 13 sierpnia 1961 roku kierownictwo NRD rozpoczęło budowę muru berlińskiego — jako reakcję na masową ucieczkę obywateli NRD na Zachód. Przez 28 lat mur nie tylko dzielił miasto, lecz symbolizował podział całej Europy.","uk":"У ніч на 13 серпня 1961 року керівництво НДР розпочало будівництво Берлінського муру — у відповідь на масову втечу громадян НДР на Захід. Протягом 28 років мур не лише розділяв місто, а й символізував поділ усієї Європи.","fa":"در شب ۱۳ اوت ۱۹۶۱، رهبری آلمان شرقی ساخت دیوار برلین را آغاز کرد — واکنشی به فرار انبوه شهروندان آلمان شرقی به غرب. این دیوار طی ۲۸ سال نه‌تنها یک شهر را تقسیم کرد، بلکه نماد تقسیم کل اروپا شد.","it":"Nella notte tra il 12 e il 13 agosto 1961 la dirigenza della DDR diede inizio alla costruzione del Muro di Berlino — una reazione alla fuga di massa dei cittadini della DDR verso l'Ovest. Per 28 anni il Muro non divise soltanto una città, ma divenne il simbolo della divisione di tutta l'Europa."},"C2":{"en":"The surprise construction of the Wall on the night of August 13, 1961, was the result of an escalating exodus of East German citizens to the West and was euphemistically labeled by the SED leadership an 'anti-fascist protective rampart' — a phrase still regarded today as emblematic of propagandistic distortion of language.","ar":"كان بناء السور المفاجئ في ليلة 13 أغسطس 1961 نتيجة لتصاعد نزوح مواطني ألمانيا الشرقية إلى الغرب، ووصفته قيادة الحزب الاشتراكي الوحدوي الألماني تلطيفاً بأنه 'سور الحماية المناهض للفاشية' — وهي عبارة لا تزال حتى اليوم رمزاً لتحريف اللغة الدعائي.","tr":"13 Ağustos 1961'i bağlayan gecedeki beklenmedik duvar inşası, Doğu Almanya vatandaşlarının Batı'ya artan göçünün bir sonucuydu ve SED liderliği tarafından örtmece bir dille 'faşizm karşıtı koruma seddi' olarak adlandırıldı — bu ifade bugün hâlâ propagandacı dil çarpıtmasının simgesi sayılır.","ru":"Неожиданное строительство стены в ночь на 13 августа 1961 года стало результатом нарастающего исхода граждан ГДР на Запад и было эвфемистически названо руководством СЕПГ 'антифашистским защитным валом' — формулировка, которая и по сей день считается символом пропагандистского извращения языка.","es":"La sorpresiva construcción del muro en la noche del 13 de agosto de 1961 fue el resultado de un éxodo cada vez mayor de ciudadanos de la RDA hacia el Oeste, y la dirección del SED lo denominó eufemísticamente 'muro de protección antifascista', una expresión que hasta hoy se considera símbolo de la tergiversación propagandística del lenguaje.","fr":"La construction surprise du mur dans la nuit du 13 août 1961 résultait d'un exode croissant de citoyens est-allemands vers l'Ouest et fut désignée euphémiquement par la direction du SED comme un 'rempart de protection antifasciste' — une formule encore aujourd'hui considérée comme emblématique de la déformation propagandiste du langage.","pl":"Zaskakująca budowa muru w nocy z 12 na 13 sierpnia 1961 roku była wynikiem narastającego exodusu obywateli NRD na Zachód i została eufemistycznie nazwana przez kierownictwo SED 'antyfaszystowskim wałem ochronnym' — sformułowaniem, które do dziś uchodzi za symbol propagandowego wypaczania języka.","uk":"Несподівана побудова муру в ніч на 13 серпня 1961 року стала результатом наростаючого виходу громадян НДР на Захід і була евфемістично названа керівництвом СЄПН 'антифашистським захисним валом' — формулюванням, яке й донині вважається символом пропагандистського викривлення мови.","fa":"ساخت غافلگیرکننده دیوار در شب ۱۳ اوت ۱۹۶۱ نتیجه فرار روزافزون شهروندان آلمان شرقی به غرب بود و رهبری حزب اتحاد سوسیالیستی آن را به‌گونه‌ای تلطیف‌شده «حصار حفاظتی ضدفاشیستی» نامید — عبارتی که تا امروز نماد تحریف تبلیغاتی زبان به شمار می‌رود.","it":"L'improvvisa costruzione del Muro nella notte tra il 12 e il 13 agosto 1961 fu il risultato di un esodo sempre più massiccio di cittadini della DDR verso l'Ovest e venne definita eufemisticamente dalla dirigenza della SED \"barriera di protezione antifascista\" — una formula che ancora oggi è considerata emblematica della distorsione propagandistica del linguaggio."}}},"08-14":{"year":1949,"levels":{"A1":"Am 14. August 1949 wählen die Deutschen zum ersten Mal den Bundestag. Das ist ein wichtiger Tag für die Demokratie.","A2":"Am 14. August 1949 findet die erste Bundestagswahl statt. Sehr viele Menschen gehen wählen — die Wahlbeteiligung liegt bei 78,5 Prozent.","B1":"Am 14. August 1949 wählen die Deutschen zum ersten Mal den Bundestag. Die Wahlbeteiligung ist mit 78,5 Prozent sehr hoch. CDU/CSU wird mit 31 Prozent stärkste Kraft, knapp vor der SPD mit 29,2 Prozent.","B2":"Am 14. August 1949 findet die erste freie, gleiche und geheime Wahl auf nationaler Ebene seit 1932 statt. Die hohe Wahlbeteiligung von 78,5 Prozent überrascht viele Beobachter, die angesichts der schwierigen Nachkriegslage mit deutlich weniger Interesse gerechnet hatten.","C1":"Die Bundestagswahl vom 14. August 1949, die erste vollständig freie Wahl auf nationaler Ebene seit der Reichstagswahl 1932, überraschte mit einer Wahlbeteiligung von 78,5 Prozent — ein Vertrauensvorschuss, der angesichts der materiellen Not und der erst 17 Jahre zurückliegenden Zerstörung der Weimarer Demokratie keineswegs selbstverständlich war.","C2":"Dass sich 78,5 Prozent der Wahlberechtigten am 14. August 1949 an der ersten Bundestagswahl beteiligten, lässt sich als kollektives Bekenntnis zu einem demokratischen Neuanfang lesen — bemerkenswert in einem Land, dessen letzte demokratische Wahlerfahrung durch die nationalsozialistische Machtergreifung gewaltsam beendet worden war und dessen Bevölkerung 1949 noch unter den unmittelbaren Folgen von Krieg und Vertreibung litt."},"translationsA1":{"en":"On August 14, 1949, Germans elect the Bundestag for the first time. This is an important day for democracy.","ar":"في 14 أغسطس 1949، انتخب الألمان البوندستاغ لأول مرة. هذا يوم مهم للديمقراطية.","tr":"14 Ağustos 1949'da Almanlar ilk kez Bundestag'ı seçti. Bu, demokrasi için önemli bir gün.","ru":"14 августа 1949 года немцы впервые избрали Бундестаг. Это важный день для демократии.","es":"El 14 de agosto de 1949, los alemanes eligen el Bundestag por primera vez. Es un día importante para la democracia.","fr":"Le 14 août 1949, les Allemands élisent le Bundestag pour la première fois. C'est un jour important pour la démocratie.","pl":"14 sierpnia 1949 roku Niemcy po raz pierwszy wybrali Bundestag. To ważny dzień dla demokracji.","uk":"14 серпня 1949 року німці вперше обрали Бундестаг. Це важливий день для демократії.","fa":"در ۱۴ اوت ۱۹۴۹، آلمانی‌ها برای اولین بار بوندستاگ را انتخاب کردند. این روز مهمی برای دموکراسی است.","it":"Il 14 agosto 1949 i tedeschi eleggono per la prima volta il Bundestag. È un giorno importante per la democrazia."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 14, 1949, the first Bundestag election takes place. Very many people go to vote — turnout is 78.5 percent.","ar":"في 14 أغسطس 1949، تُجرى أول انتخابات للبرلمان الألماني (البوندستاغ). يذهب عدد كبير جداً من الناس للتصويت — تبلغ نسبة المشاركة 78.5 بالمئة.","tr":"14 Ağustos 1949'da ilk Federal Meclis (Bundestag) seçimi yapılır. Çok sayıda insan oy kullanmaya gider — katılım oranı yüzde 78,5'tir.","ru":"14 августа 1949 года проходят первые выборы в бундестаг. На выборы приходит очень много людей — явка составляет 78,5 процента.","es":"El 14 de agosto de 1949 se celebran las primeras elecciones al Bundestag. Muchísimas personas acuden a votar: la participación alcanza el 78,5 por ciento.","fr":"Le 14 août 1949 ont lieu les premières élections au Bundestag. Un très grand nombre de personnes vont voter — le taux de participation atteint 78,5 %.","pl":"14 sierpnia 1949 roku odbywają się pierwsze wybory do Bundestagu. Bardzo wielu ludzi idzie głosować — frekwencja wynosi 78,5 procent.","uk":"14 серпня 1949 року відбуваються перші вибори до Бундестагу. Дуже багато людей ідуть голосувати — явка становить 78,5 відсотка.","fa":"در ۱۴ اوت ۱۹۴۹، نخستین انتخابات بوندستاگ برگزار می‌شود. تعداد بسیار زیادی از مردم در رأی‌گیری شرکت می‌کنند — میزان مشارکت ۷۸.۵ درصد است.","it":"Il 14 agosto 1949 si svolgono le prime elezioni del Bundestag. Moltissime persone vanno a votare: l'affluenza è del 78,5 per cento."},"B1":{"en":"On August 14, 1949, Germans elect the Bundestag for the first time. Voter turnout is very high at 78.5 percent. The CDU/CSU becomes the strongest party with 31 percent, narrowly ahead of the SPD with 29.2 percent.","ar":"في 14 أغسطس 1949، ينتخب الألمان البرلمان الاتحادي لأول مرة. نسبة المشاركة عالية جداً، حيث بلغت 78.5 بالمئة. أصبح تحالف الاتحاد المسيحي (CDU/CSU) القوة الأكبر بنسبة 31 بالمئة، متقدماً بفارق ضئيل على الحزب الاشتراكي الديمقراطي (SPD) بنسبة 29.2 بالمئة.","tr":"14 Ağustos 1949'da Almanlar ilk kez Federal Meclis'i seçer. Katılım oranı yüzde 78,5 ile çok yüksektir. CDU/CSU yüzde 31 ile en güçlü parti olurken, yüzde 29,2 ile SPD'yi az farkla geride bırakır.","ru":"14 августа 1949 года немцы впервые избирают бундестаг. Явка избирателей очень высока — 78,5 процента. ХДС/ХСС становится сильнейшей партией с 31 процентом, немного опережая СДПГ с 29,2 процента.","es":"El 14 de agosto de 1949, los alemanes eligen por primera vez el Bundestag. La participación es muy alta, del 78,5 por ciento. La CDU/CSU se convierte en la fuerza más votada con un 31 por ciento, por delante del SPD, que obtiene un 29,2 por ciento.","fr":"Le 14 août 1949, les Allemands élisent pour la première fois le Bundestag. La participation est très élevée, à 78,5 %. La CDU/CSU devient la force la plus puissante avec 31 %, juste devant le SPD avec 29,2 %.","pl":"14 sierpnia 1949 roku Niemcy po raz pierwszy wybierają Bundestag. Frekwencja wyborcza jest bardzo wysoka i wynosi 78,5 procent. CDU/CSU zostaje najsilniejszą siłą z wynikiem 31 procent, tuż przed SPD z wynikiem 29,2 procent.","uk":"14 серпня 1949 року німці вперше обирають Бундестаг. Явка виборців дуже висока — 78,5 відсотка. ХДС/ХСС стає найсильнішою партією з результатом 31 відсоток, ледь випереджаючи СДПН із 29,2 відсотка.","fa":"در ۱۴ اوت ۱۹۴۹، آلمانی‌ها برای نخستین بار بوندستاگ را انتخاب می‌کنند. میزان مشارکت با ۷۸.۵ درصد بسیار بالاست. اتحادیه مسیحی (CDU/CSU) با ۳۱ درصد قوی‌ترین نیرو می‌شود و با اختلافی اندک از حزب سوسیال دموکرات (SPD) با ۲۹.۲ درصد پیشی می‌گیرد.","it":"Il 14 agosto 1949 i tedeschi eleggono per la prima volta il Bundestag. L'affluenza, con il 78,5 per cento, è molto alta. La CDU/CSU diventa il primo partito con il 31 per cento, di poco davanti alla SPD con il 29,2 per cento."},"B2":{"en":"On August 14, 1949, the first free, equal, and secret election at the national level since 1932 takes place. The high turnout of 78.5 percent surprises many observers, who, given the difficult post-war situation, had expected considerably less interest.","ar":"في 14 أغسطس 1949، تُجرى أول انتخابات حرة ومتساوية وسرية على المستوى الوطني منذ عام 1932. أثارت نسبة المشاركة المرتفعة البالغة 78.5 بالمئة دهشة العديد من المراقبين، الذين توقعوا اهتماماً أقل بكثير نظراً للوضع الصعب لما بعد الحرب.","tr":"14 Ağustos 1949'da 1932'den bu yana ulusal düzeyde ilk özgür, eşit ve gizli seçim yapılır. Yüzde 78,5'lik yüksek katılım oranı, savaş sonrası zor koşullar nedeniyle çok daha az ilgi bekleyen birçok gözlemciyi şaşırtır.","ru":"14 августа 1949 года проходят первые с 1932 года свободные, равные и тайные выборы на общенациональном уровне. Высокая явка в 78,5 процента удивляет многих наблюдателей, которые, учитывая тяжёлое послевоенное положение, ожидали значительно меньшего интереса.","es":"El 14 de agosto de 1949 se celebran las primeras elecciones libres, iguales y secretas a nivel nacional desde 1932. La alta participación del 78,5 por ciento sorprende a muchos observadores, que, dada la difícil situación de posguerra, esperaban un interés mucho menor.","fr":"Le 14 août 1949 ont lieu les premières élections libres, égalitaires et secrètes au niveau national depuis 1932. Le fort taux de participation de 78,5 % surprend de nombreux observateurs, qui, vu la situation d'après-guerre difficile, s'attendaient à un intérêt bien moindre.","pl":"14 sierpnia 1949 roku odbywają się pierwsze od 1932 roku wolne, równe i tajne wybory na szczeblu ogólnokrajowym. Wysoka frekwencja wynosząca 78,5 procent zaskakuje wielu obserwatorów, którzy wobec trudnej sytuacji powojennej spodziewali się znacznie mniejszego zainteresowania.","uk":"14 серпня 1949 року відбуваються перші з 1932 року вільні, рівні й таємні вибори загальнонаціонального рівня. Висока явка у 78,5 відсотка дивує багатьох спостерігачів, які через складне повоєнне становище очікували значно меншого інтересу.","fa":"در ۱۴ اوت ۱۹۴۹، نخستین انتخابات آزاد، برابر و مخفی در سطح ملی از سال ۱۹۳۲ برگزار می‌شود. مشارکت بالای ۷۸.۵ درصدی بسیاری از ناظران را که با توجه به شرایط دشوار پس از جنگ انتظار علاقه‌ای بسیار کمتر داشتند، شگفت‌زده می‌کند.","it":"Il 14 agosto 1949 si tiene la prima elezione libera, uguale e segreta a livello nazionale dal 1932. L'alta affluenza, pari al 78,5 per cento, sorprende molti osservatori, che, vista la difficile situazione del dopoguerra, si aspettavano un interesse nettamente inferiore."},"C1":{"en":"The Bundestag election of August 14, 1949, the first fully free election at the national level since the Reichstag election of 1932, surprised with a turnout of 78.5 percent — an advance of trust that was by no means a given, given the material hardship and the destruction of Weimar democracy just 17 years earlier.","ar":"فاجأت انتخابات البرلمان الاتحادي في 14 أغسطس 1949، وهي أول انتخابات حرة تماماً على المستوى الوطني منذ انتخابات الرايخستاغ عام 1932، بنسبة مشاركة بلغت 78.5 بالمئة — وهي سلفة ثقة لم تكن بديهية على الإطلاق نظراً للعوز المادي ولانهيار ديمقراطية فايمار الذي لم يمض عليه سوى 17 عاماً.","tr":"14 Ağustos 1949 Federal Meclis seçimi — 1932 Reichstag seçiminden bu yana ulusal düzeydeki ilk tamamen özgür seçim — yüzde 78,5'lik katılım oranıyla şaşırttı; bu, maddi sıkıntı ve Weimar demokrasisinin yok edilmesinin üzerinden henüz 17 yıl geçmiş olması karşısında hiç de kendiliğinden gelen bir güven avansı değildi.","ru":"Выборы в бундестаг 14 августа 1949 года, первые полностью свободные общенациональные выборы со времён выборов в рейхстаг 1932 года, удивили явкой в 78,5 процента — аванс доверия, который отнюдь не был сам собой разумеющимся, учитывая материальную нужду и то, что разрушение веймарской демократии произошло всего 17 лет назад.","es":"Las elecciones al Bundestag del 14 de agosto de 1949, las primeras elecciones plenamente libres a nivel nacional desde las elecciones al Reichstag de 1932, sorprendieron con una participación del 78,5 por ciento, un anticipo de confianza que no era en absoluto evidente dada la penuria material y la destrucción de la democracia de Weimar apenas 17 años antes.","fr":"L'élection au Bundestag du 14 août 1949, première élection pleinement libre au niveau national depuis les élections au Reichstag de 1932, surprit par un taux de participation de 78,5 % — une avance de confiance qui n'avait rien d'évident compte tenu de la misère matérielle et de la destruction de la démocratie de Weimar seulement 17 ans plus tôt.","pl":"Wybory do Bundestagu z 14 sierpnia 1949 roku, pierwsze w pełni wolne wybory na szczeblu ogólnokrajowym od wyborów do Reichstagu w 1932 roku, zaskoczyły frekwencją na poziomie 78,5 procent — zaliczka zaufania, która wcale nie była oczywista wobec materialnej nędzy i zniszczenia demokracji weimarskiej zaledwie 17 lat wcześniej.","uk":"Вибори до Бундестагу 14 серпня 1949 року, перші повністю вільні загальнонаціональні вибори з часів виборів до Рейхстагу 1932 року, здивували явкою у 78,5 відсотка — аванс довіри, який зовсім не був самоочевидним з огляду на матеріальну скруту та знищення веймарської демократії лише 17 роками раніше.","fa":"انتخابات بوندستاگ در ۱۴ اوت ۱۹۴۹، نخستین انتخابات کاملاً آزاد در سطح ملی از زمان انتخابات رایشستاگ در سال ۱۹۳۲، با مشارکت ۷۸.۵ درصدی شگفتی آفرید — پیش‌پرداختی از اعتماد که با توجه به تنگدستی مادی و ویرانی دموکراسی وایمار تنها ۱۷ سال پیش از آن، به‌هیچ‌وجه بدیهی نبود.","it":"Le elezioni del Bundestag del 14 agosto 1949, le prime completamente libere a livello nazionale dalle elezioni del Reichstag del 1932, sorpresero con un'affluenza del 78,5 per cento — un atto di fiducia tutt'altro che scontato, viste le difficoltà materiali e la distruzione della democrazia di Weimar avvenuta solo 17 anni prima."},"C2":{"en":"The fact that 78.5 percent of eligible voters took part in the first Bundestag election on August 14, 1949, can be read as a collective commitment to a democratic new beginning — remarkable in a country whose last democratic voting experience had been violently ended by the National Socialist seizure of power, and whose population in 1949 was still suffering the immediate consequences of war and displacement.","ar":"يمكن قراءة مشاركة 78.5 بالمئة من الناخبين المؤهلين في أول انتخابات للبرلمان الاتحادي في 14 أغسطس 1949 كالتزام جماعي ببداية ديمقراطية جديدة — وهو أمر لافت في بلد أُنهيت آخر تجربة انتخابية ديمقراطية فيه بالقوة عبر استيلاء النازيين على السلطة، وكان سكانه في عام 1949 لا يزالون يعانون من التبعات المباشرة للحرب والتهجير.","tr":"14 Ağustos 1949'da seçme hakkına sahip olanların yüzde 78,5'inin ilk Federal Meclis seçimine katılması, demokratik bir yeniden başlangıca kolektif bir bağlılık olarak okunabilir — Nasyonal Sosyalist iktidar gaspıyla son demokratik seçim deneyimi zorla sona erdirilmiş ve 1949'da nüfusu hâlâ savaşın ve sürgünün doğrudan sonuçlarından muzdarip olan bir ülkede dikkat çekicidir.","ru":"То, что 78,5 процента избирателей приняли участие в первых выборах в бундестаг 14 августа 1949 года, можно прочитать как коллективное признание демократического нового начала — примечательно для страны, чей последний демократический избирательный опыт был насильственно прерван национал-социалистическим захватом власти и население которой в 1949 году всё ещё страдало от непосредственных последствий войны и изгнания.","es":"Que el 78,5 por ciento de los electores participara en las primeras elecciones al Bundestag el 14 de agosto de 1949 puede leerse como un compromiso colectivo con un nuevo comienzo democrático, algo notable en un país cuya última experiencia electoral democrática había sido interrumpida violentamente por la toma del poder nacionalsocialista y cuya población en 1949 aún sufría las consecuencias inmediatas de la guerra y el desplazamiento.","fr":"Le fait que 78,5 % des électeurs aient participé à la première élection au Bundestag le 14 août 1949 peut être interprété comme un engagement collectif envers un nouveau départ démocratique — remarquable dans un pays dont la dernière expérience électorale démocratique avait été violemment interrompue par la prise du pouvoir national-socialiste et dont la population souffrait encore en 1949 des conséquences immédiates de la guerre et des déplacements forcés.","pl":"Fakt, że 78,5 procent uprawnionych do głosowania wzięło udział w pierwszych wyborach do Bundestagu 14 sierpnia 1949 roku, można odczytać jako zbiorowe opowiedzenie się za demokratycznym nowym początkiem — godne uwagi w kraju, którego ostatnie demokratyczne doświadczenie wyborcze zostało brutalnie zakończone przez narodowosocjalistyczne przejęcie władzy, a którego ludność w 1949 roku wciąż cierpiała z powodu bezpośrednich skutków wojny i wypędzeń.","uk":"Те, що 78,5 відсотка виборців узяли участь у перших виборах до Бундестагу 14 серпня 1949 року, можна прочитати як колективне визнання демократичного нового початку — примітно для країни, чий останній демократичний виборчий досвід було насильно перервано націонал-соціалістичним захопленням влади і чиє населення у 1949 році все ще страждало від безпосередніх наслідків війни та вигнання.","fa":"این‌که ۷۸.۵ درصد از واجدان شرایط رأی‌دهی در ۱۴ اوت ۱۹۴۹ در نخستین انتخابات بوندستاگ شرکت کردند، می‌تواند به‌عنوان تعهدی جمعی به یک آغاز دوباره دموکراتیک خوانده شود — امری قابل توجه در کشوری که آخرین تجربه انتخاباتی دموکراتیک آن با به‌قدرت‌رسیدن ناسیونال‌سوسیالیست‌ها به‌زور پایان یافته بود و جمعیت آن در سال ۱۹۴۹ هنوز از پیامدهای مستقیم جنگ و آوارگی رنج می‌برد.","it":"Il fatto che il 78,5 per cento degli aventi diritto abbia partecipato, il 14 agosto 1949, alle prime elezioni del Bundestag può essere letto come un'adesione collettiva a un nuovo inizio democratico — un dato notevole in un paese la cui ultima esperienza elettorale democratica era stata interrotta con la violenza dalla presa del potere nazionalsocialista, e la cui popolazione nel 1949 soffriva ancora delle conseguenze dirette della guerra e delle espulsioni."}}},"08-15":{"year":1923,"levels":{"A1":"Am 15. August 1923 beginnt in Weimar eine große Ausstellung. Sie zeigt Möbel, Häuser und Lampen vom Bauhaus. Viele Menschen kommen und staunen.","A2":"Am 15. August 1923 eröffnet in Weimar die erste große Bauhaus-Ausstellung. Zum ersten Mal sah ein breites Publikum, was die Schule entwickelt hatte: klare Formen, wenig Verzierung, alles zum Gebrauch gedacht.","B1":"Am 15. August 1923 beginnt in Weimar die erste Bauhaus-Ausstellung. Gezeigt wurde ein komplettes Musterhaus mit allem, was darin steht. Der Stil wirkte damals kahl und ist heute der Normalfall in Möbelkatalogen weltweit.","B2":"Am 15. August 1923 stellt sich das Bauhaus erstmals der Öffentlichkeit. Die Ausstellung war zugleich eine politische Notwendigkeit: Die Schule musste zeigen, dass sie brauchbare Ergebnisse liefert, weil das Land ihr Geld strich. Kunst musste sich hier rechtfertigen wie ein Betrieb.","C1":"Die Ausstellung vom 15. August 1923 markiert den Übergang des Bauhauses vom Kunsthandwerk zur Industrieform. Der Leitsatz lautete nun Kunst und Technik, eine neue Einheit — eine Abkehr von der ursprünglich handwerklichen Ausrichtung, erzwungen ebenso von der Sache wie von der Finanzlage.","C2":"Am 15. August 1923 zeigte sich, wie eng ästhetische Programme an ihre Existenzbedingungen gebunden sind. Das Bauhaus wandte sich der Industrie zu, als das Handwerk keine Zukunft mehr versprach, und formulierte diese Notwendigkeit als Erkenntnis. Dass daraus die einflussreichste Gestaltungslehre des Jahrhunderts wurde, ändert nichts daran, dass ihr Ausgangspunkt eine Finanzierungsfrage war."},"translationsA1":{"en":"On August 15, 1923, a large exhibition opens in Weimar. It shows furniture, houses and lamps from the Bauhaus. Many people come and marvel.","ar":"في 15 أغسطس 1923، افتُتح معرض كبير في فايمار. عرض أثاثًا وبيوتًا ومصابيح من الباوهاوس. جاء كثيرون وأُعجبوا.","tr":"15 Ağustos 1923'te Weimar'da büyük bir sergi açıldı. Bauhaus'un mobilyalarını, evlerini ve lambalarını gösterdi. Birçok kişi gelip şaşırdı.","ru":"15 августа 1923 года в Веймаре открылась большая выставка. Она показывает мебель, дома и лампы Баухауса. Многие приходят и удивляются.","es":"El 15 de agosto de 1923 se inaugura en Weimar una gran exposición. Muestra muebles, casas y lámparas de la Bauhaus. Mucha gente viene y se asombra.","fr":"Le 15 août 1923, une grande exposition ouvre à Weimar. Elle montre meubles, maisons et lampes du Bauhaus. Beaucoup de gens viennent et s'étonnent.","pl":"15 sierpnia 1923 roku w Weimarze otwarto wielką wystawę. Pokazuje meble, domy i lampy Bauhausu. Przychodzi wielu ludzi i podziwia.","uk":"15 серпня 1923 року у Веймарі відкрилася велика виставка. Вона показує меблі, будинки та лампи Баугаусу. Багато людей приходять і дивуються.","fa":"در ۱۵ اوت ۱۹۲۳، نمایشگاهی بزرگ در وایمار گشوده شد. مبلمان، خانه‌ها و چراغ‌های باوهاوس را نشان می‌داد. بسیاری آمدند و شگفت‌زده شدند.","it":"Il 15 agosto 1923 inizia a Weimar una grande mostra. Espone mobili, case e lampade del Bauhaus. Molte persone vengono e restano stupite."},"translationsByLevel":{"A2":{"en":"On August 15, 1923, the first major Bauhaus exhibition opens in Weimar. For the first time, a broad audience saw what the school had developed: clear forms, little ornamentation, everything designed for use.","ar":"في 15 أغسطس 1923، يُفتتح في فايمار أول معرض كبير لمدرسة الباوهاوس. لأول مرة، رأى جمهور واسع ما طورته المدرسة: أشكال واضحة، زخرفة قليلة، كل شيء مصمم للاستخدام.","tr":"15 Ağustos 1923'te Weimar'da ilk büyük Bauhaus sergisi açılır. Geniş bir kitle ilk kez okulun geliştirdiklerini görür: net formlar, az süsleme, her şey kullanım için tasarlanmış.","ru":"15 августа 1923 года в Веймаре открывается первая крупная выставка Баухауса. Впервые широкая публика увидела то, что разработала школа: чёткие формы, мало украшений, всё создано для практического использования.","es":"El 15 de agosto de 1923 se inaugura en Weimar la primera gran exposición de la Bauhaus. Por primera vez, un público amplio vio lo que la escuela había desarrollado: formas claras, poca ornamentación, todo pensado para el uso.","fr":"Le 15 août 1923 s'ouvre à Weimar la première grande exposition du Bauhaus. Pour la première fois, un large public découvre ce que l'école avait développé : des formes claires, peu d'ornements, tout conçu pour l'usage.","pl":"15 sierpnia 1923 roku w Weimarze otwiera się pierwsza duża wystawa Bauhausu. Po raz pierwszy szeroka publiczność zobaczyła, co wypracowała szkoła: jasne formy, mało zdobień, wszystko pomyślane do użytku.","uk":"15 серпня 1923 року у Веймарі відкривається перша велика виставка Баугаузу. Уперше широка публіка побачила те, що розробила школа: чіткі форми, мало прикрас, усе призначене для використання.","fa":"در ۱۵ اوت ۱۹۲۳، نخستین نمایشگاه بزرگ باوهاوس در وایمار افتتاح می‌شود. برای نخستین بار، عموم مردم آنچه را که این مدرسه توسعه داده بود دیدند: فرم‌های ساده، تزیین اندک، همه‌چیز برای کاربرد طراحی شده بود.","it":"Il 15 agosto 1923 apre a Weimar la prima grande mostra del Bauhaus. Per la prima volta un vasto pubblico vede ciò che la scuola aveva sviluppato: forme chiare, poche decorazioni, tutto pensato per l'uso quotidiano."},"B1":{"en":"On August 15, 1923, the first Bauhaus exhibition begins in Weimar. A complete model house was shown, with everything inside it. The style seemed bare back then and is today the norm in furniture catalogs worldwide.","ar":"في 15 أغسطس 1923، يبدأ في فايمار أول معرض للباوهاوس. عُرض بيت نموذجي كامل بكل ما فيه من أثاث. بدا الطراز حينها عارياً بلا زخرفة وهو اليوم القاعدة المعتادة في كتالوجات الأثاث حول العالم.","tr":"15 Ağustos 1923'te Weimar'da ilk Bauhaus sergisi başlar. İçindeki her şeyle birlikte tam bir örnek ev gösterildi. Üslup o zamanlar çıplak görünüyordu ve bugün dünya çapında mobilya kataloglarında olağan hale gelmiştir.","ru":"15 августа 1923 года в Веймаре открывается первая выставка Баухауса. Был показан полностью обустроенный образцовый дом со всем содержимым. Стиль тогда казался голым, а сегодня он норма в мебельных каталогах по всему миру.","es":"El 15 de agosto de 1923 comienza en Weimar la primera exposición de la Bauhaus. Se mostró una casa modelo completa con todo lo que había en ella. El estilo parecía entonces desnudo y hoy es la norma en los catálogos de muebles de todo el mundo.","fr":"Le 15 août 1923 débute à Weimar la première exposition du Bauhaus. Fut présentée une maison témoin complète avec tout ce qu'elle contenait. Le style paraissait alors dépouillé et constitue aujourd'hui la norme dans les catalogues de meubles du monde entier.","pl":"15 sierpnia 1923 roku w Weimarze rozpoczyna się pierwsza wystawa Bauhausu. Pokazano kompletny dom wzorcowy wraz z całym wyposażeniem. Styl wydawał się wówczas surowy, a dziś jest normą w katalogach mebli na całym świecie.","uk":"15 серпня 1923 року у Веймарі розпочинається перша виставка Баугаузу. Було показано повністю обладнаний зразковий дім з усім, що в ньому є. Стиль тоді здавався голим, а сьогодні є нормою в меблевих каталогах по всьому світу.","fa":"در ۱۵ اوت ۱۹۲۳، نخستین نمایشگاه باوهاوس در وایمار آغاز می‌شود. یک خانه نمونه کامل با تمام وسایل داخل آن به نمایش گذاشته شد. این سبک در آن زمان لخت و ساده به نظر می‌رسید و امروزه در کاتالوگ‌های مبلمان سراسر جهان امری عادی است.","it":"Il 15 agosto 1923 inizia a Weimar la prima mostra del Bauhaus. Viene presentata una casa modello completa, con tutti i suoi arredi. Lo stile appariva allora spoglio ed è oggi la norma nei cataloghi di mobili di tutto il mondo."},"B2":{"en":"On August 15, 1923, the Bauhaus presents itself to the public for the first time. The exhibition was also a political necessity: the school had to show that it delivered usable results, because the state was cutting its funding. Here, art had to justify itself like a business.","ar":"في 15 أغسطس 1923، يقدم الباوهاوس نفسه للجمهور لأول مرة. كان المعرض في الوقت نفسه ضرورة سياسية: كان على المدرسة أن تُظهر أنها تقدم نتائج مفيدة، لأن الولاية كانت تقطع تمويلها. كان على الفن هنا أن يبرر نفسه مثل أي منشأة اقتصادية.","tr":"15 Ağustos 1923'te Bauhaus ilk kez kamuoyuna kendini tanıtır. Sergi aynı zamanda siyasi bir zorunluluktu: okul, kullanılabilir sonuçlar sunduğunu göstermek zorundaydı, çünkü eyalet ona verdiği parayı kesiyordu. Sanat burada tıpkı bir işletme gibi kendini haklı çıkarmak zorundaydı.","ru":"15 августа 1923 года Баухаус впервые предстаёт перед публикой. Выставка была одновременно политической необходимостью: школе нужно было доказать, что она даёт полезные результаты, так как государство урезало её финансирование. Искусству здесь приходилось оправдывать себя, как предприятию.","es":"El 15 de agosto de 1923, la Bauhaus se presenta por primera vez ante el público. La exposición era al mismo tiempo una necesidad política: la escuela tenía que demostrar que ofrecía resultados útiles, porque el estado le recortaba la financiación. Aquí el arte tenía que justificarse como una empresa.","fr":"Le 15 août 1923, le Bauhaus se présente pour la première fois au public. L'exposition était en même temps une nécessité politique : l'école devait prouver qu'elle produisait des résultats utilisables, car l'État lui coupait les crédits. L'art devait ici se justifier comme une entreprise.","pl":"15 sierpnia 1923 roku Bauhaus po raz pierwszy prezentuje się publiczności. Wystawa była zarazem koniecznością polityczną: szkoła musiała pokazać, że dostarcza użyteczne rezultaty, ponieważ kraj związkowy ograniczał jej finansowanie. Sztuka musiała się tu usprawiedliwiać jak przedsiębiorstwo.","uk":"15 серпня 1923 року Баугауз уперше постає перед публікою. Виставка водночас була політичною необхідністю: школа мала показати, що дає корисні результати, бо земля скорочувала її фінансування. Мистецтву тут довелося виправдовувати себе, як підприємству.","fa":"در ۱۵ اوت ۱۹۲۳، باوهاوس برای نخستین بار خود را به عموم مردم معرفی می‌کند. این نمایشگاه در عین حال یک ضرورت سیاسی بود: مدرسه باید نشان می‌داد که نتایج کاربردی ارائه می‌دهد، زیرا ایالت بودجه آن را قطع کرده بود. هنر در اینجا باید مانند یک بنگاه اقتصادی خود را توجیه می‌کرد.","it":"Il 15 agosto 1923 il Bauhaus si presenta per la prima volta al pubblico. La mostra era anche una necessità politica: la scuola doveva dimostrare di produrre risultati utili, perché il Land le aveva tagliato i finanziamenti. L'arte doveva qui giustificarsi come un'impresa."},"C1":{"en":"The exhibition of August 15, 1923, marks the Bauhaus's transition from arts and crafts to industrial design. The new guiding principle was now Art and Technology — a New Unity — a departure from the school's originally craft-based orientation, forced as much by the subject matter as by its financial situation.","ar":"يمثل معرض 15 أغسطس 1923 انتقال الباوهاوس من الحرفة الفنية إلى الشكل الصناعي. أصبح الشعار الآن 'الفن والتقنية، وحدة جديدة' — وهو ابتعاد عن التوجه الحرفي الأصلي، فرضته طبيعة الأمور بقدر ما فرضه الوضع المالي.","tr":"15 Ağustos 1923 sergisi, Bauhaus'un el sanatlarından endüstriyel forma geçişini işaret eder. Yeni ilke artık 'Sanat ve Teknik, yeni bir birlik' idi — bu, hem meselenin doğasından hem de mali durumdan kaynaklanan, okulun başlangıçtaki el sanatları odaklı yöneliminden bir uzaklaşmaydı.","ru":"Выставка 15 августа 1923 года знаменует переход Баухауса от художественного ремесла к промышленной форме. Новым девизом стало 'Искусство и техника — новое единство' — отход от изначально ремесленной ориентации, вынужденный как самой сутью дела, так и финансовым положением.","es":"La exposición del 15 de agosto de 1923 marca la transición de la Bauhaus del artesanado artístico a la forma industrial. El nuevo lema fue Arte y Técnica, una nueva unidad —un giro respecto a la orientación artesanal original, impuesto tanto por la naturaleza del asunto como por la situación financiera.","fr":"L'exposition du 15 août 1923 marque le passage du Bauhaus de l'artisanat d'art à la forme industrielle. Le nouveau principe directeur était désormais Art et technique, une unité nouvelle — un abandon de l'orientation artisanale d'origine, imposé autant par la nature des choses que par la situation financière.","pl":"Wystawa z 15 sierpnia 1923 roku wyznacza przejście Bauhausu od rzemiosła artystycznego do formy przemysłowej. Nowym hasłem przewodnim stało się teraz 'Sztuka i technika, nowa jedność' — odejście od pierwotnie rzemieślniczej orientacji, wymuszone zarówno przez samą sprawę, jak i sytuację finansową.","uk":"Виставка 15 серпня 1923 року позначає перехід Баугаузу від художнього ремесла до промислової форми. Новим гаслом стало 'Мистецтво і техніка — нова єдність' — відхід від початково ремісничої орієнтації, вимушений як самою суттю справи, так і фінансовим становищем.","fa":"نمایشگاه ۱۵ اوت ۱۹۲۳ گذار باوهاوس از صنایع دستی هنری به فرم صنعتی را نشان می‌دهد. اصل راهنمای جدید اکنون این بود: «هنر و فناوری، وحدتی نو» — دوری از جهت‌گیری اولیه صنعتگرانه که هم به‌واسطه ماهیت موضوع و هم وضعیت مالی تحمیل شده بود.","it":"La mostra del 15 agosto 1923 segna il passaggio del Bauhaus dall'artigianato artistico alla forma industriale. Il motto divenne allora \"arte e tecnica, una nuova unità\" — un allontanamento dall'orientamento originariamente artigianale, imposto tanto dalla logica delle cose quanto dalla situazione finanziaria."},"C2":{"en":"On August 15, 1923, it became clear how closely aesthetic programs are bound to the conditions of their existence. The Bauhaus turned to industry once craftsmanship no longer promised a future, and it framed this necessity as insight. That this became the most influential design doctrine of the century does not change the fact that its starting point was a funding question.","ar":"في 15 أغسطس 1923 اتضح مدى ارتباط البرامج الجمالية الوثيق بظروف وجودها. تحوّل الباوهاوس نحو الصناعة عندما لم تعد الحرفة تعِد بمستقبل، وصاغ هذه الضرورة على أنها اكتشاف معرفي. وكون ذلك أصبح أكثر نظريات التصميم تأثيراً في القرن، لا يغيّر من حقيقة أن نقطة انطلاقه كانت مسألة تمويل.","tr":"15 Ağustos 1923'te estetik programların varoluş koşullarına ne kadar sıkı bağlı olduğu ortaya çıktı. Bauhaus, el sanatları artık bir gelecek vaat etmeyince endüstriye yöneldi ve bu zorunluluğu bir kavrayış olarak formüle etti. Bunun yüzyılın en etkili tasarım öğretisi haline gelmesi, çıkış noktasının bir finansman sorunu olduğu gerçeğini değiştirmez.","ru":"15 августа 1923 года стало видно, насколько тесно эстетические программы связаны с условиями своего существования. Баухаус обратился к промышленности, когда ремесло перестало сулить будущее, и представил эту необходимость как открытие. То, что из этого выросла самая влиятельная теория проектирования столетия, не отменяет того факта, что её отправной точкой был вопрос финансирования.","es":"El 15 de agosto de 1923 se hizo evidente cuán estrechamente están ligados los programas estéticos a sus condiciones de existencia. La Bauhaus se volcó hacia la industria cuando el artesanado ya no prometía futuro, y formuló esta necesidad como un descubrimiento. Que de ahí surgiera la doctrina de diseño más influyente del siglo no cambia el hecho de que su punto de partida fuera una cuestión de financiación.","fr":"Le 15 août 1923 montra à quel point les programmes esthétiques sont liés à leurs conditions d'existence. Le Bauhaus se tourna vers l'industrie lorsque l'artisanat ne promettait plus d'avenir, et présenta cette nécessité comme une prise de conscience. Que cela soit devenu la doctrine de conception la plus influente du siècle ne change rien au fait que son point de départ était une question de financement.","pl":"15 sierpnia 1923 roku pokazało, jak ściśle programy estetyczne są związane z warunkami swojego istnienia. Bauhaus zwrócił się ku przemysłowi, gdy rzemiosło przestało obiecywać przyszłość, i przedstawił tę konieczność jako odkrycie. To, że wyrosła z tego najbardziej wpływowa doktryna projektowa stulecia, nie zmienia faktu, że jej punktem wyjścia była kwestia finansowania.","uk":"15 серпня 1923 року стало видно, наскільки тісно естетичні програми пов'язані з умовами свого існування. Баугауз звернувся до промисловості, коли ремесло перестало обіцяти майбутнє, і сформулював цю необхідність як осяяння. Те, що з цього виросла найвпливовіша теорія дизайну століття, не скасовує того факту, що її відправною точкою було питання фінансування.","fa":"در ۱۵ اوت ۱۹۲۳ آشکار شد که برنامه‌های زیبایی‌شناختی تا چه اندازه به شرایط وجودی خود وابسته‌اند. باوهاوس زمانی به سمت صنعت روی آورد که صنایع دستی دیگر آینده‌ای را نوید نمی‌داد، و این ضرورت را به‌صورت یک بینش صورت‌بندی کرد. اینکه از آن مؤثرترین آموزه طراحی قرن پدید آمد، این واقعیت را تغییر نمی‌دهد که نقطه آغازش یک مسئله مالی بود.","it":"Il 15 agosto 1923 si rivelò quanto strettamente i programmi estetici siano legati alle proprie condizioni materiali di esistenza. Il Bauhaus si rivolse all'industria quando l'artigianato non prometteva più alcun futuro, e trasformò questa necessità in una presa di coscienza teorica. Il fatto che ne sia nata la dottrina progettuale più influente del secolo non cambia il fatto che il suo punto di partenza fosse una questione di finanziamento."}},"sideFacts":[]},"08-16":{"year":1832,"levels":{"A1":"Am 16. August 1832 wird Wilhelm Wundt geboren. Er untersucht, wie Menschen denken und fühlen. Dafür macht er zum ersten Mal Versuche im Labor.","A2":"Am 16. August 1832 kommt Wilhelm Wundt zur Welt. Er richtete in Leipzig das erste Labor für Psychologie ein. Vorher hatte man über die Seele nur nachgedacht, nicht gemessen.","B1":"Am 16. August 1832 wird Wilhelm Wundt geboren. 1879 gründete er in Leipzig das erste psychologische Labor der Welt. Damit wurde aus einem Zweig der Philosophie eine eigene Wissenschaft mit Messgeräten und Versuchsreihen.","B2":"Am 16. August 1832 wird Wilhelm Wundt geboren. Seine Entscheidung war methodisch: Er maß Reaktionszeiten, statt über das Bewusstsein nachzudenken. Damit legte er fest, was die Psychologie künftig als Frage zulässt — und was sie an die Philosophie zurückgibt.","C1":"Der am 16. August 1832 Geborene gab einer Disziplin ihre Form, indem er ihren Gegenstand einschränkte. Was sich nicht messen ließ, fiel aus dem Fach heraus. Dieser Preis wird bei jeder Verwissenschaftlichung gezahlt — und er ist erst dann ein Problem, wenn man vergisst, dass er gezahlt wurde.","C2":"An Wundt, geboren am 16. August 1832, lässt sich beobachten, wie Fächer entstehen: nicht durch neue Fragen, sondern durch neue Zulässigkeitsregeln für Antworten. Die Psychologie kaufte ihre wissenschaftliche Anerkennung mit dem Verzicht auf ihre schwierigsten Fragen — und ringt seither periodisch darum, sie zurückzuholen."},"translationsA1":{"en":"On August 16, 1832, Wilhelm Wundt is born. He studies how people think and feel. For this he carries out laboratory experiments for the first time.","ar":"في 16 أغسطس 1832، وُلد فيلهلم فونت. درس كيف يفكر الناس ويشعرون. ولذلك أجرى تجارب في المختبر لأول مرة.","tr":"16 Ağustos 1832'de Wilhelm Wundt doğdu. İnsanların nasıl düşünüp hissettiğini araştırdı. Bunun için ilk kez laboratuvarda deneyler yaptı.","ru":"16 августа 1832 года родился Вильгельм Вундт. Он изучал, как люди думают и чувствуют. Для этого он впервые проводил опыты в лаборатории.","es":"El 16 de agosto de 1832 nace Wilhelm Wundt. Investiga cómo piensan y sienten las personas. Para ello realiza por primera vez experimentos de laboratorio.","fr":"Le 16 août 1832, Wilhelm Wundt naît. Il étudie comment les gens pensent et ressentent. Pour cela, il mène pour la première fois des expériences en laboratoire.","pl":"16 sierpnia 1832 roku urodził się Wilhelm Wundt. Badał, jak ludzie myślą i czują. W tym celu po raz pierwszy prowadził doświadczenia w laboratorium.","uk":"16 серпня 1832 року народився Вільгельм Вундт. Він досліджував, як люди думають і відчувають. Для цього він уперше проводив досліди в лабораторії.","fa":"در ۱۶ اوت ۱۸۳۲، ویلهلم وونت به دنیا آمد. او پژوهید که مردم چگونه می‌اندیشند و احساس می‌کنند. برای این کار نخستین بار در آزمایشگاه آزمایش کرد.","it":"Il 16 agosto 1832 nasce Wilhelm Wundt. Studia come le persone pensano e provano emozioni. Per farlo, è il primo a condurre esperimenti in laboratorio."},"translationsByLevel":{"A2":{"en":"On August 16, 1832, Wilhelm Wundt is born. He set up the first psychology laboratory in Leipzig. Before that, people had only thought about the soul, not measured it.","ar":"في 16 أغسطس 1832، وُلد فيلهلم فونت. أسس في لايبزيغ أول مختبر لعلم النفس. قبل ذلك، كان الناس يفكرون في الروح فقط دون قياسها.","tr":"16 Ağustos 1832'de Wilhelm Wundt dünyaya gelir. Leipzig'de ilk psikoloji laboratuvarını kurdu. Daha önce ruh hakkında yalnızca düşünülür, ölçülmezdi.","ru":"16 августа 1832 года рождается Вильгельм Вундт. Он основал в Лейпциге первую лабораторию психологии. До этого о душе только размышляли, но не измеряли её.","es":"El 16 de agosto de 1832 nace Wilhelm Wundt. Fundó en Leipzig el primer laboratorio de psicología. Antes, solo se había reflexionado sobre el alma, no se la había medido.","fr":"Le 16 août 1832 naît Wilhelm Wundt. Il créa à Leipzig le premier laboratoire de psychologie. Auparavant, on avait seulement réfléchi sur l'âme, sans jamais la mesurer.","pl":"16 sierpnia 1832 roku przychodzi na świat Wilhelm Wundt. Założył w Lipsku pierwsze laboratorium psychologiczne. Wcześniej o duszy jedynie rozmyślano, nie mierzono jej.","uk":"16 серпня 1832 року народжується Вільгельм Вундт. Він заснував у Лейпцигу першу лабораторію психології. До цього про душу лише розмірковували, а не вимірювали її.","fa":"در ۱۶ اوت ۱۸۳۲، ویلهلم وونت به دنیا می‌آید. او نخستین آزمایشگاه روان‌شناسی را در لایپزیگ تأسیس کرد. پیش از آن، درباره روح فقط تأمل می‌شد، نه اندازه‌گیری.","it":"Il 16 agosto 1832 nasce Wilhelm Wundt. A Lipsia fonda il primo laboratorio di psicologia. Prima di lui, sull'anima si era solo riflettuto, non si era mai misurato nulla."},"B1":{"en":"On August 16, 1832, Wilhelm Wundt is born. In 1879, he founded the world's first psychological laboratory in Leipzig. This turned a branch of philosophy into an independent science with measuring instruments and series of experiments.","ar":"في 16 أغسطس 1832، وُلد فيلهلم فونت. أسس عام 1879 في لايبزيغ أول مختبر نفسي في العالم. وبذلك تحوّل فرع من الفلسفة إلى علم مستقل بأجهزة قياس وسلاسل تجارب.","tr":"16 Ağustos 1832'de Wilhelm Wundt doğdu. 1879'da Leipzig'de dünyanın ilk psikoloji laboratuvarını kurdu. Böylece felsefenin bir dalı, ölçüm cihazları ve deney serileriyle bağımsız bir bilim haline geldi.","ru":"16 августа 1832 года родился Вильгельм Вундт. В 1879 году он основал в Лейпциге первую в мире психологическую лабораторию. Так одна из ветвей философии превратилась в самостоятельную науку с измерительными приборами и сериями опытов.","es":"El 16 de agosto de 1832 nace Wilhelm Wundt. En 1879 fundó en Leipzig el primer laboratorio psicológico del mundo. Así, una rama de la filosofía se convirtió en una ciencia independiente con instrumentos de medición y series de experimentos.","fr":"Le 16 août 1832 naît Wilhelm Wundt. En 1879, il fonda à Leipzig le premier laboratoire de psychologie du monde. Une branche de la philosophie devint ainsi une science à part entière, dotée d'instruments de mesure et de séries d'expériences.","pl":"16 sierpnia 1832 roku rodzi się Wilhelm Wundt. W 1879 roku założył w Lipsku pierwsze na świecie laboratorium psychologiczne. Dzięki temu gałąź filozofii stała się samodzielną nauką z przyrządami pomiarowymi i seriami eksperymentów.","uk":"16 серпня 1832 року народжується Вільгельм Вундт. У 1879 році він заснував у Лейпцигу першу у світі психологічну лабораторію. Так галузь філософії перетворилася на самостійну науку з вимірювальними приладами й серіями експериментів.","fa":"در ۱۶ اوت ۱۸۳۲، ویلهلم وونت متولد می‌شود. او در سال ۱۸۷۹ نخستین آزمایشگاه روان‌شناسی جهان را در لایپزیگ بنیان نهاد. بدین‌سان شاخه‌ای از فلسفه به علمی مستقل با ابزارهای اندازه‌گیری و مجموعه‌ای از آزمایش‌ها تبدیل شد.","it":"Il 16 agosto 1832 nasce Wilhelm Wundt. Nel 1879 fonda a Lipsia il primo laboratorio di psicologia del mondo. Un ramo della filosofia diventò così una scienza autonoma, fatta di strumenti di misurazione e serie di esperimenti."},"B2":{"en":"On August 16, 1832, Wilhelm Wundt is born. His decision was methodological: he measured reaction times instead of reflecting on consciousness. In doing so, he determined what psychology would henceforth admit as a legitimate question — and what it would hand back to philosophy.","ar":"في 16 أغسطس 1832، وُلد فيلهلم فونت. كان قراره منهجياً: قاس أزمنة رد الفعل بدلاً من التفكير في الوعي. وبذلك حدد ما سيسمح به علم النفس مستقبلاً كسؤال مشروع — وما سيعيده إلى الفلسفة.","tr":"16 Ağustos 1832'de Wilhelm Wundt doğdu. Kararı metodolojikti: bilinç üzerine düşünmek yerine tepki sürelerini ölçtü. Böylece psikolojinin bundan böyle bir soru olarak neyi kabul edeceğini — ve neyi felsefeye geri bırakacağını belirledi.","ru":"16 августа 1832 года родился Вильгельм Вундт. Его решение носило методологический характер: он измерял время реакции вместо того, чтобы размышлять о сознании. Тем самым он определил, что психология впредь будет допускать в качестве вопроса — а что вернёт философии.","es":"El 16 de agosto de 1832 nace Wilhelm Wundt. Su decisión fue metodológica: midió tiempos de reacción en lugar de reflexionar sobre la conciencia. Con ello determinó qué admitiría en adelante la psicología como pregunta legítima, y qué le devolvería a la filosofía.","fr":"Le 16 août 1832 naît Wilhelm Wundt. Sa décision fut méthodologique : il mesura des temps de réaction plutôt que de réfléchir sur la conscience. Il détermina ainsi ce que la psychologie admettrait désormais comme question légitime — et ce qu'elle rendrait à la philosophie.","pl":"16 sierpnia 1832 roku rodzi się Wilhelm Wundt. Jego decyzja miała charakter metodologiczny: mierzył czasy reakcji zamiast rozmyślać o świadomości. Tym samym ustalił, co psychologia będzie odtąd dopuszczać jako pytanie — a co odda z powrotem filozofii.","uk":"16 серпня 1832 року народжується Вільгельм Вундт. Його рішення було методологічним: він вимірював час реакції замість того, щоб розмірковувати про свідомість. Тим самим він визначив, що психологія відтепер визнаватиме як питання — а що повертатиме філософії.","fa":"در ۱۶ اوت ۱۸۳۲، ویلهلم وونت متولد می‌شود. تصمیم او روش‌شناختی بود: او به‌جای تأمل درباره آگاهی، زمان واکنش را اندازه‌گیری کرد. بدین‌ترتیب او تعیین کرد که روان‌شناسی از این پس چه چیزی را به‌عنوان پرسش می‌پذیرد — و چه چیزی را به فلسفه بازمی‌گرداند.","it":"Il 16 agosto 1832 nasce Wilhelm Wundt. La sua fu una scelta di metodo: misurava i tempi di reazione invece di riflettere sulla coscienza. In questo modo stabilì che cosa la psicologia avrebbe da allora ammesso come domanda legittima — e che cosa avrebbe restituito alla filosofia."},"C1":{"en":"The man born on August 16, 1832, gave a discipline its shape by restricting its subject matter. Whatever could not be measured fell outside the field. This is a price paid in every scientization — and it only becomes a problem once one forgets that it was paid.","ar":"أعطى المولود في 16 أغسطس 1832 شكلاً لتخصص علمي عن طريق تضييق موضوعه. كل ما لا يمكن قياسه سقط خارج نطاق التخصص. هذا ثمن يُدفع في كل عملية أَعْلَمة — ولا يصبح مشكلة إلا حين يُنسى أنه دُفع.","tr":"16 Ağustos 1832'de doğan kişi, konusunu daraltarak bir disipline şeklini verdi. Ölçülemeyen her şey alanın dışında kaldı. Bu bedel, her bilimselleşme sürecinde ödenir — ve sorun ancak ödendiği unutulduğunda ortaya çıkar.","ru":"Рождённый 16 августа 1832 года придал дисциплине форму, ограничив её предмет. То, что нельзя было измерить, выпадало из области науки. Эта цена платится при любой сциентизации — и становится проблемой лишь тогда, когда забывают, что она была уплачена.","es":"El nacido el 16 de agosto de 1832 dio forma a una disciplina restringiendo su objeto. Lo que no podía medirse quedaba fuera del campo. Este precio se paga en toda cientifización — y solo se convierte en un problema cuando se olvida que se ha pagado.","fr":"Celui qui naquit le 16 août 1832 donna sa forme à une discipline en en restreignant l'objet. Ce qui ne pouvait être mesuré tombait hors du champ. Ce prix se paie à chaque scientifisation — et il ne devient un problème que lorsqu'on oublie qu'il a été payé.","pl":"Urodzony 16 sierpnia 1832 roku nadał dyscyplinie kształt, ograniczając jej przedmiot. To, czego nie dało się zmierzyć, wypadało poza tę dziedzinę. Tę cenę płaci się przy każdej naukowej formalizacji — i staje się ona problemem dopiero wtedy, gdy się zapomina, że została zapłacona.","uk":"Народжений 16 серпня 1832 року надав дисципліні форми, обмеживши її предмет. Те, що не піддавалося вимірюванню, випадало з галузі. Цю ціну платять за будь-якої сцієнтизації — і вона стає проблемою лише тоді, коли забувають, що її було сплачено.","fa":"متولد ۱۶ اوت ۱۸۳۲ با محدود کردن موضوع یک رشته، به آن شکل داد. هرچه قابل اندازه‌گیری نبود، از حیطه این رشته کنار گذاشته می‌شد. این هزینه‌ای است که در هر علمی‌سازی پرداخت می‌شود — و تنها زمانی مشکل‌ساز می‌شود که فراموش شود این هزینه پرداخت شده است.","it":"Nato il 16 agosto 1832, diede forma a una disciplina limitandone l'oggetto. Ciò che non si poteva misurare usciva dal campo della materia. Questo prezzo si paga in ogni processo di scientificizzazione — e diventa un problema solo quando ci si dimentica di averlo pagato."},"C2":{"en":"In Wundt, born August 16, 1832, one can observe how disciplines emerge: not through new questions, but through new rules of admissibility for answers. Psychology bought its scientific recognition by renouncing its most difficult questions — and has periodically struggled ever since to reclaim them.","ar":"يمكن أن نلاحظ في حالة فونت، المولود في 16 أغسطس 1832، كيف تنشأ التخصصات العلمية: ليس عبر أسئلة جديدة، بل عبر قواعد جديدة لمقبولية الإجابات. اشترى علم النفس اعترافه العلمي بالتخلي عن أصعب أسئلته — ومنذ ذلك الحين يكافح دورياً لاستعادتها.","tr":"16 Ağustos 1832'de doğan Wundt üzerinden, disiplinlerin nasıl ortaya çıktığı gözlemlenebilir: yeni sorularla değil, cevaplar için yeni kabul edilebilirlik kurallarıyla. Psikoloji, bilimsel tanınırlığını en zor sorularından vazgeçerek satın aldı — ve o zamandan beri periyodik olarak onları geri almak için mücadele ediyor.","ru":"На примере Вундта, родившегося 16 августа 1832 года, можно наблюдать, как возникают научные дисциплины: не благодаря новым вопросам, а благодаря новым правилам допустимости ответов. Психология купила своё научное признание ценой отказа от своих труднейших вопросов — и с тех пор периодически борется за то, чтобы вернуть их себе.","es":"En Wundt, nacido el 16 de agosto de 1832, se puede observar cómo surgen las disciplinas: no mediante preguntas nuevas, sino mediante nuevas reglas de admisibilidad para las respuestas. La psicología compró su reconocimiento científico renunciando a sus preguntas más difíciles, y desde entonces lucha periódicamente por recuperarlas.","fr":"Chez Wundt, né le 16 août 1832, on observe comment naissent les disciplines : non par de nouvelles questions, mais par de nouvelles règles de recevabilité des réponses. La psychologie acheta sa reconnaissance scientifique en renonçant à ses questions les plus difficiles — et lutte depuis, périodiquement, pour les récupérer.","pl":"Na przykładzie Wundta, urodzonego 16 sierpnia 1832 roku, można obserwować, jak powstają dyscypliny naukowe: nie przez nowe pytania, lecz przez nowe reguły dopuszczalności odpowiedzi. Psychologia kupiła swoje naukowe uznanie, rezygnując ze swoich najtrudniejszych pytań — i od tamtej pory okresowo walczy o ich odzyskanie.","uk":"На прикладі Вундта, народженого 16 серпня 1832 року, можна спостерігати, як виникають наукові дисципліни: не через нові питання, а через нові правила допустимості відповідей. Психологія купила своє наукове визнання ціною відмови від найскладніших своїх питань — і відтоді періодично бореться за те, щоб повернути їх.","fa":"در مورد وونت، متولد ۱۶ اوت ۱۸۳۲، می‌توان دید که چگونه رشته‌های علمی شکل می‌گیرند: نه از طریق پرسش‌های تازه، بلکه از طریق قواعد تازه‌ای برای مقبولیت پاسخ‌ها. روان‌شناسی، شناخته‌شدن علمی خود را با چشم‌پوشی از دشوارترین پرسش‌هایش خریداری کرد — و از آن زمان به‌طور دوره‌ای برای بازپس‌گیری آن‌ها تلاش می‌کند.","it":"Nella figura di Wundt, nato il 16 agosto 1832, si osserva come nascono le discipline: non attraverso nuove domande, ma attraverso nuove regole di ammissibilità per le risposte. La psicologia acquistò il proprio riconoscimento scientifico rinunciando alle sue domande più difficili — e da allora lotta periodicamente per riconquistarle."}},"sideFacts":[]},"08-17":{"year":1956,"levels":{"A1":"Am 17. August 1956 verbietet ein Gericht eine Partei in Deutschland. Sie heißt KPD.","A2":"Am 17. August 1956 verbietet das Bundesverfassungsgericht die Kommunistische Partei Deutschlands (KPD). Das Gericht sagt, die Partei verstößt gegen die Verfassung.","B1":"Am 17. August 1956 erklärt das Bundesverfassungsgericht die Kommunistische Partei Deutschlands (KPD) für verfassungswidrig und verbietet sie. Es ist erst das zweite Parteiverbot in der Geschichte der Bundesrepublik.","B2":"Am 17. August 1956 verbietet das Bundesverfassungsgericht nach fast fünfjährigem Verfahren die KPD als verfassungswidrig — sie strebe die Abschaffung der freiheitlich-demokratischen Grundordnung an. Polizei durchsucht noch am selben Tag Parteibüros im ganzen Land.","C1":"Das KPD-Verbot vom 17. August 1956, nach fünfjährigem Verfahren vom Bundesverfassungsgericht verhängt, war erst das zweite Parteiverbot der Bundesrepublik nach der neonazistischen SRP 1952. Es zeigt die hohen rechtlichen Hürden, aber auch die Entschlossenheit des jungen Staates gegenüber Verfassungsfeinden von links wie rechts.","C2":"Das Urteil zum KPD-Verbot vom 17. August 1956 markiert bis heute einen der seltenen Fälle exekutierter wehrhafter Demokratie in der Bundesrepublik und bleibt historisch umstritten — Kritiker sehen darin eine im Kalten Krieg motivierte Kriminalisierung linker Opposition, während Befürworter es als notwendige Verteidigung der freiheitlich-demokratischen Grundordnung werten."},"translationsA1":{"en":"On August 17, 1956, a court bans a party in Germany. It is called the KPD.","ar":"في 17 أغسطس 1956، حظرت محكمة حزباً في ألمانيا. اسمه الحزب الشيوعي الألماني.","tr":"17 Ağustos 1956'da bir mahkeme Almanya'da bir partiyi yasakladı. Adı KPD.","ru":"17 августа 1956 года суд запретил партию в Германии. Она называется КПГ.","es":"El 17 de agosto de 1956, un tribunal prohíbe un partido en Alemania. Se llama KPD.","fr":"Le 17 août 1956, un tribunal interdit un parti en Allemagne. Il s'appelle le KPD.","pl":"17 sierpnia 1956 roku sąd zdelegalizował partię w Niemczech. Nazywała się KPD.","uk":"17 серпня 1956 року суд заборонив партію в Німеччині. Вона називалася КПН.","fa":"در ۱۷ اوت ۱۹۵۶، دادگاهی حزبی را در آلمان ممنوع کرد. نام آن حزب کمونیست آلمان بود.","it":"Il 17 agosto 1956 un tribunale mette al bando un partito in Germania. Si chiama KPD."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 17, 1956, the Federal Constitutional Court bans the Communist Party of Germany (KPD). The court says the party violates the constitution.","ar":"في 17 أغسطس 1956، تحظر المحكمة الدستورية الاتحادية الحزب الشيوعي الألماني (KPD). تقول المحكمة إن الحزب يخالف الدستور.","tr":"17 Ağustos 1956'da Federal Anayasa Mahkemesi Almanya Komünist Partisi'ni (KPD) yasaklar. Mahkeme, partinin anayasaya aykırı olduğunu söyler.","ru":"17 августа 1956 года Федеральный конституционный суд запрещает Коммунистическую партию Германии (КПГ). Суд заявляет, что партия нарушает конституцию.","es":"El 17 de agosto de 1956, el Tribunal Constitucional Federal prohíbe el Partido Comunista de Alemania (KPD). El tribunal dice que el partido viola la constitución.","fr":"Le 17 août 1956, la Cour constitutionnelle fédérale interdit le Parti communiste d'Allemagne (KPD). La Cour affirme que le parti viole la Constitution.","pl":"17 sierpnia 1956 roku Federalny Trybunał Konstytucyjny delegalizuje Komunistyczną Partię Niemiec (KPD). Trybunał stwierdza, że partia narusza konstytucję.","uk":"17 серпня 1956 року Федеральний конституційний суд забороняє Комуністичну партію Німеччини (КПН). Суд заявляє, що партія порушує конституцію.","fa":"در ۱۷ اوت ۱۹۵۶، دادگاه قانون اساسی فدرال حزب کمونیست آلمان (KPD) را ممنوع می‌کند. دادگاه می‌گوید این حزب قانون اساسی را نقض می‌کند.","it":"Il 17 agosto 1956 la Corte costituzionale federale mette al bando il Partito Comunista di Germania (KPD). La Corte dichiara che il partito viola la Costituzione."},"B1":{"en":"On August 17, 1956, the Federal Constitutional Court declares the Communist Party of Germany (KPD) unconstitutional and bans it. It is only the second party ban in the history of the Federal Republic.","ar":"في 17 أغسطس 1956، تُعلن المحكمة الدستورية الاتحادية أن الحزب الشيوعي الألماني (KPD) غير دستوري وتحظره. إنه ثاني حظر لحزب فقط في تاريخ جمهورية ألمانيا الاتحادية.","tr":"17 Ağustos 1956'da Federal Anayasa Mahkemesi, Almanya Komünist Partisi'ni (KPD) anayasaya aykırı ilan ederek yasaklar. Bu, Federal Almanya Cumhuriyeti tarihindeki ikinci parti yasağıdır.","ru":"17 августа 1956 года Федеральный конституционный суд объявляет Коммунистическую партию Германии (КПГ) неконституционной и запрещает её. Это лишь второй запрет партии в истории ФРГ.","es":"El 17 de agosto de 1956, el Tribunal Constitucional Federal declara inconstitucional al Partido Comunista de Alemania (KPD) y lo prohíbe. Es apenas la segunda prohibición de un partido en la historia de la República Federal.","fr":"Le 17 août 1956, la Cour constitutionnelle fédérale déclare le Parti communiste d'Allemagne (KPD) anticonstitutionnel et l'interdit. C'est seulement la deuxième interdiction de parti de l'histoire de la République fédérale.","pl":"17 sierpnia 1956 roku Federalny Trybunał Konstytucyjny uznaje Komunistyczną Partię Niemiec (KPD) za niezgodną z konstytucją i delegalizuje ją. To dopiero druga delegalizacja partii w historii Republiki Federalnej.","uk":"17 серпня 1956 року Федеральний конституційний суд визнає Комуністичну партію Німеччини (КПН) неконституційною і забороняє її. Це лише друга заборона партії в історії ФРН.","fa":"در ۱۷ اوت ۱۹۵۶، دادگاه قانون اساسی فدرال حزب کمونیست آلمان (KPD) را غیرقانونی اعلام کرده و آن را ممنوع می‌کند. این تنها دومین ممنوعیت حزبی در تاریخ جمهوری فدرال آلمان است.","it":"Il 17 agosto 1956 la Corte costituzionale federale dichiara incostituzionale il Partito Comunista di Germania (KPD) e lo mette al bando. È solo il secondo divieto di partito nella storia della Repubblica Federale."},"B2":{"en":"On August 17, 1956, after a trial lasting almost five years, the Federal Constitutional Court bans the KPD as unconstitutional — it was seeking to abolish the free democratic basic order. Police search party offices across the country that same day.","ar":"في 17 أغسطس 1956، وبعد محاكمة استمرت نحو خمس سنوات، تحظر المحكمة الدستورية الاتحادية الحزب الشيوعي الألماني (KPD) باعتباره مخالفاً للدستور — إذ كان يسعى إلى إلغاء النظام الديمقراطي الحر. وفي اليوم نفسه، تفتش الشرطة مكاتب الحزب في جميع أنحاء البلاد.","tr":"17 Ağustos 1956'da, yaklaşık beş yıl süren bir yargılamanın ardından, Federal Anayasa Mahkemesi KPD'yi anayasaya aykırı bularak yasaklar — parti, özgürlükçü demokratik temel düzeni ortadan kaldırmayı amaçlıyordu. Polis aynı gün ülke genelinde parti bürolarını arar.","ru":"17 августа 1956 года, после почти пятилетнего разбирательства, Федеральный конституционный суд запрещает КПГ как неконституционную — партия якобы стремилась к упразднению свободного демократического строя. В тот же день полиция обыскивает партийные офисы по всей стране.","es":"El 17 de agosto de 1956, tras un proceso de casi cinco años, el Tribunal Constitucional Federal prohíbe al KPD por inconstitucional: pretendía abolir el orden fundamental democrático liberal. Ese mismo día, la policía registra oficinas del partido en todo el país.","fr":"Le 17 août 1956, après une procédure de près de cinq ans, la Cour constitutionnelle fédérale interdit le KPD comme anticonstitutionnel — il aspirait, selon elle, à abolir l'ordre fondamental démocratique et libéral. La police perquisitionne le jour même les bureaux du parti dans tout le pays.","pl":"17 sierpnia 1956 roku, po niemal pięcioletnim postępowaniu, Federalny Trybunał Konstytucyjny delegalizuje KPD jako sprzeczną z konstytucją — partia dążyła rzekomo do zniesienia wolnościowo-demokratycznego porządku podstawowego. Jeszcze tego samego dnia policja przeszukuje biura partii w całym kraju.","uk":"17 серпня 1956 року, після майже п'ятирічного процесу, Федеральний конституційний суд забороняє КПН як неконституційну — вона нібито прагнула скасувати вільний демократичний лад. Того ж дня поліція проводить обшуки в партійних офісах по всій країні.","fa":"در ۱۷ اوت ۱۹۵۶، پس از دادرسی‌ای نزدیک به پنج سال، دادگاه قانون اساسی فدرال حزب کمونیست آلمان را غیرقانونی اعلام کرده و ممنوع می‌کند — این حزب در پی براندازی نظم اساسی دموکراتیک آزاد بود. پلیس همان روز دفاتر حزب را در سراسر کشور بازرسی می‌کند.","it":"Il 17 agosto 1956, al termine di un procedimento durato quasi cinque anni, la Corte costituzionale federale mette al bando il KPD in quanto incostituzionale, ritenendo che miri all'abolizione dell'ordinamento fondamentale liberal-democratico. Lo stesso giorno la polizia perquisisce le sedi del partito in tutto il paese."},"C1":{"en":"The KPD ban of August 17, 1956, imposed by the Federal Constitutional Court after a five-year proceeding, was only the second party ban in the Federal Republic, after the neo-Nazi SRP in 1952. It shows the high legal hurdles, but also the young state's determination against enemies of the constitution from both left and right.","ar":"كان حظر الحزب الشيوعي الألماني في 17 أغسطس 1956، الذي فرضته المحكمة الدستورية الاتحادية بعد محاكمة استمرت خمس سنوات، ثاني حظر حزب فقط في جمهورية ألمانيا الاتحادية بعد حزب الرايخ الاشتراكي النازي الجديد (SRP) عام 1952. وهو يُظهر العقبات القانونية العالية، لكنه يُظهر أيضاً عزم الدولة الفتية تجاه أعداء الدستور من اليسار واليمين على حد سواء.","tr":"17 Ağustos 1956'daki KPD yasağı, Federal Anayasa Mahkemesi tarafından beş yıllık bir yargılama sonrasında uygulanmış olup, 1952'deki neo-Nazi SRP'den sonra Federal Almanya'nın yalnızca ikinci parti yasağıydı. Bu, yüksek hukuki engelleri, ama aynı zamanda genç devletin hem soldan hem sağdan anayasa düşmanlarına karşı kararlılığını da gösterir.","ru":"Запрет КПГ от 17 августа 1956 года, наложенный Федеральным конституционным судом после пятилетнего разбирательства, был лишь вторым запретом партии в ФРГ после неонацистской СРП в 1952 году. Он показывает высокие правовые барьеры, но также решимость молодого государства противостоять врагам конституции как слева, так и справа.","es":"La prohibición del KPD del 17 de agosto de 1956, dictada por el Tribunal Constitucional Federal tras un proceso de cinco años, fue apenas la segunda prohibición de un partido en la República Federal, tras el neonazi SRP en 1952. Muestra los altos obstáculos legales, pero también la determinación del joven Estado frente a enemigos de la constitución tanto de izquierda como de derecha.","fr":"L'interdiction du KPD du 17 août 1956, prononcée par la Cour constitutionnelle fédérale après une procédure de cinq ans, ne fut que la deuxième interdiction de parti dans la République fédérale, après le SRP néonazi en 1952. Elle illustre les obstacles juridiques élevés, mais aussi la détermination du jeune État face aux ennemis de la Constitution, tant à gauche qu'à droite.","pl":"Delegalizacja KPD z 17 sierpnia 1956 roku, orzeczona przez Federalny Trybunał Konstytucyjny po pięcioletnim postępowaniu, była dopiero drugą delegalizacją partii w Republice Federalnej, po neonazistowskiej SRP w 1952 roku. Pokazuje ona wysokie bariery prawne, ale też determinację młodego państwa wobec wrogów konstytucji zarówno z lewicy, jak i z prawicy.","uk":"Заборона КПН від 17 серпня 1956 року, накладена Федеральним конституційним судом після п'ятирічного процесу, була лише другою забороною партії у ФРН після неонацистської СРП у 1952 році. Вона демонструє високі правові бар'єри, але й рішучість молодої держави протистояти ворогам конституції як зліва, так і справа.","fa":"ممنوعیت حزب کمونیست آلمان در ۱۷ اوت ۱۹۵۶، که پس از دادرسی پنج‌ساله توسط دادگاه قانون اساسی فدرال صادر شد، تنها دومین ممنوعیت حزبی در جمهوری فدرال آلمان پس از حزب نئونازی SRP در سال ۱۹۵۲ بود. این نشان‌دهنده موانع حقوقی بالا، اما همچنین عزم دولت جوان در برابر دشمنان قانون اساسی از چپ و راست است.","it":"Il divieto del KPD del 17 agosto 1956, pronunciato dalla Corte costituzionale federale dopo un procedimento durato cinque anni, fu solo il secondo divieto di partito della Repubblica Federale dopo quello del neonazista SRP nel 1952. Esso rivela sia gli alti ostacoli giuridici, sia la determinazione del giovane Stato nei confronti dei nemici della Costituzione, tanto di sinistra quanto di destra."},"C2":{"en":"The ruling on the KPD ban of August 17, 1956, remains to this day one of the rare cases of enforced militant democracy in the Federal Republic and remains historically contested — critics see it as a Cold War-motivated criminalization of leftist opposition, while proponents view it as a necessary defense of the free democratic basic order.","ar":"لا يزال حكم حظر الحزب الشيوعي الألماني الصادر في 17 أغسطس 1956 حتى اليوم واحداً من الحالات النادرة لتنفيذ 'الديمقراطية المتحصنة' في جمهورية ألمانيا الاتحادية، ولا يزال مثيراً للجدل تاريخياً — إذ يرى فيه المنتقدون تجريماً للمعارضة اليسارية بدافع الحرب الباردة، بينما يعتبره المؤيدون دفاعاً ضرورياً عن النظام الديمقراطي الحر.","tr":"17 Ağustos 1956 tarihli KPD yasağı kararı, bugüne kadar Federal Almanya'da uygulanan 'militan demokrasi'nin ender örneklerinden birini oluşturur ve tarihsel olarak tartışmalı olmaya devam eder — eleştirmenler bunu Soğuk Savaş motivasyonlu bir sol muhalefeti suçlulaştırma olarak görürken, savunucular bunu özgürlükçü demokratik temel düzenin gerekli bir savunması olarak değerlendirir.","ru":"Решение о запрете КПГ от 17 августа 1956 года до сих пор остаётся одним из редких случаев реализованной 'воинствующей демократии' в ФРГ и по сей день исторически спорно — критики видят в нём криминализацию левой оппозиции, мотивированную холодной войной, тогда как сторонники расценивают его как необходимую защиту свободного демократического строя.","es":"La sentencia sobre la prohibición del KPD del 17 de agosto de 1956 sigue siendo hasta hoy uno de los pocos casos de 'democracia militante' aplicada en la República Federal y permanece históricamente controvertida: los críticos ven en ella una criminalización de la oposición de izquierda motivada por la Guerra Fría, mientras que sus defensores la consideran una defensa necesaria del orden fundamental democrático liberal.","fr":"L'arrêt sur l'interdiction du KPD du 17 août 1956 reste à ce jour l'un des rares cas de « démocratie militante » mise en œuvre dans la République fédérale et demeure historiquement controversé — les critiques y voient une criminalisation de l'opposition de gauche motivée par la Guerre froide, tandis que ses défenseurs la considèrent comme une défense nécessaire de l'ordre fondamental démocratique et libéral.","pl":"Wyrok w sprawie delegalizacji KPD z 17 sierpnia 1956 roku do dziś stanowi jeden z rzadkich przypadków wyegzekwowanej 'demokracji zdolnej do obrony' w Republice Federalnej i pozostaje historycznie kontrowersyjny — krytycy widzą w nim motywowaną zimną wojną kryminalizację lewicowej opozycji, podczas gdy zwolennicy oceniają go jako niezbędną obronę wolnościowo-demokratycznego porządku podstawowego.","uk":"Рішення про заборону КПН від 17 серпня 1956 року й досі залишається одним із рідкісних випадків реалізованої 'войовничої демократії' у ФРН і залишається історично суперечливим — критики вбачають у ньому вмотивовану холодною війною криміналізацію лівої опозиції, тоді як прихильники розцінюють його як необхідний захист вільного демократичного ладу.","fa":"حکم مربوط به ممنوعیت حزب کمونیست آلمان در ۱۷ اوت ۱۹۵۶ تا به امروز یکی از موارد نادر اجرای 'دموکراسی مقاوم' در جمهوری فدرال آلمان محسوب می‌شود و از نظر تاریخی همچنان بحث‌برانگیز است — منتقدان آن را جرم‌انگاری اپوزیسیون چپ با انگیزه‌های جنگ سرد می‌دانند، در حالی که طرفداران آن را دفاعی ضروری از نظم اساسی دموکراتیک آزاد ارزیابی می‌کنند.","it":"La sentenza sul divieto del KPD del 17 agosto 1956 rappresenta ancora oggi uno dei rari casi di \"democrazia protetta\" effettivamente applicata nella Repubblica Federale e resta storicamente controversa: i critici vi scorgono una criminalizzazione dell'opposizione di sinistra motivata dalla Guerra Fredda, mentre i sostenitori la considerano una necessaria difesa dell'ordinamento fondamentale liberal-democratico."}}},"08-18":{"year":1896,"levels":{"A1":"Am 18. August 1896 bekommt Deutschland ein neues Gesetzbuch. Es regelt Kaufen, Mieten, Heiraten und Erben. Es gilt bis heute.","A2":"Am 18. August 1896 wird das Bürgerliche Gesetzbuch verkündet. Es regelt fast alles, was Menschen miteinander vereinbaren: Kauf, Miete, Ehe, Erbe. In Kraft trat es zum 1. Januar 1900.","B1":"Am 18. August 1896 wird das BGB verkündet, nach über zwanzig Jahren Arbeit. Zum ersten Mal galt im ganzen Reich dasselbe Zivilrecht. Es ist mit vielen Änderungen bis heute in Kraft — eines der langlebigsten Gesetzbücher der Welt.","B2":"Am 18. August 1896 wird das Bürgerliche Gesetzbuch verkündet. Seine Sprache ist bewusst abstrakt: Statt Einzelfälle aufzuzählen, formuliert es allgemeine Regeln. Genau diese Zurückhaltung erklärt, warum es über hundert Jahre und mehrere Staatsformen überdauert hat.","C1":"Das BGB vom 18. August 1896 zog die Lehre aus dem preußischen Landrecht: Wer jeden Fall regeln will, veraltet schnell. Generalklauseln wie Treu und Glauben ließen Raum für eine Rechtsprechung, die sich mit der Gesellschaft veränderte, ohne dass der Text geändert werden musste.","C2":"Am 18. August 1896 wurde ein Text in Kraft gesetzt, dessen Familienrecht heute unkenntlich ist und dessen Schuldrecht weitgehend steht. Der Unterschied liegt nicht in der Qualität der Paragraphen, sondern darin, wie stark sich die geregelten Verhältnisse verändert haben. Kodifikationen altern nicht gleichmäßig, sondern dort zuerst, wo Gesellschaft am beweglichsten ist."},"translationsA1":{"en":"On August 18, 1896, Germany gets a new legal code. It governs buying, renting, marrying and inheriting. It still applies today.","ar":"في 18 أغسطس 1896، حصلت ألمانيا على قانون جديد. ينظّم البيع والإيجار والزواج والميراث. وما زال ساريًا حتى اليوم.","tr":"18 Ağustos 1896'da Almanya yeni bir kanun kitabı aldı. Alım, kira, evlilik ve mirası düzenler. Bugün hâlâ geçerlidir.","ru":"18 августа 1896 года Германия получила новый свод законов. Он регулирует покупку, аренду, брак и наследование. Он действует и сегодня.","es":"El 18 de agosto de 1896, Alemania recibe un nuevo código. Regula la compra, el alquiler, el matrimonio y la herencia. Sigue vigente hoy.","fr":"Le 18 août 1896, l'Allemagne reçoit un nouveau code. Il régit l'achat, la location, le mariage et l'héritage. Il est encore en vigueur.","pl":"18 sierpnia 1896 roku Niemcy otrzymały nowy kodeks. Reguluje kupno, najem, małżeństwo i dziedziczenie. Obowiązuje do dziś.","uk":"18 серпня 1896 року Німеччина отримала новий кодекс. Він регулює купівлю, оренду, шлюб і спадкування. Він діє й сьогодні.","fa":"در ۱۸ اوت ۱۸۹۶، آلمان قانون‌نامه‌ای تازه یافت. خرید، اجاره، ازدواج و ارث را سامان می‌دهد. تا امروز معتبر است.","it":"Il 18 agosto 1896 la Germania si dota di un nuovo codice. Disciplina compravendite, affitti, matrimoni ed eredità. È ancora in vigore oggi."},"translationsByLevel":{"A2":{"en":"On August 18, 1896, the Civil Code (BGB) is promulgated. It regulates almost everything people agree upon with one another: purchase, rent, marriage, inheritance. It took effect on January 1, 1900.","ar":"في 18 أغسطس 1896 يُعلن القانون المدني الألماني. وهو ينظم كل ما يكاد يتفق عليه الناس فيما بينهم: البيع والإيجار والزواج والإرث. دخل حيز التنفيذ في 1 يناير 1900.","tr":"18 Ağustos 1896'da Medeni Kanun (BGB) ilan edilir. İnsanların birbirleriyle anlaştığı hemen her şeyi düzenler: alım-satım, kira, evlilik, miras. 1 Ocak 1900'de yürürlüğe girmiştir.","ru":"18 августа 1896 года провозглашается Гражданское уложение (BGB). Оно регулирует почти всё, о чём договариваются между собой люди: куплю-продажу, аренду, брак, наследство. В силу оно вступило 1 января 1900 года.","es":"El 18 de agosto de 1896 se promulga el Código Civil alemán (BGB). Regula casi todo lo que las personas acuerdan entre sí: compraventa, alquiler, matrimonio, herencia. Entró en vigor el 1 de enero de 1900.","fr":"Le 18 août 1896, le Code civil allemand (BGB) est promulgué. Il régit presque tout ce que les gens conviennent entre eux : achat, location, mariage, héritage. Il entra en vigueur le 1er janvier 1900.","pl":"18 sierpnia 1896 roku ogłoszono niemiecki kodeks cywilny (BGB). Reguluje on niemal wszystko, co ludzie ze sobą uzgadniają: kupno, najem, małżeństwo, spadek. Wszedł w życie 1 stycznia 1900 roku.","uk":"18 серпня 1896 року оприлюднено Цивільне уложення (BGB). Воно регулює майже все, про що домовляються люди між собою: купівлю, оренду, шлюб, спадщину. Набуло чинності 1 січня 1900 року.","fa":"در ۱۸ اوت ۱۸۹۶، قانون مدنی آلمان (BGB) اعلام می‌شود. این قانون تقریباً همه چیزی را که مردم با یکدیگر توافق می‌کنند تنظیم می‌کند: خرید، اجاره، ازدواج، ارث. این قانون از اول ژانویه ۱۹۰۰ لازم‌الاجرا شد.","it":"Il 18 agosto 1896 viene promulgato il Codice civile tedesco (Bürgerliches Gesetzbuch, BGB). Regola quasi tutto ciò che le persone stipulano tra loro: compravendita, locazione, matrimonio, eredità. Entrò in vigore il 1° gennaio 1900."},"B1":{"en":"On August 18, 1896, the BGB is promulgated after more than twenty years of work. For the first time, the same civil law applied throughout the empire. With many amendments, it remains in force to this day — one of the longest-lasting law codes in the world.","ar":"في 18 أغسطس 1896 يُعلن القانون المدني بعد أكثر من عشرين عاما من العمل. ولأول مرة سرى القانون المدني نفسه في جميع أنحاء الإمبراطورية. لا يزال ساري المفعول حتى اليوم بعد تعديلات كثيرة - وهو من أطول القوانين عمرا في العالم.","tr":"18 Ağustos 1896'da, yirmi yılı aşkın bir çalışmanın ardından BGB ilan edilir. İlk kez tüm imparatorlukta aynı medeni hukuk geçerli olur. Birçok değişiklikle bugün hâlâ yürürlüktedir - dünyanın en uzun ömürlü kanunlarından biridir.","ru":"18 августа 1896 года после более чем двадцатилетней работы провозглашается BGB. Впервые во всей империи стало действовать единое гражданское право. С многочисленными изменениями оно действует и сегодня - один из самых долговечных сводов законов в мире.","es":"El 18 de agosto de 1896 se promulga el BGB, tras más de veinte años de trabajo. Por primera vez rigió el mismo derecho civil en todo el Imperio. Con numerosas modificaciones, sigue vigente hoy en día, uno de los códigos legales más longevos del mundo.","fr":"Le 18 août 1896, le BGB est promulgué après plus de vingt ans de travail. Pour la première fois, le même droit civil s'appliquait dans tout l'Empire. Avec de nombreuses modifications, il reste en vigueur aujourd'hui - l'un des codes de lois les plus durables au monde.","pl":"18 sierpnia 1896 roku ogłoszono BGB po ponad dwudziestu latach pracy. Po raz pierwszy w całej Rzeszy obowiązywało to samo prawo cywilne. Z licznymi zmianami obowiązuje do dziś - to jeden z najdłużej obowiązujących kodeksów na świecie.","uk":"18 серпня 1896 року після понад двадцяти років роботи оприлюднено BGB. Уперше в усій імперії діяло єдине цивільне право. З численними змінами воно чинне й досі - один із найдовговічніших кодексів у світі.","fa":"در ۱۸ اوت ۱۸۹۶، پس از بیش از بیست سال کار، قانون مدنی اعلام می‌شود. برای نخستین بار حقوق مدنی یکسانی در سراسر امپراتوری اعمال شد. این قانون با تغییرات فراوان تا امروز پابرجاست — یکی از دیرپاترین قوانین جهان.","it":"Il 18 agosto 1896 viene promulgato il BGB, dopo oltre vent'anni di lavoro. Per la prima volta lo stesso diritto civile vale in tutto l'Impero. Con molte modifiche è in vigore ancora oggi — uno dei codici più longevi al mondo."},"B2":{"en":"On August 18, 1896, the Civil Code is promulgated. Its language is deliberately abstract: instead of listing individual cases, it formulates general rules. It is precisely this restraint that explains why it has outlasted more than a hundred years and several forms of government.","ar":"في 18 أغسطس 1896 يُعلن القانون المدني. لغته مجردة بشكل متعمد: فبدلا من سرد الحالات الفردية، يصوغ قواعد عامة. هذا التحفظ بالذات يفسر لماذا بقي أكثر من مئة عام ونجا من عدة أشكال للدولة.","tr":"18 Ağustos 1896'da Medeni Kanun ilan edilir. Dili bilinçli olarak soyuttur: Tek tek durumları saymak yerine genel kurallar formüle eder. Tam da bu ölçülülük, yüz yılı ve birden fazla devlet biçimini aşmasını açıklar.","ru":"18 августа 1896 года провозглашается Гражданское уложение. Его язык намеренно абстрактен: вместо перечисления отдельных случаев оно формулирует общие правила. Именно эта сдержанность объясняет, почему оно пережило более ста лет и несколько форм государственного устройства.","es":"El 18 de agosto de 1896 se promulga el Código Civil. Su lenguaje es deliberadamente abstracto: en lugar de enumerar casos concretos, formula reglas generales. Precisamente esa contención explica por qué ha perdurado más de cien años y varias formas de Estado.","fr":"Le 18 août 1896, le Code civil est promulgué. Son langage est délibérément abstrait : au lieu d'énumérer des cas particuliers, il formule des règles générales. C'est précisément cette retenue qui explique qu'il ait traversé plus de cent ans et plusieurs formes d'État.","pl":"18 sierpnia 1896 roku ogłoszono kodeks cywilny. Jego język jest świadomie abstrakcyjny: zamiast wyliczać poszczególne przypadki, formułuje ogólne zasady. To właśnie ta powściągliwość tłumaczy, dlaczego przetrwał ponad sto lat i kilka form ustroju państwowego.","uk":"18 серпня 1896 року оприлюднено Цивільне уложення. Його мова навмисно абстрактна: замість перелічувати окремі випадки, воно формулює загальні правила. Саме ця стриманість пояснює, чому воно пережило понад сто років і кілька форм державного устрою.","fa":"در ۱۸ اوت ۱۸۹۶، قانون مدنی اعلام می‌شود. زبان آن عمداً انتزاعی است: به‌جای برشمردن موارد جزئی، قواعد کلی تدوین می‌کند. دقیقاً همین خویشتنداری توضیح می‌دهد چرا بیش از صد سال و چندین شکل حکومتی را پشت سر گذاشته است.","it":"Il 18 agosto 1896 viene promulgato il Codice civile tedesco. Il suo linguaggio è deliberatamente astratto: invece di elencare casi singoli, formula regole generali. È proprio questa sobrietà a spiegare perché sia sopravvissuto a oltre cent'anni e a diverse forme di Stato."},"C1":{"en":"The BGB of August 18, 1896, drew a lesson from the Prussian General Law Code: whoever tries to regulate every single case grows outdated quickly. General clauses such as good faith left room for case law that could evolve with society without requiring the text itself to be changed.","ar":"استخلص القانون المدني الصادر في 18 أغسطس 1896 الدرس من القانون البروسي العام: من يريد تنظيم كل حالة يشيخ بسرعة. أتاحت البنود العامة مثل حسن النية مجالا لاجتهاد قضائي يتطور مع المجتمع دون الحاجة إلى تعديل النص.","tr":"18 Ağustos 1896 tarihli BGB, Prusya toprak hukukundan ders çıkardı: her durumu düzenlemek isteyen çabuk eskir. Dürüstlük kuralı gibi genel maddeler, metnin değiştirilmesine gerek kalmadan toplumla birlikte değişebilen bir içtihada yer açtı.","ru":"BGB от 18 августа 1896 года извлек урок из прусского земского права: тот, кто хочет урегулировать каждый случай, быстро устаревает. Общие клаузулы, такие как добросовестность, оставляли простор для судебной практики, способной меняться вместе с обществом без необходимости изменять сам текст.","es":"El BGB del 18 de agosto de 1896 extrajo la lección del derecho territorial prusiano: quien quiere regular cada caso envejece rápido. Cláusulas generales como la buena fe dejaron espacio para una jurisprudencia que evolucionaba con la sociedad sin necesidad de modificar el texto.","fr":"Le BGB du 18 août 1896 tira la leçon du droit territorial prussien : qui veut régler chaque cas devient vite obsolète. Des clauses générales comme la bonne foi laissaient place à une jurisprudence évoluant avec la société, sans qu'il faille modifier le texte.","pl":"BGB z 18 sierpnia 1896 roku wyciągnął naukę z pruskiego prawa krajowego: kto chce uregulować każdy przypadek, szybko się dezaktualizuje. Klauzule generalne, takie jak dobra wiara, pozostawiały miejsce na orzecznictwo zmieniające się wraz ze społeczeństwem, bez konieczności zmiany samego tekstu.","uk":"BGB від 18 серпня 1896 року винесло урок із прусського земського права: хто хоче врегулювати кожен випадок, швидко застаріває. Загальні клаузули, як-от добросовісність, залишали простір для судової практики, що змінювалася разом із суспільством без потреби змінювати сам текст.","fa":"قانون مدنی مصوب ۱۸ اوت ۱۸۹۶ درسی از حقوق ایالتی پروس گرفت: هرکس بخواهد هر مورد را تنظیم کند، به‌سرعت کهنه می‌شود. بندهای کلی مانند حسن نیت فضایی برای رویه قضایی باز گذاشتند که می‌توانست همراه با جامعه تغییر کند، بدون آن‌که متن قانون نیاز به تغییر داشته باشد.","it":"Il BGB del 18 agosto 1896 trasse insegnamento dal diritto territoriale prussiano (Landrecht): chi vuole disciplinare ogni singolo caso invecchia in fretta. Clausole generali come la buona fede lasciarono spazio a una giurisprudenza capace di evolversi insieme alla società, senza che il testo dovesse essere modificato."},"C2":{"en":"On August 18, 1896, a text was put into force whose family law is unrecognizable today, while its law of obligations largely still stands. The difference lies not in the quality of its provisions, but in how much the regulated relationships themselves have changed. Codifications do not age evenly — they age first wherever society is most mobile.","ar":"في 18 أغسطس 1896 دخل حيز التنفيذ نص أصبح قانون الأسرة فيه اليوم غير قابل للتعرف عليه، بينما لا يزال قانون الالتزامات فيه قائما إلى حد كبير. لا يكمن الفرق في جودة المواد، بل في مدى تغير العلاقات التي تنظمها. فالتقنينات لا تشيخ بالتساوي، بل تشيخ أولا حيث يكون المجتمع أكثر حركية.","tr":"18 Ağustos 1896'da, aile hukuku bugün artık tanınmaz hâle gelmiş, borçlar hukuku ise büyük ölçüde geçerliliğini korumuş bir metin yürürlüğe girdi. Fark, maddelerin kalitesinde değil, düzenlenen ilişkilerin ne kadar değiştiğinde yatıyor. Kodifikasyonlar eşit biçimde yaşlanmaz - önce toplumun en hareketli olduğu yerlerde yaşlanır.","ru":"18 августа 1896 года вступил в силу текст, семейное право которого сегодня неузнаваемо, а обязательственное право во многом сохраняется. Различие заключается не в качестве параграфов, а в том, насколько сильно изменились регулируемые ими отношения. Кодификации стареют неравномерно - в первую очередь там, где общество наиболее подвижно.","es":"El 18 de agosto de 1896 entró en vigor un texto cuyo derecho de familia es hoy irreconocible, mientras que su derecho de obligaciones sigue vigente en gran medida. La diferencia no radica en la calidad de los artículos, sino en cuánto han cambiado las relaciones reguladas. Las codificaciones no envejecen de manera uniforme, sino primero allí donde la sociedad es más móvil.","fr":"Le 18 août 1896 entra en vigueur un texte dont le droit de la famille est aujourd'hui méconnaissable, tandis que son droit des obligations tient largement encore. La différence ne réside pas dans la qualité des articles, mais dans l'ampleur du changement des rapports qu'ils régissaient. Les codifications ne vieillissent pas uniformément, mais d'abord là où la société est la plus mobile.","pl":"18 sierpnia 1896 roku wszedł w życie tekst, którego prawo rodzinne jest dziś nie do poznania, podczas gdy prawo zobowiązań w dużej mierze się ostało. Różnica nie leży w jakości przepisów, lecz w tym, jak bardzo zmieniły się regulowane stosunki. Kodyfikacje nie starzeją się równomiernie, lecz najpierw tam, gdzie społeczeństwo jest najbardziej ruchliwe.","uk":"18 серпня 1896 року набув чинності текст, сімейне право якого сьогодні невпізнанне, тоді як зобов'язальне право значною мірою залишається чинним. Різниця полягає не в якості статей, а в тому, наскільки сильно змінилися врегульовані відносини. Кодифікації старіють нерівномірно - передусім там, де суспільство найрухливіше.","fa":"در ۱۸ اوت ۱۸۹۶ متنی لازم‌الاجرا شد که حقوق خانواده آن امروز ناشناختنی است، در حالی که حقوق تعهدات آن تا حد زیادی برقرار مانده. تفاوت نه در کیفیت مواد قانونی، بلکه در میزان تغییر روابط تنظیم‌شده نهفته است. تدوین‌های قانونی به‌طور یکنواخت کهنه نمی‌شوند، بلکه نخست در جایی کهنه می‌شوند که جامعه متحرک‌ترین است.","it":"Il 18 agosto 1896 entrò in vigore un testo il cui diritto di famiglia è oggi irriconoscibile e il cui diritto delle obbligazioni resta in gran parte intatto. La differenza non sta nella qualità degli articoli, ma in quanto siano cambiati i rapporti da essi disciplinati. Le codificazioni non invecchiano in modo uniforme, ma invecchiano prima proprio dove la società è più mobile."}},"sideFacts":[]},"08-19":{"year":1989,"levels":{"A1":"Am 19. August 1989 wird an der Grenze zwischen Ungarn und Österreich ein Tor geöffnet. Hunderte Menschen aus der DDR laufen hindurch. Sie sind frei.","A2":"Am 19. August 1989 öffnet sich bei einem Fest an der ungarisch-österreichischen Grenze für kurze Zeit ein Tor. Hunderte DDR-Bürger nutzten den Moment und liefen in den Westen. Es war die größte Flucht seit dem Mauerbau.","B1":"Am 19. August 1989 findet an der Grenze zwischen Ungarn und Österreich ein Friedensfest statt, bei dem ein Grenztor symbolisch geöffnet werden soll. Hunderte DDR-Bürger, die davon gehört hatten, liefen hindurch. Die ungarischen Grenzer schossen nicht.","B2":"Am 19. August 1989 nutzen mehr als sechshundert DDR-Bürger ein kurzzeitig geöffnetes Grenztor. Entscheidend war eine Nichthandlung: Die ungarischen Grenzsoldaten griffen nicht ein. Damit war öffentlich sichtbar, dass die Ostblockstaaten ihre Grenzen nicht mehr geschlossen halten wollten.","C1":"Der 19. August 1989 gehört zu den Ereignissen, deren Bedeutung im Unterlassen liegt. Kein Befehl wurde gegeben, keine Erklärung abgegeben — und genau daraus zogen Zehntausende den Schluss, dass der Zeitpunkt gekommen war. Autorität endet nicht mit ihrem Sturz, sondern damit, dass sie ihre Regeln nicht mehr durchsetzt.","C2":"Am 19. August 1989 wurde sichtbar, wie Machtverhältnisse tatsächlich kippen: nicht durch eine Entscheidung, sondern durch eine Ansteckung von Erwartungen. Solange jeder glaubt, dass geschossen wird, bleibt die Grenze dicht; sobald ein einziges Beispiel das Gegenteil zeigt, ändert sich das Kalkül aller. Genau diese Nichtlinearität macht das Ende von Diktaturen so schwer vorhersagbar."},"translationsA1":{"en":"On August 19, 1989, a gate is opened on the border between Hungary and Austria. Hundreds of people from the GDR run through. They are free.","ar":"في 19 أغسطس 1989، فُتحت بوابة على الحدود بين المجر والنمسا. عبر منها مئات من مواطني ألمانيا الشرقية. صاروا أحرارًا.","tr":"19 Ağustos 1989'da Macaristan ile Avusturya sınırında bir kapı açıldı. Doğu Almanya'dan yüzlerce kişi oradan geçti. Özgür oldular.","ru":"19 августа 1989 года на границе Венгрии и Австрии открыли ворота. Сотни людей из ГДР прошли через них. Они свободны.","es":"El 19 de agosto de 1989 se abre una puerta en la frontera entre Hungría y Austria. Cientos de personas de la RDA pasan corriendo. Son libres.","fr":"Le 19 août 1989, une porte est ouverte à la frontière entre la Hongrie et l'Autriche. Des centaines de gens de la RDA la franchissent. Ils sont libres.","pl":"19 sierpnia 1989 roku na granicy Węgier i Austrii otwarto bramę. Setki ludzi z NRD przebiegły przez nią. Są wolni.","uk":"19 серпня 1989 року на кордоні Угорщини та Австрії відкрили ворота. Сотні людей із НДР пробігли крізь них. Вони вільні.","fa":"در ۱۹ اوت ۱۹۸۹، دروازه‌ای در مرز مجارستان و اتریش گشوده شد. صدها نفر از آلمان شرقی از آن گذشتند. آنان آزاد شدند.","it":"Il 19 agosto 1989 viene aperto un cancello al confine tra Ungheria e Austria. Centinaia di persone della DDR lo attraversano di corsa. Sono libere."},"translationsByLevel":{"A2":{"en":"On August 19, 1989, a gate at the Hungarian-Austrian border briefly opens during a festival. Hundreds of East German citizens seized the moment and ran to the West. It was the largest escape since the Wall was built.","ar":"في 19 أغسطس 1989 يُفتح بوابة عند الحدود المجرية النمساوية لفترة قصيرة خلال احتفال. اغتنم مئات من مواطني ألمانيا الشرقية اللحظة وهربوا إلى الغرب. كانت أكبر عملية هروب منذ بناء الجدار.","tr":"19 Ağustos 1989'da Macaristan-Avusturya sınırında bir festival sırasında kısa süreliğine bir kapı açılır. Yüzlerce Doğu Almanya vatandaşı bu anı değerlendirerek Batı'ya koştu. Bu, Duvar'ın inşasından bu yana en büyük kaçıştı.","ru":"19 августа 1989 года на венгерско-австрийской границе во время праздника ненадолго открываются ворота. Сотни граждан ГДР воспользовались моментом и перебежали на Запад. Это было крупнейшее бегство со времени возведения стены.","es":"El 19 de agosto de 1989 se abre brevemente una puerta en la frontera húngaro-austriaca durante una fiesta. Cientos de ciudadanos de la RDA aprovecharon el momento y corrieron hacia el Oeste. Fue la mayor fuga desde la construcción del Muro.","fr":"Le 19 août 1989, une porte s'ouvre brièvement à la frontière hungaro-autrichienne lors d'une fête. Des centaines de citoyens est-allemands saisirent l'occasion et coururent vers l'Ouest. Ce fut la plus grande évasion depuis la construction du Mur.","pl":"19 sierpnia 1989 roku na granicy węgiersko-austriackiej podczas festynu na krótko otwiera się brama. Setki obywateli NRD wykorzystały tę chwilę i przebiegły na Zachód. Była to największa ucieczka od czasu budowy muru.","uk":"19 серпня 1989 року на угорсько-австрійському кордоні під час свята на короткий час відкривається брама. Сотні громадян НДР скористалися моментом і побігли на Захід. Це була найбільша втеча від часу спорудження муру.","fa":"در ۱۹ اوت ۱۹۸۹، در جشنی در مرز مجارستان و اتریش، دروازه‌ای برای مدت کوتاهی باز می‌شود. صدها شهروند آلمان شرقی از این لحظه استفاده کرده و به سمت غرب دویدند. این بزرگ‌ترین فرار از زمان ساخت دیوار بود.","it":"Il 19 agosto 1989, durante una festa al confine tra Ungheria e Austria, un cancello si apre per pochi minuti. Centinaia di cittadini della DDR colgono l'occasione e corrono verso l'Ovest. Fu la fuga di massa più grande dalla costruzione del Muro."},"B1":{"en":"On August 19, 1989, a peace picnic is held at the border between Hungary and Austria, at which a border gate is meant to be opened symbolically. Hundreds of East German citizens who had heard about it ran through it. The Hungarian border guards did not shoot.","ar":"في 19 أغسطس 1989 يُقام حفل سلام عند الحدود بين المجر والنمسا، ومن المقرر فتح بوابة حدودية بشكل رمزي فيه. عبر مئات من مواطني ألمانيا الشرقية الذين سمعوا بذلك من خلالها. لم يطلق الحرس الحدودي المجري النار.","tr":"19 Ağustos 1989'da Macaristan ile Avusturya sınırında, sembolik olarak bir sınır kapısının açılması planlanan bir barış şöleni düzenlenir. Bunu duyan yüzlerce Doğu Almanya vatandaşı kapıdan koşarak geçti. Macar sınır muhafızları ateş açmadı.","ru":"19 августа 1989 года на границе между Венгрией и Австрией проходит праздник мира, в рамках которого символически должны были открыть пограничные ворота. Сотни граждан ГДР, узнавших об этом, пробежали через них. Венгерские пограничники не стреляли.","es":"El 19 de agosto de 1989 se celebra un picnic por la paz en la frontera entre Hungría y Austria, en el que se planea abrir simbólicamente una puerta fronteriza. Cientos de ciudadanos de la RDA que se habían enterado corrieron a través de ella. Los guardias fronterizos húngaros no dispararon.","fr":"Le 19 août 1989, un pique-nique de la paix se tient à la frontière entre la Hongrie et l'Autriche, au cours duquel une porte frontalière doit être ouverte symboliquement. Des centaines de citoyens est-allemands, qui en avaient entendu parler, la franchirent en courant. Les gardes-frontières hongrois ne tirèrent pas.","pl":"19 sierpnia 1989 roku na granicy węgiersko-austriackiej odbywa się piknik pokoju, podczas którego symbolicznie ma zostać otwarta brama graniczna. Setki obywateli NRD, którzy o tym usłyszeli, przebiegły przez nią. Węgierscy pogranicznicy nie strzelali.","uk":"19 серпня 1989 року на кордоні між Угорщиною та Австрією відбувається пікнік миру, під час якого символічно мала відкритися прикордонна брама. Сотні громадян НДР, які про це почули, пробігли крізь неї. Угорські прикордонники не стріляли.","fa":"در ۱۹ اوت ۱۹۸۹، در مرز میان مجارستان و اتریش یک پیک‌نیک صلح برگزار می‌شود که قرار است طی آن دروازه مرزی به‌طور نمادین باز شود. صدها شهروند آلمان شرقی که از این موضوع باخبر شده بودند، از آن عبور کردند. مرزبانان مجارستانی تیراندازی نکردند.","it":"Il 19 agosto 1989 si tiene, al confine tra Ungheria e Austria, una festa della pace nel corso della quale un cancello di frontiera doveva essere aperto simbolicamente. Centinaia di cittadini della DDR, che ne erano venuti a conoscenza, lo attraversarono di corsa. Le guardie di frontiera ungheresi non spararono."},"B2":{"en":"On August 19, 1989, more than six hundred East German citizens use a briefly opened border gate. What proved decisive was a non-action: the Hungarian border guards did not intervene. This made it publicly visible that the Eastern Bloc states no longer wanted to keep their borders closed.","ar":"في 19 أغسطس 1989 يستغل أكثر من ستمئة مواطن من ألمانيا الشرقية بوابة حدودية فُتحت لفترة قصيرة. كان الحاسم هو عدم التدخل: لم يتدخل حرس الحدود المجري. وبذلك أصبح واضحا للعلن أن دول الكتلة الشرقية لم تعد تريد إبقاء حدودها مغلقة.","tr":"19 Ağustos 1989'da altı yüzden fazla Doğu Almanya vatandaşı kısa süreliğine açılan bir sınır kapısını kullanır. Belirleyici olan bir eylemsizlikti: Macar sınır askerleri müdahale etmedi. Böylece Doğu Bloku ülkelerinin sınırlarını artık kapalı tutmak istemedikleri kamuoyunca görünür hâle geldi.","ru":"19 августа 1989 года более шестисот граждан ГДР воспользовались ненадолго открытыми пограничными воротами. Решающим стало бездействие: венгерские пограничники не вмешались. Тем самым публично стало видно, что страны восточного блока больше не хотят держать свои границы закрытыми.","es":"El 19 de agosto de 1989, más de seiscientos ciudadanos de la RDA aprovechan una puerta fronteriza abierta brevemente. Lo decisivo fue una no acción: los guardias fronterizos húngaros no intervinieron. Con ello quedó públicamente visible que los estados del bloque del Este ya no querían mantener cerradas sus fronteras.","fr":"Le 19 août 1989, plus de six cents citoyens est-allemands profitent d'une porte frontalière brièvement ouverte. Ce qui fut déterminant, c'est une non-action : les gardes-frontières hongrois n'intervinrent pas. Il devint ainsi publiquement visible que les États du bloc de l'Est ne voulaient plus garder leurs frontières fermées.","pl":"19 sierpnia 1989 roku ponad sześciuset obywateli NRD wykorzystuje krótko otwartą bramę graniczną. Decydujący był brak działania: węgierscy żołnierze graniczni nie interweniowali. Dzięki temu publicznie stało się widoczne, że państwa bloku wschodniego nie chcą już utrzymywać zamkniętych granic.","uk":"19 серпня 1989 року понад шістсот громадян НДР скористалися короткочасно відкритою прикордонною брамою. Вирішальною виявилася бездіяльність: угорські прикордонники не втрутилися. Тим самим стало публічно видно, що держави східного блоку більше не хочуть тримати свої кордони закритими.","fa":"در ۱۹ اوت ۱۹۸۹، بیش از ششصد شهروند آلمان شرقی از دروازه مرزی که برای مدت کوتاهی باز شده بود استفاده کردند. آنچه تعیین‌کننده بود، عدم اقدام بود: مرزبانان مجارستانی دخالت نکردند. بدین‌ترتیب برای همگان آشکار شد که کشورهای بلوک شرق دیگر نمی‌خواهند مرزهای خود را بسته نگه دارند.","it":"Il 19 agosto 1989 più di seicento cittadini della DDR approfittano di un cancello di frontiera aperto solo per breve tempo. Decisiva fu una non-azione: le guardie di frontiera ungheresi non intervennero. Divenne così pubblicamente visibile che gli Stati del blocco orientale non volevano più tenere i propri confini chiusi."},"C1":{"en":"August 19, 1989, belongs to those events whose significance lies in omission. No order was given, no statement made — and it was precisely from this that tens of thousands concluded that the moment had come. Authority does not end with its overthrow, but with its failure to enforce its own rules any longer.","ar":"ينتمي يوم 19 أغسطس 1989 إلى الأحداث التي تكمن أهميتها في الامتناع عن الفعل. لم يُصدر أمر، ولم يُعلن بيان - ومن هذا بالتحديد استنتج عشرات الآلاف أن اللحظة قد حانت. لا تنتهي السلطة بسقوطها، بل بعجزها عن فرض قواعدها بعد الآن.","tr":"19 Ağustos 1989, öneminin eylemsizlikte yattığı olaylardan biridir. Ne bir emir verildi ne de bir açıklama yapıldı - ve tam da bundan on binlerce kişi anın geldiği sonucunu çıkardı. Otorite, devrilmesiyle değil, kendi kurallarını artık uygulayamamasıyla sona erer.","ru":"19 августа 1989 года относится к тем событиям, значение которых заключается в бездействии. Не был отдан ни один приказ, не сделано ни одно заявление - и именно из этого десятки тысяч сделали вывод, что момент настал. Власть заканчивается не с её свержением, а с того момента, когда она перестает обеспечивать соблюдение собственных правил.","es":"El 19 de agosto de 1989 pertenece a los acontecimientos cuyo significado reside en la omisión. No se dio ninguna orden, no se hizo ninguna declaración, y precisamente de ello decenas de miles concluyeron que había llegado el momento. La autoridad no termina con su derrocamiento, sino cuando deja de imponer sus propias reglas.","fr":"Le 19 août 1989 fait partie de ces événements dont la portée réside dans l'omission. Aucun ordre ne fut donné, aucune déclaration faite — et c'est précisément de cela que des dizaines de milliers de personnes conclurent que le moment était venu. L'autorité ne prend pas fin avec sa chute, mais lorsqu'elle cesse de faire respecter ses propres règles.","pl":"19 sierpnia 1989 roku należy do wydarzeń, których znaczenie tkwi w zaniechaniu. Nie wydano żadnego rozkazu, nie złożono żadnego oświadczenia - i właśnie z tego dziesiątki tysięcy ludzi wywnioskowały, że nadszedł ten moment. Władza kończy się nie wraz z jej obaleniem, lecz wtedy, gdy przestaje egzekwować własne zasady.","uk":"19 серпня 1989 року належить до подій, значення яких полягає в бездіяльності. Не було віддано жодного наказу, не зроблено жодної заяви - і саме з цього десятки тисяч зробили висновок, що момент настав. Влада закінчується не з її поваленням, а тоді, коли вона перестає забезпечувати виконання власних правил.","fa":"۱۹ اوت ۱۹۸۹ در زمره رویدادهایی است که اهمیت آن‌ها در ترک فعل نهفته است. هیچ فرمانی صادر نشد، هیچ بیانیه‌ای اعلام نشد — و دقیقاً از همین امر بود که ده‌ها هزار نفر نتیجه گرفتند زمان فرارسیده است. اقتدار نه با سرنگونی، بلکه زمانی پایان می‌یابد که دیگر نتواند قواعد خود را اجرا کند.","it":"Il 19 agosto 1989 appartiene a quegli eventi il cui significato risiede in ciò che non viene fatto. Non fu impartito alcun ordine, non fu rilasciata alcuna dichiarazione — e proprio da questo silenzio decine di migliaia di persone trassero la conclusione che il momento fosse arrivato. Un'autorità non finisce quando viene rovesciata, ma quando smette di far rispettare le proprie regole."},"C2":{"en":"On August 19, 1989, it became visible how power relations actually tip over: not through a decision, but through a contagion of expectations. As long as everyone believes that shots will be fired, the border stays sealed; as soon as a single example shows the opposite, everyone's calculus changes. It is precisely this non-linearity that makes the end of dictatorships so hard to predict.","ar":"في 19 أغسطس 1989 اتضح كيف تنقلب موازين القوى فعليا: ليس عبر قرار، بل عبر عدوى في التوقعات. فطالما يعتقد الجميع أنه سيُطلق النار، تبقى الحدود مغلقة؛ وما إن يُظهر مثال واحد عكس ذلك، حتى يتغير حساب الجميع. هذا اللاخطية بالتحديد هو ما يجعل نهاية الديكتاتوريات صعبة التنبؤ.","tr":"19 Ağustos 1989'da güç ilişkilerinin gerçekte nasıl tersine döndüğü görünür hâle geldi: bir kararla değil, beklentilerin bulaşmasıyla. Herkes ateş edileceğine inandığı sürece sınır kapalı kalır; tek bir örnek tersini gösterir göstermez herkesin hesabı değişir. Diktatörlüklerin sonunu bu kadar öngörülemez kılan tam da bu doğrusal olmayan yapıdır.","ru":"19 августа 1989 года стало видно, как на самом деле переворачиваются отношения власти: не через решение, а через заражение ожиданиями. Пока все верят, что будут стрелять, граница остается закрытой; но как только один-единственный пример показывает обратное, расчёт меняется у всех. Именно эта нелинейность делает конец диктатур столь трудно предсказуемым.","es":"El 19 de agosto de 1989 se hizo visible cómo se invierten realmente las relaciones de poder: no mediante una decisión, sino mediante un contagio de expectativas. Mientras todos crean que se va a disparar, la frontera permanece cerrada; en cuanto un solo ejemplo muestra lo contrario, cambia el cálculo de todos. Es precisamente esta no linealidad lo que hace tan difícil de predecir el final de las dictaduras.","fr":"Le 19 août 1989 rendit visible la manière dont les rapports de pouvoir basculent réellement : non par une décision, mais par une contagion des attentes. Tant que chacun croit que l'on tirera, la frontière reste fermée ; dès qu'un seul exemple montre le contraire, le calcul de tous change. C'est précisément cette non-linéarité qui rend la fin des dictatures si difficile à prévoir.","pl":"19 sierpnia 1989 roku stało się widoczne, jak naprawdę odwracają się stosunki władzy: nie przez decyzję, lecz przez zarażanie się oczekiwaniami. Dopóki wszyscy wierzą, że będzie się strzelać, granica pozostaje szczelna; gdy tylko jeden przykład pokaże coś przeciwnego, kalkulacja wszystkich się zmienia. To właśnie ta nieliniowość sprawia, że koniec dyktatur jest tak trudny do przewidzenia.","uk":"19 серпня 1989 року стало видно, як насправді перекидаються відносини влади: не через рішення, а через зараження очікуваннями. Поки всі вірять, що стрілятимуть, кордон залишається закритим; щойно один-єдиний приклад показує протилежне, розрахунок усіх змінюється. Саме ця нелінійність робить кінець диктатур таким важким для прогнозування.","fa":"در ۱۹ اوت ۱۹۸۹ آشکار شد که روابط قدرت در واقع چگونه واژگون می‌شود: نه از طریق یک تصمیم، بلکه از طریق سرایت انتظارات. تا زمانی که همه باور دارند تیراندازی خواهد شد، مرز بسته می‌ماند؛ به‌محض این‌که یک نمونه واحد خلاف آن را نشان دهد، محاسبات همه تغییر می‌کند. دقیقاً همین غیرخطی بودن است که پایان دیکتاتوری‌ها را این‌قدر غیرقابل پیش‌بینی می‌کند.","it":"Il 19 agosto 1989 si rese visibile come i rapporti di potere si ribaltino realmente: non per effetto di una decisione, ma di un contagio di aspettative. Finché tutti credono che si spari, il confine resta chiuso; non appena un solo esempio dimostra il contrario, cambia il calcolo di tutti. È proprio questa non linearità a rendere la fine delle dittature così difficile da prevedere."}},"sideFacts":[]},"08-20":{"year":1915,"levels":{"A1":"Am 20. August 1915 stirbt Paul Ehrlich. Er ist Arzt und Forscher. Er sucht Medikamente, die nur die Krankheit treffen.","A2":"Am 20. August 1915 stirbt Paul Ehrlich. Er suchte nach Stoffen, die im Körper genau den Erreger angreifen und sonst nichts. Er nannte das die Zauberkugel.","B1":"Am 20. August 1915 stirbt Paul Ehrlich. Seine Idee war einfach und neu: ein Medikament, das im Körper zielgenau nur den Erreger trifft. 1909 fand sein Team nach über sechshundert Versuchen einen solchen Wirkstoff.","B2":"Am 20. August 1915 stirbt Paul Ehrlich. Er begründete die Chemotherapie im ursprünglichen Sinn: Krankheiten mit gezielt hergestellten Molekülen behandeln statt mit Naturstoffen. Sein Vorgehen — systematisch Hunderte Varianten prüfen — ist bis heute das Grundmuster der Wirkstoffsuche.","C1":"Der am 20. August 1915 Gestorbene verband eine Vorstellung mit einer Methode. Die Zauberkugel war ein Bild, die Prüfreihe war die Arbeit. Beide zusammen machten aus der Suche nach Heilmitteln ein planbares Verfahren statt eines Glücksfalls.","C2":"An Ehrlich, gestorben am 20. August 1915, lässt sich die Ambivalenz der Zielgenauigkeit betrachten. Sein Wirkstoff gegen die Syphilis war der erste seiner Art und zugleich giftig genug, um Debatten auszulösen, die heute jede Zulassung begleiten: Welches Risiko ist einem Kranken zumutbar, wenn die Alternative das Ausbleiben jeder Behandlung ist?"},"translationsA1":{"en":"On August 20, 1915, Paul Ehrlich dies. He is a doctor and researcher. He looks for medicines that hit only the disease.","ar":"في 20 أغسطس 1915، توفي باول إرليش. كان طبيبًا وباحثًا. بحث عن أدوية تصيب المرض وحده.","tr":"20 Ağustos 1915'te Paul Ehrlich öldü. O hekim ve araştırmacıydı. Yalnızca hastalığı vuran ilaçlar aradı.","ru":"20 августа 1915 года умер Пауль Эрлих. Он был врачом и исследователем. Он искал лекарства, которые поражают только болезнь.","es":"El 20 de agosto de 1915 muere Paul Ehrlich. Es médico e investigador. Busca medicamentos que solo alcancen a la enfermedad.","fr":"Le 20 août 1915, Paul Ehrlich meurt. C'est un médecin et chercheur. Il cherche des médicaments qui n'atteignent que la maladie.","pl":"20 sierpnia 1915 roku zmarł Paul Ehrlich. Był lekarzem i badaczem. Szukał leków, które trafiają tylko chorobę.","uk":"20 серпня 1915 року помер Пауль Ерліх. Він був лікарем і дослідником. Він шукав ліки, що вражають лише хворобу.","fa":"در ۲۰ اوت ۱۹۱۵، پاول ارلیش درگذشت. او پزشک و پژوهشگر بود. او به دنبال دارویی بود که تنها بیماری را هدف بگیرد.","it":"Il 20 agosto 1915 muore Paul Ehrlich. È medico e ricercatore. Cerca farmaci che colpiscano solo la malattia."},"translationsByLevel":{"A2":{"en":"On August 20, 1915, Paul Ehrlich dies. He searched for substances that would attack exactly the pathogen in the body and nothing else. He called this the magic bullet.","ar":"في 20 أغسطس 1915 يموت بول إيرليش. كان يبحث عن مواد تهاجم في الجسم مسبب المرض بالتحديد ولا شيء غيره. أطلق على ذلك اسم الرصاصة السحرية.","tr":"20 Ağustos 1915'te Paul Ehrlich ölür. Vücutta yalnızca hastalık etkenine saldıran ve başka hiçbir şeye zarar vermeyen maddeler arıyordu. Buna sihirli mermi adını verdi.","ru":"20 августа 1915 года умирает Пауль Эрлих. Он искал вещества, которые в организме атакуют именно возбудителя болезни и ничего больше. Он назвал это волшебной пулей.","es":"El 20 de agosto de 1915 muere Paul Ehrlich. Buscaba sustancias que atacaran en el cuerpo exactamente al agente patógeno y nada más. A eso lo llamó la bala mágica.","fr":"Le 20 août 1915 meurt Paul Ehrlich. Il cherchait des substances qui, dans le corps, n'attaquent que l'agent pathogène et rien d'autre. Il appelait cela la balle magique.","pl":"20 sierpnia 1915 roku umiera Paul Ehrlich. Szukał substancji, które w organizmie atakują dokładnie patogen i nic poza tym. Nazywał to magiczną kulą.","uk":"20 серпня 1915 року помирає Пауль Ерліх. Він шукав речовини, які в організмі атакують саме збудника хвороби і більше нічого. Він назвав це чарівною кулею.","fa":"در ۲۰ اوت ۱۹۱۵، پل ارلیش درگذشت. او به دنبال موادی بود که در بدن دقیقاً عامل بیماری‌زا را هدف بگیرند و به چیز دیگری آسیب نرسانند. او این را گلوله جادویی نامید.","it":"Il 20 agosto 1915 muore Paul Ehrlich. Cercava sostanze che nel corpo attaccassero esattamente l'agente patogeno e nient'altro. Chiamava questa idea il \"proiettile magico\"."},"B1":{"en":"On August 20, 1915, Paul Ehrlich dies. His idea was simple and new: a drug that hits only the pathogen precisely in the body. In 1909, after more than six hundred attempts, his team found such a substance.","ar":"في 20 أغسطس 1915 يموت بول إيرليش. كانت فكرته بسيطة وجديدة: دواء يصيب في الجسم مسبب المرض فقط وبدقة. عثر فريقه عام 1909 بعد أكثر من ستمئة محاولة على مادة فعالة من هذا النوع.","tr":"20 Ağustos 1915'te Paul Ehrlich ölür. Fikri basit ve yeniydi: vücutta yalnızca hastalık etkenini hedef alan bir ilaç. Ekibi 1909'da altı yüzden fazla denemenin ardından böyle bir etken madde buldu.","ru":"20 августа 1915 года умирает Пауль Эрлих. Его идея была простой и новой: лекарство, которое в организме прицельно поражает только возбудителя. В 1909 году после более чем шестисот попыток его команда нашла такое действующее вещество.","es":"El 20 de agosto de 1915 muere Paul Ehrlich. Su idea era simple y nueva: un medicamento que en el cuerpo alcanzara con precisión solo al agente patógeno. En 1909, tras más de seiscientos ensayos, su equipo halló una sustancia así.","fr":"Le 20 août 1915 meurt Paul Ehrlich. Son idée était simple et nouvelle : un médicament qui, dans le corps, touche précisément et uniquement l'agent pathogène. En 1909, après plus de six cents essais, son équipe trouva une telle substance.","pl":"20 sierpnia 1915 roku umiera Paul Ehrlich. Jego pomysł był prosty i nowy: lek, który w organizmie trafia precyzyjnie tylko w patogen. W 1909 roku, po ponad sześciuset próbach, jego zespół znalazł taką substancję czynną.","uk":"20 серпня 1915 року помирає Пауль Ерліх. Його ідея була простою і новою: ліки, які в організмі влучно вражають лише збудника. У 1909 році після понад шестисот спроб його команда знайшла таку діючу речовину.","fa":"در ۲۰ اوت ۱۹۱۵، پل ارلیش درگذشت. ایده او ساده و نو بود: دارویی که در بدن دقیقاً فقط عامل بیماری‌زا را هدف قرار دهد. تیم او در سال ۱۹۰۹ پس از بیش از ششصد آزمایش، چنین ماده مؤثری را یافت.","it":"Il 20 agosto 1915 muore Paul Ehrlich. La sua idea era semplice e innovativa: un farmaco che, nel corpo, colpisse con precisione solo l'agente patogeno. Nel 1909 la sua équipe trovò, dopo oltre seicento tentativi, un principio attivo di questo tipo."},"B2":{"en":"On August 20, 1915, Paul Ehrlich dies. He founded chemotherapy in its original sense: treating diseases with deliberately synthesized molecules instead of natural substances. His approach — systematically testing hundreds of variants — remains the basic pattern of drug discovery to this day.","ar":"في 20 أغسطس 1915 يموت بول إيرليش. أسس العلاج الكيميائي بمعناه الأصلي: معالجة الأمراض بجزيئات مُصنّعة عن قصد بدلا من المواد الطبيعية. أسلوبه - فحص مئات المتغيرات بشكل منهجي - لا يزال حتى اليوم النمط الأساسي للبحث عن المواد الفعالة.","tr":"20 Ağustos 1915'te Paul Ehrlich ölür. Kemoterapiyi özgün anlamıyla temellendirdi: hastalıkları doğal maddeler yerine amaçlı üretilmiş moleküllerle tedavi etmek. Yaklaşımı - yüzlerce varyantı sistematik olarak test etmek - bugün hâlâ etkin madde arayışının temel modelidir.","ru":"20 августа 1915 года умирает Пауль Эрлих. Он заложил основы химиотерапии в первоначальном смысле: лечение болезней целенаправленно синтезированными молекулами вместо природных веществ. Его подход - систематическая проверка сотен вариантов - остаётся базовой моделью поиска лекарственных веществ по сей день.","es":"El 20 de agosto de 1915 muere Paul Ehrlich. Fundó la quimioterapia en su sentido original: tratar enfermedades con moléculas fabricadas deliberadamente en lugar de sustancias naturales. Su método -probar sistemáticamente cientos de variantes- sigue siendo hoy el patrón básico de la búsqueda de principios activos.","fr":"Le 20 août 1915 meurt Paul Ehrlich. Il fonda la chimiothérapie au sens originel : traiter les maladies avec des molécules synthétisées délibérément plutôt qu'avec des substances naturelles. Sa méthode - tester systématiquement des centaines de variantes - reste aujourd'hui encore le schéma de base de la recherche de principes actifs.","pl":"20 sierpnia 1915 roku umiera Paul Ehrlich. Zapoczątkował chemioterapię w pierwotnym znaczeniu: leczenie chorób celowo wytworzonymi cząsteczkami zamiast substancjami naturalnymi. Jego metoda - systematyczne badanie setek wariantów - do dziś stanowi podstawowy wzorzec poszukiwania substancji czynnych.","uk":"20 серпня 1915 року помирає Пауль Ерліх. Він започаткував хіміотерапію в первісному сенсі: лікування хвороб цілеспрямовано синтезованими молекулами замість природних речовин. Його підхід - систематична перевірка сотень варіантів - і донині залишається базовою моделлю пошуку діючих речовин.","fa":"در ۲۰ اوت ۱۹۱۵، پل ارلیش درگذشت. او شیمی‌درمانی را به معنای اصیل آن بنیان نهاد: درمان بیماری‌ها با مولکول‌های ساخته‌شده هدفمند به‌جای مواد طبیعی. رویکرد او — آزمایش نظام‌مند صدها گونه — تا امروز الگوی پایه جست‌وجوی داروهای مؤثر است.","it":"Il 20 agosto 1915 muore Paul Ehrlich. Fondò la chemioterapia nel suo senso originario: curare le malattie con molecole create appositamente invece che con sostanze naturali. Il suo metodo — testare sistematicamente centinaia di varianti — resta ancora oggi lo schema di base della ricerca farmacologica."},"C1":{"en":"The man who died on August 20, 1915, combined an idea with a method. The magic bullet was the image, the series of trials was the work. Together, the two turned the search for remedies into a plannable procedure rather than a matter of luck.","ar":"جمع المتوفى في 20 أغسطس 1915 بين تصور ومنهج. كانت الرصاصة السحرية صورة، وكانت سلسلة الاختبارات هي العمل. جمع الاثنان معا حوّل البحث عن العلاجات إلى إجراء قابل للتخطيط بدلا من مصادفة سعيدة.","tr":"20 Ağustos 1915'te ölen kişi bir tasarımı bir yöntemle birleştirdi. Sihirli mermi bir imgeydi, deneme dizisi ise işin kendisiydi. İkisi birlikte, tedavi arayışını bir şans meselesi olmaktan çıkarıp planlanabilir bir sürece dönüştürdü.","ru":"Умерший 20 августа 1915 года соединил идею с методом. Волшебная пуля была образом, серия испытаний - работой. Вместе они превратили поиск лекарств из счастливой случайности в планируемую процедуру.","es":"El fallecido el 20 de agosto de 1915 unió una idea con un método. La bala mágica era una imagen; la serie de ensayos, el trabajo. Juntas, ambas cosas convirtieron la búsqueda de remedios en un procedimiento planificable en lugar de un golpe de suerte.","fr":"Celui qui mourut le 20 août 1915 associa une idée à une méthode. La balle magique était une image, la série d'essais était le travail. Ensemble, les deux transformèrent la recherche de remèdes en une procédure planifiable plutôt qu'en un coup de chance.","pl":"Zmarły 20 sierpnia 1915 roku połączył wyobrażenie z metodą. Magiczna kula była obrazem, seria prób była pracą. Razem oba te elementy zamieniły poszukiwanie leków w planowalną procedurę zamiast szczęśliwego trafu.","uk":"Померлий 20 серпня 1915 року поєднав уявлення з методом. Чарівна куля була образом, серія випробувань - роботою. Разом обидва перетворили пошук ліків на планований процес замість щасливого випадку.","fa":"متوفی در ۲۰ اوت ۱۹۱۵ یک تصور را با یک روش پیوند داد. گلوله جادویی یک تصویر بود و مجموعه آزمایش‌ها کار واقعی. این دو با هم جست‌وجوی درمان‌ها را از یک شانس محض به فرآیندی قابل‌برنامه‌ریزی تبدیل کردند.","it":"Morto il 20 agosto 1915, egli unì un'idea a un metodo. Il \"proiettile magico\" era un'immagine, la serie di test era il lavoro concreto. Insieme, i due elementi trasformarono la ricerca di rimedi in una procedura pianificabile, non più in un colpo di fortuna."},"C2":{"en":"In Ehrlich, who died on August 20, 1915, one can observe the ambivalence of precision. His drug against syphilis was the first of its kind and at the same time toxic enough to trigger debates that accompany every drug approval today: what level of risk is reasonable to ask of a patient when the alternative is no treatment at all?","ar":"يمكن ملاحظة ازدواجية الدقة المستهدفة من خلال إيرليش، المتوفى في 20 أغسطس 1915. كانت مادته الفعالة ضد الزهري الأولى من نوعها، وفي الوقت نفسه سامة بما يكفي لإثارة نقاشات ترافق اليوم كل ترخيص دوائي: أي مخاطرة يمكن أن تُطلب من مريض إذا كان البديل هو غياب أي علاج؟","tr":"20 Ağustos 1915'te ölen Ehrlich üzerinden, hedef isabetinin ikircikli yapısı gözlemlenebilir. Frengiye karşı geliştirdiği etken madde türünün ilkiydi ve aynı zamanda bugün her ilaç ruhsatlandırmasına eşlik eden tartışmaları başlatacak kadar zehirliydi: Alternatif hiçbir tedavinin olmaması ise, bir hastadan hangi risk beklenebilir?","ru":"На примере Эрлиха, умершего 20 августа 1915 года, можно рассмотреть амбивалентность точности воздействия. Его препарат против сифилиса был первым в своем роде и одновременно достаточно токсичным, чтобы вызвать дебаты, сопровождающие сегодня любое лекарственное одобрение: какой риск допустим для больного, если альтернатива - полное отсутствие лечения?","es":"En Ehrlich, fallecido el 20 de agosto de 1915, puede observarse la ambivalencia de la precisión. Su fármaco contra la sífilis fue el primero de su tipo y, al mismo tiempo, lo bastante tóxico como para desatar debates que hoy acompañan toda autorización de medicamentos: ¿qué riesgo es razonable exigirle a un enfermo cuando la alternativa es la ausencia total de tratamiento?","fr":"Chez Ehrlich, mort le 20 août 1915, on peut observer l'ambivalence de la précision ciblée. Son remède contre la syphilis fut le premier de son genre, et en même temps suffisamment toxique pour déclencher des débats qui accompagnent aujourd'hui toute autorisation de mise sur le marché : quel risque peut-on raisonnablement demander à un malade lorsque l'alternative est l'absence totale de traitement ?","pl":"Na przykładzie Ehrlicha, zmarłego 20 sierpnia 1915 roku, można przyjrzeć się ambiwalencji precyzji działania. Jego lek przeciw kile był pierwszym tego rodzaju i zarazem na tyle toksyczny, by wywołać debaty towarzyszące dziś każdej rejestracji leku: jakie ryzyko można uznać za dopuszczalne wobec chorego, gdy alternatywą jest brak jakiegokolwiek leczenia?","uk":"На прикладі Ерліха, який помер 20 серпня 1915 року, можна розглянути амбівалентність точності впливу. Його препарат проти сифілісу був першим у своєму роді й водночас достатньо токсичним, щоб викликати дискусії, які сьогодні супроводжують будь-яке схвалення ліків: який ризик можна вважати прийнятним для хворого, якщо альтернативою є повна відсутність лікування?","fa":"با نگاه به ارلیش، درگذشته در ۲۰ اوت ۱۹۱۵، می‌توان دوگانگی دقت هدف‌گیری را بررسی کرد. داروی او علیه سیفلیس نخستین نمونه از نوع خود بود و در عین حال به‌اندازه‌ای سمی که مناظراتی را برانگیزد که امروز همراه هر تأیید دارویی است: چه میزان خطر برای یک بیمار قابل‌قبول است، وقتی جایگزین آن نبود هیچ درمانی است؟","it":"Nella figura di Ehrlich, morto il 20 agosto 1915, si può osservare l'ambivalenza della precisione mirata. Il suo farmaco contro la sifilide fu il primo del suo genere e al tempo stesso abbastanza tossico da suscitare dibattiti che ancora oggi accompagnano ogni processo di approvazione: quale rischio si può chiedere a un malato di sopportare, se l'alternativa è la totale assenza di cura?"}},"sideFacts":[]},"08-21":{"year":1838,"levels":{"A1":"Am 21. August 1838 stirbt Adelbert von Chamisso. Er kommt aus Frankreich und schreibt auf Deutsch. Seine Geschichte handelt von einem Mann ohne Schatten.","A2":"Am 21. August 1838 stirbt Adelbert von Chamisso. Er war als Kind aus Frankreich geflohen und wurde ein deutscher Dichter. Berühmt ist seine Erzählung von Peter Schlemihl, der seinen Schatten verkauft.","B1":"Am 21. August 1838 stirbt Adelbert von Chamisso. Er kam als Kind ohne ein Wort Deutsch nach Berlin und schrieb später in dieser Sprache Weltliteratur. Nach ihm ist heute ein Preis für Autoren benannt, deren Muttersprache nicht Deutsch ist.","B2":"Am 21. August 1838 stirbt Chamisso. Seine Geschichte vom Mann, der seinen Schatten verkauft und dadurch überall auffällt, liest sich als Bild für Fremdsein. Wer irgendwo dazugehören will und etwas Unsichtbares nicht mitbringt, kennt die Erfahrung.","C1":"Der am 21. August 1838 Gestorbene ist ein früher Fall dessen, was heute Mehrsprachigkeit in der Literatur heißt. Er blieb sein Leben lang zwischen zwei Ländern und schrieb gerade daraus eine Erzählung, die niemandem eindeutig zuzuordnen ist — was ihre Haltbarkeit erklärt.","C2":"An Chamisso, gestorben am 21. August 1838, lässt sich prüfen, was Nationalliteratur eigentlich meint. Ein französischer Adliger schreibt auf Deutsch eine Erzählung, die als deutsche Romantik gilt, und wird zum Namensgeber eines Preises für Zuwanderer. Die Kategorie hält solchen Fällen nicht stand — und war vermutlich nie mehr als eine ordnungspolitische Bequemlichkeit."},"translationsA1":{"en":"On August 21, 1838, Adelbert von Chamisso dies. He comes from France and writes in German. His story is about a man without a shadow.","ar":"في 21 أغسطس 1838، توفي أدلبرت فون شاميسو. جاء من فرنسا وكتب بالألمانية. قصته عن رجل بلا ظل.","tr":"21 Ağustos 1838'de Adelbert von Chamisso öldü. Fransa'dan geldi ve Almanca yazdı. Öyküsü gölgesiz bir adamı anlatır.","ru":"21 августа 1838 года умер Адельберт фон Шамиссо. Он был родом из Франции и писал по-немецки. Его повесть — о человеке без тени.","es":"El 21 de agosto de 1838 muere Adelbert von Chamisso. Viene de Francia y escribe en alemán. Su relato trata de un hombre sin sombra.","fr":"Le 21 août 1838, Adelbert von Chamisso meurt. Il vient de France et écrit en allemand. Son récit parle d'un homme sans ombre.","pl":"21 sierpnia 1838 roku zmarł Adelbert von Chamisso. Pochodził z Francji i pisał po niemiecku. Jego opowieść mówi o człowieku bez cienia.","uk":"21 серпня 1838 року помер Адельберт фон Шаміссо. Він походив із Франції й писав німецькою. Його повість — про людину без тіні.","fa":"در ۲۱ اوت ۱۸۳۸، آدلبرت فون شامیسو درگذشت. او از فرانسه آمده بود و به آلمانی می‌نوشت. داستان او درباره مردی بی‌سایه است.","it":"Il 21 agosto 1838 muore Adelbert von Chamisso. Viene dalla Francia e scrive in tedesco. La sua storia più famosa parla di un uomo senza ombra."},"translationsByLevel":{"A2":{"en":"On August 21, 1838, Adelbert von Chamisso dies. As a child he had fled from France and became a German poet. Famous is his story of Peter Schlemihl, who sells his shadow.","ar":"في 21 أغسطس 1838 يموت أديلبرت فون شاميسو. كان قد هرب من فرنسا وهو طفل وأصبح شاعرا ألمانيا. اشتهرت قصته عن بيتر شليميل، الذي يبيع ظله.","tr":"21 Ağustos 1838'de Adelbert von Chamisso ölür. Çocukken Fransa'dan kaçmış ve bir Alman şair olmuştur. Gölgesini satan Peter Schlemihl adlı öyküsüyle ünlüdür.","ru":"21 августа 1838 года умирает Адельберт фон Шамиссо. Ребёнком он бежал из Франции и стал немецким поэтом. Знаменит его рассказ о Петере Шлемиле, продавшем свою тень.","es":"El 21 de agosto de 1838 muere Adelbert von Chamisso. De niño había huido de Francia y se convirtió en poeta alemán. Es célebre su relato de Peter Schlemihl, que vende su sombra.","fr":"Le 21 août 1838 meurt Adelbert von Chamisso. Enfant, il avait fui la France et devint poète allemand. Son récit de Peter Schlemihl, qui vend son ombre, est célèbre.","pl":"21 sierpnia 1838 roku umiera Adelbert von Chamisso. Jako dziecko uciekł z Francji i został niemieckim poetą. Znane jest jego opowiadanie o Peterze Schlemihlu, który sprzedaje swój cień.","uk":"21 серпня 1838 року помирає Адельберт фон Шаміссо. У дитинстві він утік із Франції і став німецьким поетом. Відома його розповідь про Петера Шлеміля, який продає свою тінь.","fa":"در ۲۱ اوت ۱۸۳۸، آدلبرت فون شامیسو درگذشت. او در کودکی از فرانسه گریخته بود و شاعری آلمانی شد. داستان مشهور او درباره پیتر شلمیل است که سایه‌اش را می‌فروشد.","it":"Il 21 agosto 1838 muore Adelbert von Chamisso. Da bambino era fuggito dalla Francia e divenne un poeta tedesco. È celebre il suo racconto di Peter Schlemihl, che vende la propria ombra."},"B1":{"en":"On August 21, 1838, Adelbert von Chamisso dies. He came to Berlin as a child without a word of German and later wrote world literature in that language. A prize for authors whose mother tongue is not German is named after him today.","ar":"في 21 أغسطس 1838 يموت أديلبرت فون شاميسو. قدم إلى برلين طفلا دون أن يعرف كلمة ألمانية واحدة، وكتب لاحقا بهذه اللغة أدبا عالميا. سُمّيت باسمه اليوم جائزة للمؤلفين الذين ليست الألمانية لغتهم الأم.","tr":"21 Ağustos 1838'de Adelbert von Chamisso ölür. Berlin'e çocukken tek kelime Almanca bilmeden geldi ve sonra bu dilde dünya edebiyatı yazdı. Bugün adını taşıyan bir ödül, ana dili Almanca olmayan yazarlara verilmektedir.","ru":"21 августа 1838 года умирает Адельберт фон Шамиссо. Ребёнком он приехал в Берлин, не зная ни слова по-немецки, а позже писал на этом языке произведения мировой литературы. Сегодня в его честь названа премия для авторов, чей родной язык не немецкий.","es":"El 21 de agosto de 1838 muere Adelbert von Chamisso. Llegó a Berlín de niño sin saber una palabra de alemán y más tarde escribió literatura universal en ese idioma. Hoy lleva su nombre un premio para autores cuya lengua materna no es el alemán.","fr":"Le 21 août 1838 meurt Adelbert von Chamisso. Enfant, il arriva à Berlin sans un mot d'allemand et écrivit plus tard dans cette langue une œuvre de littérature mondiale. Un prix pour les auteurs dont la langue maternelle n'est pas l'allemand porte aujourd'hui son nom.","pl":"21 sierpnia 1838 roku umiera Adelbert von Chamisso. Jako dziecko przybył do Berlina, nie znając ani słowa po niemiecku, a później pisał w tym języku dzieła literatury światowej. Dziś jego imieniem nazwana jest nagroda dla autorów, których językiem ojczystym nie jest niemiecki.","uk":"21 серпня 1838 року помирає Адельберт фон Шаміссо. Дитиною він прибув до Берліна, не знаючи жодного слова німецькою, а пізніше писав цією мовою твори світової літератури. Сьогодні його ім'ям названо премію для авторів, чия рідна мова не німецька.","fa":"در ۲۱ اوت ۱۸۳۸، آدلبرت فون شامیسو درگذشت. او در کودکی بدون دانستن حتی یک کلمه آلمانی به برلین آمد و بعدها به این زبان آثاری در ادبیات جهانی نوشت. امروز جایزه‌ای برای نویسندگانی که زبان مادری‌شان آلمانی نیست، به نام او نامگذاری شده است.","it":"Il 21 agosto 1838 muore Adelbert von Chamisso. Arrivò a Berlino da bambino senza conoscere una parola di tedesco, e in quella lingua scrisse in seguito opere di letteratura mondiale. Oggi porta il suo nome un premio destinato ad autori la cui lingua madre non è il tedesco."},"B2":{"en":"On August 21, 1838, Chamisso dies. His story about the man who sells his shadow and is thereby conspicuous everywhere reads as an image of being an outsider. Anyone who wants to belong somewhere but lacks something invisible knows the experience.","ar":"في 21 أغسطس 1838 يموت شاميسو. تُقرأ قصته عن الرجل الذي يبيع ظله فيصبح لافتا للنظر أينما ذهب كصورة للغربة. كل من يريد الانتماء إلى مكان ما ولا يمتلك شيئا غير مرئي يعرف هذه التجربة.","tr":"21 Ağustos 1838'de Chamisso ölür. Gölgesini satan ve bu yüzden her yerde dikkat çeken adamın hikâyesi, yabancılığın bir imgesi olarak okunur. Bir yere ait olmak isteyip görünmez bir şeye sahip olmayan herkes bu deneyimi bilir.","ru":"21 августа 1838 года умирает Шамиссо. Его история о человеке, который продал свою тень и оттого повсюду выделяется, читается как образ чужеродности. Каждый, кто хочет где-то принадлежать и не обладает чем-то невидимым, знает это чувство.","es":"El 21 de agosto de 1838 muere Chamisso. Su historia sobre el hombre que vende su sombra y por ello llama la atención en todas partes se lee como una imagen de la condición de forastero. Quien quiere pertenecer a algún lugar y carece de algo invisible conoce esa experiencia.","fr":"Le 21 août 1838 meurt Chamisso. Son histoire de l'homme qui vend son ombre et se fait ainsi remarquer partout se lit comme une image de l'étrangeté. Quiconque veut appartenir quelque part et ne possède pas quelque chose d'invisible connaît cette expérience.","pl":"21 sierpnia 1838 roku umiera Chamisso. Jego opowieść o człowieku, który sprzedaje swój cień i przez to wszędzie rzuca się w oczy, czyta się jako obraz obcości. Kto chce gdzieś przynależeć, a brakuje mu czegoś niewidzialnego, zna to doświadczenie.","uk":"21 серпня 1838 року помирає Шаміссо. Його історія про чоловіка, який продає свою тінь і через це всюди привертає увагу, читається як образ чужинства. Кожен, хто хоче кудись належати, а не має чогось невидимого, знає це відчуття.","fa":"در ۲۱ اوت ۱۸۳۸، شامیسو درگذشت. داستان او درباره مردی که سایه‌اش را می‌فروشد و از این رو در همه‌جا جلب توجه می‌کند، همچون تصویری از غریبگی خوانده می‌شود. هرکس بخواهد جایی متعلق باشد و چیزی نامرئی را همراه نداشته باشد، این تجربه را می‌شناسد.","it":"Il 21 agosto 1838 muore Chamisso. La sua storia dell'uomo che vende la propria ombra, rendendosi per questo notato ovunque, si legge come un'immagine dell'essere straniero. Chiunque voglia appartenere a un luogo senza possedere qualcosa di invisibile ma essenziale conosce quella sensazione."},"C1":{"en":"The man who died on August 21, 1838, is an early instance of what is called multilingualism in literature today. He remained caught between two countries throughout his life and wrote, precisely out of that condition, a story that cannot be clearly assigned to anyone — which explains its lasting power.","ar":"المتوفى في 21 أغسطس 1838 هو حالة مبكرة لما يُسمى اليوم بتعدد اللغات في الأدب. ظل طوال حياته بين بلدين، وكتب من هذا الوضع بالذات قصة لا يمكن نسبتها بوضوح إلى أحد - وهو ما يفسر بقاءها.","tr":"21 Ağustos 1838'de ölen kişi, bugün edebiyatta çok dillilik olarak adlandırılan olgunun erken bir örneğidir. Hayatı boyunca iki ülke arasında kaldı ve tam da bu durumdan, kimseye açıkça atfedilemeyen bir öykü yazdı - bu da onun kalıcılığını açıklar.","ru":"Умерший 21 августа 1838 года - ранний пример того, что сегодня называют многоязычием в литературе. Он всю жизнь оставался между двумя странами и именно из этого положения написал повесть, которую нельзя однозначно приписать кому-либо, - что и объясняет её долговечность.","es":"El fallecido el 21 de agosto de 1838 es un caso temprano de lo que hoy se llama multilingüismo en la literatura. Permaneció toda su vida entre dos países y escribió precisamente a partir de ello un relato que no puede atribuirse claramente a nadie, lo que explica su perdurabilidad.","fr":"Celui qui mourut le 21 août 1838 est un cas précoce de ce qu'on appelle aujourd'hui le plurilinguisme littéraire. Il resta toute sa vie entre deux pays et écrivit précisément à partir de cela un récit qu'on ne peut attribuer clairement à personne — ce qui explique sa durabilité.","pl":"Zmarły 21 sierpnia 1838 roku to wczesny przypadek tego, co dziś nazywa się wielojęzycznością w literaturze. Przez całe życie pozostawał między dwoma krajami i właśnie z tego napisał opowiadanie, którego nie można jednoznacznie do nikogo przypisać - co tłumaczy jego trwałość.","uk":"Померлий 21 серпня 1838 року - ранній приклад того, що сьогодні називають багатомовністю в літературі. Він усе життя залишався між двома країнами і саме з цього стану написав повість, яку неможливо однозначно комусь приписати - що й пояснює її тривкість.","fa":"متوفی در ۲۱ اوت ۱۸۳۸ نمونه‌ای اولیه از آن چیزی است که امروز چندزبانگی در ادبیات نامیده می‌شود. او تمام عمر خود میان دو کشور باقی ماند و دقیقاً از همین وضعیت داستانی نوشت که نمی‌توان آن را به‌روشنی به کسی نسبت داد — که همین امر ماندگاری آن را توضیح می‌دهد.","it":"Morto il 21 agosto 1838, egli rappresenta un caso precoce di ciò che oggi si definirebbe plurilinguismo letterario. Rimase per tutta la vita sospeso tra due paesi, e fu proprio da questa condizione che nacque un racconto impossibile da attribuire in modo univoco a una sola tradizione — il che ne spiega la straordinaria durata nel tempo."},"C2":{"en":"In Chamisso, who died on August 21, 1838, one can test what national literature actually means. A French nobleman writes in German a story that counts as German Romanticism, and becomes the namesake of a prize for immigrants. The category does not hold up to such cases — and was probably never more than an administrative convenience.","ar":"يمكن من خلال شاميسو، المتوفى في 21 أغسطس 1838، اختبار ما تعنيه فعلا الأدب القومي. نبيل فرنسي يكتب بالألمانية قصة تُعتبر من الرومانسية الألمانية، ويصبح اسمه اسم جائزة للمهاجرين. لا تصمد الفئة أمام حالات كهذه - ولم تكن على الأرجح أكثر من راحة تنظيمية إدارية.","tr":"21 Ağustos 1838'de ölen Chamisso üzerinden, ulusal edebiyatın aslında ne anlama geldiği sınanabilir. Fransız bir soylu, Almanca olarak Alman Romantizmi sayılan bir öykü yazar ve göçmenlere verilen bir ödülün adını verdiği kişi olur. Kategori bu tür durumlar karşısında dayanamaz - ve muhtemelen hiçbir zaman idari bir kolaylıktan başka bir şey olmamıştır.","ru":"На примере Шамиссо, умершего 21 августа 1838 года, можно проверить, что на самом деле означает национальная литература. Французский аристократ пишет по-немецки повесть, которая считается образцом немецкого романтизма, и становится тезоименным для премии для иммигрантов. Категория не выдерживает подобных случаев - и, вероятно, никогда не была ничем большим, чем административным удобством.","es":"En Chamisso, fallecido el 21 de agosto de 1838, puede examinarse qué significa en realidad la literatura nacional. Un noble francés escribe en alemán un relato considerado romanticismo alemán, y da nombre a un premio para inmigrantes. La categoría no resiste casos así, y probablemente nunca fue más que una comodidad administrativa.","fr":"Chez Chamisso, mort le 21 août 1838, on peut mettre à l'épreuve ce que signifie réellement la littérature nationale. Un noble français écrit en allemand un récit considéré comme relevant du romantisme allemand, et devient l'éponyme d'un prix pour immigrés. La catégorie ne résiste pas à de tels cas - et n'a probablement jamais été qu'une commodité administrative.","pl":"Na przykładzie Chamisso, zmarłego 21 sierpnia 1838 roku, można sprawdzić, co właściwie oznacza literatura narodowa. Francuski szlachcic pisze po niemiecku opowiadanie uznawane za niemiecki romantyzm i staje się patronem nagrody dla imigrantów. Kategoria ta nie wytrzymuje takich przypadków - i prawdopodobnie nigdy nie była niczym więcej niż administracyjną wygodą.","uk":"На прикладі Шаміссо, який помер 21 серпня 1838 року, можна перевірити, що насправді означає національна література. Французький дворянин пише німецькою повість, яку вважають німецьким романтизмом, і стає покровителем премії для іммігрантів. Ця категорія не витримує таких випадків - і, ймовірно, ніколи не була нічим більшим за адміністративну зручність.","fa":"با نگاه به شامیسو، درگذشته در ۲۱ اوت ۱۸۳۸، می‌توان بررسی کرد که ادبیات ملی واقعاً به چه معناست. یک اشراف‌زاده فرانسوی به آلمانی داستانی می‌نویسد که رمانتیسم آلمانی به شمار می‌رود و نام او بر جایزه‌ای برای مهاجران گذاشته می‌شود. این مقوله در برابر چنین مواردی دوام نمی‌آورد — و احتمالاً هرگز چیزی بیش از یک راحتی اداری نبوده است.","it":"Nella figura di Chamisso, morto il 21 agosto 1838, si può verificare che cosa significhi realmente \"letteratura nazionale\". Un aristocratico francese scrive in tedesco un racconto considerato parte del Romanticismo tedesco, e dà poi il nome a un premio destinato agli immigrati. Una categoria del genere non regge a casi come questo — e probabilmente non fu mai altro che una comoda etichetta di ordinamento."}},"sideFacts":[]},"08-22":{"year":1928,"levels":{"A1":"Am 22. August 1928 wird Karlheinz Stockhausen geboren. Er macht Musik mit Maschinen. Viele finden sie sehr seltsam.","A2":"Am 22. August 1928 kommt Karlheinz Stockhausen bei Köln zur Welt. Er komponierte als einer der Ersten Musik aus elektronischen Klängen. Ohne ihn klänge heutige Popmusik anders.","B1":"Am 22. August 1928 wird Karlheinz Stockhausen geboren. Im Kölner Studio für elektronische Musik erzeugte er Klänge, die es in der Natur nicht gibt. Musiker von den Beatles bis zur Techno-Szene haben sich auf ihn berufen.","B2":"Am 22. August 1928 wird Stockhausen geboren. Seine Entscheidung war grundsätzlich: Nicht mehr Instrumente aufnehmen, sondern den Klang selbst herstellen. Damit verschob sich die Arbeit des Komponisten von der Notenschrift ins Studio — eine Verschiebung, von der die gesamte Popmusik lebt.","C1":"Der am 22. August 1928 Geborene löste die Musik von der Voraussetzung, dass jemand etwas spielen muss. Wo der Klang konstruiert wird, gibt es keine Aufführung im alten Sinn mehr. Diese Grundfrage — was bleibt von Musik ohne Interpret — beschäftigt die Musikwissenschaft bis heute.","C2":"An Stockhausen, geboren am 22. August 1928, lässt sich das schwierige Verhältnis von Avantgarde und Breitenwirkung beobachten. Seine eigenen Werke erreichten ein kleines Publikum, seine Verfahren erreichten alle. Einfluss in der Kunst bemisst sich deshalb nur begrenzt an Hörerzahlen — entscheidend ist, wie viele Nachfolger das Werkzeug übernehmen."},"translationsA1":{"en":"On August 22, 1928, Karlheinz Stockhausen is born. He makes music with machines. Many people find it very strange.","ar":"في 22 أغسطس 1928، وُلد كارلهاينتس شتوكهاوزن. صنع موسيقى بالآلات. كثيرون يجدونها غريبة جدًا.","tr":"22 Ağustos 1928'de Karlheinz Stockhausen doğdu. Makinelerle müzik yaptı. Birçok kişi bunu çok tuhaf buluyor.","ru":"22 августа 1928 года родился Карлхайнц Штокхаузен. Он создавал музыку с помощью машин. Многим она кажется очень странной.","es":"El 22 de agosto de 1928 nace Karlheinz Stockhausen. Hace música con máquinas. A muchos les parece muy extraña.","fr":"Le 22 août 1928, Karlheinz Stockhausen naît. Il fait de la musique avec des machines. Beaucoup la trouvent très étrange.","pl":"22 sierpnia 1928 roku urodził się Karlheinz Stockhausen. Tworzył muzykę maszynami. Wielu uważa ją za bardzo dziwną.","uk":"22 серпня 1928 року народився Карлгайнц Штокгаузен. Він створював музику за допомогою машин. Багатьом вона здається дуже дивною.","fa":"در ۲۲ اوت ۱۹۲۸، کارل‌هاینتس اشتوکهاوزن به دنیا آمد. او با ماشین‌ها موسیقی می‌ساخت. بسیاری آن را بسیار عجیب می‌یابند.","it":"Il 22 agosto 1928 nasce Karlheinz Stockhausen. Crea musica con le macchine. Molti la trovano molto strana."},"translationsByLevel":{"A2":{"en":"On August 22, 1928, Karlheinz Stockhausen was born near Cologne. He was one of the first to compose music from electronic sounds. Without him, today's pop music would sound different.","ar":"في 22 أغسطس 1928، وُلد كارلهاينتس شتوكهاوزن بالقرب من كولونيا. كان من أوائل من ألفوا موسيقى من أصوات إلكترونية. لولاه لكانت موسيقى البوب اليوم مختلفة.","tr":"22 Ağustos 1928'de Karlheinz Stockhausen, Köln yakınlarında dünyaya geldi. Elektronik seslerden müzik besteleyen ilk kişilerden biriydi. O olmasaydı, günümüz pop müziği farklı olurdu.","ru":"22 августа 1928 года недалеко от Кёльна родился Карлхайнц Штокхаузен. Он был одним из первых, кто сочинял музыку из электронных звуков. Без него современная поп-музыка звучала бы иначе.","es":"El 22 de agosto de 1928 nació Karlheinz Stockhausen cerca de Colonia. Fue uno de los primeros en componer música a partir de sonidos electrónicos. Sin él, la música pop actual sonaría diferente.","fr":"Le 22 août 1928, Karlheinz Stockhausen est né près de Cologne. Il fut l'un des premiers à composer de la musique à partir de sons électroniques. Sans lui, la musique pop d'aujourd'hui sonnerait différemment.","pl":"22 sierpnia 1928 roku w pobliżu Kolonii urodził się Karlheinz Stockhausen. Był jednym z pierwszych, którzy komponowali muzykę z dźwięków elektronicznych. Bez niego dzisiejsza muzyka pop brzmiałaby inaczej.","uk":"22 серпня 1928 року неподалік Кельна народився Карлхайнц Штокгаузен. Він був одним із перших, хто створював музику з електронних звуків. Без нього сучасна поп-музика звучала б інакше.","fa":"در ۲۲ اوت ۱۹۲۸، کارلهاینتس اشتوکهاوزن نزدیک کلن به دنیا آمد. او یکی از نخستین کسانی بود که از صداهای الکترونیکی موسیقی می‌ساخت. بدون او، موسیقی پاپ امروزی متفاوت به نظر می‌رسید.","it":"Il 22 agosto 1928 nasce Karlheinz Stockhausen vicino a Colonia. Fu tra i primi a comporre musica con suoni elettronici. Senza di lui la musica pop di oggi suonerebbe diversa."},"B1":{"en":"Karlheinz Stockhausen was born on August 22, 1928. At the Cologne studio for electronic music, he created sounds that do not exist in nature. Musicians from the Beatles to the techno scene have cited him as an influence.","ar":"وُلد كارلهاينتس شتوكهاوزن في 22 أغسطس 1928. في استوديو الموسيقى الإلكترونية في كولونيا، أنتج أصواتاً لا وجود لها في الطبيعة. استشهد به موسيقيون من فرقة البيتلز وحتى مشهد موسيقى التكنو.","tr":"Karlheinz Stockhausen 22 Ağustos 1928'de doğdu. Köln'deki elektronik müzik stüdyosunda, doğada bulunmayan sesler üretti. Beatles'tan tekno sahnesine kadar birçok müzisyen ona atıfta bulundu.","ru":"22 августа 1928 года родился Карлхайнц Штокхаузен. В Кёльнской студии электронной музыки он создавал звуки, которых не существует в природе. На него ссылались музыканты от The Beatles до техно-сцены.","es":"Karlheinz Stockhausen nació el 22 de agosto de 1928. En el estudio de música electrónica de Colonia, creó sonidos que no existen en la naturaleza. Músicos desde los Beatles hasta la escena tecno lo han citado como influencia.","fr":"Karlheinz Stockhausen est né le 22 août 1928. Au studio de musique électronique de Cologne, il a créé des sons qui n'existent pas dans la nature. Des musiciens, des Beatles jusqu'à la scène techno, se sont réclamés de lui.","pl":"Karlheinz Stockhausen urodził się 22 sierpnia 1928 roku. W kolońskim studiu muzyki elektronicznej tworzył dźwięki, których nie ma w naturze. Powoływali się na niego muzycy od Beatlesów po scenę techno.","uk":"Карлхайнц Штокгаузен народився 22 серпня 1928 року. У кельнській студії електронної музики він створював звуки, яких немає в природі. На нього посилалися музиканти від The Beatles до техно-сцени.","fa":"کارلهاینتس اشتوکهاوزن در ۲۲ اوت ۱۹۲۸ به دنیا آمد. او در استودیوی موسیقی الکترونیک کلن صداهایی خلق کرد که در طبیعت وجود ندارند. موسیقی‌دانانی از بیتلز گرفته تا صحنه موسیقی تکنو به او استناد کرده‌اند.","it":"Il 22 agosto 1928 nasce Karlheinz Stockhausen. Nello studio di musica elettronica di Colonia produsse suoni che non esistono in natura. Musicisti dai Beatles fino alla scena techno si sono richiamati a lui."},"B2":{"en":"Stockhausen was born on August 22, 1928. His decision was fundamental: no longer to record instruments, but to produce the sound itself. This shifted the composer's work from musical notation to the studio — a shift that all of pop music now thrives on.","ar":"وُلد شتوكهاوزن في 22 أغسطس 1928. كان قراره جذرياً: عدم تسجيل الآلات الموسيقية بعد الآن، بل إنتاج الصوت نفسه. بهذا انتقل عمل الملحن من التدوين الموسيقي إلى الاستوديو — وهو تحول تعيش عليه موسيقى البوب بأكملها اليوم.","tr":"Stockhausen 22 Ağustos 1928'de doğdu. Kararı köklüydü: Artık enstrümanları kaydetmek değil, sesin kendisini üretmek. Böylece bestecinin işi nota yazımından stüdyoya kaydı — tüm pop müziğin beslendiği bir dönüşüm.","ru":"Штокхаузен родился 22 августа 1928 года. Его решение было принципиальным: больше не записывать инструменты, а создавать сам звук. Тем самым работа композитора переместилась от нотной записи в студию — сдвиг, на котором держится вся современная поп-музыка.","es":"Stockhausen nació el 22 de agosto de 1928. Su decisión fue radical: dejar de grabar instrumentos y producir el sonido mismo. Con ello, el trabajo del compositor se desplazó de la partitura al estudio, un desplazamiento del que vive toda la música pop actual.","fr":"Stockhausen est né le 22 août 1928. Sa décision fut radicale : ne plus enregistrer des instruments, mais produire le son lui-même. Le travail du compositeur s'est ainsi déplacé de la partition vers le studio — un déplacement dont vit toute la musique pop.","pl":"Stockhausen urodził się 22 sierpnia 1928 roku. Jego decyzja miała fundamentalne znaczenie: nie nagrywać już instrumentów, lecz wytwarzać sam dźwięk. Praca kompozytora przesunęła się tym samym z zapisu nutowego do studia — przesunięcie, na którym opiera się cała muzyka pop.","uk":"Штокгаузен народився 22 серпня 1928 року. Його рішення було принциповим: більше не записувати інструменти, а створювати сам звук. Так робота композитора перемістилася з нотного запису до студії — зсув, на якому тримається вся сучасна поп-музика.","fa":"اشتوکهاوزن در ۲۲ اوت ۱۹۲۸ به دنیا آمد. تصمیم او بنیادین بود: دیگر نه ضبط سازها، بلکه تولید خودِ صدا. بدین‌سان کار آهنگساز از نت‌نویسی به استودیو منتقل شد؛ تحولی که تمام موسیقی پاپ امروز از آن بهره می‌برد.","it":"Il 22 agosto 1928 nasce Stockhausen. La sua fu una scelta radicale: non più registrare strumenti, ma produrre il suono stesso. Il lavoro del compositore si spostò così dalla scrittura sul pentagramma allo studio di registrazione — uno spostamento da cui vive ancora oggi tutta la musica pop."},"C1":{"en":"Born on August 22, 1928, he freed music from the premise that someone must play something. Where sound is constructed, there is no performance in the old sense anymore. This fundamental question — what remains of music without a performer — still occupies musicology today.","ar":"المولود في 22 أغسطس 1928 حرّر الموسيقى من الافتراض القائل بأن على أحد ما أن يعزف شيئاً. حيث يُصنع الصوت، لم يعد هناك أداء بالمعنى القديم. هذا السؤال الجوهري — ما الذي يتبقى من الموسيقى بلا عازف — لا يزال يشغل علم الموسيقى حتى اليوم.","tr":"22 Ağustos 1928'de doğan bu kişi, müziği birinin bir şey çalması gerektiği önkoşulundan kurtardı. Sesin inşa edildiği yerde, eski anlamda bir icra artık yoktur. Bu temel soru — bir yorumcu olmadan müzikten geriye ne kalır — müzikbilimini bugün hâlâ meşgul etmektedir.","ru":"Родившийся 22 августа 1928 года освободил музыку от предпосылки, что кто-то должен что-то исполнять. Там, где звук конструируется, больше нет исполнения в старом смысле. Этот фундаментальный вопрос — что остаётся от музыки без исполнителя — занимает музыковедение по сей день.","es":"El nacido el 22 de agosto de 1928 liberó a la música de la premisa de que alguien debe tocar algo. Donde el sonido se construye, ya no hay interpretación en el sentido antiguo. Esta cuestión fundamental —qué queda de la música sin intérprete— ocupa a la musicología hasta hoy.","fr":"Né le 22 août 1928, il a libéré la musique de la condition selon laquelle quelqu'un doit jouer quelque chose. Là où le son est construit, il n'y a plus d'exécution au sens ancien du terme. Cette question fondamentale — ce qui reste de la musique sans interprète — occupe encore la musicologie aujourd'hui.","pl":"Urodzony 22 sierpnia 1928 roku uwolnił muzykę od założenia, że ktoś musi coś zagrać. Tam, gdzie dźwięk jest konstruowany, nie ma już wykonania w dawnym sensie. To fundamentalne pytanie — co pozostaje z muzyki bez wykonawcy — zajmuje muzykologię do dziś.","uk":"Народжений 22 серпня 1928 року звільнив музику від передумови, що хтось має щось грати. Там, де звук конструюється, вже немає виконання у старому сенсі. Це фундаментальне питання — що залишається від музики без виконавця — займає музикознавство й донині.","fa":"متولد ۲۲ اوت ۱۹۲۸، موسیقی را از این پیش‌فرض رها کرد که کسی باید چیزی بنوازد. جایی که صدا ساخته می‌شود، دیگر اجرایی به معنای قدیم وجود ندارد. این پرسش بنیادین — از موسیقی بدون نوازنده چه می‌ماند — تا امروز ذهن موسیقی‌شناسی را به خود مشغول کرده است.","it":"Nato il 22 agosto 1928, egli liberò la musica dal presupposto che qualcuno debba suonare qualcosa. Dove il suono viene costruito, non esiste più un'esecuzione nel senso tradizionale del termine. Questa domanda di fondo — che cosa resta della musica senza un interprete — occupa ancora oggi la musicologia."},"C2":{"en":"Stockhausen, born on August 22, 1928, illustrates the difficult relationship between avant-garde and broad impact. His own works reached a small audience; his methods reached everyone. Influence in art can therefore only be measured to a limited extent by listener numbers — what matters is how many successors adopt the tool.","ar":"يمكن ملاحظة العلاقة الصعبة بين الطليعة والتأثير الواسع من خلال شتوكهاوزن، المولود في 22 أغسطس 1928. وصلت أعماله الخاصة إلى جمهور صغير، بينما وصلت أساليبه إلى الجميع. لذلك فإن التأثير في الفن يُقاس بشكل محدود فقط بأعداد المستمعين — والحاسم هو عدد الخلفاء الذين يتبنون الأداة.","tr":"22 Ağustos 1928'de doğan Stockhausen üzerinden, avangard ile geniş etki arasındaki zor ilişki gözlemlenebilir. Kendi eserleri küçük bir kitleye ulaştı, yöntemleri ise herkese ulaştı. Bu nedenle sanattaki etki, dinleyici sayısıyla ancak sınırlı ölçüde ölçülebilir — belirleyici olan, aracı kaç ardılın devraldığıdır.","ru":"На примере Штокхаузена, родившегося 22 августа 1928 года, можно наблюдать сложное отношение между авангардом и широким воздействием. Его собственные произведения достигли небольшой аудитории, зато его методы — всех. Поэтому влияние в искусстве лишь отчасти измеряется числом слушателей — решающим является то, сколько последователей перенимают инструмент.","es":"En Stockhausen, nacido el 22 de agosto de 1928, se observa la difícil relación entre vanguardia e impacto masivo. Sus propias obras llegaron a un público reducido; sus métodos llegaron a todos. La influencia en el arte, por tanto, solo se mide de forma limitada por el número de oyentes: lo decisivo es cuántos sucesores adoptan la herramienta.","fr":"Chez Stockhausen, né le 22 août 1928, on observe la relation difficile entre avant-garde et rayonnement populaire. Ses propres œuvres n'ont touché qu'un public restreint, ses procédés ont touché tout le monde. L'influence dans l'art ne se mesure donc que de façon limitée au nombre d'auditeurs — ce qui compte, c'est combien de successeurs reprennent l'outil.","pl":"Na przykładzie Stockhausena, urodzonego 22 sierpnia 1928 roku, widać trudną relację między awangardą a szerokim oddziaływaniem. Jego własne dzieła dotarły do niewielkiej publiczności, jego metody dotarły do wszystkich. Wpływ w sztuce mierzy się więc tylko w ograniczonym stopniu liczbą słuchaczy — decydujące jest to, ilu następców przejmuje narzędzie.","uk":"На прикладі Штокгаузена, народженого 22 серпня 1928 року, можна спостерігати складні стосунки між авангардом і широким впливом. Його власні твори охопили невелику аудиторію, тоді як його методи охопили всіх. Тому вплив у мистецтві лише обмежено вимірюється кількістю слухачів — вирішальним є те, скільки послідовників переймають цей інструмент.","fa":"در وجود اشتوکهاوزن، متولد ۲۲ اوت ۱۹۲۸، می‌توان رابطه دشوار میان آوانگارد و تأثیرگذاری گسترده را مشاهده کرد. آثار خودِ او به مخاطبانی اندک رسید، اما روش‌های او به همه رسید. از این‌رو تأثیر در هنر تنها به‌طور محدود با تعداد شنوندگان سنجیده می‌شود؛ آنچه تعیین‌کننده است این است که چند نسل بعدی این ابزار را به کار می‌گیرند.","it":"Nella figura di Stockhausen, nato il 22 agosto 1928, si osserva il difficile rapporto tra avanguardia e diffusione di massa. Le sue opere raggiunsero un pubblico ristretto, i suoi procedimenti raggiunsero tutti. L'influenza nell'arte si misura quindi solo in parte dal numero di ascoltatori: ciò che conta è quanti successori ne adottino gli strumenti."}},"sideFacts":[]},"08-23":{"year":1939,"levels":{"A1":"Am 23. August 1939 unterschreiben Deutschland und die Sowjetunion einen Vertrag. Er heißt Hitler-Stalin-Pakt.","A2":"Am 23. August 1939 unterschreiben Deutschland und die Sowjetunion einen Nichtangriffspakt. Er wird Hitler-Stalin-Pakt genannt.","B1":"In der Nacht zum 24. August 1939 unterschreiben Deutschland und die Sowjetunion den Hitler-Stalin-Pakt — einen Nichtangriffsvertrag. Er ebnet den Weg für den Überfall auf Polen wenige Tage später.","B2":"In der Nacht zum 24. August 1939 unterzeichnen die Außenminister Ribbentrop und Molotow in Moskau den deutsch-sowjetischen Nichtangriffspakt. Ein geheimes Zusatzprotokoll teilt Osteuropa bereits im Voraus in Interessensphären auf — die Grundlage für den Überfall auf Polen neun Tage später.","C1":"Der in der Nacht zum 24. August 1939 unterzeichnete deutsch-sowjetische Nichtangriffspakt sicherte Hitler die sowjetische Neutralität für den bereits beschlossenen Überfall auf Polen. Ein geheimes Zusatzprotokoll regelte die Aufteilung Ost- und Ostmitteleuropas in Einflusssphären.","C2":"Der Hitler-Stalin-Pakt vom 23./24. August 1939, scheinbar ein Friedensvertrag zwischen ideologischen Erzfeinden, entpuppte sich als zynisches machtpolitisches Kalkül: Das geheime Zusatzprotokoll besiegelte die Aufteilung Osteuropas und bedeutete für die baltischen Staaten den Beginn einer Fremdherrschaft, die erst 1989/90 endete."},"translationsA1":{"en":"On August 23, 1939, Germany and the Soviet Union sign a treaty. It is called the Hitler-Stalin Pact.","ar":"في 23 أغسطس 1939، وقّعت ألمانيا والاتحاد السوفيتي معاهدة. تسمى ميثاق هتلر-ستالين.","tr":"23 Ağustos 1939'da Almanya ve Sovyetler Birliği bir anlaşma imzaladı. Adı Hitler-Stalin Paktı.","ru":"23 августа 1939 года Германия и Советский Союз подписали договор. Он называется пакт Гитлера-Сталина.","es":"El 23 de agosto de 1939, Alemania y la Unión Soviética firman un tratado. Se llama el Pacto Hitler-Stalin.","fr":"Le 23 août 1939, l'Allemagne et l'Union soviétique signent un traité. Il s'appelle le pacte Hitler-Staline.","pl":"23 sierpnia 1939 roku Niemcy i Związek Radziecki podpisały traktat. Nazywa się paktem Hitler-Stalin.","uk":"23 серпня 1939 року Німеччина та Радянський Союз підписали договір. Він називається пактом Гітлера-Сталіна.","fa":"در ۲۳ اوت ۱۹۳۹، آلمان و اتحاد جماهیر شوروی پیمانی امضا کردند. نامش پیمان هیتلر-استالین است.","it":"Il 23 agosto 1939 la Germania e l'Unione Sovietica firmano un trattato. È chiamato patto Hitler-Stalin."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 23, 1939, Germany and the Soviet Union signed a non-aggression pact. It is called the Hitler-Stalin Pact.","ar":"في 23 أغسطس 1939، وقّعت ألمانيا والاتحاد السوفيتي اتفاقية عدم اعتداء. تُعرف باسم ميثاق هتلر-ستالين.","tr":"23 Ağustos 1939'da Almanya ve Sovyetler Birliği bir saldırmazlık paktı imzaladı. Buna Hitler-Stalin Paktı denir.","ru":"23 августа 1939 года Германия и Советский Союз подписали пакт о ненападении. Он называется пактом Гитлера-Сталина.","es":"El 23 de agosto de 1939, Alemania y la Unión Soviética firmaron un pacto de no agresión. Se le llama el Pacto Hitler-Stalin.","fr":"Le 23 août 1939, l'Allemagne et l'Union soviétique signent un pacte de non-agression. Il est appelé le pacte Hitler-Staline.","pl":"23 sierpnia 1939 roku Niemcy i Związek Radziecki podpisały pakt o nieagresji. Nazywa się go paktem Hitler-Stalin.","uk":"23 серпня 1939 року Німеччина та Радянський Союз підписали пакт про ненапад. Його називають пактом Гітлера-Сталіна.","fa":"در ۲۳ اوت ۱۹۳۹، آلمان و اتحاد جماهیر شوروی پیمان عدم تجاوز را امضا کردند. این پیمان، پیمان هیتلر-استالین نامیده می‌شود.","it":"Il 23 agosto 1939 la Germania e l'Unione Sovietica firmano un patto di non aggressione. Viene chiamato patto Hitler-Stalin."},"B1":{"en":"On the night of August 24, 1939, Germany and the Soviet Union signed the Hitler-Stalin Pact — a non-aggression treaty. It paved the way for the invasion of Poland a few days later.","ar":"في ليلة 24 أغسطس 1939، وقّعت ألمانيا والاتحاد السوفيتي ميثاق هتلر-ستالين — معاهدة عدم اعتداء. مهّد هذا الميثاق الطريق لغزو بولندا بعد أيام قليلة.","tr":"24 Ağustos 1939'a bağlayan gecede Almanya ve Sovyetler Birliği Hitler-Stalin Paktı'nı — bir saldırmazlık anlaşmasını — imzaladı. Bu, birkaç gün sonra Polonya'ya yapılan saldırının yolunu açtı.","ru":"В ночь на 24 августа 1939 года Германия и Советский Союз подписали пакт Гитлера-Сталина — договор о ненападении. Он проложил путь к нападению на Польшу несколько дней спустя.","es":"En la noche del 24 de agosto de 1939, Alemania y la Unión Soviética firmaron el Pacto Hitler-Stalin, un tratado de no agresión. Allanó el camino para la invasión de Polonia pocos días después.","fr":"Dans la nuit du 24 août 1939, l'Allemagne et l'Union soviétique signent le pacte Hitler-Staline, un traité de non-agression. Il ouvre la voie à l'invasion de la Pologne quelques jours plus tard.","pl":"W nocy z 23 na 24 sierpnia 1939 roku Niemcy i Związek Radziecki podpisały pakt Hitler-Stalin — traktat o nieagresji. Utorował on drogę do napaści na Polskę kilka dni później.","uk":"У ніч на 24 серпня 1939 року Німеччина та Радянський Союз підписали пакт Гітлера-Сталіна — договір про ненапад. Він проклав шлях до нападу на Польщу кількома днями пізніше.","fa":"در شب ۲۴ اوت ۱۹۳۹، آلمان و اتحاد جماهیر شوروی پیمان هیتلر-استالین را امضا کردند؛ پیمانی مبتنی بر عدم تجاوز. این پیمان راه را برای حمله به لهستان چند روز بعد هموار کرد.","it":"Nella notte tra il 23 e il 24 agosto 1939 la Germania e l'Unione Sovietica firmano il patto Hitler-Stalin, un trattato di non aggressione. Esso spiana la strada all'invasione della Polonia, che avverrà pochi giorni dopo."},"B2":{"en":"On the night of August 24, 1939, foreign ministers Ribbentrop and Molotov signed the German-Soviet non-aggression pact in Moscow. A secret additional protocol already divided Eastern Europe into spheres of interest in advance — the basis for the invasion of Poland nine days later.","ar":"في ليلة 24 أغسطس 1939، وقّع وزيرا الخارجية ريبنتروب ومولوتوف في موسكو ميثاق عدم الاعتداء الألماني-السوفيتي. قسّم بروتوكول سري إضافي أوروبا الشرقية مسبقاً إلى مناطق نفوذ — وهو الأساس لغزو بولندا بعد تسعة أيام.","tr":"24 Ağustos 1939'a bağlayan gecede Dışişleri Bakanları Ribbentrop ve Molotov, Moskova'da Alman-Sovyet saldırmazlık paktını imzaladı. Gizli bir ek protokol, Doğu Avrupa'yı önceden nüfuz alanlarına böldü — bu da dokuz gün sonraki Polonya işgalinin temelini oluşturdu.","ru":"В ночь на 24 августа 1939 года министры иностранных дел Риббентроп и Молотов подписали в Москве германо-советский пакт о ненападении. Секретный дополнительный протокол заранее разделил Восточную Европу на сферы интересов — основа для нападения на Польшу девять дней спустя.","es":"En la noche del 24 de agosto de 1939, los ministros de Exteriores Ribbentrop y Mólotov firmaron en Moscú el pacto de no agresión germano-soviético. Un protocolo secreto adicional ya dividía de antemano Europa del Este en esferas de interés, la base para la invasión de Polonia nueve días después.","fr":"Dans la nuit du 24 août 1939, les ministres des Affaires étrangères Ribbentrop et Molotov signent à Moscou le pacte germano-soviétique de non-agression. Un protocole secret additionnel divise déjà à l'avance l'Europe de l'Est en zones d'influence — la base de l'invasion de la Pologne neuf jours plus tard.","pl":"W nocy z 23 na 24 sierpnia 1939 roku ministrowie spraw zagranicznych Ribbentrop i Mołotow podpisali w Moskwie niemiecko-radziecki pakt o nieagresji. Tajny protokół dodatkowy już wcześniej dzielił Europę Wschodnią na strefy wpływów — podstawę napaści na Polskę dziewięć dni później.","uk":"У ніч на 24 серпня 1939 року міністри закордонних справ Ріббентроп і Молотов підписали в Москві німецько-радянський пакт про ненапад. Таємний додатковий протокол заздалегідь поділив Східну Європу на сфери впливу — основу для нападу на Польщу через дев'ять днів.","fa":"در شب ۲۴ اوت ۱۹۳۹، وزرای امور خارجه ریبنتروپ و مولوتوف در مسکو پیمان عدم تجاوز آلمان و شوروی را امضا کردند. یک پروتکل الحاقی مخفی از پیش اروپای شرقی را به مناطق نفوذ تقسیم کرد؛ زمینه‌ای برای حمله به لهستان نه روز بعد.","it":"Nella notte tra il 23 e il 24 agosto 1939 i ministri degli Esteri Ribbentrop e Molotov firmano a Mosca il patto di non aggressione tedesco-sovietico. Un protocollo segreto aggiuntivo divide già in anticipo l'Europa orientale in sfere di influenza — la base per l'invasione della Polonia, nove giorni più tardi."},"C1":{"en":"The German-Soviet non-aggression pact, signed on the night of August 24, 1939, secured Soviet neutrality for Hitler's already-decided invasion of Poland. A secret additional protocol regulated the division of Eastern and East-Central Europe into spheres of influence.","ar":"ضَمِن ميثاق عدم الاعتداء الألماني-السوفيتي، الموقّع في ليلة 24 أغسطس 1939، الحياد السوفيتي لهتلر من أجل غزو بولندا الذي كان قد تقرر بالفعل. نظّم بروتوكول سري إضافي تقسيم أوروبا الشرقية ووسط شرق أوروبا إلى مناطق نفوذ.","tr":"24 Ağustos 1939'a bağlayan gece imzalanan Alman-Sovyet saldırmazlık paktı, Hitler'e zaten karar verilmiş olan Polonya işgali için Sovyet tarafsızlığını sağladı. Gizli bir ek protokol, Doğu ve Doğu-Orta Avrupa'nın nüfuz alanlarına bölünmesini düzenledi.","ru":"Германо-советский пакт о ненападении, подписанный в ночь на 24 августа 1939 года, обеспечил Гитлеру советский нейтралитет для уже решённого нападения на Польшу. Секретный дополнительный протокол регулировал раздел Восточной и Центрально-Восточной Европы на сферы влияния.","es":"El pacto de no agresión germano-soviético, firmado en la noche del 24 de agosto de 1939, aseguró a Hitler la neutralidad soviética para la ya decidida invasión de Polonia. Un protocolo secreto adicional regulaba la división de Europa del Este y centro-oriental en esferas de influencia.","fr":"Le pacte germano-soviétique de non-agression, signé dans la nuit du 24 août 1939, garantit à Hitler la neutralité soviétique pour l'invasion de la Pologne déjà décidée. Un protocole secret additionnel réglait le partage de l'Europe orientale et centre-orientale en zones d'influence.","pl":"Niemiecko-radziecki pakt o nieagresji, podpisany w nocy z 23 na 24 sierpnia 1939 roku, zapewnił Hitlerowi radziecką neutralność wobec już postanowionej napaści na Polskę. Tajny protokół dodatkowy regulował podział Europy Wschodniej i Środkowo-Wschodniej na strefy wpływów.","uk":"Німецько-радянський пакт про ненапад, підписаний у ніч на 24 серпня 1939 року, забезпечив Гітлеру радянський нейтралітет для вже вирішеного нападу на Польщу. Таємний додатковий протокол регулював поділ Східної та Центрально-Східної Європи на сфери впливу.","fa":"پیمان عدم تجاوز آلمان و شوروی که در شب ۲۴ اوت ۱۹۳۹ امضا شد، بی‌طرفی شوروی را برای حمله‌ای که هیتلر از پیش برای لهستان تصمیم گرفته بود تضمین کرد. یک پروتکل الحاقی مخفی تقسیم اروپای شرقی و مرکزی-شرقی به مناطق نفوذ را تنظیم می‌کرد.","it":"Il patto di non aggressione tedesco-sovietico, firmato nella notte tra il 23 e il 24 agosto 1939, garantì a Hitler la neutralità sovietica per l'invasione della Polonia, già decisa. Un protocollo segreto aggiuntivo disciplinava la spartizione dell'Europa orientale e centro-orientale in sfere di influenza."},"C2":{"en":"The Hitler-Stalin Pact of August 23/24, 1939, ostensibly a peace treaty between ideological arch-enemies, turned out to be a cynical calculation of power politics: the secret additional protocol sealed the partition of Eastern Europe and meant, for the Baltic states, the beginning of a foreign domination that did not end until 1989/90.","ar":"تبيّن أن ميثاق هتلر-ستالين المؤرخ 23/24 أغسطس 1939، الذي بدا وكأنه معاهدة سلام بين عدوين أيديولوجيين لدودين، كان حساباً سياسياً واقعياً وقحاً: ختم البروتوكول السري الإضافي تقسيم أوروبا الشرقية، وعنى بالنسبة لدول البلطيق بداية سيطرة أجنبية لم تنتهِ إلا في 1989/90.","tr":"23/24 Ağustos 1939 tarihli Hitler-Stalin Paktı, görünüşte ideolojik baş düşmanlar arasında bir barış antlaşması olsa da, sinik bir güç politikası hesabı olduğu ortaya çıktı: Gizli ek protokol, Doğu Avrupa'nın paylaşımını mühürledi ve Baltık devletleri için ancak 1989/90'da sona erecek bir yabancı egemenliğin başlangıcı anlamına geldi.","ru":"Пакт Гитлера-Сталина от 23/24 августа 1939 года, внешне мирный договор между идеологическими заклятыми врагами, оказался циничным расчётом силовой политики: секретный дополнительный протокол закрепил раздел Восточной Европы и означал для прибалтийских государств начало иностранного господства, завершившегося лишь в 1989/90 годах.","es":"El Pacto Hitler-Stalin del 23/24 de agosto de 1939, aparentemente un tratado de paz entre enemigos ideológicos acérrimos, resultó ser un cínico cálculo de política de poder: el protocolo secreto adicional selló la partición de Europa del Este y significó, para los estados bálticos, el comienzo de un dominio extranjero que no terminó hasta 1989/90.","fr":"Le pacte Hitler-Staline du 23/24 août 1939, apparemment un traité de paix entre ennemis idéologiques jurés, s'est révélé être un cynique calcul de politique de puissance : le protocole secret additionnel scellait le partage de l'Europe de l'Est et signifiait, pour les États baltes, le début d'une domination étrangère qui ne prit fin qu'en 1989/90.","pl":"Pakt Hitler-Stalin z 23/24 sierpnia 1939 roku, pozornie traktat pokojowy między ideologicznymi zaciekłymi wrogami, okazał się cynicznym rachunkiem polityki siły: tajny protokół dodatkowy przypieczętował podział Europy Wschodniej i oznaczał dla państw bałtyckich początek obcego panowania, które zakończyło się dopiero w latach 1989/90.","uk":"Пакт Гітлера-Сталіна від 23/24 серпня 1939 року, на позір мирний договір між ідеологічними заклятими ворогами, виявився цинічним розрахунком силової політики: таємний додатковий протокол закріпив поділ Східної Європи і означав для балтійських держав початок чужоземного панування, яке закінчилося лише у 1989/90 роках.","fa":"پیمان هیتلر-استالین در ۲۳/۲۴ اوت ۱۹۳۹، که ظاهراً پیمانی صلح‌آمیز میان دو دشمن ایدئولوژیک دیرینه بود، در واقع محاسبه‌ای بی‌رحمانه در سیاست قدرت از آب درآمد: پروتکل الحاقی مخفی تقسیم اروپای شرقی را مهر و موم کرد و برای کشورهای بالتیک به معنای آغاز سلطه‌ای بیگانه بود که تنها در ۱۹۸۹/۹۰ پایان یافت.","it":"Il patto Hitler-Stalin del 23-24 agosto 1939, apparentemente un trattato di pace tra nemici ideologici giurati, si rivelò un cinico calcolo di potere: il protocollo segreto aggiuntivo sancì la spartizione dell'Europa orientale e significò, per gli Stati baltici, l'inizio di un dominio straniero che sarebbe finito soltanto nel 1989-90."}}},"08-24":{"year":1953,"levels":{"A1":"Am 24. August 1953 kommt der Zebrastreifen in die Verkehrsregeln. Autos müssen dort halten. So können Menschen sicher über die Straße gehen.","A2":"Am 24. August 1953 wird der Zebrastreifen in die deutsche Straßenverkehrsordnung aufgenommen. Vorher hatten Fußgänger dort keinen Vorrang. Erst 1964 mussten Autos wirklich anhalten.","B1":"Am 24. August 1953 nimmt die Straßenverkehrsordnung den Zebrastreifen auf. Zunächst blieb er eine Empfehlung — Autofahrer mussten noch nicht anhalten. Erst elf Jahre später bekam der Fußgänger dort ein echtes Vorrecht.","B2":"Am 24. August 1953 wird der Zebrastreifen eingeführt. Der Fall zeigt, wie langsam sich Verkehrsregeln durchsetzen: Zwischen Markierung und Vorrangregel lagen elf Jahre, in denen die Streifen vor allem eine Bitte waren. Regeln wirken erst, wenn sie eine Pflicht formulieren.","C1":"Die Einführung vom 24. August 1953 markiert einen frühen Schritt in einem langen Umdenken. Bis in die 1950er Jahre galt die Straße als Raum der Fahrzeuge, in dem Fußgänger sich einzurichten hatten. Die Verlagerung der Rücksichtspflicht auf den Stärkeren war eine der wirksamsten Sicherheitsmaßnahmen überhaupt.","C2":"Am 24. August 1953 begann eine Entwicklung, die bis heute nicht abgeschlossen ist. Wer im Verkehr Vorrang genießt, entscheidet darüber, wer sein Verhalten anpassen muss — und damit indirekt, wer im Zweifel verunglückt. Verkehrsregeln sind deshalb nie bloß technische Ordnungen, sondern Verteilungsentscheidungen über Risiko."},"translationsA1":{"en":"On August 24, 1953, the zebra crossing enters the traffic rules. Cars have to stop there. That way people can cross the street safely.","ar":"في 24 أغسطس 1953، دخل ممر المشاة قواعد المرور. على السيارات أن تقف هناك. هكذا يعبر الناس الشارع بأمان.","tr":"24 Ağustos 1953'te yaya geçidi trafik kurallarına girdi. Arabalar orada durmak zorunda. Böylece insanlar caddeyi güvenle geçebilir.","ru":"24 августа 1953 года пешеходный переход вошёл в правила дорожного движения. Машины должны там останавливаться. Так люди безопасно переходят улицу.","es":"El 24 de agosto de 1953, el paso de cebra entra en las normas de tráfico. Los coches deben detenerse allí. Así la gente puede cruzar con seguridad.","fr":"Le 24 août 1953, le passage piéton entre dans le code de la route. Les voitures doivent s'y arrêter. Les gens peuvent ainsi traverser en sécurité.","pl":"24 sierpnia 1953 roku przejście dla pieszych weszło do przepisów drogowych. Samochody muszą tam stanąć. Dzięki temu ludzie bezpiecznie przechodzą przez ulicę.","uk":"24 серпня 1953 року пішохідний перехід увійшов до правил дорожнього руху. Автомобілі мають там зупинятися. Так люди безпечно переходять вулицю.","fa":"در ۲۴ اوت ۱۹۵۳، خط‌کشی عابر پیاده وارد قوانین راهنمایی شد. خودروها باید آنجا بایستند. این‌گونه مردم با ایمنی از خیابان می‌گذرند.","it":"Il 24 agosto 1953 le strisce pedonali entrano nel codice della strada tedesco. Le auto devono fermarsi. Così le persone possono attraversare la strada in sicurezza."},"translationsByLevel":{"A2":{"en":"On August 24, 1953, the zebra crossing was added to the German road traffic regulations. Before that, pedestrians had no right of way there. Only in 1964 did cars actually have to stop.","ar":"في 24 أغسطس 1953، أُدرج ممر المشاة (زيبرا) في نظام المرور الألماني. قبل ذلك لم يكن للمشاة أولوية هناك. لم تُجبر السيارات على التوقف فعلياً إلا في عام 1964.","tr":"24 Ağustos 1953'te yaya geçidi (zebra) Alman trafik yönetmeliğine dahil edildi. Daha önce yayaların orada önceliği yoktu. Arabaların gerçekten durması gerekliliği ancak 1964'te geldi.","ru":"24 августа 1953 года пешеходный переход «зебра» был включён в немецкие правила дорожного движения. До этого у пешеходов там не было преимущества. Только в 1964 году автомобили действительно должны были останавливаться.","es":"El 24 de agosto de 1953, el paso de cebra se incorporó al reglamento de tráfico alemán. Antes, los peatones no tenían preferencia allí. Solo en 1964 los coches tuvieron que detenerse realmente.","fr":"Le 24 août 1953, le passage pour piétons (zébré) est intégré au code de la route allemand. Auparavant, les piétons n'y avaient pas la priorité. Ce n'est qu'en 1964 que les voitures ont vraiment dû s'arrêter.","pl":"24 sierpnia 1953 roku pasy dla pieszych zostały wprowadzone do niemieckiego kodeksu drogowego. Wcześniej piesi nie mieli tam pierwszeństwa. Dopiero w 1964 roku samochody rzeczywiście musiały się zatrzymywać.","uk":"24 серпня 1953 року пішохідний перехід «зебра» було включено до німецьких правил дорожнього руху. До цього пішоходи там не мали переваги. Лише у 1964 році автомобілі справді мусили зупинятися.","fa":"در ۲۴ اوت ۱۹۵۳، خط عابر پیاده (گورخری) در آیین‌نامه راهنمایی و رانندگی آلمان گنجانده شد. پیش از آن، عابران پیاده در آنجا حق تقدم نداشتند. تنها از سال ۱۹۶۴ بود که خودروها واقعاً موظف به توقف شدند.","it":"Il 24 agosto 1953 le strisce pedonali vengono introdotte nel codice della strada tedesco. Prima di allora i pedoni non avevano lì alcuna precedenza. Solo nel 1964 le auto furono davvero obbligate a fermarsi."},"B1":{"en":"On August 24, 1953, the road traffic regulations adopted the zebra crossing. At first it remained a recommendation — drivers did not yet have to stop. Only eleven years later did pedestrians get a real right of way there.","ar":"في 24 أغسطس 1953، أضاف نظام المرور ممر المشاة. ظل في البداية مجرد توصية — لم يكن على السائقين التوقف بعد. لم يحصل المشاة على حق أولوية حقيقي هناك إلا بعد أحد عشر عاماً.","tr":"24 Ağustos 1953'te trafik yönetmeliği yaya geçidini kabul etti. Başlangıçta bu sadece bir tavsiye olarak kaldı — sürücülerin henüz durması gerekmiyordu. Yayalar orada gerçek bir önceliğe ancak on bir yıl sonra kavuştu.","ru":"24 августа 1953 года правила дорожного движения включили пешеходный переход-«зебру». Поначалу это оставалось лишь рекомендацией — водителям ещё не нужно было останавливаться. Только одиннадцать лет спустя пешеход получил там настоящее преимущество.","es":"El 24 de agosto de 1953, el reglamento de tráfico incorporó el paso de cebra. Al principio siguió siendo una recomendación: los conductores aún no tenían que detenerse. Solo once años después el peatón obtuvo allí un verdadero derecho de preferencia.","fr":"Le 24 août 1953, le code de la route adopte le passage pour piétons. Au début, il restait une simple recommandation — les automobilistes n'étaient pas encore obligés de s'arrêter. Ce n'est que onze ans plus tard que le piéton y a obtenu un véritable droit de priorité.","pl":"24 sierpnia 1953 roku kodeks drogowy wprowadził pasy dla pieszych. Początkowo pozostawały one jedynie zaleceniem — kierowcy nie musieli jeszcze się zatrzymywać. Dopiero jedenaście lat później pieszy uzyskał tam prawdziwe pierwszeństwo.","uk":"24 серпня 1953 року правила дорожнього руху включили пішохідний перехід «зебру». Спочатку це залишалося лише рекомендацією — водії ще не мусили зупинятися. Лише через одинадцять років пішохід отримав там справжню перевагу.","fa":"در ۲۴ اوت ۱۹۵۳، آیین‌نامه راهنمایی و رانندگی خط عابر پیاده را پذیرفت. در ابتدا این فقط یک توصیه بود؛ رانندگان هنوز مجبور به توقف نبودند. تنها یازده سال بعد بود که عابران پیاده در آنجا حق تقدم واقعی به دست آوردند.","it":"Il 24 agosto 1953 il codice della strada tedesco introduce le strisce pedonali. Inizialmente restarono una semplice raccomandazione: gli automobilisti non erano ancora obbligati a fermarsi. Solo undici anni dopo il pedone ottenne lì un vero diritto di precedenza."},"B2":{"en":"On August 24, 1953, the zebra crossing was introduced. The case shows how slowly traffic rules take hold: eleven years lay between the marking and the right-of-way rule, during which the stripes were mainly a request. Rules only work once they formulate an obligation.","ar":"في 24 أغسطس 1953، تم إدخال ممر المشاة. توضح هذه الحالة مدى بطء ترسخ قواعد المرور: مرت أحد عشر عاماً بين وضع العلامة وقاعدة الأولوية، كانت خلالها الخطوط بمثابة رجاء في المقام الأول. لا تُصبح القواعد فعّالة إلا عندما تصوغ التزاماً.","tr":"24 Ağustos 1953'te yaya geçidi tanıtıldı. Bu durum, trafik kurallarının ne kadar yavaş yerleştiğini gösteriyor: işaretleme ile öncelik kuralı arasında, çizgilerin öncelikle bir rica olarak kaldığı on bir yıl geçti. Kurallar ancak bir yükümlülük ifade ettiğinde işe yarar.","ru":"24 августа 1953 года был введён пешеходный переход-«зебра». Этот случай показывает, насколько медленно приживаются правила дорожного движения: между разметкой и правилом приоритета прошло одиннадцать лет, в течение которых полосы были прежде всего просьбой. Правила действуют лишь тогда, когда формулируют обязанность.","es":"El 24 de agosto de 1953 se introdujo el paso de cebra. El caso muestra lo lentamente que se imponen las normas de tráfico: entre la señalización y la norma de prioridad pasaron once años, durante los cuales las franjas eran ante todo una petición. Las normas solo funcionan cuando formulan una obligación.","fr":"Le 24 août 1953, le passage pour piétons est introduit. Ce cas montre à quel point les règles de circulation s'imposent lentement : onze ans séparaient le marquage de la règle de priorité, période durant laquelle les bandes n'étaient guère qu'une prière. Les règles n'agissent que lorsqu'elles formulent une obligation.","pl":"24 sierpnia 1953 roku wprowadzono pasy dla pieszych. Ten przypadek pokazuje, jak wolno wprowadzają się przepisy drogowe: między oznakowaniem a zasadą pierwszeństwa minęło jedenaście lat, w czasie których pasy były przede wszystkim prośbą. Przepisy działają dopiero wtedy, gdy formułują obowiązek.","uk":"24 серпня 1953 року було запроваджено пішохідний перехід «зебру». Цей випадок показує, як повільно приживаються правила дорожнього руху: між розміткою та правилом пріоритету минуло одинадцять років, протягом яких смуги були передусім проханням. Правила діють лише тоді, коли формулюють обов'язок.","fa":"در ۲۴ اوت ۱۹۵۳ خط عابر پیاده معرفی شد. این نمونه نشان می‌دهد قوانین راهنمایی و رانندگی چقدر به‌کندی جا می‌افتند: میان علامت‌گذاری و قاعده حق تقدم یازده سال فاصله بود که در طی آن این خطوط بیشتر یک درخواست بودند. قوانین تنها زمانی اثر می‌کنند که یک الزام را بیان کنند.","it":"Il 24 agosto 1953 vengono introdotte le strisce pedonali. Il caso mostra quanto lentamente si affermino le norme del traffico: tra la segnaletica e la regola di precedenza trascorsero undici anni, durante i quali le strisce erano soprattutto una richiesta. Le regole diventano efficaci solo quando formulano un obbligo."},"C1":{"en":"The introduction on August 24, 1953, marks an early step in a long rethinking. Into the 1950s, the street was considered a space for vehicles, in which pedestrians had to accommodate themselves. Shifting the duty of care onto the stronger party was one of the most effective safety measures of all.","ar":"يمثل إدخال هذا النظام في 24 أغسطس 1953 خطوة مبكرة في إعادة تفكير طويلة. حتى خمسينيات القرن الماضي، كان يُنظر إلى الشارع على أنه فضاء للمركبات، كان على المشاة أن يتكيفوا معه. كان نقل واجب المراعاة إلى الطرف الأقوى واحداً من أنجع إجراءات السلامة على الإطلاق.","tr":"24 Ağustos 1953 tarihli bu düzenleme, uzun bir zihniyet değişiminde erken bir adımı işaret eder. 1950'lere kadar cadde, yayaların uyum sağlaması gereken bir araç alanı olarak görülüyordu. Dikkat yükümlülüğünün daha güçlü tarafa kaydırılması, en etkili güvenlik önlemlerinden biriydi.","ru":"Введение этой нормы 24 августа 1953 года стало ранним шагом в долгом переосмыслении. Вплоть до 1950-х годов улица считалась пространством транспортных средств, к которому пешеходам приходилось приспосабливаться. Перенос обязанности проявлять осторожность на более сильную сторону стал одной из самых эффективных мер безопасности вообще.","es":"La introducción del 24 de agosto de 1953 marca un paso temprano en un largo cambio de mentalidad. Hasta los años cincuenta, la calle se consideraba un espacio para los vehículos, al que los peatones debían adaptarse. Trasladar el deber de precaución a la parte más fuerte fue una de las medidas de seguridad más eficaces que existen.","fr":"L'introduction du 24 août 1953 marque une étape précoce dans un long changement de mentalité. Jusque dans les années 1950, la rue était considérée comme un espace réservé aux véhicules, auquel les piétons devaient s'adapter. Le transfert du devoir de vigilance vers la partie la plus forte fut l'une des mesures de sécurité les plus efficaces qui soient.","pl":"Wprowadzenie z 24 sierpnia 1953 roku wyznacza wczesny krok w długiej zmianie myślenia. Aż do lat 50. XX wieku ulica uchodziła za przestrzeń pojazdów, do której musieli dostosować się piesi. Przeniesienie obowiązku ostrożności na stronę silniejszą było jednym z najskuteczniejszych środków bezpieczeństwa w ogóle.","uk":"Запровадження від 24 серпня 1953 року стало раннім кроком у тривалому переосмисленні. Аж до 1950-х років вулиця вважалася простором транспортних засобів, до якого мали пристосовуватися пішоходи. Перенесення обов'язку обачності на сильнішу сторону було одним із найефективніших заходів безпеки взагалі.","fa":"این اقدام در ۲۴ اوت ۱۹۵۳ گامی زودهنگام در یک بازاندیشی طولانی بود. تا دهه ۱۹۵۰، خیابان فضایی برای وسایل نقلیه تلقی می‌شد که عابران پیاده باید خود را با آن وفق می‌دادند. انتقال وظیفه مراقبت به طرف قوی‌تر یکی از مؤثرترین اقدامات ایمنی به شمار می‌رود.","it":"L'introduzione del 24 agosto 1953 segna un primo passo in un lungo cambiamento di mentalità. Fino agli anni Cinquanta la strada era considerata uno spazio dei veicoli, in cui i pedoni dovevano adattarsi. Lo spostamento dell'obbligo di attenzione sulla parte più forte fu una delle misure di sicurezza più efficaci in assoluto."},"C2":{"en":"On August 24, 1953, a development began that is still not complete today. Whoever enjoys right of way in traffic determines who must adjust their behavior — and thus, indirectly, who is likely to be injured in case of doubt. Traffic rules are therefore never merely technical arrangements, but decisions about the distribution of risk.","ar":"في 24 أغسطس 1953، بدأ تطور لم يكتمل حتى اليوم. من يتمتع بالأولوية في المرور يقرر من عليه تعديل سلوكه — وبذلك، بشكل غير مباشر، من سيتعرض للحادث عند الشك. لذلك لا تُعد قواعد المرور مجرد أنظمة تقنية، بل قرارات توزيع للمخاطر.","tr":"24 Ağustos 1953'te bugün hâlâ tamamlanmamış bir gelişme başladı. Trafikte önceliğe sahip olan, kimin davranışını uyarlaması gerektiğine — ve dolayısıyla dolaylı olarak şüphe durumunda kimin kazaya uğrayacağına — karar verir. Bu nedenle trafik kuralları asla sadece teknik düzenlemeler değil, risk dağılımı kararlarıdır.","ru":"24 августа 1953 года началось развитие, которое не завершено и по сей день. Тот, кто пользуется преимуществом в движении, определяет, кто должен изменить своё поведение — а значит, косвенно, кто в случае сомнения пострадает. Поэтому правила дорожного движения никогда не являются просто техническими предписаниями, а представляют собой решения о распределении риска.","es":"El 24 de agosto de 1953 comenzó un desarrollo que aún hoy no ha concluido. Quien goza de prioridad en el tráfico determina quién debe adaptar su comportamiento, y con ello, indirectamente, quién resultará accidentado en caso de duda. Las normas de tráfico nunca son, por tanto, meros ordenamientos técnicos, sino decisiones sobre el reparto del riesgo.","fr":"Le 24 août 1953 a commencé une évolution qui n'est toujours pas achevée aujourd'hui. Celui qui bénéficie de la priorité dans la circulation détermine qui doit adapter son comportement — et donc, indirectement, qui risque d'être accidenté en cas de doute. Les règles de circulation ne sont donc jamais de simples dispositifs techniques, mais des décisions de répartition du risque.","pl":"24 sierpnia 1953 roku rozpoczął się proces, który do dziś nie został zakończony. Ten, kto ma pierwszeństwo w ruchu drogowym, decyduje o tym, kto musi dostosować swoje zachowanie — a tym samym pośrednio, kto w razie wątpliwości ulegnie wypadkowi. Przepisy drogowe nigdy więc nie są jedynie technicznymi regulacjami, lecz decyzjami o rozłożeniu ryzyka.","uk":"24 серпня 1953 року розпочався процес, який не завершений і донині. Той, хто має перевагу в русі, визначає, хто повинен змінити свою поведінку — а отже, опосередковано, хто в разі сумніву постраждає. Тому правила дорожнього руху ніколи не є лише технічними приписами, а є рішеннями про розподіл ризику.","fa":"در ۲۴ اوت ۱۹۵۳ روندی آغاز شد که تا امروز به پایان نرسیده است. هر که در ترافیک حق تقدم دارد، تعیین می‌کند چه کسی باید رفتار خود را تطبیق دهد — و از این طریق، به‌طور غیرمستقیم، چه کسی در صورت تردید دچار حادثه می‌شود. از این‌رو قوانین راهنمایی و رانندگی هرگز صرفاً مقررات فنی نیستند، بلکه تصمیماتی درباره توزیع ریسک‌اند.","it":"Il 24 agosto 1953 ebbe inizio un processo tuttora non concluso. Chi gode di precedenza nel traffico determina indirettamente chi deve adattare il proprio comportamento — e dunque, in caso di dubbio, chi rischia di subire un incidente. Le regole della circolazione non sono quindi mai semplici ordinamenti tecnici, ma decisioni sulla distribuzione del rischio."}},"sideFacts":[]},"08-25":{"year":1967,"levels":{"A1":"Am 25. August 1967 startet in Deutschland das Farbfernsehen. Vorher war Fernsehen nur schwarz-weiß.","A2":"Am 25. August 1967 startet in Deutschland offiziell das Farbfernsehen. Die Einführung findet auf der Internationalen Funkausstellung in Berlin statt.","B1":"Am 25. August 1967 wird auf der Internationalen Funkausstellung in Berlin das Farbfernsehen in Deutschland eingeführt. Bis dahin konnte man nur in Schwarz-Weiß fernsehen.","B2":"Am 25. August 1967 drückt der damalige Vizekanzler Willy Brandt auf der Internationalen Funkausstellung in Berlin symbolisch einen roten Knopf und schaltet damit offiziell das Farbfernsehen in Deutschland frei — allerdings besitzen zu diesem Zeitpunkt nur wenige Haushalte überhaupt ein Farbfernsehgerät.","C1":"Die symbolische Einschaltung des Farbfernsehens durch Willy Brandt am 25. August 1967 auf der Internationalen Funkausstellung markiert einen medientechnischen Meilenstein, dessen gesellschaftliche Wirkung sich erst über die folgenden Jahre entfaltete, da Farbfernsehgeräte anfangs teuer und selten waren.","C2":"Die feierliche Einführung des Farbfernsehens 1967 illustriert exemplarisch, wie technologische Innovationen und ihre tatsächliche gesellschaftliche Durchdringung zeitlich auseinanderfallen können: Trotz des symbolträchtigen Startknopfdrucks dauerte es noch über ein Jahrzehnt, bis Farbfernseher in deutschen Wohnzimmern zur Selbstverständlichkeit wurden."},"translationsA1":{"en":"On August 25, 1967, color television starts in Germany. Before that, TV was only black and white.","ar":"في 25 أغسطس 1967، بدأ التلفزيون الملون في ألمانيا. قبل ذلك كان التلفزيون بالأبيض والأسود فقط.","tr":"25 Ağustos 1967'de Almanya'da renkli televizyon başladı. Daha önce televizyon sadece siyah-beyazdı.","ru":"25 августа 1967 года в Германии началось цветное телевидение. До этого телевидение было только чёрно-белым.","es":"El 25 de agosto de 1967, comienza la televisión en color en Alemania. Antes, la televisión era solo en blanco y negro.","fr":"Le 25 août 1967, la télévision en couleur démarre en Allemagne. Avant, la télévision était seulement en noir et blanc.","pl":"25 sierpnia 1967 roku w Niemczech zaczęła się telewizja kolorowa. Wcześniej telewizja była tylko czarno-biała.","uk":"25 серпня 1967 року в Німеччині почалося кольорове телебачення. До того телебачення було лише чорно-білим.","fa":"در ۲۵ اوت ۱۹۶۷، تلویزیون رنگی در آلمان آغاز شد. قبل از آن، تلویزیون فقط سیاه و سفید بود.","it":"Il 25 agosto 1967 parte in Germania la televisione a colori. Prima la televisione era solo in bianco e nero."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 25, 1967, color television officially started in Germany. The launch took place at the International Radio Exhibition in Berlin.","ar":"في 25 أغسطس 1967، انطلق التلفزيون الملون رسمياً في ألمانيا. جرى الإطلاق في معرض البث الدولي في برلين.","tr":"25 Ağustos 1967'de Almanya'da renkli televizyon resmi olarak başladı. Tanıtım, Berlin'deki Uluslararası Radyo Sergisi'nde gerçekleşti.","ru":"25 августа 1967 года в Германии официально стартовало цветное телевидение. Запуск состоялся на Международной радиовыставке в Берлине.","es":"El 25 de agosto de 1967, la televisión en color comenzó oficialmente en Alemania. El lanzamiento tuvo lugar en la Exposición Internacional de Radio en Berlín.","fr":"Le 25 août 1967, la télévision en couleur démarre officiellement en Allemagne. Le lancement a lieu au Salon international de la radio à Berlin.","pl":"25 sierpnia 1967 roku w Niemczech oficjalnie wystartowała telewizja kolorowa. Wprowadzenie miało miejsce na Międzynarodowych Targach Radiowych w Berlinie.","uk":"25 серпня 1967 року в Німеччині офіційно стартувало кольорове телебачення. Запуск відбувся на Міжнародній радіовиставці в Берліні.","fa":"در ۲۵ اوت ۱۹۶۷، تلویزیون رنگی به‌طور رسمی در آلمان آغاز شد. این رویداد در نمایشگاه بین‌المللی رادیو در برلین برگزار شد.","it":"Il 25 agosto 1967 la televisione a colori viene ufficialmente lanciata in Germania. L'inaugurazione avviene alla Fiera Internazionale della Radio di Berlino."},"B1":{"en":"On August 25, 1967, color television was introduced in Germany at the International Radio Exhibition in Berlin. Until then, people could only watch television in black and white.","ar":"في 25 أغسطس 1967، تم تقديم التلفزيون الملون في ألمانيا في معرض البث الدولي في برلين. حتى ذلك الحين، لم يكن بالإمكان مشاهدة التلفزيون إلا بالأبيض والأسود.","tr":"25 Ağustos 1967'de Berlin'deki Uluslararası Radyo Sergisi'nde Almanya'da renkli televizyon tanıtıldı. O zamana kadar sadece siyah beyaz televizyon izlenebiliyordu.","ru":"25 августа 1967 года на Международной радиовыставке в Берлине в Германии было введено цветное телевидение. До этого смотреть телевизор можно было только в чёрно-белом изображении.","es":"El 25 de agosto de 1967 se introdujo la televisión en color en Alemania en la Exposición Internacional de Radio en Berlín. Hasta entonces solo se podía ver la televisión en blanco y negro.","fr":"Le 25 août 1967, la télévision en couleur est introduite en Allemagne lors du Salon international de la radio à Berlin. Jusque-là, on ne pouvait regarder la télévision qu'en noir et blanc.","pl":"25 sierpnia 1967 roku na Międzynarodowych Targach Radiowych w Berlinie wprowadzono w Niemczech telewizję kolorową. Do tej pory telewizję można było oglądać tylko czarno-białą.","uk":"25 серпня 1967 року на Міжнародній радіовиставці в Берліні в Німеччині запровадили кольорове телебачення. До цього дивитися телевізор можна було лише в чорно-білому зображенні.","fa":"در ۲۵ اوت ۱۹۶۷، تلویزیون رنگی در نمایشگاه بین‌المللی رادیو در برلین به آلمان معرفی شد. تا پیش از آن، تماشای تلویزیون تنها به‌صورت سیاه و سفید ممکن بود.","it":"Il 25 agosto 1967, alla Fiera Internazionale della Radio di Berlino, viene introdotta in Germania la televisione a colori. Fino ad allora si poteva guardare la TV solo in bianco e nero."},"B2":{"en":"On August 25, 1967, the then Vice Chancellor Willy Brandt symbolically pressed a red button at the International Radio Exhibition in Berlin, officially launching color television in Germany — although at this point only a few households actually owned a color television set.","ar":"في 25 أغسطس 1967، ضغط نائب المستشار آنذاك فيلي براندت رمزياً على زر أحمر في معرض البث الدولي في برلين، ليطلق بذلك رسمياً التلفزيون الملون في ألمانيا — رغم أن عدداً قليلاً فقط من الأسر كان يمتلك جهاز تلفزيون ملون في ذلك الوقت.","tr":"25 Ağustos 1967'de dönemin Başbakan Yardımcısı Willy Brandt, Berlin'deki Uluslararası Radyo Sergisi'nde sembolik olarak kırmızı bir düğmeye basarak Almanya'da renkli televizyonu resmen açtı — ancak o dönemde çok az hane zaten bir renkli televizyon cihazına sahipti.","ru":"25 августа 1967 года тогдашний вице-канцлер Вилли Брандт символически нажал красную кнопку на Международной радиовыставке в Берлине и тем самым официально запустил цветное телевидение в Германии — хотя на тот момент лишь немногие семьи вообще имели цветной телевизор.","es":"El 25 de agosto de 1967, el entonces vicecanciller Willy Brandt pulsó simbólicamente un botón rojo en la Exposición Internacional de Radio en Berlín, dando así comienzo oficialmente a la televisión en color en Alemania, aunque en ese momento solo pocos hogares poseían siquiera un televisor en color.","fr":"Le 25 août 1967, le vice-chancelier de l'époque, Willy Brandt, appuie symboliquement sur un bouton rouge lors du Salon international de la radio à Berlin et lance ainsi officiellement la télévision en couleur en Allemagne — bien qu'à cette date, peu de foyers possèdent seulement un téléviseur couleur.","pl":"25 sierpnia 1967 roku ówczesny wicekanclerz Willy Brandt symbolicznie nacisnął czerwony przycisk na Międzynarodowych Targach Radiowych w Berlinie, oficjalnie uruchamiając telewizję kolorową w Niemczech — choć w tym momencie zaledwie nieliczne gospodarstwa domowe w ogóle posiadały odbiornik kolorowy.","uk":"25 серпня 1967 року тодішній віцеканцлер Віллі Брандт символічно натиснув червону кнопку на Міжнародній радіовиставці в Берліні, офіційно запустивши кольорове телебачення в Німеччині — хоча на той момент лише небагато сімей взагалі мали кольоровий телевізор.","fa":"در ۲۵ اوت ۱۹۶۷، ویلی برانت، صدراعظم فرعی وقت، به‌طور نمادین دکمه‌ای قرمز را در نمایشگاه بین‌المللی رادیو در برلین فشرد و بدین‌سان تلویزیون رنگی را رسماً در آلمان فعال کرد — هرچند در آن زمان تنها تعداد کمی از خانوارها اصلاً دستگاه تلویزیون رنگی داشتند.","it":"Il 25 agosto 1967 l'allora vicecancelliere Willy Brandt preme simbolicamente un pulsante rosso alla Fiera Internazionale della Radio di Berlino, avviando ufficialmente la televisione a colori in Germania — anche se, a quel tempo, solo poche famiglie possiedono davvero un televisore a colori."},"C1":{"en":"The symbolic switching-on of color television by Willy Brandt on August 25, 1967, at the International Radio Exhibition marks a milestone in media technology, whose social impact only unfolded over the following years, since color television sets were initially expensive and rare.","ar":"يشكل تشغيل التلفزيون الملون رمزياً بواسطة فيلي براندت في 25 أغسطس 1967 في معرض البث الدولي معلماً بارزاً في تقنية الإعلام، لم يظهر أثره الاجتماعي إلا على مدى السنوات التالية، إذ كانت أجهزة التلفزيون الملون في البداية باهظة الثمن ونادرة.","tr":"Willy Brandt'ın 25 Ağustos 1967'de Uluslararası Radyo Sergisi'nde renkli televizyonu sembolik olarak devreye alması, medya teknolojisinde bir dönüm noktasını işaret eder; bu gelişmenin toplumsal etkisi ise renkli televizyon cihazlarının başlangıçta pahalı ve nadir olması nedeniyle ancak izleyen yıllarda ortaya çıktı.","ru":"Символическое включение цветного телевидения Вилли Брандтом 25 августа 1967 года на Международной радиовыставке стало вехой в развитии медиатехники, чьё общественное воздействие проявилось лишь в последующие годы, поскольку цветные телевизоры поначалу были дорогими и редкими.","es":"El encendido simbólico de la televisión en color por Willy Brandt el 25 de agosto de 1967 en la Exposición Internacional de Radio marca un hito en la tecnología mediática, cuyo impacto social solo se desplegó en los años siguientes, ya que los televisores en color eran al principio caros y escasos.","fr":"L'allumage symbolique de la télévision en couleur par Willy Brandt le 25 août 1967 au Salon international de la radio marque un jalon dans l'histoire des médias, dont l'impact social ne s'est déployé qu'au fil des années suivantes, les téléviseurs couleur étant au départ chers et rares.","pl":"Symboliczne uruchomienie telewizji kolorowej przez Willy'ego Brandta 25 sierpnia 1967 roku na Międzynarodowych Targach Radiowych stanowi kamień milowy w technologii medialnej, którego społeczny wpływ ujawnił się dopiero w kolejnych latach, ponieważ odbiorniki kolorowe były początkowo drogie i rzadkie.","uk":"Символічне увімкнення кольорового телебачення Віллі Брандтом 25 серпня 1967 року на Міжнародній радіовиставці стало віхою в розвитку медіатехніки, суспільний вплив якої проявився лише в наступні роки, оскільки кольорові телевізори спочатку були дорогими й рідкісними.","fa":"روشن‌سازی نمادین تلویزیون رنگی توسط ویلی برانت در ۲۵ اوت ۱۹۶۷ در نمایشگاه بین‌المللی رادیو، نقطه عطفی در فناوری رسانه به شمار می‌رود که تأثیر اجتماعی آن تنها طی سال‌های بعد آشکار شد، زیرا دستگاه‌های تلویزیون رنگی در آغاز گران و کمیاب بودند.","it":"L'accensione simbolica della televisione a colori da parte di Willy Brandt il 25 agosto 1967, alla Fiera Internazionale della Radio, segna una pietra miliare nella storia dei media, il cui effetto sociale si dispiegò solo negli anni successivi, poiché inizialmente i televisori a colori erano costosi e rari."},"C2":{"en":"The ceremonial introduction of color television in 1967 illustrates exemplarily how technological innovations and their actual social penetration can diverge in time: despite the symbolically charged push of the start button, it took more than a decade before color televisions became a matter of course in German living rooms.","ar":"يوضح الإدخال الاحتفالي للتلفزيون الملون عام 1967 بشكل نموذجي كيف يمكن أن يتباعد زمنياً الابتكار التكنولوجي عن انتشاره الاجتماعي الفعلي: فرغم الضغطة الرمزية على زر البدء، استغرق الأمر أكثر من عقد حتى أصبح التلفزيون الملون أمراً بديهياً في غرف المعيشة الألمانية.","tr":"1967'deki renkli televizyonun törensel şekilde tanıtılması, teknolojik yeniliklerin ve bunların gerçek toplumsal yayılımının zaman içinde nasıl ayrışabileceğini örnek olarak gösterir: sembolik başlatma düğmesine basılmasına rağmen, renkli televizyonların Alman oturma odalarında sıradanlaşması on yıldan fazla sürdü.","ru":"Торжественное введение цветного телевидения в 1967 году наглядно иллюстрирует, как технологические новшества и их реальное проникновение в общество могут расходиться во времени: несмотря на символическое нажатие стартовой кнопки, прошло более десятилетия, прежде чем цветные телевизоры стали чем-то само собой разумеющимся в немецких гостиных.","es":"La introducción festiva de la televisión en color en 1967 ilustra de manera ejemplar cómo las innovaciones tecnológicas y su penetración social real pueden estar temporalmente desfasadas: pese a la simbólica pulsación del botón de inicio, pasó más de una década antes de que los televisores en color se convirtieran en algo natural en los salones alemanes.","fr":"L'introduction solennelle de la télévision en couleur en 1967 illustre de façon exemplaire comment les innovations technologiques et leur pénétration sociale effective peuvent être décalées dans le temps : malgré la pression symbolique du bouton de mise en marche, il fallut plus d'une décennie pour que les téléviseurs couleur deviennent une évidence dans les salons allemands.","pl":"Uroczyste wprowadzenie telewizji kolorowej w 1967 roku ilustruje przykładowo, jak innowacje technologiczne i ich rzeczywiste przenikanie do społeczeństwa mogą się rozmijać w czasie: mimo symbolicznego naciśnięcia przycisku startowego minęło ponad dziesięć lat, zanim kolorowe telewizory stały się czymś oczywistym w niemieckich salonach.","uk":"Урочисте запровадження кольорового телебачення 1967 року показово ілюструє, як технологічні інновації та їхнє реальне проникнення в суспільство можуть розходитися в часі: попри символічне натискання стартової кнопки, минуло більше десятиліття, перш ніж кольорові телевізори стали звичною річчю в німецьких вітальнях.","fa":"معرفی تشریفاتی تلویزیون رنگی در سال ۱۹۶۷ به‌روشنی نشان می‌دهد که چگونه نوآوری‌های فناورانه و نفوذ اجتماعی واقعی آن‌ها می‌توانند از نظر زمانی از هم فاصله بگیرند: با وجود فشردن نمادین دکمه آغاز، بیش از یک دهه طول کشید تا تلویزیون‌های رنگی در خانه‌های آلمانی امری بدیهی شوند.","it":"La solenne introduzione della televisione a colori nel 1967 illustra in modo esemplare come le innovazioni tecnologiche e la loro effettiva diffusione sociale possano essere separate nel tempo: nonostante il simbolico gesto inaugurale, ci vollero oltre dieci anni prima che il televisore a colori diventasse un elemento scontato dei salotti tedeschi."}}},"08-26":{"year":1807,"levels":{"A1":"Am 26. August 1807 führt Bayern eine Impfpflicht ein. Alle Kinder sollen gegen Pocken geimpft werden. Kein Land hat das vorher gemacht.","A2":"Am 26. August 1807 führt das Königreich Bayern als erster Staat der Welt eine Impfpflicht gegen Pocken ein. Die Pocken töteten damals jedes Jahr Tausende Kinder. Innerhalb weniger Jahrzehnte verschwand die Krankheit dort fast völlig.","B1":"Am 26. August 1807 beschließt Bayern die weltweit erste Impfpflicht. Die Pockenimpfung war erst elf Jahre zuvor entwickelt worden. Der Staat entschied, dass der Schutz aller wichtiger sei als die Wahlfreiheit des Einzelnen — eine Abwägung, über die bis heute gestritten wird.","B2":"Am 26. August 1807 führt Bayern eine Impfpflicht ein, als noch niemand genau erklären konnte, warum die Impfung wirkt. Man wusste nur, dass sie wirkt. Der Fall zeigt, dass praktische Wirksamkeit einer Erklärung oft vorausgeht — und Politik trotzdem entscheiden muss.","C1":"Die Regelung vom 26. August 1807 stellte die Grundfrage jeder Gesundheitspolitik: Wann darf der Staat den Einzelnen zu etwas verpflichten, das vor allem anderen nützt? Die Pockenimpfung schützt am stärksten dann, wenn fast alle mitmachen — sie ist der Musterfall eines Guts, das sich nicht individuell herstellen lässt.","C2":"Am 26. August 1807 wurde eine Abwägung getroffen, die sich zweihundert Jahre später unverändert wiederholt hat. Bemerkenswert ist, dass die Pocken tatsächlich ausgerottet wurden — ein Ergebnis, das kein anderes Verfahren erreicht hätte. Das entscheidet die Grundsatzfrage nicht, verschiebt aber die Beweislast: Wer Pflichten ablehnt, muss erklären, wie das Ziel sonst erreichbar wäre."},"translationsA1":{"en":"On August 26, 1807, Bavaria introduces compulsory vaccination. All children are to be vaccinated against smallpox. No country had done this before.","ar":"في 26 أغسطس 1807، فرضت بافاريا التطعيم الإلزامي. على كل الأطفال أن يُطعّموا ضد الجدري. لم يفعل ذلك أي بلد من قبل.","tr":"26 Ağustos 1807'de Bavyera zorunlu aşıyı getirdi. Tüm çocuklar çiçek hastalığına karşı aşılanmalı. Bunu daha önce hiçbir ülke yapmamıştı.","ru":"26 августа 1807 года Бавария ввела обязательную прививку. Всех детей должны прививать от оспы. До этого так не делала ни одна страна.","es":"El 26 de agosto de 1807, Baviera introduce la vacunación obligatoria. Todos los niños deben vacunarse contra la viruela. Ningún país lo había hecho antes.","fr":"Le 26 août 1807, la Bavière instaure la vaccination obligatoire. Tous les enfants doivent être vaccinés contre la variole. Aucun pays ne l'avait fait avant.","pl":"26 sierpnia 1807 roku Bawaria wprowadziła obowiązek szczepień. Wszystkie dzieci mają być szczepione przeciw ospie. Wcześniej nie zrobił tego żaden kraj.","uk":"26 серпня 1807 року Баварія запровадила обов'язкове щеплення. Усіх дітей мають щепити від віспи. До того цього не робила жодна країна.","fa":"در ۲۶ اوت ۱۸۰۷، بایرن واکسیناسیون اجباری را برقرار کرد. همه کودکان باید علیه آبله واکسینه شوند. پیش از آن هیچ کشوری چنین نکرده بود.","it":"Il 26 agosto 1807 la Baviera introduce l'obbligo vaccinale. Tutti i bambini devono essere vaccinati contro il vaiolo. Nessuno Stato lo aveva mai fatto prima."},"translationsByLevel":{"A2":{"en":"On August 26, 1807, the Kingdom of Bavaria became the first state in the world to introduce a smallpox vaccination requirement. Smallpox killed thousands of children there every year at the time. Within a few decades, the disease almost completely disappeared there.","ar":"في 26 أغسطس 1807، أصبحت مملكة بافاريا أول دولة في العالم تفرض إلزامية التطعيم ضد الجدري. كان الجدري آنذاك يقتل آلاف الأطفال كل عام. وفي غضون بضعة عقود، اختفى المرض هناك بشكل شبه كامل.","tr":"26 Ağustos 1807'de Bavyera Krallığı, dünyada çiçek hastalığına karşı zorunlu aşılamayı getiren ilk devlet oldu. O dönemde çiçek hastalığı her yıl binlerce çocuğun ölümüne neden oluyordu. Birkaç on yıl içinde hastalık orada neredeyse tamamen ortadan kalktı.","ru":"26 августа 1807 года Королевство Бавария стало первым государством в мире, введшим обязательную вакцинацию против оспы. В то время оспа ежегодно убивала там тысячи детей. В течение нескольких десятилетий болезнь там почти полностью исчезла.","es":"El 26 de agosto de 1807, el Reino de Baviera se convirtió en el primer estado del mundo en introducir la vacunación obligatoria contra la viruela. En aquella época, la viruela mataba cada año a miles de niños. En pocas décadas, la enfermedad desapareció allí casi por completo.","fr":"Le 26 août 1807, le royaume de Bavière devient le premier État au monde à instaurer une obligation vaccinale contre la variole. À l'époque, la variole tuait chaque année des milliers d'enfants. En quelques décennies, la maladie y disparut presque totalement.","pl":"26 sierpnia 1807 roku Królestwo Bawarii jako pierwsze państwo na świecie wprowadziło obowiązek szczepienia przeciwko ospie. Ospa zabijała wówczas co roku tysiące dzieci. W ciągu kilku dziesięcioleci choroba niemal całkowicie tam zniknęła.","uk":"26 серпня 1807 року Королівство Баварія стало першою державою у світі, яка запровадила обов'язкову вакцинацію проти віспи. У той час віспа щороку вбивала там тисячі дітей. Протягом кількох десятиліть хвороба там майже повністю зникла.","fa":"در ۲۶ اوت ۱۸۰۷، پادشاهی باواریا نخستین دولت جهان شد که واکسیناسیون اجباری علیه آبله را معرفی کرد. در آن زمان آبله هرساله هزاران کودک را در آنجا می‌کشت. طی چند دهه، این بیماری تقریباً به‌طور کامل از آنجا رخت بربست.","it":"Il 26 agosto 1807 il Regno di Baviera introduce, primo Stato al mondo, l'obbligo di vaccinazione contro il vaiolo. All'epoca il vaiolo uccideva ogni anno migliaia di bambini. Nel giro di pochi decenni la malattia scomparve quasi del tutto."},"B1":{"en":"On August 26, 1807, Bavaria decided on the world's first vaccination mandate. The smallpox vaccine had only been developed eleven years earlier. The state decided that protecting everyone was more important than the individual's freedom of choice — a trade-off still debated today.","ar":"في 26 أغسطس 1807، قررت بافاريا فرض أول إلزامية تطعيم في العالم. لم يكن قد مضى على تطوير لقاح الجدري سوى أحد عشر عاماً. قررت الدولة أن حماية الجميع أهم من حرية اختيار الفرد — وهي موازنة لا يزال النقاش قائماً حولها حتى اليوم.","tr":"26 Ağustos 1807'de Bavyera, dünyanın ilk zorunlu aşılama kararını aldı. Çiçek aşısı ancak on bir yıl önce geliştirilmişti. Devlet, herkesin korunmasının bireyin seçim özgürlüğünden daha önemli olduğuna karar verdi — bugün hâlâ tartışılan bir denge.","ru":"26 августа 1807 года Бавария приняла первый в мире закон об обязательной вакцинации. Вакцина против оспы была разработана всего одиннадцатью годами ранее. Государство решило, что защита всех важнее свободы выбора отдельного человека — компромисс, о котором спорят до сих пор.","es":"El 26 de agosto de 1807, Baviera decretó la primera obligación de vacunación del mundo. La vacuna contra la viruela había sido desarrollada solo once años antes. El Estado decidió que la protección de todos era más importante que la libertad de elección del individuo, una ponderación que sigue debatiéndose hoy.","fr":"Le 26 août 1807, la Bavière décide de la première obligation vaccinale au monde. Le vaccin contre la variole n'avait été mis au point que onze ans auparavant. L'État a jugé que la protection de tous primait sur la liberté de choix de l'individu — un arbitrage encore débattu aujourd'hui.","pl":"26 sierpnia 1807 roku Bawaria wprowadziła pierwszy na świecie obowiązek szczepień. Szczepionka przeciwko ospie została opracowana zaledwie jedenaście lat wcześniej. Państwo uznało, że ochrona wszystkich jest ważniejsza niż wolność wyboru jednostki — kompromis, o który spiera się do dziś.","uk":"26 серпня 1807 року Баварія ухвалила перший у світі обов'язок вакцинації. Вакцину проти віспи розробили лише за одинадцять років до цього. Держава вирішила, що захист усіх важливіший за свободу вибору окремої людини — компроміс, про який сперечаються й донині.","fa":"در ۲۶ اوت ۱۸۰۷، باواریا نخستین قانون واکسیناسیون اجباری جهان را تصویب کرد. واکسن آبله تنها یازده سال پیش از آن ساخته شده بود. دولت تصمیم گرفت که محافظت از همگان مهم‌تر از آزادی انتخاب فرد است — موازنه‌ای که تا امروز محل بحث است.","it":"Il 26 agosto 1807 la Baviera decreta il primo obbligo vaccinale al mondo. Il vaccino contro il vaiolo era stato sviluppato appena undici anni prima. Lo Stato stabilì che la protezione di tutti fosse più importante della libertà di scelta del singolo — un bilanciamento tuttora oggetto di discussione."},"B2":{"en":"On August 26, 1807, Bavaria introduced a vaccination mandate at a time when no one could yet explain exactly why the vaccine worked. People only knew that it worked. The case shows that practical effectiveness often precedes an explanation — and that politics must decide regardless.","ar":"في 26 أغسطس 1807، فرضت بافاريا إلزامية التطعيم في وقت لم يكن فيه أحد قادراً على تفسير سبب فعالية اللقاح بدقة. كان الناس يعرفون فقط أنه فعّال. تُظهر هذه الحالة أن الفعالية العملية كثيراً ما تسبق التفسير — وأن على السياسة أن تقرر رغم ذلك.","tr":"26 Ağustos 1807'de Bavyera, aşının neden işe yaradığını henüz kimsenin tam olarak açıklayamadığı bir dönemde zorunlu aşılamayı getirdi. Sadece işe yaradığı biliniyordu. Bu durum, pratik etkinliğin çoğu zaman açıklamadan önce geldiğini — ve siyasetin yine de karar vermesi gerektiğini gösteriyor.","ru":"26 августа 1807 года Бавария ввела обязательную вакцинацию, когда ещё никто не мог точно объяснить, почему прививка действует. Знали лишь, что она действует. Этот случай показывает, что практическая эффективность часто опережает объяснение — а политике всё равно приходится принимать решения.","es":"El 26 de agosto de 1807, Baviera introdujo la obligación de vacunación cuando todavía nadie podía explicar exactamente por qué funcionaba la vacuna. Solo se sabía que funcionaba. El caso muestra que la eficacia práctica a menudo precede a la explicación, y que la política debe decidir de todos modos.","fr":"Le 26 août 1807, la Bavière instaure une obligation vaccinale alors que personne ne pouvait encore expliquer exactement pourquoi le vaccin fonctionnait. On savait seulement qu'il fonctionnait. Ce cas montre que l'efficacité pratique précède souvent l'explication — et que la politique doit néanmoins trancher.","pl":"26 sierpnia 1807 roku Bawaria wprowadziła obowiązek szczepień, gdy nikt nie potrafił jeszcze dokładnie wyjaśnić, dlaczego szczepionka działa. Wiedziano tylko, że działa. Ten przypadek pokazuje, że praktyczna skuteczność często wyprzedza wyjaśnienie — a polityka i tak musi podejmować decyzje.","uk":"26 серпня 1807 року Баварія запровадила обов'язкову вакцинацію тоді, коли ще ніхто не міг точно пояснити, чому щеплення діє. Знали лише, що воно діє. Цей випадок показує, що практична ефективність часто випереджає пояснення — а політика все одно мусить приймати рішення.","fa":"در ۲۶ اوت ۱۸۰۷، باواریا واکسیناسیون اجباری را در زمانی معرفی کرد که هنوز کسی نمی‌توانست دقیقاً توضیح دهد چرا واکسن اثر می‌کند. فقط می‌دانستند که اثر می‌کند. این نمونه نشان می‌دهد که کارآمدی عملی اغلب بر توضیح علمی پیشی می‌گیرد — و سیاست با این حال باید تصمیم بگیرد.","it":"Il 26 agosto 1807 la Baviera introduce l'obbligo vaccinale in un momento in cui nessuno sapeva ancora spiegare esattamente perché il vaccino funzionasse. Si sapeva soltanto che funzionava. Il caso mostra come l'efficacia pratica spesso preceda la spiegazione scientifica — e come la politica debba comunque decidere."},"C1":{"en":"The regulation of August 26, 1807, posed the fundamental question of all health policy: when may the state oblige the individual to do something that primarily benefits others? Smallpox vaccination protects most strongly when nearly everyone takes part — it is the model case of a good that cannot be produced individually.","ar":"طرح قرار 26 أغسطس 1807 السؤال الجوهري لكل سياسة صحية: متى يحق للدولة إلزام الفرد بشيء ينفع الآخرين في المقام الأول؟ يوفر لقاح الجدري أقوى حماية عندما يشارك فيه الجميع تقريباً — إنه المثال النموذجي لمنفعة لا يمكن إنتاجها بشكل فردي.","tr":"26 Ağustos 1807 tarihli düzenleme, her sağlık politikasının temel sorusunu ortaya koydu: Devlet, bireyi öncelikle başkalarına yarar sağlayan bir şeye ne zaman zorlayabilir? Çiçek aşısı, neredeyse herkes katıldığında en güçlü korumayı sağlar — bu, bireysel olarak üretilemeyen bir kamu malının örnek vakasıdır.","ru":"Постановление от 26 августа 1807 года поставило основной вопрос всей политики здравоохранения: когда государство вправе обязывать отдельного человека к тому, что приносит пользу прежде всего другим? Вакцинация против оспы защищает сильнее всего тогда, когда участвуют почти все — это классический пример блага, которое невозможно произвести индивидуально.","es":"La normativa del 26 de agosto de 1807 planteó la pregunta fundamental de toda política sanitaria: ¿cuándo puede el Estado obligar al individuo a algo que beneficia sobre todo a los demás? La vacunación contra la viruela protege con mayor eficacia cuando participa casi todo el mundo; es el caso ejemplar de un bien que no puede producirse individualmente.","fr":"La réglementation du 26 août 1807 posait la question fondamentale de toute politique de santé : quand l'État peut-il obliger l'individu à faire quelque chose qui profite avant tout aux autres ? La vaccination contre la variole protège le mieux lorsque presque tout le monde y participe — c'est le cas exemplaire d'un bien qui ne peut être produit individuellement.","pl":"Regulacja z 26 sierpnia 1807 roku postawiła podstawowe pytanie każdej polityki zdrowotnej: kiedy państwo może zobowiązać jednostkę do czegoś, co przede wszystkim przynosi korzyść innym? Szczepienie przeciwko ospie chroni najskuteczniej wtedy, gdy uczestniczą w nim niemal wszyscy — to modelowy przypadek dobra, którego nie da się wytworzyć indywidualnie.","uk":"Постанова від 26 серпня 1807 року поставила основне питання будь-якої політики охорони здоров'я: коли держава може зобов'язати окрему людину до чогось, що передусім корисне іншим? Вакцинація проти віспи захищає найсильніше тоді, коли бере участь майже кожен — це класичний приклад блага, яке неможливо створити індивідуально.","fa":"این مقرره در ۲۶ اوت ۱۸۰۷ پرسش بنیادین هر سیاست بهداشتی را مطرح کرد: دولت چه زمانی می‌تواند فرد را به کاری موظف کند که پیش از هر چیز به نفع دیگران است؟ واکسیناسیون آبله زمانی قوی‌ترین محافظت را ایجاد می‌کند که تقریباً همه در آن مشارکت کنند — این نمونه بارز کالایی است که نمی‌توان آن را به‌صورت فردی تولید کرد.","it":"Il provvedimento del 26 agosto 1807 pose la domanda fondamentale di ogni politica sanitaria: quando può lo Stato obbligare il singolo a qualcosa che giova soprattutto agli altri? La vaccinazione contro il vaiolo protegge al massimo quando quasi tutti vi aderiscono — è il caso esemplare di un bene che non può essere prodotto individualmente."},"C2":{"en":"On August 26, 1807, a trade-off was made that repeated itself unchanged two hundred years later. Remarkably, smallpox was actually eradicated — a result no other method would have achieved. That does not settle the fundamental question, but it does shift the burden of proof: whoever rejects mandates must explain how the goal could otherwise be achieved.","ar":"في 26 أغسطس 1807، تمت موازنة تكررت دون تغيير بعد مائتي عام. اللافت أن الجدري استُؤصل بالفعل — وهي نتيجة لم يكن ليحققها أي أسلوب آخر. لا يحسم هذا السؤال الجوهري، لكنه ينقل عبء الإثبات: فمن يرفض الإلزام عليه أن يوضح كيف يمكن تحقيق الهدف بطريقة أخرى.","tr":"26 Ağustos 1807'de yapılan bir tartma, iki yüz yıl sonra değişmeden tekrarlandı. Dikkat çekici olan, çiçek hastalığının gerçekten ortadan kaldırılmış olmasıdır — başka hiçbir yöntemin ulaşamayacağı bir sonuç. Bu, temel soruyu çözmez, ama ispat yükünü kaydırır: yükümlülükleri reddedenlerin, hedefe başka nasıl ulaşılabileceğini açıklaması gerekir.","ru":"26 августа 1807 года был сделан компромисс, который спустя двести лет повторился в неизменном виде. Примечательно, что оспа действительно была искоренена — результат, которого не достигла бы никакая другая мера. Это не решает принципиальный вопрос, но переносит бремя доказывания: тот, кто отвергает обязательность, должен объяснить, как иначе можно достичь цели.","es":"El 26 de agosto de 1807 se hizo una ponderación que, doscientos años después, se ha repetido sin cambios. Es notable que la viruela fuera realmente erradicada, un resultado que ningún otro método habría logrado. Esto no zanja la cuestión de fondo, pero sí traslada la carga de la prueba: quien rechaza las obligaciones debe explicar cómo se alcanzaría el objetivo de otro modo.","fr":"Le 26 août 1807 fut opéré un arbitrage qui s'est reproduit, inchangé, deux cents ans plus tard. Il est remarquable que la variole ait effectivement été éradiquée — un résultat qu'aucune autre méthode n'aurait permis d'atteindre. Cela ne tranche pas la question de principe, mais déplace la charge de la preuve : qui rejette les obligations doit expliquer comment atteindre autrement l'objectif.","pl":"26 sierpnia 1807 roku dokonano wyważenia, które dwieście lat później powtórzyło się w niezmienionej formie. Godne uwagi jest to, że ospa została faktycznie wykorzeniona — rezultat, którego nie osiągnęłaby żadna inna metoda. Nie rozstrzyga to pytania zasadniczego, ale przesuwa ciężar dowodu: kto odrzuca obowiązki, musi wyjaśnić, jak inaczej można by osiągnąć ten cel.","uk":"26 серпня 1807 року було зроблено вибір, який через двісті років повторився без змін. Показово, що віспу справді викоренили — результат, якого не досяг би жоден інший метод. Це не вирішує принципового питання, але переносить тягар доведення: хто відкидає обов'язковість, має пояснити, як інакше можна досягти мети.","fa":"در ۲۶ اوت ۱۸۰۷ موازنه‌ای صورت گرفت که دویست سال بعد بدون تغییر تکرار شد. نکته قابل توجه این است که آبله واقعاً ریشه‌کن شد — نتیجه‌ای که هیچ روش دیگری به آن دست نمی‌یافت. این امر پرسش اصولی را حل نمی‌کند، اما بار اثبات را جابه‌جا می‌کند: هر که با الزام مخالف است باید توضیح دهد هدف از چه راه دیگری قابل‌دستیابی است.","it":"Il 26 agosto 1807 fu compiuto un bilanciamento che, duecento anni dopo, si è ripetuto immutato. È notevole che il vaiolo sia stato effettivamente debellato — un risultato che nessun'altra strategia avrebbe potuto ottenere. Ciò non risolve la questione di principio, ma sposta l'onere della prova: chi rifiuta gli obblighi deve spiegare in che altro modo l'obiettivo potrebbe essere raggiunto."}},"sideFacts":[]},"08-27":{"year":1770,"levels":{"A1":"Am 27. August 1770 wird Hegel geboren. Er ist Philosoph. Er sagt: Die Welt verändert sich durch Widersprüche.","A2":"Am 27. August 1770 kommt Georg Wilhelm Friedrich Hegel in Stuttgart zur Welt. Er dachte über die Geschichte als einen langen Weg nach. Seine Sätze gelten als besonders schwer zu verstehen.","B1":"Am 27. August 1770 wird Hegel geboren. Für ihn entwickelt sich alles über Widersprüche: Auf eine Behauptung folgt ihr Gegenteil, und aus beiden entsteht etwas Neues. Dieses Denkmuster hat die Philosophie und die Politik des 19. Jahrhunderts geprägt.","B2":"Am 27. August 1770 wird Hegel geboren. Sein Gedanke, dass Gegensätze nicht bloß Fehler, sondern Motoren der Entwicklung sind, war neu. Marx übernahm dieses Muster und wandte es auf die Wirtschaft an — ohne Hegel gäbe es seine Theorie nicht in dieser Form.","C1":"Der am 27. August 1770 Geborene stellte die Frage, ob Geschichte einer Richtung folgt. Seine Antwort — sie sei der Fortschritt im Bewusstsein der Freiheit — ist so anspruchsvoll wie angreifbar. Sie unterstellt, dass sich hinterher ein Sinn erkennen lässt, den die Beteiligten nie sehen konnten.","C2":"An Hegel, geboren am 27. August 1770, hängt eine Denkfigur mit ungewöhnlicher Reichweite und ungewöhnlichem Risiko. Wer der Geschichte eine Richtung zuschreibt, gewinnt Orientierung und liefert zugleich jedem Regime das Argument, im Namen des Fortschritts über Menschen hinweggehen zu dürfen. Beides folgt aus derselben Annahme — und lässt sich nicht sauber trennen."},"translationsA1":{"en":"On August 27, 1770, Hegel is born. He is a philosopher. He says: the world changes through contradictions.","ar":"في 27 أغسطس 1770، وُلد هيغل. كان فيلسوفًا. قال: العالم يتغير عبر التناقضات.","tr":"27 Ağustos 1770'te Hegel doğdu. O bir filozoftu. Şöyle der: Dünya çelişkilerle değişir.","ru":"27 августа 1770 года родился Гегель. Он был философом. Он говорил: мир меняется через противоречия.","es":"El 27 de agosto de 1770 nace Hegel. Es filósofo. Dice: el mundo cambia a través de las contradicciones.","fr":"Le 27 août 1770, Hegel naît. C'est un philosophe. Il dit : le monde change par les contradictions.","pl":"27 sierpnia 1770 roku urodził się Hegel. Był filozofem. Mówił: świat zmienia się przez sprzeczności.","uk":"27 серпня 1770 року народився Геґель. Він був філософом. Він казав: світ змінюється через суперечності.","fa":"در ۲۷ اوت ۱۷۷۰، هگل به دنیا آمد. او فیلسوف بود. او می‌گفت: جهان از راه تضادها دگرگون می‌شود.","it":"Il 27 agosto 1770 nasce Hegel. È un filosofo. Dice che il mondo cambia attraverso le contraddizioni."},"translationsByLevel":{"A2":{"en":"On August 27, 1770, Georg Wilhelm Friedrich Hegel was born in Stuttgart. He thought of history as a long journey. His sentences are considered particularly difficult to understand.","ar":"في 27 أغسطس 1770، وُلد غيورغ فيلهلم فريدريش هيغل في شتوتغارت. تأمل التاريخ باعتباره طريقاً طويلاً. تُعد جمله من أصعب الجمل فهماً.","tr":"27 Ağustos 1770'te Georg Wilhelm Friedrich Hegel Stuttgart'ta dünyaya geldi. Tarihi uzun bir yol olarak düşündü. Cümleleri özellikle anlaşılması zor kabul edilir.","ru":"27 августа 1770 года в Штутгарте родился Георг Вильгельм Фридрих Гегель. Он размышлял об истории как о долгом пути. Его фразы считаются особенно трудными для понимания.","es":"El 27 de agosto de 1770 nació Georg Wilhelm Friedrich Hegel en Stuttgart. Reflexionó sobre la historia como un largo camino. Sus frases se consideran especialmente difíciles de entender.","fr":"Le 27 août 1770, Georg Wilhelm Friedrich Hegel naît à Stuttgart. Il concevait l'histoire comme un long chemin. Ses phrases sont réputées particulièrement difficiles à comprendre.","pl":"27 sierpnia 1770 roku w Stuttgarcie urodził się Georg Wilhelm Friedrich Hegel. Rozmyślał o historii jako o długiej drodze. Jego zdania uchodzą za szczególnie trudne do zrozumienia.","uk":"27 серпня 1770 року в Штутгарті народився Георг Вільгельм Фрідріх Гегель. Він розмірковував про історію як про довгий шлях. Його речення вважаються особливо складними для розуміння.","fa":"در ۲۷ اوت ۱۷۷۰، گئورگ ویلهلم فریدریش هگل در اشتوتگارت به دنیا آمد. او درباره تاریخ به‌عنوان راهی طولانی می‌اندیشید. جملات او به‌ویژه دشوارفهم شمرده می‌شوند.","it":"Il 27 agosto 1770 nasce a Stoccarda Georg Wilhelm Friedrich Hegel. Riflette sulla storia come su un lungo cammino. Le sue frasi sono considerate particolarmente difficili da comprendere."},"B1":{"en":"Hegel was born on August 27, 1770. For him, everything develops through contradictions: a claim is followed by its opposite, and from both something new emerges. This pattern of thought shaped the philosophy and politics of the 19th century.","ar":"وُلد هيغل في 27 أغسطس 1770. بالنسبة له، يتطور كل شيء عبر التناقضات: يتبع الادعاءَ نقيضُه، ومن كليهما ينشأ شيء جديد. صاغ هذا النمط الفكري فلسفة القرن التاسع عشر وسياسته.","tr":"Hegel 27 Ağustos 1770'te doğdu. Ona göre her şey çelişkiler üzerinden gelişir: bir iddiayı onun karşıtı izler ve ikisinden yeni bir şey doğar. Bu düşünce kalıbı, 19. yüzyıl felsefesini ve siyasetini derinden etkiledi.","ru":"Гегель родился 27 августа 1770 года. По его мнению, всё развивается через противоречия: за утверждением следует его противоположность, и из обоих возникает нечто новое. Этот образ мышления определил философию и политику XIX века.","es":"Hegel nació el 27 de agosto de 1770. Para él, todo se desarrolla a través de contradicciones: a una afirmación le sigue su contrario, y de ambos surge algo nuevo. Este patrón de pensamiento marcó la filosofía y la política del siglo XIX.","fr":"Hegel est né le 27 août 1770. Pour lui, tout se développe par des contradictions : à une affirmation succède son contraire, et des deux naît quelque chose de nouveau. Ce schéma de pensée a marqué la philosophie et la politique du XIXe siècle.","pl":"Hegel urodził się 27 sierpnia 1770 roku. Według niego wszystko rozwija się poprzez sprzeczności: po twierdzeniu następuje jego przeciwieństwo, a z obu powstaje coś nowego. Ten wzorzec myślenia ukształtował filozofię i politykę XIX wieku.","uk":"Гегель народився 27 серпня 1770 року. На його думку, все розвивається через суперечності: за твердженням слідує його протилежність, і з обох виникає щось нове. Цей спосіб мислення сформував філософію та політику XIX століття.","fa":"هگل در ۲۷ اوت ۱۷۷۰ به دنیا آمد. از دیدگاه او، همه‌چیز از طریق تضادها تحول می‌یابد: پس از یک ادعا، نقیض آن می‌آید و از هر دو چیزی نو پدید می‌آید. این الگوی فکری فلسفه و سیاست قرن نوزدهم را شکل داد.","it":"Il 27 agosto 1770 nasce Hegel. Per lui tutto si sviluppa attraverso le contraddizioni: a un'affermazione segue il suo contrario, e dai due nasce qualcosa di nuovo. Questo schema di pensiero ha segnato la filosofia e la politica del diciannovesimo secolo."},"B2":{"en":"Hegel was born on August 27, 1770. His idea that opposites are not merely errors but engines of development was new. Marx adopted this pattern and applied it to economics — without Hegel, his theory would not exist in this form.","ar":"وُلد هيغل في 27 أغسطس 1770. كانت فكرته بأن التناقضات ليست مجرد أخطاء بل محركات للتطور فكرة جديدة. تبنى ماركس هذا النمط وطبقه على الاقتصاد — لولا هيغل لما وُجدت نظريته بهذا الشكل.","tr":"Hegel 27 Ağustos 1770'te doğdu. Karşıtlıkların yalnızca hata değil, gelişimin motorları olduğu fikri yeniydi. Marx bu kalıbı devraldı ve ekonomiye uyguladı — Hegel olmasaydı, teorisi bu şekilde var olmazdı.","ru":"Гегель родился 27 августа 1770 года. Его мысль о том, что противоположности являются не просто ошибками, а движущими силами развития, была новой. Маркс перенял этот образец и применил его к экономике — без Гегеля его теория не существовала бы в такой форме.","es":"Hegel nació el 27 de agosto de 1770. Su idea de que los opuestos no son meros errores, sino motores del desarrollo, era novedosa. Marx adoptó este patrón y lo aplicó a la economía; sin Hegel, su teoría no existiría en esta forma.","fr":"Hegel est né le 27 août 1770. Son idée selon laquelle les contraires ne sont pas de simples erreurs, mais des moteurs du développement, était nouvelle. Marx a repris ce schéma et l'a appliqué à l'économie — sans Hegel, sa théorie n'existerait pas sous cette forme.","pl":"Hegel urodził się 27 sierpnia 1770 roku. Jego myśl, że przeciwieństwa nie są jedynie błędami, lecz siłami napędowymi rozwoju, była nowatorska. Marks przejął ten wzorzec i zastosował go do ekonomii — bez Hegla jego teoria nie istniałaby w tej formie.","uk":"Гегель народився 27 серпня 1770 року. Його думка про те, що протилежності є не просто помилками, а рушіями розвитку, була новою. Маркс перейняв цю модель і застосував її до економіки — без Гегеля його теорії не існувало б у такій формі.","fa":"هگل در ۲۷ اوت ۱۷۷۰ به دنیا آمد. این اندیشه او که تضادها صرفاً خطا نیستند بلکه موتور تحول‌اند، ایده‌ای نو بود. مارکس این الگو را برگرفت و آن را در اقتصاد به کار بست — بدون هگل، نظریه او به این شکل وجود نمی‌داشت.","it":"Il 27 agosto 1770 nasce Hegel. La sua idea che le contraddizioni non siano semplici errori, ma motori dello sviluppo, era una novità. Marx riprese questo schema e lo applicò all'economia: senza Hegel la sua teoria non esisterebbe in questa forma."},"C1":{"en":"Born on August 27, 1770, he raised the question of whether history follows a direction. His answer — that it is progress in the consciousness of freedom — is as ambitious as it is vulnerable to attack. It presupposes that afterward one can discern a meaning that those involved could never see.","ar":"طرح المولود في 27 أغسطس 1770 سؤالاً حول ما إذا كان التاريخ يتبع اتجاهاً معيناً. إجابته — بأنه التقدم في وعي الحرية — طموحة بقدر ما هي عرضة للنقد. إذ تفترض أنه يمكن لاحقاً إدراك معنى لم يستطع المشاركون فيه رؤيته قط.","tr":"27 Ağustos 1770'te doğan bu kişi, tarihin bir yön izleyip izlemediği sorusunu ortaya attı. Yanıtı — özgürlük bilincindeki ilerleme olduğu — hem iddialı hem de eleştiriye açıktır. Bu yanıt, olayların içindekilerin hiçbir zaman göremediği bir anlamın sonradan tanınabileceğini varsayar.","ru":"Родившийся 27 августа 1770 года поставил вопрос о том, следует ли история какому-либо направлению. Его ответ — что это прогресс в осознании свободы — столь же амбициозен, сколь и уязвим для критики. Он предполагает, что впоследствии можно распознать смысл, который участники событий никогда не могли увидеть.","es":"El nacido el 27 de agosto de 1770 planteó la pregunta de si la historia sigue una dirección. Su respuesta —que es el progreso en la conciencia de la libertad— es tan ambiciosa como criticable. Presupone que después se puede reconocer un sentido que los implicados nunca pudieron ver.","fr":"Né le 27 août 1770, il posa la question de savoir si l'histoire suit une direction. Sa réponse — qu'elle serait le progrès dans la conscience de la liberté — est aussi ambitieuse que contestable. Elle présuppose qu'on peut a posteriori discerner un sens que les acteurs n'ont jamais pu percevoir.","pl":"Urodzony 27 sierpnia 1770 roku postawił pytanie, czy historia podąża jakimś kierunkiem. Jego odpowiedź — że jest to postęp w świadomości wolności — jest tyleż ambitna, co podatna na krytykę. Zakłada bowiem, że później można rozpoznać sens, którego uczestnicy wydarzeń nigdy nie mogli dostrzec.","uk":"Народжений 27 серпня 1770 року поставив питання, чи прямує історія в певному напрямку. Його відповідь — що це прогрес в усвідомленні свободи — настільки ж амбітна, наскільки й вразлива для критики. Вона припускає, що згодом можна розпізнати сенс, якого учасники подій ніколи не могли побачити.","fa":"متولد ۲۷ اوت ۱۷۷۰ این پرسش را مطرح کرد که آیا تاریخ از مسیری مشخص پیروی می‌کند. پاسخ او — که آن پیشرفت در آگاهی از آزادی است — به همان اندازه بلندپروازانه است که آسیب‌پذیر. این پاسخ فرض می‌کند که بعداً می‌توان معنایی را تشخیص داد که خودِ شرکت‌کنندگان هرگز قادر به دیدن آن نبودند.","it":"Nato il 27 agosto 1770, egli pose la domanda se la storia segua una direzione. La sua risposta — essa sarebbe il progresso nella coscienza della libertà — è tanto ambiziosa quanto discutibile. Presuppone infatti che, a posteriori, si possa riconoscere un senso che i protagonisti non potevano mai scorgere."},"C2":{"en":"Hegel, born on August 27, 1770, is bound up with a figure of thought of unusual reach and unusual risk. Whoever ascribes a direction to history gains orientation, and at the same time hands every regime the argument that it may ride roughshod over people in the name of progress. Both follow from the same assumption — and cannot be cleanly separated.","ar":"يرتبط بهيغل، المولود في 27 أغسطس 1770، بنية فكرية ذات مدى غير عادي ومخاطر غير عادية. من ينسب اتجاهاً إلى التاريخ يكتسب توجهاً، ويمنح في الوقت نفسه كل نظام حجة يبرر بها تجاوز البشر باسم التقدم. كلاهما ينبع من الافتراض ذاته — ولا يمكن الفصل بينهما بشكل نظيف.","tr":"27 Ağustos 1770'te doğan Hegel'e, olağandışı bir kapsam ve olağandışı bir riski olan bir düşünce figürü bağlıdır. Tarihe bir yön atfeden kişi yönelim kazanır, aynı zamanda her rejime ilerleme adına insanları hiçe sayma argümanını sunar. Her ikisi de aynı varsayımdan kaynaklanır — ve birbirinden temiz bir şekilde ayrılamaz.","ru":"С Гегелем, родившимся 27 августа 1770 года, связана мыслительная фигура необычайного охвата и необычайного риска. Тот, кто приписывает истории направление, обретает ориентир и одновременно даёт любому режиму аргумент — во имя прогресса переступать через людей. Оба следствия вытекают из одного и того же допущения — и их невозможно чисто разделить.","es":"En torno a Hegel, nacido el 27 de agosto de 1770, se articula una figura de pensamiento de un alcance inusual y un riesgo inusual. Quien atribuye una dirección a la historia gana orientación y, al mismo tiempo, ofrece a cualquier régimen el argumento para pasar por encima de las personas en nombre del progreso. Ambas cosas se derivan del mismo supuesto, y no pueden separarse limpiamente.","fr":"À Hegel, né le 27 août 1770, se rattache une figure de pensée d'une portée et d'un risque peu communs. Quiconque attribue une direction à l'histoire gagne un repère, tout en fournissant à n'importe quel régime l'argument permettant de piétiner les hommes au nom du progrès. Les deux découlent de la même prémisse — et ne peuvent être clairement séparés.","pl":"Z Heglem, urodzonym 27 sierpnia 1770 roku, wiąże się figura myślowa o niezwykłym zasięgu i niezwykłym ryzyku. Kto przypisuje historii kierunek, zyskuje orientację, a jednocześnie dostarcza każdemu reżimowi argumentu, by w imię postępu przechodzić do porządku dziennego nad ludźmi. Obie rzeczy wynikają z tego samego założenia — i nie da się ich czysto rozdzielić.","uk":"З Гегелем, народженим 27 серпня 1770 року, пов'язана мисленнєва фігура незвичайного масштабу й незвичайного ризику. Хто приписує історії напрямок, здобуває орієнтир і водночас дає кожному режиму аргумент — в ім'я прогресу переступати через людей. Обидва наслідки випливають з одного й того самого припущення — і їх неможливо чисто розділити.","fa":"به هگل، متولد ۲۷ اوت ۱۷۷۰، الگویی فکری با گستره‌ای نامعمول و خطری نامعمول وابسته است. هر که به تاریخ جهتی نسبت دهد، جهت‌گیری به دست می‌آورد و در همان حال به هر رژیمی این استدلال را می‌دهد که به نام پیشرفت از روی انسان‌ها بگذرد. هر دو از یک پیش‌فرض ناشی می‌شوند — و نمی‌توان آن‌ها را به‌روشنی از هم جدا کرد.","it":"Alla figura di Hegel, nato il 27 agosto 1770, è legata una figura di pensiero di portata e insieme di rischio non comuni. Chi attribuisce una direzione alla storia guadagna orientamento, ma fornisce al tempo stesso a qualsiasi regime l'argomento per calpestare gli esseri umani in nome del progresso. Le due cose derivano dalla stessa premessa — e non si possono separare nettamente."}},"sideFacts":[]},"08-28":{"year":1988,"levels":{"A1":"Am 28. August 1988 gibt es einen Unfall bei einer Flugshow in Ramstein. Viele Menschen sterben.","A2":"Am 28. August 1988 stoßen bei einer Flugshow in Ramstein drei Flugzeuge zusammen. Es ist eines der schlimmsten Unglücke bei einer Flugshow weltweit.","B1":"Am 28. August 1988 kollidieren bei einer Flugschau auf der Air Base Ramstein drei Kunstflugzeuge in der Luft. 70 Menschen sterben — es ist eines der schwersten Flugshow-Unglücke der Geschichte.","B2":"Am 28. August 1988 kollidieren vor rund 300.000 Zuschauern drei Maschinen der italienischen Kunstflugstaffel Frecce Tricolori bei einer Flugschau auf der Air Base Ramstein. 70 Menschen sterben. Das Unglück verändert die Sicherheitsauflagen für Flugschauen in ganz Europa dauerhaft.","C1":"Das Flugtagunglück von Ramstein am 28. August 1988, bei dem drei Maschinen der Frecce Tricolori vor rund 300.000 Zuschauern kollidierten und 70 Menschen ihr Leben verloren, zählt zu den folgenschwersten Katastrophen dieser Art weltweit und führte zu grundlegend verschärften Sicherheitsauflagen für Flugschauen in Deutschland und Europa.","C2":"Die Flugtagkatastrophe von Ramstein am 28. August 1988 markiert einen Wendepunkt in der Geschichte der Flugschau-Sicherheit: Die parlamentarische Aufarbeitung durch einen Untersuchungsausschuss des Bundestages führte zu bis heute geltenden, drastisch verschärften Abstands- und Sicherheitsregeln für Kunstflugvorführungen in ganz Europa."},"translationsA1":{"en":"On August 28, 1988, there is an accident at an air show in Ramstein. Many people die.","ar":"في 28 أغسطس 1988، وقع حادث في معرض جوي في رامشتاين. مات كثير من الناس.","tr":"28 Ağustos 1988'de Ramstein'daki bir hava gösterisinde kaza oldu. Birçok insan öldü.","ru":"28 августа 1988 года произошла авария на авиашоу в Рамштайне. Погибло много людей.","es":"El 28 de agosto de 1988 ocurre un accidente en un espectáculo aéreo en Ramstein. Mueren muchas personas.","fr":"Le 28 août 1988, un accident se produit lors d'un meeting aérien à Ramstein. Beaucoup de gens meurent.","pl":"28 sierpnia 1988 roku doszło do wypadku na pokazie lotniczym w Ramstein. Zginęło wielu ludzi.","uk":"28 серпня 1988 року стався нещасний випадок на авіашоу в Рамштайні. Загинуло багато людей.","fa":"در ۲۸ اوت ۱۹۸۸، حادثه‌ای در نمایش هوایی رامشتاین رخ داد. افراد زیادی جان باختند.","it":"Il 28 agosto 1988 c'è un incidente durante una manifestazione aerea a Ramstein. Muoiono molte persone."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 28, 1988, three aircraft collided during an air show in Ramstein. It is one of the worst accidents ever at an air show worldwide.","ar":"في 28 أغسطس 1988، اصطدمت ثلاث طائرات في عرض جوي في رامشتاين. يُعد هذا من أسوأ الحوادث في عرض جوي على مستوى العالم.","tr":"28 Ağustos 1988'de Ramstein'daki bir hava gösterisinde üç uçak çarpıştı. Bu, dünya çapında bir hava gösterisinde yaşanan en kötü kazalardan biridir.","ru":"28 августа 1988 года на авиашоу в Рамштайне столкнулись три самолёта. Это одна из самых тяжёлых катастроф на авиашоу в мире.","es":"El 28 de agosto de 1988, tres aviones colisionaron durante un espectáculo aéreo en Ramstein. Es uno de los peores accidentes en un espectáculo aéreo a nivel mundial.","fr":"Le 28 août 1988, trois avions entrent en collision lors d'un meeting aérien à Ramstein. C'est l'un des pires accidents survenus lors d'un meeting aérien dans le monde.","pl":"28 sierpnia 1988 roku podczas pokazu lotniczego w Ramstein zderzyły się trzy samoloty. To jedna z najgorszych katastrof podczas pokazu lotniczego na świecie.","uk":"28 серпня 1988 року під час авіашоу в Рамштайні зіткнулися три літаки. Це одна з найгірших катастроф на авіашоу у світі.","fa":"در ۲۸ اوت ۱۹۸۸، در یک نمایش هوایی در رامشتاین، سه هواپیما با هم برخورد کردند. این یکی از بدترین حوادث در یک نمایش هوایی در سطح جهان است.","it":"Il 28 agosto 1988, durante una manifestazione aerea a Ramstein, tre aerei si scontrano in volo. È uno degli incidenti più gravi mai avvenuti in una manifestazione aerea nel mondo."},"B1":{"en":"On August 28, 1988, three aerobatic aircraft collided in mid-air during an air show at Ramstein Air Base. 70 people died — it is one of the worst air show disasters in history.","ar":"في 28 أغسطس 1988، اصطدمت ثلاث طائرات استعراضية في الجو خلال عرض جوي في قاعدة رامشتاين الجوية. توفي 70 شخصاً — إنها واحدة من أفدح كوارث العروض الجوية في التاريخ.","tr":"28 Ağustos 1988'de Ramstein Hava Üssü'ndeki bir hava gösterisinde üç akrobasi uçağı havada çarpıştı. 70 kişi öldü — bu, tarihin en ağır hava gösterisi felaketlerinden biridir.","ru":"28 августа 1988 года на авиабазе Рамштайн во время авиашоу столкнулись в воздухе три пилотажных самолёта. Погибли 70 человек — это одна из самых тяжёлых катастроф на авиашоу в истории.","es":"El 28 de agosto de 1988, tres aviones acrobáticos colisionaron en el aire durante un espectáculo aéreo en la base aérea de Ramstein. Murieron 70 personas: es uno de los peores desastres de espectáculos aéreos de la historia.","fr":"Le 28 août 1988, trois avions de voltige entrent en collision en plein vol lors d'un meeting aérien à la base aérienne de Ramstein. 70 personnes meurent — c'est l'une des plus graves catastrophes de meeting aérien de l'histoire.","pl":"28 sierpnia 1988 roku podczas pokazu lotniczego na bazie lotniczej Ramstein trzy samoloty akrobacyjne zderzyły się w powietrzu. Zginęło 70 osób — to jedna z najcięższych katastrof pokazów lotniczych w historii.","uk":"28 серпня 1988 року на авіабазі Рамштайн під час авіашоу в повітрі зіткнулися три пілотажні літаки. Загинуло 70 людей — це одна з найважчих катастроф авіашоу в історії.","fa":"در ۲۸ اوت ۱۹۸۸، در یک نمایش هوایی در پایگاه هوایی رامشتاین، سه هواپیمای آکروباتیک در آسمان با هم برخورد کردند. ۷۰ نفر جان باختند — این یکی از سنگین‌ترین فاجعه‌های نمایش هوایی در تاریخ است.","it":"Il 28 agosto 1988, durante un'esibizione aerea sulla base aerea di Ramstein, tre aerei acrobatici collidono in volo. Muoiono 70 persone: è uno degli incidenti più gravi della storia delle manifestazioni aeree."},"B2":{"en":"On August 28, 1988, three aircraft of the Italian aerobatic squadron Frecce Tricolori collided in front of around 300,000 spectators at an air show at Ramstein Air Base. 70 people died. The disaster permanently changed safety regulations for air shows across Europe.","ar":"في 28 أغسطس 1988، اصطدمت ثلاث طائرات تابعة لفريق الاستعراض الجوي الإيطالي «فريتشي تريكولوري» أمام نحو 300,000 متفرج خلال عرض جوي في قاعدة رامشتاين الجوية. توفي 70 شخصاً. غيّرت الكارثة بشكل دائم متطلبات السلامة للعروض الجوية في جميع أنحاء أوروبا.","tr":"28 Ağustos 1988'de Ramstein Hava Üssü'ndeki bir hava gösterisinde, yaklaşık 300.000 seyirci önünde İtalyan akrobasi filosu Frecce Tricolori'ye ait üç uçak çarpıştı. 70 kişi öldü. Kaza, tüm Avrupa'da hava gösterileri için güvenlik koşullarını kalıcı olarak değiştirdi.","ru":"28 августа 1988 года на глазах примерно 300 000 зрителей на авиашоу на авиабазе Рамштайн столкнулись три самолёта итальянской пилотажной группы Frecce Tricolori. Погибли 70 человек. Катастрофа навсегда изменила требования безопасности для авиашоу по всей Европе.","es":"El 28 de agosto de 1988, ante unos 300.000 espectadores, colisionaron tres aviones de la escuadrilla acrobática italiana Frecce Tricolori durante un espectáculo aéreo en la base aérea de Ramstein. Murieron 70 personas. El desastre cambió de forma permanente las normas de seguridad para los espectáculos aéreos en toda Europa.","fr":"Le 28 août 1988, devant environ 300 000 spectateurs, trois avions de la patrouille acrobatique italienne Frecce Tricolori entrent en collision lors d'un meeting aérien à la base aérienne de Ramstein. 70 personnes meurent. La catastrophe modifie durablement les normes de sécurité des meetings aériens dans toute l'Europe.","pl":"28 sierpnia 1988 roku na oczach około 300 000 widzów zderzyły się trzy samoloty włoskiej eskadry akrobacyjnej Frecce Tricolori podczas pokazu lotniczego na bazie Ramstein. Zginęło 70 osób. Katastrofa trwale zmieniła przepisy bezpieczeństwa dla pokazów lotniczych w całej Europie.","uk":"28 серпня 1988 року на очах близько 300 000 глядачів зіткнулися три літаки італійської пілотажної групи Frecce Tricolori під час авіашоу на авіабазі Рамштайн. Загинуло 70 людей. Катастрофа назавжди змінила вимоги безпеки для авіашоу в усій Європі.","fa":"در ۲۸ اوت ۱۹۸۸، در برابر حدود ۳۰۰٬۰۰۰ تماشاگر، سه هواپیمای گروه آکروباتیک ایتالیایی «فرچه تریکولوری» در یک نمایش هوایی در پایگاه هوایی رامشتاین با هم برخورد کردند. ۷۰ نفر جان باختند. این فاجعه مقررات ایمنی نمایش‌های هوایی را در سراسر اروپا برای همیشه تغییر داد.","it":"Il 28 agosto 1988, davanti a circa 300.000 spettatori, tre velivoli della pattuglia acrobatica italiana Frecce Tricolori si scontrano durante un'esibizione sulla base aerea di Ramstein. Muoiono 70 persone. La tragedia cambia in modo permanente le norme di sicurezza per le manifestazioni aeree in tutta Europa."},"C1":{"en":"The Ramstein air show disaster of August 28, 1988, in which three Frecce Tricolori aircraft collided in front of around 300,000 spectators and 70 people lost their lives, ranks among the most consequential catastrophes of its kind worldwide and led to fundamentally tightened safety regulations for air shows in Germany and Europe.","ar":"تُعد كارثة اليوم الجوي في رامشتاين في 28 أغسطس 1988، حيث اصطدمت ثلاث طائرات تابعة لفريق فريتشي تريكولوري أمام نحو 300,000 متفرج وفقد 70 شخصاً حياتهم، من أخطر الكوارث من نوعها على مستوى العالم، وأدت إلى تشديد جذري لمتطلبات السلامة للعروض الجوية في ألمانيا وأوروبا.","tr":"28 Ağustos 1988'deki Ramstein hava gösterisi felaketinde, Frecce Tricolori'ye ait üç uçak yaklaşık 300.000 seyirci önünde çarpışmış ve 70 kişi hayatını kaybetmişti; bu olay, türünün dünya çapındaki en ağır sonuçlu felaketlerinden biri sayılır ve Almanya ile Avrupa'da hava gösterileri için köklü biçimde sıkılaştırılmış güvenlik koşullarına yol açtı.","ru":"Катастрофа на авиашоу в Рамштайне 28 августа 1988 года, где на глазах около 300 000 зрителей столкнулись три самолёта Frecce Tricolori и погибли 70 человек, считается одной из самых тяжёлых катастроф такого рода в мире и привела к принципиально ужесточённым требованиям безопасности для авиашоу в Германии и Европе.","es":"El desastre del espectáculo aéreo de Ramstein del 28 de agosto de 1988, en el que colisionaron tres aviones de los Frecce Tricolori ante unos 300.000 espectadores y perdieron la vida 70 personas, se cuenta entre las catástrofes más graves de este tipo a nivel mundial y condujo a una normativa de seguridad fundamentalmente más estricta para los espectáculos aéreos en Alemania y Europa.","fr":"La catastrophe du meeting aérien de Ramstein du 28 août 1988, au cours de laquelle trois avions des Frecce Tricolori sont entrés en collision devant environ 300 000 spectateurs et 70 personnes ont perdu la vie, compte parmi les catastrophes de ce type les plus lourdes de conséquences dans le monde et a entraîné un durcissement fondamental des normes de sécurité pour les meetings aériens en Allemagne et en Europe.","pl":"Katastrofa pokazu lotniczego w Ramstein z 28 sierpnia 1988 roku, podczas której zderzyły się trzy samoloty Frecce Tricolori na oczach około 300 000 widzów, a 70 osób straciło życie, należy do najbardziej brzemiennych w skutki katastrof tego rodzaju na świecie i doprowadziła do zasadniczo zaostrzonych przepisów bezpieczeństwa dla pokazów lotniczych w Niemczech i Europie.","uk":"Катастрофа на авіашоу в Рамштайні 28 серпня 1988 року, під час якої на очах близько 300 000 глядачів зіткнулися три літаки Frecce Tricolori і загинуло 70 людей, належить до найтяжчих за наслідками катастроф такого роду у світі та призвела до принципово посилених вимог безпеки для авіашоу в Німеччині та Європі.","fa":"فاجعه نمایش هوایی رامشتاین در ۲۸ اوت ۱۹۸۸، که در آن سه هواپیمای گروه فرچه تریکولوری در برابر حدود ۳۰۰٬۰۰۰ تماشاگر با هم برخورد کردند و ۷۰ نفر جان باختند، از پرآسیب‌ترین فجایع از این نوع در جهان به شمار می‌رود و به مقررات ایمنی اساساً سخت‌گیرانه‌تر برای نمایش‌های هوایی در آلمان و اروپا انجامید.","it":"Il disastro aereo di Ramstein del 28 agosto 1988, in cui tre velivoli delle Frecce Tricolori si scontrarono davanti a circa 300.000 spettatori causando la morte di 70 persone, è tra le catastrofi più gravi del suo genere a livello mondiale e portò a un drastico inasprimento delle norme di sicurezza per le manifestazioni aeree in Germania e in Europa."},"C2":{"en":"The Ramstein air show catastrophe of August 28, 1988, marks a turning point in the history of air show safety: the parliamentary review by a Bundestag committee of inquiry led to drastically tightened distance and safety rules for aerobatic displays across Europe that still apply today.","ar":"تُشكل كارثة اليوم الجوي في رامشتاين في 28 أغسطس 1988 نقطة تحول في تاريخ سلامة العروض الجوية: أدت المراجعة البرلمانية عبر لجنة تحقيق في البوندستاغ إلى قواعد مسافة وسلامة صارمة بشكل جذري للاستعراضات الجوية في جميع أنحاء أوروبا، لا تزال سارية حتى اليوم.","tr":"28 Ağustos 1988'deki Ramstein hava gösterisi felaketi, hava gösterisi güvenliği tarihinde bir dönüm noktasını işaret eder: Bundestag'ın bir soruşturma komisyonu aracılığıyla yaptığı parlamento incelemesi, bugüne kadar geçerli olan, tüm Avrupa'daki akrobasi gösterileri için ciddi biçimde sıkılaştırılmış mesafe ve güvenlik kurallarına yol açtı.","ru":"Катастрофа на авиашоу в Рамштайне 28 августа 1988 года стала поворотным пунктом в истории безопасности авиашоу: парламентское расследование, проведённое следственной комиссией Бундестага, привело к действующим и по сей день, значительно ужесточённым правилам дистанции и безопасности для пилотажных выступлений по всей Европе.","es":"La catástrofe del espectáculo aéreo de Ramstein del 28 de agosto de 1988 marca un punto de inflexión en la historia de la seguridad de los espectáculos aéreos: la investigación parlamentaria, llevada a cabo por una comisión de investigación del Bundestag, dio lugar a normas de distancia y seguridad drásticamente más estrictas, vigentes hasta hoy, para las exhibiciones acrobáticas en toda Europa.","fr":"La catastrophe du meeting aérien de Ramstein du 28 août 1988 marque un tournant dans l'histoire de la sécurité des meetings aériens : l'examen parlementaire mené par une commission d'enquête du Bundestag a abouti à des règles de distance et de sécurité radicalement renforcées, toujours en vigueur aujourd'hui, pour les démonstrations de voltige dans toute l'Europe.","pl":"Katastrofa pokazu lotniczego w Ramstein 28 sierpnia 1988 roku wyznacza punkt zwrotny w historii bezpieczeństwa pokazów lotniczych: parlamentarne wyjaśnienie sprawy przez komisję śledczą Bundestagu doprowadziło do drastycznie zaostrzonych, obowiązujących do dziś zasad odległości i bezpieczeństwa dla pokazów akrobacji lotniczej w całej Europie.","uk":"Катастрофа на авіашоу в Рамштайні 28 серпня 1988 року стала поворотним пунктом в історії безпеки авіашоу: парламентське розслідування слідчою комісією Бундестагу призвело до чинних і донині, різко посилених правил дистанції та безпеки для пілотажних виступів по всій Європі.","fa":"فاجعه نمایش هوایی رامشتاین در ۲۸ اوت ۱۹۸۸ نقطه عطفی در تاریخ ایمنی نمایش‌های هوایی است: بررسی پارلمانی توسط کمیته تحقیق بوندستاگ به قوانین فاصله و ایمنی به‌شدت سخت‌گیرانه‌تری برای نمایش‌های آکروباتیک در سراسر اروپا انجامید که تا امروز نیز معتبر است.","it":"La catastrofe aerea di Ramstein del 28 agosto 1988 segna una svolta nella storia della sicurezza delle manifestazioni aeree: l'inchiesta parlamentare condotta da una commissione d'indagine del Bundestag portò a regole di distanza e di sicurezza drasticamente più severe per le esibizioni acrobatiche in tutta Europa, tuttora in vigore."}}},"08-29":{"year":1929,"levels":{"A1":"Am 29. August 1929 landet das deutsche Luftschiff „Graf Zeppelin“ wieder in Amerika. Es ist einmal um die ganze Welt geflogen.","A2":"Am 29. August 1929 kehrt das deutsche Luftschiff „Graf Zeppelin“ nach Lakehurst in den USA zurück. Es hat als erstes Luftschiff die Erde umrundet.","B1":"Am 29. August 1929 landet das deutsche Luftschiff „Graf Zeppelin“ nach rund 21 Tagen wieder in Lakehurst (USA) und beendet damit die erste Erdumrundung eines Luftschiffs — eine technische Sensation ihrer Zeit.","B2":"Am 29. August 1929 kehrt das deutsche Luftschiff LZ 127 „Graf Zeppelin“ unter dem Kommando von Hugo Eckener nach rund 21 Tagen und über 30.000 zurückgelegten Kilometern nach Lakehurst (USA) zurück und schließt damit die erste Erdumrundung eines Luftschiffs erfolgreich ab.","C1":"Die am 29. August 1929 in Lakehurst abgeschlossene Weltumrundung des deutschen Luftschiffs LZ 127 „Graf Zeppelin“ unter Kapitän Hugo Eckener — mit Zwischenstopps in Friedrichshafen, Tokio und Los Angeles — gilt als eine der herausragenden technischen Leistungen der frühen Luftfahrtgeschichte und löste weltweit eine regelrechte Zeppelin-Begeisterung aus.","C2":"Die am 29. August 1929 vollendete, rund 21-tägige Weltumrundung des Luftschiffs LZ 127 „Graf Zeppelin“ unter der Leitung Hugo Eckeners demonstrierte eindrucksvoll das Potenzial der zivilen Luftschifffahrt und markierte zugleich deren historischen Höhepunkt, noch bevor die Technologie wenige Jahre später durch die Katastrophe der „Hindenburg“ ihren Ruf und ihre Zukunft verlieren sollte."},"translationsA1":{"en":"On August 29, 1929, the German airship 'Graf Zeppelin' lands in America again. It has flown all the way around the world.","ar":"في 29 أغسطس 1929، هبطت السفينة الجوية الألمانية «غراف زيبلين» في أمريكا مرة أخرى. لقد طارت حول العالم بأكمله.","tr":"29 Ağustos 1929'da Alman hava gemisi 'Graf Zeppelin' tekrar Amerika'ya indi. Tüm dünyayı dolaşarak uçmuştu.","ru":"29 августа 1929 года немецкий дирижабль «Граф Цеппелин» снова приземлился в Америке. Он облетел весь земной шар.","es":"El 29 de agosto de 1929, el dirigible alemán 'Graf Zeppelin' aterriza de nuevo en América. Ha volado alrededor de todo el mundo.","fr":"Le 29 août 1929, le dirigeable allemand « Graf Zeppelin » atterrit de nouveau en Amérique. Il a volé tout autour du monde.","pl":"29 sierpnia 1929 roku niemiecki sterowiec „Graf Zeppelin” ponownie wylądował w Ameryce. Okrążył cały świat.","uk":"29 серпня 1929 року німецький дирижабль «Граф Цеппелін» знову приземлився в Америці. Він облетів навколо всієї земної кулі.","fa":"در ۲۹ اوت ۱۹۲۹، کشتی هوایی آلمانی «گراف تسپلین» دوباره در آمریکا فرود آمد. این کشتی دور تا دور جهان پرواز کرده بود.","it":"Il 29 agosto 1929 il dirigibile tedesco \"Graf Zeppelin\" atterra di nuovo in America. Ha compiuto il giro del mondo intero."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 29, 1929, the German airship \"Graf Zeppelin\" returned to Lakehurst in the USA. It was the first airship to circumnavigate the globe.","ar":"في 29 أغسطس 1929، عادت المنطاد الألماني «غراف تسبلين» إلى ليكهيرست في الولايات المتحدة. كانت أول منطاد يدور حول الأرض.","tr":"29 Ağustos 1929'da Alman zeplini \"Graf Zeppelin\", ABD'deki Lakehurst'e geri döndü. Dünyayı dolaşan ilk hava gemisi olmuştu.","ru":"29 августа 1929 года немецкий дирижабль «Граф Цеппелин» вернулся в Лейкхёрст в США. Это был первый дирижабль, совершивший кругосветное путешествие.","es":"El 29 de agosto de 1929, el dirigible alemán \"Graf Zeppelin\" regresó a Lakehurst, en Estados Unidos. Fue el primer dirigible en dar la vuelta al mundo.","fr":"Le 29 août 1929, le dirigeable allemand « Graf Zeppelin » revient à Lakehurst, aux États-Unis. Il fut le premier dirigeable à faire le tour du monde.","pl":"29 sierpnia 1929 roku niemiecki sterowiec „Graf Zeppelin” wrócił do Lakehurst w USA. Był to pierwszy sterowiec, który okrążył Ziemię.","uk":"29 серпня 1929 року німецький дирижабль «Граф Цепелін» повернувся до Лейкхерста у США. Це був перший дирижабль, який облетів навколо Землі.","fa":"در ۲۹ اوت ۱۹۲۹، کشتی هوایی آلمانی «گراف زپلین» به لیک‌هرست در ایالات متحده بازگشت. این نخستین کشتی هوایی بود که دور زمین را طی کرد.","it":"Il 29 agosto 1929 il dirigibile tedesco \"Graf Zeppelin\" torna a Lakehurst, negli Stati Uniti. È stato il primo dirigibile a compiere il giro del mondo."},"B1":{"en":"On August 29, 1929, the German airship \"Graf Zeppelin\" landed again in Lakehurst (USA) after about 21 days, thereby completing the first circumnavigation of the globe by an airship — a technical sensation of its time.","ar":"في 29 أغسطس 1929، هبط المنطاد الألماني «غراف تسبلين» مجدداً في ليكهيرست (الولايات المتحدة) بعد نحو 21 يوماً، منهياً بذلك أول رحلة لمنطاد حول الأرض — وهي إثارة تقنية في زمانها.","tr":"29 Ağustos 1929'da Alman zeplini \"Graf Zeppelin\", yaklaşık 21 gün sonra tekrar Lakehurst'e (ABD) indi ve böylece bir zeplinin ilk dünya turunu tamamlamış oldu — döneminin teknik bir sansasyonuydu.","ru":"29 августа 1929 года немецкий дирижабль «Граф Цеппелин» приземлился обратно в Лейкхёрсте (США) примерно через 21 день, завершив тем самым первое кругосветное путешествие дирижабля — техническую сенсацию своего времени.","es":"El 29 de agosto de 1929, el dirigible alemán \"Graf Zeppelin\" aterrizó de nuevo en Lakehurst (EE. UU.) tras unos 21 días, completando así la primera vuelta al mundo de un dirigible, una sensación técnica de su época.","fr":"Le 29 août 1929, le dirigeable allemand « Graf Zeppelin » atterrit de nouveau à Lakehurst (États-Unis) après environ 21 jours, achevant ainsi le premier tour du monde effectué par un dirigeable — une sensation technique pour l'époque.","pl":"29 sierpnia 1929 roku niemiecki sterowiec „Graf Zeppelin” wylądował ponownie w Lakehurst (USA) po około 21 dniach, kończąc tym samym pierwsze okrążenie Ziemi przez sterowiec — techniczną sensację swoich czasów.","uk":"29 серпня 1929 року німецький дирижабль «Граф Цепелін» приземлився знову в Лейкхерсті (США) приблизно через 21 день, завершивши перше навколосвітнє облітання Землі дирижаблем — технічну сенсацію свого часу.","fa":"در ۲۹ اوت ۱۹۲۹، کشتی هوایی آلمانی «گراف زپلین» پس از حدود ۲۱ روز دوباره در لیک‌هرست (ایالات متحده) فرود آمد و بدین‌سان نخستین دور زدن یک کشتی هوایی به دور زمین را به پایان رساند — رویدادی تکنولوژیک شگفت‌انگیز در زمان خود.","it":"Il 29 agosto 1929 il dirigibile tedesco \"Graf Zeppelin\" atterra nuovamente a Lakehurst (USA) dopo circa 21 giorni, concludendo così il primo giro del mondo compiuto da un dirigibile — una sensazione tecnica per l'epoca."},"B2":{"en":"On August 29, 1929, the German airship LZ 127 \"Graf Zeppelin\", under the command of Hugo Eckener, returned to Lakehurst (USA) after about 21 days and more than 30,000 kilometers travelled, thereby successfully completing the first circumnavigation of the globe by an airship.","ar":"في 29 أغسطس 1929، عاد المنطاد الألماني LZ 127 «غراف تسبلين» تحت قيادة هوغو إكنر إلى ليكهيرست (الولايات المتحدة) بعد نحو 21 يوماً وأكثر من 30,000 كيلومتر مقطوعة، لينهي بذلك بنجاح أول رحلة لمنطاد حول الأرض.","tr":"29 Ağustos 1929'da Hugo Eckener komutasındaki Alman zeplini LZ 127 \"Graf Zeppelin\", yaklaşık 21 gün ve 30.000 kilometreden fazla yol kat ettikten sonra Lakehurst'e (ABD) döndü ve böylece bir zeplinin ilk dünya turunu başarıyla tamamladı.","ru":"29 августа 1929 года немецкий дирижабль LZ 127 «Граф Цеппелин» под командованием Хуго Эккенера вернулся в Лейкхёрст (США) после примерно 21 дня и более 30 000 пройденных километров, тем самым успешно завершив первое кругосветное путешествие дирижабля.","es":"El 29 de agosto de 1929, el dirigible alemán LZ 127 \"Graf Zeppelin\", al mando de Hugo Eckener, regresó a Lakehurst (EE. UU.) tras unos 21 días y más de 30.000 kilómetros recorridos, completando así con éxito la primera vuelta al mundo de un dirigible.","fr":"Le 29 août 1929, le dirigeable allemand LZ 127 « Graf Zeppelin », sous le commandement de Hugo Eckener, revient à Lakehurst (États-Unis) après environ 21 jours et plus de 30 000 kilomètres parcourus, achevant ainsi avec succès le premier tour du monde effectué par un dirigeable.","pl":"29 sierpnia 1929 roku niemiecki sterowiec LZ 127 „Graf Zeppelin” pod dowództwem Hugo Eckenera wrócił do Lakehurst (USA) po około 21 dniach i ponad 30 000 przebytych kilometrów, pomyślnie kończąc tym samym pierwsze okrążenie Ziemi przez sterowiec.","uk":"29 серпня 1929 року німецький дирижабль LZ 127 «Граф Цепелін» під командуванням Гуго Еккенера повернувся до Лейкхерста (США) приблизно через 21 день і понад 30 000 подоланих кілометрів, успішно завершивши перше навколосвітнє облітання дирижаблем.","fa":"در ۲۹ اوت ۱۹۲۹، کشتی هوایی آلمانی LZ 127 «گراف زپلین» تحت فرماندهی هوگو اکنر پس از حدود ۲۱ روز و بیش از ۳۰٬۰۰۰ کیلومتر مسافت پیموده‌شده به لیک‌هرست (ایالات متحده) بازگشت و بدین‌سان نخستین دور زدن یک کشتی هوایی به دور زمین را با موفقیت به پایان رساند.","it":"Il 29 agosto 1929 il dirigibile tedesco LZ 127 \"Graf Zeppelin\", al comando di Hugo Eckener, torna a Lakehurst (Stati Uniti) dopo circa 21 giorni e oltre 30.000 chilometri percorsi, concludendo con successo il primo giro del mondo compiuto da un dirigibile."},"C1":{"en":"The circumnavigation of the globe by the German airship LZ 127 \"Graf Zeppelin\" under Captain Hugo Eckener, completed in Lakehurst on August 29, 1929 — with stopovers in Friedrichshafen, Tokyo, and Los Angeles — is considered one of the outstanding technical achievements of early aviation history and sparked a veritable zeppelin craze worldwide.","ar":"تُعد رحلة الطواف حول العالم التي أتمها المنطاد الألماني LZ 127 «غراف تسبلين» بقيادة الكابتن هوغو إكنر في ليكهيرست في 29 أغسطس 1929 — بمحطات توقف في فريدريشسهافن وطوكيو ولوس أنجلوس — واحدة من أبرز الإنجازات التقنية في تاريخ الطيران المبكر، وأثارت حماساً حقيقياً للمناطيد في جميع أنحاء العالم.","tr":"Kaptan Hugo Eckener komutasındaki Alman zeplini LZ 127 \"Graf Zeppelin\"in, Friedrichshafen, Tokyo ve Los Angeles'ta yapılan aralarla 29 Ağustos 1929'da Lakehurst'te tamamladığı dünya turu, erken havacılık tarihinin en dikkat çekici teknik başarılarından biri olarak kabul edilir ve dünya çapında gerçek bir zeplin coşkusu yarattı.","ru":"Кругосветное путешествие немецкого дирижабля LZ 127 «Граф Цеппелин» под командованием капитана Хуго Эккенера, завершившееся в Лейкхёрсте 29 августа 1929 года — с промежуточными остановками во Фридрихсхафене, Токио и Лос-Анджелесе, — считается одним из выдающихся технических достижений ранней истории авиации и вызвало во всём мире настоящий цеппелиновый ажиотаж.","es":"La vuelta al mundo del dirigible alemán LZ 127 \"Graf Zeppelin\" al mando del capitán Hugo Eckener, concluida en Lakehurst el 29 de agosto de 1929 —con escalas en Friedrichshafen, Tokio y Los Ángeles—, se considera uno de los logros técnicos sobresalientes de los inicios de la aviación y desató en todo el mundo un verdadero entusiasmo por los zepelines.","fr":"Le tour du monde du dirigeable allemand LZ 127 « Graf Zeppelin », sous les ordres du capitaine Hugo Eckener, achevé à Lakehurst le 29 août 1929 — avec des escales à Friedrichshafen, Tokyo et Los Angeles — est considéré comme l'un des exploits techniques marquants des débuts de l'histoire de l'aviation et déclencha dans le monde entier un véritable engouement pour les zeppelins.","pl":"Okrążenie Ziemi przez niemiecki sterowiec LZ 127 „Graf Zeppelin” pod dowództwem kapitana Hugo Eckenera, zakończone w Lakehurst 29 sierpnia 1929 roku — z międzylądowaniami we Friedrichshafen, Tokio i Los Angeles — uchodzi za jedno z wybitnych osiągnięć technicznych wczesnej historii lotnictwa i wywołało na całym świecie prawdziwą fascynację sterowcami.","uk":"Навколосвітня подорож німецького дирижабля LZ 127 «Граф Цепелін» під командуванням капітана Гуго Еккенера, завершена в Лейкхерсті 29 серпня 1929 року — із зупинками у Фрідріхсгафені, Токіо та Лос-Анджелесі, — вважається одним із визначних технічних досягнень ранньої історії авіації і викликала у світі справжнє захоплення дирижаблями.","fa":"دور زدن به دور زمین توسط کشتی هوایی آلمانی LZ 127 «گراف زپلین» به فرماندهی کاپیتان هوگو اکنر، که در ۲۹ اوت ۱۹۲۹ در لیک‌هرست به پایان رسید — با توقف‌هایی در فریدریشسهافن، توکیو و لس‌آنجلس — یکی از دستاوردهای برجسته فنی تاریخ اولیه هوانوردی به شمار می‌رود و شور و شوقی واقعی نسبت به کشتی‌های هوایی زپلین در سراسر جهان برانگیخت.","it":"Il giro del mondo del dirigibile tedesco LZ 127 \"Graf Zeppelin\", al comando del capitano Hugo Eckener, concluso a Lakehurst il 29 agosto 1929 — con scali a Friedrichshafen, Tokyo e Los Angeles — è considerato una delle imprese tecniche più straordinarie dei primi anni dell'aviazione e scatenò in tutto il mondo un vero e proprio entusiasmo per gli zeppelin."},"C2":{"en":"The roughly 21-day circumnavigation of the globe by the airship LZ 127 \"Graf Zeppelin\" under the leadership of Hugo Eckener, completed on August 29, 1929, impressively demonstrated the potential of civilian airship travel and at the same time marked its historic high point, even before the technology would lose its reputation and its future a few years later through the \"Hindenburg\" disaster.","ar":"أظهرت رحلة الطواف حول العالم التي استغرقت نحو 21 يوماً واكتملت في 29 أغسطس 1929 للمنطاد LZ 127 «غراف تسبلين» بقيادة هوغو إكنر إمكانات الملاحة الجوية المدنية بشكل مبهر، وشكّلت في الوقت نفسه ذروتها التاريخية، قبل أن تفقد هذه التقنية سمعتها ومستقبلها بعد سنوات قليلة إثر كارثة «هيندنبورغ».","tr":"Hugo Eckener önderliğinde 29 Ağustos 1929'da tamamlanan, yaklaşık 21 günlük LZ 127 \"Graf Zeppelin\" dünya turu, sivil hava gemiciliğinin potansiyelini etkileyici biçimde gösterdi ve aynı zamanda bu teknolojinin, birkaç yıl sonra \"Hindenburg\" felaketiyle itibarını ve geleceğini kaybetmesinden önceki tarihsel doruk noktasını işaret etti.","ru":"Завершившееся 29 августа 1929 года почти 21-дневное кругосветное путешествие дирижабля LZ 127 «Граф Цеппелин» под руководством Хуго Эккенера впечатляюще продемонстрировало потенциал гражданского дирижаблестроения и одновременно ознаменовало его исторический пик — ещё до того, как эта технология спустя несколько лет утратила свою репутацию и будущее из-за катастрофы «Гинденбурга».","es":"La vuelta al mundo de unos 21 días del dirigible LZ 127 \"Graf Zeppelin\", bajo la dirección de Hugo Eckener y concluida el 29 de agosto de 1929, demostró de manera impresionante el potencial de la navegación aérea civil y marcó al mismo tiempo su punto culminante histórico, aún antes de que la tecnología perdiera su reputación y su futuro pocos años después a causa del desastre del \"Hindenburg\".","fr":"Le tour du monde d'environ 21 jours du dirigeable LZ 127 « Graf Zeppelin », sous la direction de Hugo Eckener et achevé le 29 août 1929, a démontré de façon impressionnante le potentiel de l'aéronautique civile par dirigeable et a marqué en même temps son apogée historique, avant même que cette technologie ne perde, quelques années plus tard, sa réputation et son avenir avec la catastrophe du « Hindenburg ».","pl":"Trwające około 21 dni okrążenie Ziemi przez sterowiec LZ 127 „Graf Zeppelin” pod kierownictwem Hugo Eckenera, zakończone 29 sierpnia 1929 roku, w imponujący sposób pokazało potencjał cywilnej żeglugi powietrznej sterowcami i jednocześnie wyznaczyło jej historyczny szczyt, jeszcze zanim technologia ta kilka lat później utraciła swoją reputację i przyszłość wskutek katastrofy „Hindenburga”.","uk":"Приблизно 21-денне навколосвітнє облітання дирижабля LZ 127 «Граф Цепелін» під керівництвом Гуго Еккенера, завершене 29 серпня 1929 року, вражаюче продемонструвало потенціал цивільного дирижаблебудування і водночас позначило його історичний пік — ще до того, як ця технологія через кілька років втратила свою репутацію та майбутнє через катастрофу «Гінденбурга».","fa":"دور زدن به دور زمین در حدود ۲۱ روز توسط کشتی هوایی LZ 127 «گراف زپلین» به رهبری هوگو اکنر، که در ۲۹ اوت ۱۹۲۹ به پایان رسید، پتانسیل کشتیرانی هوایی غیرنظامی را به‌طرز چشمگیری نشان داد و در همان حال اوج تاریخی آن را رقم زد — پیش از آنکه این فناوری چند سال بعد با فاجعه «هیندنبورگ» شهرت و آینده خود را از دست بدهد.","it":"Il giro del mondo del dirigibile LZ 127 \"Graf Zeppelin\", durato circa 21 giorni e completato il 29 agosto 1929 sotto la guida di Hugo Eckener, dimostrò in modo impressionante il potenziale dell'aeronavigazione civile e ne segnò al contempo l'apice storico, prima che, pochi anni dopo, la catastrofe dell'\"Hindenburg\" facesse perdere a questa tecnologia la propria reputazione e il proprio futuro."}}},"08-30":{"year":1945,"levels":{"A1":"Am 30. August 1945 treffen sich wichtige Politiker in Berlin. Sie bilden den Alliierten Kontrollrat. Er regiert jetzt ganz Deutschland.","A2":"Am 30. August 1945 gründen die vier Siegermächte den Alliierten Kontrollrat in Berlin. Dieser übernimmt die höchste Regierungsgewalt über ganz Deutschland.","B1":"Am 30. August 1945 konstituiert sich in Berlin der Alliierte Kontrollrat. Er besteht aus den vier Oberbefehlshabern der Besatzungstruppen und übernimmt gemeinsam die oberste Regierungsgewalt über Deutschland.","B2":"Am 30. August 1945 nimmt in Berlin der Alliierte Kontrollrat seine Arbeit auf — zusammengesetzt aus den vier Oberbefehlshabern der amerikanischen, britischen, französischen und sowjetischen Besatzungszone. Er repräsentiert Deutschland fortan als Ganzes, auch wenn sich die vier Zonen politisch bald eher auseinanderentwickeln als annähern.","C1":"Mit der Konstituierung des Alliierten Kontrollrats am 30. August 1945 in Berlin übernehmen die vier Besatzungsmächte offiziell die oberste Regierungsgewalt über das besiegte Deutschland — ein Gremium, dessen anfänglicher Anspruch auf gemeinsame Verwaltung schon bald an den unterschiedlichen politischen Zielen der Siegermächte scheitern sollte.","C2":"Die Konstituierung des Alliierten Kontrollrats am 30. August 1945 markiert formal den Beginn der gemeinsamen alliierten Verwaltung Deutschlands — ein Anspruch, der angesichts der bald divergierenden Besatzungspolitiken, allen voran des französischen Vetos gegen gesamtdeutsche Zentralverwaltungen, schon im Herbst desselben Jahres brüchig wurde und den Weg in die spätere deutsche Teilung mitbereitete."},"translationsA1":{"en":"On August 30, 1945, important politicians meet in Berlin. They form the Allied Control Council. It now governs all of Germany.","ar":"في 30 أغسطس 1945، اجتمع سياسيون مهمون في برلين. شكّلوا مجلس الرقابة الحلفاء. يحكم الآن ألمانيا بأكملها.","tr":"30 Ağustos 1945'te önemli politikacılar Berlin'de bir araya geldi. Müttefik Kontrol Konseyi'ni kurdular. Artık tüm Almanya'yı yönetiyor.","ru":"30 августа 1945 года важные политики встретились в Берлине. Они образовали Союзный контрольный совет. Теперь он управляет всей Германией.","es":"El 30 de agosto de 1945, importantes políticos se reúnen en Berlín. Forman el Consejo de Control Aliado. Ahora gobierna toda Alemania.","fr":"Le 30 août 1945, d'importants hommes politiques se réunissent à Berlin. Ils forment le Conseil de contrôle allié. Il gouverne désormais toute l'Allemagne.","pl":"30 sierpnia 1945 roku ważni politycy spotkali się w Berlinie. Utworzyli Sojuszniczą Radę Kontroli. Rządzi ona teraz całymi Niemcami.","uk":"30 серпня 1945 року важливі політики зустрілися в Берліні. Вони утворили Союзну контрольну раду. Тепер вона керує всією Німеччиною.","fa":"در ۳۰ اوت ۱۹۴۵، سیاستمداران مهم در برلین گرد هم آمدند. آن‌ها شورای کنترل متفقین را تشکیل دادند. اکنون این شورا بر کل آلمان حکومت می‌کند.","it":"Il 30 agosto 1945 importanti politici si incontrano a Berlino. Formano il Consiglio di Controllo Alleato. Ora governa tutta la Germania."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 30, 1945, the four victorious powers founded the Allied Control Council in Berlin. It took over the highest governmental authority over the whole of Germany.","ar":"في 30 أغسطس 1945، أسست القوى المنتصرة الأربع مجلس الرقابة الحلفاء في برلين. تولى هذا المجلس أعلى سلطة حكومية على ألمانيا بأكملها.","tr":"30 Ağustos 1945'te dört galip devlet Berlin'de Müttefik Kontrol Konseyi'ni kurdu. Bu konsey, tüm Almanya üzerindeki en yüksek hükümet yetkisini devraldı.","ru":"30 августа 1945 года четыре державы-победительницы основали в Берлине Союзный контрольный совет. Он взял на себя высшую государственную власть над всей Германией.","es":"El 30 de agosto de 1945, las cuatro potencias vencedoras fundaron el Consejo de Control Aliado en Berlín. Este asumió la máxima autoridad de gobierno sobre toda Alemania.","fr":"Le 30 août 1945, les quatre puissances victorieuses fondent le Conseil de contrôle allié à Berlin. Celui-ci prend en charge le pouvoir gouvernemental suprême sur l'ensemble de l'Allemagne.","pl":"30 sierpnia 1945 roku cztery mocarstwa zwycięskie założyły w Berlinie Sojuszniczą Radę Kontroli. Przejęła ona najwyższą władzę rządową nad całymi Niemcami.","uk":"30 серпня 1945 року чотири держави-переможниці заснували в Берліні Союзну контрольну раду. Вона взяла на себе найвищу урядову владу над усією Німеччиною.","fa":"در ۳۰ اوت ۱۹۴۵، چهار قدرت پیروز شورای کنترل متفقین را در برلین تأسیس کردند. این شورا بالاترین قدرت حکومتی بر سراسر آلمان را بر عهده گرفت.","it":"Il 30 agosto 1945 le quattro potenze vincitrici fondano a Berlino il Consiglio di Controllo Alleato. Esso assume il potere di governo supremo su tutta la Germania."},"B1":{"en":"On August 30, 1945, the Allied Control Council was constituted in Berlin. It consisted of the four commanders-in-chief of the occupying forces and jointly took over supreme governmental authority over Germany.","ar":"في 30 أغسطس 1945، تأسس مجلس الرقابة الحلفاء في برلين. يتألف من القادة العامين الأربعة لقوات الاحتلال، وتولوا معاً السلطة الحكومية العليا على ألمانيا.","tr":"30 Ağustos 1945'te Müttefik Kontrol Konseyi Berlin'de kuruldu. Konsey, işgal kuvvetlerinin dört başkomutanından oluşuyor ve Almanya üzerindeki en yüksek hükümet yetkisini ortaklaşa devralıyordu.","ru":"30 августа 1945 года в Берлине был образован Союзный контрольный совет. Он состоял из четырёх главнокомандующих оккупационными войсками и совместно принял высшую государственную власть над Германией.","es":"El 30 de agosto de 1945 se constituyó en Berlín el Consejo de Control Aliado. Estaba formado por los cuatro comandantes en jefe de las tropas de ocupación y asumió conjuntamente la máxima autoridad de gobierno sobre Alemania.","fr":"Le 30 août 1945, le Conseil de contrôle allié se constitue à Berlin. Il se compose des quatre commandants en chef des troupes d'occupation et assume conjointement le pouvoir gouvernemental suprême sur l'Allemagne.","pl":"30 sierpnia 1945 roku w Berlinie ukonstytuowała się Sojusznicza Rada Kontroli. Składała się z czterech naczelnych dowódców wojsk okupacyjnych i wspólnie przejęła najwyższą władzę rządową nad Niemcami.","uk":"30 серпня 1945 року в Берліні утворилася Союзна контрольна рада. До її складу входили чотири головнокомандувачі окупаційних військ, які спільно взяли на себе найвищу урядову владу над Німеччиною.","fa":"در ۳۰ اوت ۱۹۴۵، شورای کنترل متفقین در برلین تشکیل شد. این شورا از چهار فرمانده کل نیروهای اشغالگر تشکیل شده بود و به‌طور مشترک بالاترین قدرت حکومتی بر آلمان را بر عهده گرفت.","it":"Il 30 agosto 1945 si costituisce a Berlino il Consiglio di Controllo Alleato. È composto dai quattro comandanti supremi delle truppe di occupazione, che assumono congiuntamente il potere di governo supremo sulla Germania."},"B2":{"en":"On August 30, 1945, the Allied Control Council began its work in Berlin — made up of the four commanders-in-chief of the American, British, French, and Soviet occupation zones. From then on it represented Germany as a whole, even though the four zones would soon develop apart politically rather than growing closer.","ar":"في 30 أغسطس 1945، بدأ مجلس الرقابة الحلفاء أعماله في برلين — مكوناً من القادة العامين الأربعة لمناطق الاحتلال الأمريكية والبريطانية والفرنسية والسوفيتية. مثّل من ثم ألمانيا ككل، رغم أن المناطق الأربع سرعان ما بدأت تتباعد سياسياً بدلاً من أن تتقارب.","tr":"30 Ağustos 1945'te Berlin'de Müttefik Kontrol Konseyi çalışmalarına başladı — Amerikan, İngiliz, Fransız ve Sovyet işgal bölgelerinin dört başkomutanından oluşuyordu. Bundan böyle Almanya'yı bir bütün olarak temsil etti, ancak dört bölge siyasi olarak kısa süre içinde yakınlaşmak yerine daha çok birbirinden uzaklaştı.","ru":"30 августа 1945 года в Берлине приступил к работе Союзный контрольный совет, состоявший из четырёх главнокомандующих американской, британской, французской и советской оккупационными зонами. Отныне он представлял Германию как единое целое, хотя вскоре четыре зоны политически стали скорее расходиться, чем сближаться.","es":"El 30 de agosto de 1945, el Consejo de Control Aliado comenzó a funcionar en Berlín, integrado por los cuatro comandantes en jefe de las zonas de ocupación estadounidense, británica, francesa y soviética. A partir de entonces representó a Alemania como un todo, aunque las cuatro zonas pronto se distanciarían políticamente en lugar de acercarse.","fr":"Le 30 août 1945, le Conseil de contrôle allié entame ses travaux à Berlin — composé des quatre commandants en chef des zones d'occupation américaine, britannique, française et soviétique. Il représente désormais l'Allemagne dans son ensemble, même si les quatre zones allaient bientôt plutôt se séparer que se rapprocher sur le plan politique.","pl":"30 sierpnia 1945 roku w Berlinie rozpoczęła pracę Sojusznicza Rada Kontroli — złożona z czterech naczelnych dowódców amerykańskiej, brytyjskiej, francuskiej i radzieckiej strefy okupacyjnej. Odtąd reprezentowała Niemcy jako całość, choć te cztery strefy wkrótce raczej rozchodziły się politycznie, niż zbliżały.","uk":"30 серпня 1945 року в Берліні розпочала роботу Союзна контрольна рада — у складі чотирьох головнокомандувачів американської, британської, французької та радянської окупаційних зон. Відтоді вона представляла Німеччину як єдине ціле, хоча незабаром чотири зони політично радше розходилися, ніж зближувалися.","fa":"در ۳۰ اوت ۱۹۴۵، شورای کنترل متفقین در برلین کار خود را آغاز کرد — متشکل از چهار فرمانده کل مناطق اشغالی آمریکایی، بریتانیایی، فرانسوی و شوروی. این شورا از آن پس آلمان را به‌عنوان یک کل نمایندگی می‌کرد، هرچند این چهار منطقه به‌زودی از نظر سیاسی بیشتر از هم دور شدند تا به هم نزدیک.","it":"Il 30 agosto 1945 il Consiglio di Controllo Alleato inizia i propri lavori a Berlino, composto dai quattro comandanti supremi delle zone di occupazione americana, britannica, francese e sovietica. Da quel momento rappresenta la Germania nel suo insieme, anche se le quattro zone si allontaneranno presto politicamente invece di avvicinarsi."},"C1":{"en":"With the constitution of the Allied Control Council on August 30, 1945, in Berlin, the four occupying powers officially took over supreme governmental authority over defeated Germany — a body whose initial claim to joint administration would soon fail because of the differing political goals of the victorious powers.","ar":"بتأسيس مجلس الرقابة الحلفاء في 30 أغسطس 1945 في برلين، تولت القوى المحتلة الأربع رسمياً السلطة الحكومية العليا على ألمانيا المهزومة — وهي هيئة كان طموحها الأولي للإدارة المشتركة سرعان ما سيفشل بسبب اختلاف الأهداف السياسية للقوى المنتصرة.","tr":"30 Ağustos 1945'te Berlin'de Müttefik Kontrol Konseyi'nin kurulmasıyla dört işgal gücü, mağlup Almanya üzerindeki en yüksek hükümet yetkisini resmen devraldı — bu organın ortak yönetim iddiası, galip devletlerin farklı siyasi hedefleri nedeniyle kısa süre içinde başarısızlığa uğrayacaktı.","ru":"С образованием Союзного контрольного совета 30 августа 1945 года в Берлине четыре оккупационные державы официально взяли на себя высшую государственную власть над побеждённой Германией — орган, чья первоначальная претензия на совместное управление вскоре потерпела крах из-за различных политических целей держав-победительниц.","es":"Con la constitución del Consejo de Control Aliado el 30 de agosto de 1945 en Berlín, las cuatro potencias ocupantes asumieron oficialmente la máxima autoridad de gobierno sobre la Alemania derrotada, un organismo cuya pretensión inicial de administración conjunta pronto fracasaría debido a los diferentes objetivos políticos de las potencias vencedoras.","fr":"Avec la constitution du Conseil de contrôle allié le 30 août 1945 à Berlin, les quatre puissances occupantes assument officiellement le pouvoir gouvernemental suprême sur l'Allemagne vaincue — un organe dont la prétention initiale à une administration commune allait bientôt échouer en raison des objectifs politiques divergents des puissances victorieuses.","pl":"Wraz z ukonstytuowaniem się Sojuszniczej Rady Kontroli 30 sierpnia 1945 roku w Berlinie cztery mocarstwa okupacyjne oficjalnie przejęły najwyższą władzę rządową nad pokonanymi Niemcami — organu, którego początkowe roszczenie do wspólnego zarządzania miało wkrótce upaść z powodu odmiennych celów politycznych mocarstw zwycięskich.","uk":"Із заснуванням Союзної контрольної ради 30 серпня 1945 року в Берліні чотири окупаційні держави офіційно взяли на себе найвищу урядову владу над переможеною Німеччиною — орган, чиї початкові претензії на спільне управління невдовзі зазнали краху через різні політичні цілі держав-переможниць.","fa":"با تشکیل شورای کنترل متفقین در ۳۰ اوت ۱۹۴۵ در برلین، چهار قدرت اشغالگر رسماً بالاترین قدرت حکومتی بر آلمان شکست‌خورده را بر عهده گرفتند — نهادی که ادعای اولیه‌اش برای اداره مشترک به‌زودی به دلیل اهداف سیاسی متفاوت قدرت‌های پیروز با شکست مواجه شد.","it":"Con la costituzione del Consiglio di Controllo Alleato a Berlino, il 30 agosto 1945, le quattro potenze occupanti assumono ufficialmente il potere di governo supremo sulla Germania sconfitta — un organo la cui iniziale pretesa di un'amministrazione comune sarebbe presto naufragata di fronte ai diversi obiettivi politici delle potenze vincitrici."},"C2":{"en":"The constitution of the Allied Control Council on August 30, 1945, formally marks the beginning of joint Allied administration of Germany — a claim that, given the soon-diverging occupation policies, above all the French veto against all-German central administrations, was already cracking by the autumn of the same year and helped pave the way toward the later division of Germany.","ar":"يُشكل تأسيس مجلس الرقابة الحلفاء في 30 أغسطس 1945 رسمياً بداية الإدارة الحليفة المشتركة لألمانيا — وهو ادعاء بدأ يتصدع بالفعل في خريف العام نفسه في ضوء تباعد سياسات الاحتلال، وفي مقدمتها الفيتو الفرنسي ضد الإدارات المركزية الألمانية الموحدة، وأسهم في تمهيد الطريق نحو الانقسام الألماني اللاحق.","tr":"30 Ağustos 1945'te Müttefik Kontrol Konseyi'nin kurulması, biçimsel olarak Almanya'nın ortak müttefik yönetiminin başlangıcını işaret eder — ancak bu iddia, işgal politikalarının kısa sürede birbirinden ayrışması, özellikle de Fransa'nın Almanya genelinde merkezi yönetimlere karşı verdiği veto nedeniyle daha aynı yılın sonbaharında sarsılmış ve sonraki Alman bölünmesinin yolunu döşemeye katkıda bulunmuştur.","ru":"Образование Союзного контрольного совета 30 августа 1945 года формально знаменует начало совместного управления Германией союзниками — притязание, которое уже осенью того же года начало давать трещину ввиду вскоре разошедшейся оккупационной политики, прежде всего французского вето на общегерманские центральные органы управления, и тем самым способствовало подготовке пути к последующему разделению Германии.","es":"La constitución del Consejo de Control Aliado el 30 de agosto de 1945 marca formalmente el inicio de la administración conjunta aliada de Alemania, una pretensión que, dadas las políticas de ocupación pronto divergentes —ante todo el veto francés a las administraciones centrales pangermanas—, ya se resquebrajaba en el otoño del mismo año y contribuyó a allanar el camino hacia la posterior división de Alemania.","fr":"La constitution du Conseil de contrôle allié le 30 août 1945 marque formellement le début de l'administration alliée commune de l'Allemagne — une prétention qui, face aux politiques d'occupation bientôt divergentes, au premier rang desquelles le veto français contre des administrations centrales pour l'ensemble de l'Allemagne, se fissurait déjà à l'automne de la même année et a contribué à préparer la voie vers la partition ultérieure de l'Allemagne.","pl":"Ukonstytuowanie się Sojuszniczej Rady Kontroli 30 sierpnia 1945 roku formalnie wyznacza początek wspólnej alianckiej administracji Niemiec — roszczenie, które wobec wkrótce rozbieżnych polityk okupacyjnych, przede wszystkim francuskiego weta wobec ogólnoniemieckich zarządów centralnych, załamało się już jesienią tego samego roku i przyczyniło się do utorowania drogi do późniejszego podziału Niemiec.","uk":"Заснування Союзної контрольної ради 30 серпня 1945 року формально знаменує початок спільного союзницького управління Німеччиною — претензія, яка з огляду на невдовзі розбіжну окупаційну політику, передусім французьке вето проти загальнонімецьких центральних адміністрацій, вже восени того самого року почала тріщати і сприяла прокладанню шляху до подальшого поділу Німеччини.","fa":"تشکیل شورای کنترل متفقین در ۳۰ اوت ۱۹۴۵ به‌طور رسمی آغاز اداره مشترک متفقین بر آلمان را رقم می‌زند — ادعایی که با توجه به سیاست‌های اشغالگرانه‌ای که به‌زودی از هم واگرا شدند، به‌ویژه وتوی فرانسه علیه اداره‌های مرکزی سراسری آلمان، همان پاییز سال مذکور سست شد و راه را برای تجزیه بعدی آلمان هموار کرد.","it":"La costituzione del Consiglio di Controllo Alleato il 30 agosto 1945 segna formalmente l'inizio dell'amministrazione congiunta alleata della Germania — una pretesa che, di fronte alle politiche di occupazione presto divergenti, prima fra tutte il veto francese contro amministrazioni centrali per l'intera Germania, si incrinò già nell'autunno dello stesso anno, contribuendo a preparare la strada verso la successiva divisione tedesca."}}},"08-31":{"year":1990,"levels":{"A1":"Am 31. August 1990 unterschreiben Ost- und Westdeutschland einen wichtigen Vertrag. Er heißt Einigungsvertrag.","A2":"Am 31. August 1990 unterschreiben BRD und DDR den Einigungsvertrag. Er regelt, wie Deutschland wieder ein Land wird.","B1":"Am 31. August 1990 unterzeichnen Vertreter von BRD und DDR in Ost-Berlin den Einigungsvertrag. Er legt die rechtlichen Regeln für die Wiedervereinigung am 3. Oktober fest.","B2":"Am 31. August 1990 unterzeichnen der westdeutsche Innenminister Wolfgang Schäuble und der DDR-Staatssekretär Günther Krause in Ost-Berlin den Einigungsvertrag — das juristische Fundament für den Beitritt der DDR zur Bundesrepublik nur fünf Wochen später.","C1":"Der am 31. August 1990 von Wolfgang Schäuble und Günther Krause unterzeichnete Einigungsvertrag regelte detailliert die rechtlichen, wirtschaftlichen und sozialen Bedingungen des DDR-Beitritts und bildete damit die verbindliche Grundlage für die formale Wiedervereinigung am 3. Oktober 1990.","C2":"Der Einigungsvertrag vom 31. August 1990 übersetzte den politischen Willen zur deutschen Einheit in ein komplexes Regelwerk, das Rechtsangleichung, Eigentumsfragen und die Übernahme west­deutscher Institutionen in den neuen Bundesländern verbindlich festlegte — ein bürokratischer Kraftakt von historischem Ausmaß."},"translationsA1":{"en":"On August 31, 1990, East and West Germany sign an important treaty. It is called the Unification Treaty.","ar":"في 31 أغسطس 1990، وقّعت ألمانيا الشرقية والغربية معاهدة مهمة. تسمى معاهدة الوحدة.","tr":"31 Ağustos 1990'da Doğu ve Batı Almanya önemli bir anlaşma imzaladı. Adı Birleşme Antlaşması.","ru":"31 августа 1990 года Восточная и Западная Германия подписали важный договор. Он называется Договор об объединении.","es":"El 31 de agosto de 1990, Alemania Oriental y Occidental firman un tratado importante. Se llama Tratado de Unificación.","fr":"Le 31 août 1990, l'Allemagne de l'Est et de l'Ouest signent un traité important. Il s'appelle le Traité d'unification.","pl":"31 sierpnia 1990 roku Niemcy Wschodnie i Zachodnie podpisały ważny traktat. Nazywa się Traktat Zjednoczeniowy.","uk":"31 серпня 1990 року Східна і Західна Німеччина підписали важливий договір. Він називається Договір про об'єднання.","fa":"در ۳۱ اوت ۱۹۹۰، آلمان شرقی و غربی پیمان مهمی امضا کردند. نامش پیمان اتحاد است.","it":"Il 31 agosto 1990 la Germania Est e la Germania Ovest firmano un trattato importante. Si chiama Trattato di unificazione."},"sideFacts":[],"translationsByLevel":{"A2":{"en":"On August 31, 1990, the FRG and the GDR signed the Unification Treaty. It regulates how Germany becomes one country again.","ar":"في 31 أغسطس 1990، وقّعت جمهورية ألمانيا الاتحادية وجمهورية ألمانيا الديمقراطية معاهدة الوحدة. تنظم هذه المعاهدة كيفية أن تصبح ألمانيا دولة واحدة مرة أخرى.","tr":"31 Ağustos 1990'da Federal Almanya ve Demokratik Almanya Birleşme Antlaşması'nı imzaladı. Bu antlaşma, Almanya'nın nasıl yeniden tek bir ülke haline geleceğini düzenler.","ru":"31 августа 1990 года ФРГ и ГДР подписали Договор об объединении. Он регулирует, как Германия снова становится единой страной.","es":"El 31 de agosto de 1990, la RFA y la RDA firmaron el Tratado de Unificación. Este regula cómo Alemania vuelve a ser un solo país.","fr":"Le 31 août 1990, la RFA et la RDA signent le traité d'unification. Il fixe comment l'Allemagne redevient un seul pays.","pl":"31 sierpnia 1990 roku RFN i NRD podpisały traktat zjednoczeniowy. Reguluje on, jak Niemcy ponownie stają się jednym krajem.","uk":"31 серпня 1990 року ФРН і НДР підписали Договір про об'єднання. Він регулює, як Німеччина знову стає єдиною країною.","fa":"در ۳۱ اوت ۱۹۹۰، آلمان غربی و آلمان شرقی پیمان اتحاد را امضا کردند. این پیمان تعیین می‌کند که آلمان چگونه دوباره یک کشور می‌شود.","it":"Il 31 agosto 1990 la RFT e la DDR firmano il Trattato di unificazione. Esso stabilisce come la Germania torni a essere un unico paese."},"B1":{"en":"On August 31, 1990, representatives of the FRG and the GDR signed the Unification Treaty in East Berlin. It laid down the legal rules for reunification on October 3.","ar":"في 31 أغسطس 1990، وقّع ممثلو جمهورية ألمانيا الاتحادية وجمهورية ألمانيا الديمقراطية في برلين الشرقية معاهدة الوحدة. حددت المعاهدة القواعد القانونية لإعادة التوحيد في 3 أكتوبر.","tr":"31 Ağustos 1990'da Federal Almanya ve Demokratik Almanya temsilcileri, Doğu Berlin'de Birleşme Antlaşması'nı imzaladı. Antlaşma, 3 Ekim'deki yeniden birleşme için yasal kuralları belirledi.","ru":"31 августа 1990 года представители ФРГ и ГДР подписали в Восточном Берлине Договор об объединении. Он установил правовые нормы для воссоединения 3 октября.","es":"El 31 de agosto de 1990, representantes de la RFA y la RDA firmaron en Berlín Oriental el Tratado de Unificación. Este establecía las normas jurídicas para la reunificación del 3 de octubre.","fr":"Le 31 août 1990, des représentants de la RFA et de la RDA signent à Berlin-Est le traité d'unification. Il fixe les règles juridiques de la réunification du 3 octobre.","pl":"31 sierpnia 1990 roku przedstawiciele RFN i NRD podpisali w Berlinie Wschodnim traktat zjednoczeniowy. Ustalał on prawne zasady zjednoczenia 3 października.","uk":"31 серпня 1990 року представники ФРН і НДР підписали у Східному Берліні Договір про об'єднання. Він визначив правові норми для возз'єднання 3 жовтня.","fa":"در ۳۱ اوت ۱۹۹۰، نمایندگان آلمان غربی و آلمان شرقی در برلین شرقی پیمان اتحاد را امضا کردند. این پیمان قواعد حقوقی اتحاد مجدد در ۳ اکتبر را تعیین کرد.","it":"Il 31 agosto 1990 i rappresentanti della RFT e della DDR firmano a Berlino Est il Trattato di unificazione. Esso fissa le norme giuridiche per la riunificazione, prevista per il 3 ottobre."},"B2":{"en":"On August 31, 1990, West German Interior Minister Wolfgang Schäuble and GDR State Secretary Günther Krause signed the Unification Treaty in East Berlin — the legal foundation for the accession of the GDR to the Federal Republic just five weeks later.","ar":"في 31 أغسطس 1990، وقّع وزير الداخلية الألماني الغربي فولفغانغ شويبله وسكرتير الدولة في جمهورية ألمانيا الديمقراطية غونتر كراوزه في برلين الشرقية معاهدة الوحدة — الأساس القانوني لانضمام جمهورية ألمانيا الديمقراطية إلى جمهورية ألمانيا الاتحادية بعد خمسة أسابيع فقط.","tr":"31 Ağustos 1990'da Batı Alman İçişleri Bakanı Wolfgang Schäuble ve Demokratik Almanya Devlet Sekreteri Günther Krause, Doğu Berlin'de Birleşme Antlaşması'nı imzaladı — bu antlaşma, sadece beş hafta sonra Demokratik Almanya'nın Federal Almanya'ya katılımının hukuki temelini oluşturdu.","ru":"31 августа 1990 года западногерманский министр внутренних дел Вольфганг Шойбле и статс-секретарь ГДР Гюнтер Краузе подписали в Восточном Берлине Договор об объединении — юридическую основу для присоединения ГДР к Федеративной Республике всего пятью неделями позже.","es":"El 31 de agosto de 1990, el ministro del Interior de Alemania Occidental, Wolfgang Schäuble, y el secretario de Estado de la RDA, Günther Krause, firmaron en Berlín Oriental el Tratado de Unificación, la base jurídica para la adhesión de la RDA a la República Federal apenas cinco semanas después.","fr":"Le 31 août 1990, le ministre de l'Intérieur ouest-allemand Wolfgang Schäuble et le secrétaire d'État est-allemand Günther Krause signent à Berlin-Est le traité d'unification — le fondement juridique de l'adhésion de la RDA à la République fédérale cinq semaines plus tard seulement.","pl":"31 sierpnia 1990 roku zachodnioniemiecki minister spraw wewnętrznych Wolfgang Schäuble i sekretarz stanu NRD Günther Krause podpisali w Berlinie Wschodnim traktat zjednoczeniowy — prawną podstawę przystąpienia NRD do Republiki Federalnej zaledwie pięć tygodni później.","uk":"31 серпня 1990 року західнонімецький міністр внутрішніх справ Вольфганг Шойбле та державний секретар НДР Гюнтер Краузе підписали у Східному Берліні Договір про об'єднання — юридичну основу для приєднання НДР до Федеративної Республіки лише через п'ять тижнів.","fa":"در ۳۱ اوت ۱۹۹۰، وولفگانگ شویبله وزیر کشور آلمان غربی و گونتر کراوزه وزیر مشاور دولت آلمان شرقی، در برلین شرقی پیمان اتحاد را امضا کردند — پایه حقوقی الحاق آلمان شرقی به جمهوری فدرال تنها پنج هفته بعد.","it":"Il 31 agosto 1990 il ministro dell'Interno della Germania Ovest Wolfgang Schäuble e il segretario di Stato della DDR Günther Krause firmano a Berlino Est il Trattato di unificazione — il fondamento giuridico per l'adesione della DDR alla Repubblica Federale, appena cinque settimane più tardi."},"C1":{"en":"The Unification Treaty signed by Wolfgang Schäuble and Günther Krause on August 31, 1990, regulated in detail the legal, economic, and social conditions of the GDR's accession and thus formed the binding basis for the formal reunification on October 3, 1990.","ar":"نظمت معاهدة الوحدة، التي وقّعها فولفغانغ شويبله وغونتر كراوزه في 31 أغسطس 1990، بالتفصيل الشروط القانونية والاقتصادية والاجتماعية لانضمام جمهورية ألمانيا الديمقراطية، وشكلت بذلك الأساس الملزم لإعادة التوحيد الرسمية في 3 أكتوبر 1990.","tr":"Wolfgang Schäuble ve Günther Krause tarafından 31 Ağustos 1990'da imzalanan Birleşme Antlaşması, Demokratik Almanya'nın katılımının hukuki, ekonomik ve sosyal koşullarını ayrıntılı biçimde düzenledi ve böylece 3 Ekim 1990'daki resmi yeniden birleşme için bağlayıcı temeli oluşturdu.","ru":"Договор об объединении, подписанный Вольфгангом Шойбле и Гюнтером Краузе 31 августа 1990 года, детально регулировал правовые, экономические и социальные условия присоединения ГДР и тем самым составил обязательную основу для формального воссоединения 3 октября 1990 года.","es":"El Tratado de Unificación firmado por Wolfgang Schäuble y Günther Krause el 31 de agosto de 1990 reguló detalladamente las condiciones jurídicas, económicas y sociales de la adhesión de la RDA, constituyendo así la base vinculante para la reunificación formal del 3 de octubre de 1990.","fr":"Le traité d'unification signé par Wolfgang Schäuble et Günther Krause le 31 août 1990 réglait en détail les conditions juridiques, économiques et sociales de l'adhésion de la RDA et constituait ainsi la base contraignante de la réunification formelle du 3 octobre 1990.","pl":"Traktat zjednoczeniowy podpisany przez Wolfganga Schäuble i Günthera Krausego 31 sierpnia 1990 roku szczegółowo regulował prawne, gospodarcze i społeczne warunki przystąpienia NRD i stanowił tym samym wiążącą podstawę formalnego zjednoczenia 3 października 1990 roku.","uk":"Договір про об'єднання, підписаний Вольфгангом Шойбле та Гюнтером Краузе 31 серпня 1990 року, детально регулював правові, економічні та соціальні умови приєднання НДР і став тим самим обов'язковою основою для офіційного возз'єднання 3 жовтня 1990 року.","fa":"پیمان اتحادی که وولفگانگ شویبله و گونتر کراوزه در ۳۱ اوت ۱۹۹۰ امضا کردند، شرایط حقوقی، اقتصادی و اجتماعی الحاق آلمان شرقی را به‌تفصیل تنظیم کرد و بدین‌سان پایه الزام‌آور اتحاد مجدد رسمی در ۳ اکتبر ۱۹۹۰ را تشکیل داد.","it":"Il Trattato di unificazione, firmato il 31 agosto 1990 da Wolfgang Schäuble e Günther Krause, disciplinò in dettaglio le condizioni giuridiche, economiche e sociali dell'adesione della DDR, costituendo così la base vincolante per la riunificazione formale del 3 ottobre 1990."},"C2":{"en":"The Unification Treaty of August 31, 1990, translated the political will for German unity into a complex body of rules that bindingly set out the harmonization of law, questions of property, and the adoption of West German institutions in the new federal states — a bureaucratic feat of historic scale.","ar":"ترجمت معاهدة الوحدة المؤرخة 31 أغسطس 1990 الإرادة السياسية للوحدة الألمانية إلى مجموعة قواعد معقدة حددت بشكل ملزم مواءمة القوانين وقضايا الملكية وتبني المؤسسات الألمانية الغربية في الولايات الفدرالية الجديدة — وهو إنجاز بيروقراطي ذو أبعاد تاريخية.","tr":"31 Ağustos 1990 tarihli Birleşme Antlaşması, Alman birliği için siyasi iradeyi, hukuk uyumlaştırmasını, mülkiyet sorunlarını ve Batı Alman kurumlarının yeni federal eyaletlerde devralınmasını bağlayıcı biçimde belirleyen karmaşık bir kurallar bütününe dönüştürdü — tarihsel boyutta bürokratik bir güç gösterisi.","ru":"Договор об объединении от 31 августа 1990 года перевёл политическую волю к германскому единству в сложную систему правил, обязательно устанавливавшую унификацию права, вопросы собственности и перенятие западногерманских институтов в новых федеральных землях — бюрократический подвиг исторического масштаба.","es":"El Tratado de Unificación del 31 de agosto de 1990 tradujo la voluntad política de la unidad alemana en un complejo cuerpo normativo que fijaba de forma vinculante la armonización jurídica, las cuestiones de propiedad y la adopción de las instituciones de Alemania Occidental en los nuevos estados federados: una hazaña burocrática de dimensión histórica.","fr":"Le traité d'unification du 31 août 1990 a traduit la volonté politique d'unité allemande en un ensemble de règles complexes, fixant de manière contraignante l'harmonisation du droit, les questions de propriété et la reprise des institutions ouest-allemandes dans les nouveaux Länder — une prouesse bureaucratique d'ampleur historique.","pl":"Traktat zjednoczeniowy z 31 sierpnia 1990 roku przełożył polityczną wolę niemieckiej jedności na złożony zbiór przepisów, który wiążąco określał ujednolicenie prawa, kwestie własnościowe oraz przejęcie zachodnioniemieckich instytucji w nowych krajach związkowych — biurokratyczny wyczyn o historycznej skali.","uk":"Договір про об'єднання від 31 серпня 1990 року переклав політичну волю до німецької єдності у складний звід правил, що обов'язково визначав уніфікацію права, майнові питання та переймання західнонімецьких інституцій у нових федеральних землях — бюрократичний подвиг історичного масштабу.","fa":"پیمان اتحاد مورخ ۳۱ اوت ۱۹۹۰ اراده سیاسی برای وحدت آلمان را به مجموعه‌ای پیچیده از مقررات تبدیل کرد که هماهنگ‌سازی حقوقی، مسائل مالکیت و پذیرش نهادهای آلمان غربی در ایالت‌های فدرال جدید را به‌طور الزام‌آور تعیین می‌کرد — دستاوردی بوروکراتیک در ابعادی تاریخی.","it":"Il Trattato di unificazione del 31 agosto 1990 tradusse la volontà politica dell'unità tedesca in un complesso apparato normativo, che stabilì in modo vincolante l'armonizzazione giuridica, le questioni patrimoniali e il trasferimento delle istituzioni della Germania occidentale nei nuovi Länder — uno sforzo burocratico di portata storica."}}}});
window.DMA_DATEN.KALENDER_MONATE["08"] = true;
